@import "tailwindcss" source(none);
@source "../src";
@import "tw-animate-css";

@theme {
  /* Premium dark fintech palette */
  --color-background: #08090c;
  --color-surface: #0e1015;
  --color-elevated: #14171e;
  --color-foreground: #f5f7fa;
  --color-muted: #737b8a;
  --color-subtle: #a2abba;
  --color-border: rgba(255, 255, 255, 0.08);
  --color-border-strong: rgba(255, 255, 255, 0.16);

  --color-accent: #22d3a5;
  --color-accent-dim: rgba(34, 211, 165, 0.12);
  --color-violet: #8b5cf6;
  --color-coral: #f87171;
  --color-mint: #22d3a5;
  --color-amber: #fbbf24;
  --color-sky: #60a5fa;
  --color-danger: #ef4444;
  --color-positive: #2fce93;
  --color-negative: #f0736f;
  --color-warning: #f3bb4c;

  --font-display: "Inter Tight", "Inter", ui-sans-serif, system-ui;
  --font-sans: "Inter", ui-sans-serif, system-ui;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  --surface-raised: linear-gradient(180deg, #161a21 0%, #101319 100%);
  --shadow-soft: 0 16px 38px rgba(0, 0, 0, 0.26);
  --shadow-lifted: 0 26px 60px rgba(0, 0, 0, 0.36);
  --shadow-card: var(--shadow-soft);
}

/* Intake location management keeps operational configuration compact and readable. */
.intake-locations-workspace {
  display: grid;
  gap: 1rem;
}
.intake-locations-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
}
.intake-locations-header h2,
.intake-locations-header h3 {
  margin: 0.18rem 0;
}
.intake-locations-header p {
  margin: 0;
  color: var(--muted, #91a4af);
}
.intake-location-metrics {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 0.75rem;
}
.intake-location-metrics .admin-panel {
  display: grid;
  grid-template-columns: auto 1fr;
  align-items: center;
  column-gap: 0.55rem;
  padding: 1rem;
}
.intake-location-metrics svg {
  color: var(--mint, #2ad7ba);
  width: 1.2rem;
}
.intake-location-metrics strong {
  font-size: 1.45rem;
}
.intake-location-metrics small {
  grid-column: 2;
  color: var(--muted, #91a4af);
}
.intake-location-directory {
  display: grid;
  gap: 1rem;
}
.intake-location-filters {
  display: grid;
  grid-template-columns: minmax(16rem, 1fr) repeat(2, minmax(10rem, 0.35fr));
  gap: 0.65rem;
}
.intake-location-filters select,
.intake-location-form select,
.intake-location-form input,
.intake-location-form textarea {
  background: #07141c;
  border: 1px solid #27414c;
  border-radius: 0.4rem;
  color: #edf8f7;
  min-height: 2.45rem;
  padding: 0.55rem 0.7rem;
}
.intake-location-table {
  display: grid;
  border: 1px solid #213943;
  border-radius: 0.55rem;
  overflow: auto;
}
.intake-location-table-row {
  display: grid;
  grid-template-columns: minmax(13rem, 1.6fr) minmax(9rem, 1fr) minmax(8rem, 1fr) minmax(
      6rem,
      0.65fr
    ) minmax(9rem, 0.9fr) minmax(6rem, 0.5fr) minmax(5rem, 0.5fr);
  gap: 0.7rem;
  align-items: center;
  padding: 0.75rem 0.85rem;
  border-bottom: 1px solid #1d333d;
  min-width: 65rem;
}
.intake-location-table-row:last-child {
  border-bottom: 0;
}
.intake-location-table-head {
  color: #7d98a3;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  background: #0c1b23;
}
.intake-location-table-row small {
  display: block;
  color: #8ba0a8;
  margin-top: 0.2rem;
}
.intake-location-pagination {
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: #8ba0a8;
}
.intake-location-pagination button {
  background: transparent;
  border: 1px solid #2c4651;
  color: #b9d4d6;
  border-radius: 0.3rem;
  min-width: 2rem;
  min-height: 2rem;
}
.intake-location-pagination button:disabled {
  opacity: 0.4;
}
.intake-location-pagination strong {
  margin: 0 0.5rem;
}
.intake-location-status-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.7rem;
  color: #a9bdc4;
}
.intake-location-status-row span:not(.admin-status-pill) {
  border-left: 1px solid #2a424c;
  padding-left: 0.7rem;
}
.intake-location-detail-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 1rem;
}
.intake-location-detail-grid h3,
.intake-location-detail-grid h4 {
  margin-top: 0;
}
.intake-location-definition {
  display: grid;
  grid-template-columns: minmax(10rem, 0.75fr) 1fr;
  gap: 0.7rem 1rem;
}
.intake-location-definition dt {
  color: #8ba0a8;
}
.intake-location-definition dd {
  margin: 0;
  color: #edf8f7;
}
.intake-location-counts {
  display: flex;
  gap: 0.65rem;
  flex-wrap: wrap;
  margin-bottom: 0.85rem;
}
.intake-location-counts span {
  background: #10252d;
  border-radius: 0.3rem;
  color: #a7c0c6;
  padding: 0.45rem 0.6rem;
  font-size: 0.75rem;
  text-transform: capitalize;
}
.intake-location-counts strong {
  color: #39d7bd;
  margin-right: 0.35rem;
}
.intake-location-history {
  display: grid;
}
.intake-location-history > div {
  display: grid;
  grid-template-columns: 1fr auto auto;
  gap: 1rem;
  border-bottom: 1px solid #1d333d;
  padding: 0.8rem 0;
}
.intake-location-history span,
.intake-location-history small {
  color: #8ba0a8;
}
.intake-location-state {
  color: #a8bec5;
  padding: 1.2rem;
  text-align: center;
}
.intake-location-modal {
  align-items: flex-start;
  background: rgb(1 9 13 / 0.8);
  display: flex;
  inset: 0;
  justify-content: center;
  overflow: auto;
  padding: 2rem 1rem;
  position: fixed;
  z-index: 80;
}
.intake-location-form {
  display: grid;
  gap: 1rem;
  max-width: 58rem;
  width: 100%;
}
.intake-location-form fieldset {
  border: 1px solid #25404b;
  border-radius: 0.55rem;
  display: grid;
  gap: 0.75rem;
  padding: 1rem;
}
.intake-location-form legend {
  color: #43d4bd;
  font-weight: 700;
  padding: 0 0.35rem;
}
.intake-location-form label {
  color: #d4e7e8;
  display: grid;
  font-size: 0.82rem;
  gap: 0.35rem;
}
.intake-location-form textarea {
  min-height: 5rem;
  resize: vertical;
}
.intake-location-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.7rem;
}
.intake-location-methods {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.7rem;
}
.intake-location-methods label {
  background: #0d2028;
  border: 1px solid #27414c;
  border-radius: 0.45rem;
  padding: 0.75rem;
}
.intake-location-methods small,
.intake-location-form-help {
  color: #8ba0a8;
}
.intake-location-form-actions {
  display: flex;
  justify-content: flex-end;
  gap: 0.65rem;
}
.intake-location-error {
  color: #ff827b;
  margin: 0;
}
@media (max-width: 900px) {
  .intake-location-metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .intake-location-detail-grid {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 640px) {
  .intake-locations-header {
    flex-direction: column;
  }
  .intake-location-filters,
  .intake-location-form-grid,
  .intake-location-methods {
    grid-template-columns: 1fr;
  }
  .intake-location-history > div {
    grid-template-columns: 1fr;
    gap: 0.2rem;
  }
}

/* Consolidated account detail: three operational surfaces, dense but readable. */
.admin-account-detail-content {
  width: min(100%, 1520px);
  margin-inline: auto;
}
.admin-account-detail-breadcrumb {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  min-height: 1.3rem;
  color: #8297a0;
  font-size: 0.64rem;
}
.admin-account-detail-breadcrumb .admin-back-link {
  margin: 0;
}
.admin-account-detail-breadcrumb strong {
  color: #dce9e6;
  font-weight: 600;
}
.admin-account-detail-header {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 1rem;
  border: 1px solid #203844;
  border-radius: 0.7rem;
  background: linear-gradient(135deg, rgba(10, 27, 37, 0.98), rgba(7, 19, 27, 0.97));
  padding: 1.1rem;
}
.admin-account-detail-identity-copy {
  min-width: 0;
}
.admin-account-detail-identity-copy h2 {
  margin: 0.25rem 0 0.35rem;
  color: #f2f8f6;
  font-family: var(--font-display);
  font-size: clamp(1.35rem, 2.2vw, 2rem);
  letter-spacing: -0.03em;
}
.admin-account-detail-identity-copy > span {
  display: block;
  overflow: hidden;
  color: #a8b9c0;
  font-size: 0.68rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.admin-account-detail-header-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 0.45rem;
  flex-wrap: wrap;
}
.admin-account-detail-header-action {
  display: inline-flex;
  min-height: 2rem;
  align-items: center;
  gap: 0.4rem;
  border: 1px solid #38515c;
  border-radius: 0.35rem;
  padding: 0.45rem 0.7rem;
  color: #d9e8e5;
  font-size: 0.6rem;
}
.admin-account-detail-header-action:hover,
.admin-account-detail-header-action:focus-visible {
  border-color: #28d0a9;
  color: #6ae8c8;
}
.admin-account-detail-header-action svg {
  width: 0.78rem;
}
.admin-account-detail-header-meta {
  display: flex;
  grid-column: 1 / -1;
  gap: 1rem;
  border-top: 1px solid rgba(46, 68, 78, 0.7);
  padding-top: 0.7rem;
  color: #91a6af;
  font-size: 0.61rem;
  flex-wrap: wrap;
}
.admin-account-detail-header-meta strong {
  color: #e2efec;
  font-weight: 600;
}
.admin-account-detail-header-meta button,
.admin-account-detail-event-id {
  border: 0;
  color: #39d7b3;
  font: inherit;
  cursor: pointer;
}
.admin-account-detail-tabs {
  margin-top: 0.15rem;
}
.admin-account-detail-main main {
  min-width: 0;
}
.admin-account-detail-stack {
  display: grid;
  gap: 1rem;
}
.admin-account-detail-state-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  overflow: hidden;
  border: 1px solid #203844;
  border-radius: 0.65rem;
  background: #091821;
}
.admin-account-detail-state-cell {
  min-width: 0;
  border-right: 1px solid #20313b;
  padding: 0.85rem 0.9rem;
}
.admin-account-detail-state-cell:last-child {
  border-right: 0;
}
.admin-account-detail-state-cell strong,
.admin-account-detail-state-cell small,
.admin-account-detail-state-label {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.admin-account-detail-state-label {
  color: #8ea4ad;
  font-size: 0.55rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.admin-account-detail-state-cell strong {
  margin-top: 0.35rem;
  color: #dcebe8;
  font-size: 0.82rem;
}
.admin-account-detail-state-cell small {
  margin-top: 0.22rem;
  color: #8da2aa;
  font-size: 0.58rem;
}
.admin-account-detail-state-cell--positive strong {
  color: #44dfbd;
}
.admin-account-detail-state-cell--warning strong {
  color: #efbe56;
}
.admin-account-detail-state-cell--critical strong {
  color: #f28e8b;
}
.admin-account-detail-state-cell--muted strong {
  color: #a8bac0;
}
.admin-account-detail-grid {
  display: grid;
  gap: 1rem;
  min-width: 0;
}
.admin-account-detail-grid--overview,
.admin-account-detail-grid--operations {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
.admin-account-detail-grid--dashboard {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}
.admin-account-detail-grid--supporting {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}
.admin-account-detail-grid--summary {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
.admin-account-detail-panel {
  min-width: 0;
  border: 1px solid #203844;
  border-radius: 0.65rem;
  background: linear-gradient(150deg, rgba(10, 27, 37, 0.96), rgba(7, 19, 27, 0.96));
  padding: 1rem;
}
.admin-account-detail-panel .admin-panel-heading {
  margin-bottom: 0.45rem;
}
.admin-account-detail-panel--empty {
  min-height: 9rem;
}
.admin-account-detail-issues,
.admin-account-detail-activity-list {
  display: grid;
  gap: 0.15rem;
}
.admin-account-detail-issue,
.admin-account-detail-activity {
  display: flex;
  min-width: 0;
  align-items: flex-start;
  gap: 0.65rem;
  border-bottom: 1px solid rgba(39, 59, 69, 0.62);
  padding: 0.68rem 0;
}
.admin-account-detail-issue:last-child,
.admin-account-detail-activity:last-child {
  border-bottom: 0;
}
.admin-account-detail-issue svg {
  width: 1rem;
  flex: 0 0 auto;
  color: #efbe56;
}
.admin-account-detail-activity svg {
  width: 1rem;
  flex: 0 0 auto;
  color: #41d9b6;
}
.admin-account-detail-issue span,
.admin-account-detail-activity span {
  display: grid;
  min-width: 0;
  gap: 0.18rem;
}
.admin-account-detail-issue strong,
.admin-account-detail-activity strong {
  overflow: hidden;
  color: #e6f0ee;
  font-size: 0.67rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.admin-account-detail-issue small,
.admin-account-detail-activity small {
  color: #94aab2;
  font-size: 0.58rem;
}
.admin-account-detail-metrics,
.admin-account-detail-finance-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  column-gap: 1.2rem;
}
.admin-account-detail-panel > .admin-detail-link {
  margin-top: 0.75rem;
}
.admin-account-detail-compact-roles {
  display: grid;
  gap: 0;
}
.admin-account-detail-compact-roles > div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  border-bottom: 1px solid rgba(39, 59, 69, 0.62);
  padding: 0.48rem 0;
}
.admin-account-detail-compact-roles > div:last-child {
  border-bottom: 0;
}
.admin-account-detail-compact-roles strong {
  color: #e4eeeb;
  font-size: 0.64rem;
}
.admin-account-detail-compact-roles span {
  color: #7f98a2;
  font-size: 0.53rem;
}
.admin-account-detail-identity-list .admin-detail-row {
  padding-block: 0.43rem;
}
.admin-account-detail-danger {
  display: grid;
  gap: 0.65rem;
  border: 1px solid rgba(115, 67, 67, 0.75);
  border-radius: 0.65rem;
  background: rgba(39, 22, 26, 0.48);
  padding: 0.8rem;
}
.admin-account-detail-danger > div:first-child {
  display: grid;
  gap: 0.2rem;
}
.admin-account-detail-danger > div:first-child strong {
  color: #f0c4be;
  font-size: 0.72rem;
}
.admin-account-detail-danger > div:first-child span {
  color: #ad8e8e;
  font-size: 0.6rem;
}
.admin-account-detail-danger .admin-status-panel {
  border-color: rgba(115, 67, 67, 0.72);
  background: rgba(10, 21, 28, 0.68);
}
.admin-account-detail-history {
  min-height: 20rem;
}
.admin-account-detail-history-table-wrap {
  margin-top: 0.8rem;
}
.admin-account-detail-history-table {
  min-width: 48rem;
}
.admin-account-detail-history-table th,
.admin-account-detail-history-table td {
  padding-block: 0.55rem;
  font-size: 0.58rem;
}
.admin-account-detail-history-table td {
  color: #afc0c3;
}
.admin-account-detail-history-table td:nth-child(2) {
  color: #e3edeb;
  font-weight: 600;
}
.admin-account-detail-history-table time {
  color: #8ea3aa;
  white-space: nowrap;
}
.admin-account-detail-history-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  border-bottom: 1px solid #203844;
  padding-bottom: 0.9rem;
}
.admin-account-detail-history-heading h3 {
  margin: 0.25rem 0;
  color: #eff8f5;
  font-family: var(--font-display);
  font-size: 1.1rem;
}
.admin-account-detail-history-heading > div:first-child > span {
  color: #93a9b1;
  font-size: 0.61rem;
}
.admin-account-detail-history-filters {
  display: flex;
  justify-content: flex-end;
  gap: 0.3rem;
  flex-wrap: wrap;
}
.admin-account-detail-history-filters button,
.admin-account-detail-category {
  border: 1px solid #29414b;
  border-radius: 999px;
  background: #0b1b24;
  padding: 0.32rem 0.5rem;
  color: #9db2b8;
  font-size: 0.56rem;
  cursor: pointer;
}
.admin-account-detail-history-filters button.is-active {
  border-color: #1ed2aa;
  background: rgba(30, 210, 170, 0.12);
  color: #5ce8c7;
}
.admin-account-detail-timeline {
  position: relative;
  display: grid;
  gap: 0;
  padding: 0.8rem 0 0.2rem;
}
.admin-account-detail-timeline::before {
  position: absolute;
  top: 1.15rem;
  bottom: 1rem;
  left: 0.9rem;
  width: 1px;
  background: #29414b;
  content: "";
}
.admin-account-detail-timeline-row {
  position: relative;
  display: grid;
  grid-template-columns: 1.8rem minmax(0, 1fr);
  gap: 0.75rem;
  padding: 0.65rem 0;
}
.admin-account-detail-timeline-marker {
  z-index: 1;
  display: grid;
  width: 1.8rem;
  height: 1.8rem;
  place-items: center;
  border: 1px solid #31505a;
  border-radius: 50%;
  background: #0b1b24;
}
.admin-account-detail-timeline-marker svg {
  width: 0.8rem;
  color: #44dfbd;
}
.admin-account-detail-timeline-marker--critical svg {
  color: #f28e8b;
}
.admin-account-detail-timeline-marker--warning svg {
  color: #efbe56;
}
.admin-account-detail-timeline-content {
  display: grid;
  min-width: 0;
  gap: 0.24rem;
  padding-bottom: 0.7rem;
  border-bottom: 1px solid rgba(39, 59, 69, 0.62);
}
.admin-account-detail-timeline-content > div {
  display: flex;
  justify-content: space-between;
  gap: 0.7rem;
}
.admin-account-detail-timeline-content time,
.admin-account-detail-timeline-content small {
  color: #91a7af;
  font-size: 0.58rem;
}
.admin-account-detail-timeline-content strong {
  color: #e4efec;
  font-size: 0.7rem;
}
.admin-account-detail-event-id {
  width: fit-content;
  padding: 0;
  background: none;
  font-size: 0.56rem;
}
@media (max-width: 1050px) {
  .admin-account-detail-state-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .admin-account-detail-state-cell:nth-child(3) {
    border-right: 0;
  }
  .admin-account-detail-state-cell:nth-child(n + 4) {
    border-top: 1px solid #20313b;
  }
  .admin-account-detail-grid--dashboard {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .admin-account-detail-grid--supporting {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 760px) {
  .admin-account-detail-header {
    grid-template-columns: 1fr;
  }
  .admin-account-detail-header-actions {
    justify-content: flex-start;
  }
  .admin-account-detail-state-grid,
  .admin-account-detail-grid--overview,
  .admin-account-detail-grid--summary,
  .admin-account-detail-grid--dashboard,
  .admin-account-detail-grid--supporting,
  .admin-account-detail-grid--operations {
    grid-template-columns: 1fr;
  }
  .admin-account-detail-state-cell {
    border-right: 0;
    border-top: 1px solid #20313b;
  }
  .admin-account-detail-state-cell:first-child {
    border-top: 0;
  }
  .admin-account-detail-history-heading {
    display: grid;
  }
  .admin-account-detail-history-filters {
    justify-content: flex-start;
  }
}
@media (max-width: 520px) {
  .admin-account-detail-content {
    padding-inline: 0.75rem;
  }
  .admin-account-detail-header {
    padding: 0.8rem;
  }
  .admin-account-detail-header-meta {
    display: grid;
    gap: 0.4rem;
  }
  .admin-account-detail-metrics,
  .admin-account-detail-finance-grid {
    grid-template-columns: 1fr;
  }
  .admin-account-detail-history-filters {
    overflow-x: auto;
    flex-wrap: nowrap;
    justify-content: flex-start;
    padding-bottom: 0.15rem;
  }
  .admin-account-detail-history-filters button {
    flex: 0 0 auto;
  }
  .admin-account-detail-panel {
    padding: 0.8rem;
  }
}

/* Payout setup and normal withdrawal confirmation */
.wallet-payout-setup-copy {
  margin: 1rem 0 0;
  color: var(--text-primary, #f5f7fb);
  font-size: 0.95rem;
  line-height: 1.55;
}

.wallet-withdrawal-review {
  width: min(100%, 32rem);
}

.wallet-withdrawal-review__summary {
  display: grid;
  gap: 0.7rem;
  margin: 1.25rem 0;
}

.wallet-withdrawal-review__summary > div {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.8rem 0;
  border-bottom: 1px solid color-mix(in srgb, currentColor 12%, transparent);
}

.wallet-withdrawal-review__summary dt {
  color: var(--text-muted, #9ba5b5);
  font-size: 0.82rem;
}

.wallet-withdrawal-review__summary dd {
  margin: 0;
  color: var(--text-primary, #f5f7fb);
  font-weight: 700;
  text-align: right;
}

@media (max-width: 520px) {
  .wallet-withdrawal-review__summary > div {
    align-items: flex-start;
    flex-direction: column;
    gap: 0.25rem;
  }

  .wallet-withdrawal-review__summary dd {
    text-align: left;
  }
