/* Professional certification verification block in List > Step 2. */
.list-certification-panel {
  display: grid;
  gap: 1rem;
  margin-top: 1.35rem;
  padding: 1.15rem 1.2rem 1.2rem;
  border: 1px solid rgba(91, 219, 190, 0.34);
  border-radius: 1rem;
  background:
    radial-gradient(circle at 0% 0%, rgba(34, 211, 165, 0.13), transparent 44%),
    linear-gradient(145deg, rgba(15, 42, 43, 0.92), rgba(8, 18, 24, 0.96));
  box-shadow:
    inset 0 1px 0 rgba(193, 255, 236, 0.05),
    0 1.2rem 2.4rem rgba(0, 0, 0, 0.12);
}
.list-certification-panel__header {
  display: grid;
  grid-template-columns: 2.35rem minmax(0, 1fr) auto;
  gap: 0.75rem;
  align-items: center;
}
.list-certification-panel__icon {
  display: grid;
  width: 2.35rem;
  height: 2.35rem;
  place-items: center;
  border: 1px solid rgba(76, 224, 186, 0.42);
  border-radius: 0.7rem;
  background: rgba(34, 211, 165, 0.11);
  color: #68e6c4;
}
.list-certification-panel__icon svg {
  width: 1.15rem;
  height: 1.15rem;
}
.list-certification-panel__header strong {
  display: block;
  color: #effcf8;
  font-size: 0.84rem;
  letter-spacing: -0.01em;
}
.list-certification-panel__header p {
  margin: 0.2rem 0 0;
  color: #91aaa9;
  font-size: 0.68rem;
  line-height: 1.35;
}
.list-certification-panel__badge {
  border: 1px solid rgba(96, 226, 193, 0.28);
  border-radius: 999px;
  padding: 0.32rem 0.55rem;
  color: #96f3d5;
  background: rgba(34, 211, 165, 0.09);
  font-size: 0.58rem;
  font-weight: 750;
  letter-spacing: 0.03em;
  white-space: nowrap;
}
.list-certification-panel > label {
  display: grid;
  gap: 0.45rem;
  min-width: 0;
}
.list-certification-panel > label > .list-field-label {
  color: #dcece9;
  font-size: 0.72rem;
}
.list-certification-input {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 0.65rem;
  align-items: center;
}
.list-certification-input input {
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  min-height: 3rem;
  border: 1px solid rgba(152, 190, 192, 0.3);
  border-radius: 0.62rem;
  padding: 0.7rem 0.8rem;
  color: #f4fffc;
  background: rgba(3, 11, 15, 0.72);
  font: inherit;
  font-size: 0.84rem;
  outline: none;
  transition:
    border-color 140ms ease,
    box-shadow 140ms ease,
    background-color 140ms ease;
}
.list-certification-input input::placeholder {
  color: #809797;
  opacity: 1;
}
.list-certification-input input:focus {
  border-color: #36dfb3;
  background: rgba(5, 20, 22, 0.92);
  box-shadow: 0 0 0 3px rgba(34, 211, 165, 0.13);
}
.list-certification-input .button-secondary {
  min-height: 3rem;
  border-color: rgba(76, 224, 186, 0.45);
  border-radius: 0.62rem;
  padding-inline: 1rem;
  color: #061b18;
  background: #55e2bd;
  font-weight: 800;
  white-space: nowrap;
}
.list-certification-input .button-secondary:hover:not(:disabled) {
  border-color: #88f5d7;
  background: #76ebc9;
}
.list-certification-input .button-secondary:disabled {
  border-color: rgba(122, 171, 167, 0.2);
  color: #7f9996;
  background: rgba(87, 131, 126, 0.2);
}
.list-certification-panel > label > .list-field-help {
  color: #9eb5b3;
  font-size: 0.67rem;
  line-height: 1.45;
}
.list-certification-status {
  display: flex;
  gap: 0.65rem;
  align-items: flex-start;
  margin-top: 0.8rem;
  padding: 0.75rem;
  border-radius: 0.75rem;
  background: rgba(245, 158, 11, 0.09);
  color: var(--text-primary, #f8fafc);
}
.list-certification-status > svg {
  flex: 0 0 auto;
  color: #fbbf24;
}
.list-certification-status > div {
  display: grid;
  gap: 0.2rem;
}
.list-certification-status span {
  color: var(--text-subtle, #9aa8bc);
  font-size: 0.85rem;
}
.list-certification-status a {
  display: inline-flex;
  align-items: center;
  gap: 0.2rem;
  color: #8ef3d4;
  font-size: 0.82rem;
}
.list-certification-status--verified {
  background: rgba(34, 197, 94, 0.1);
}
.list-certification-status--verified > svg {
  color: #86efac;
}
.list-certification-status--mismatch {
  background: rgba(239, 68, 68, 0.1);
}
.list-certification-status--mismatch > svg {
  color: #fca5a5;
}
.list-scale-unavailable {
  display: flex;
  gap: 0.45rem;
  align-items: center;
  min-height: 2.8rem;
  padding: 0.65rem 0.8rem;
  border: 1px dashed var(--border-subtle, #263449);
  border-radius: 0.65rem;
  color: var(--text-subtle, #9aa8bc);
  font-size: 0.82rem;
}
@media (max-width: 640px) {
  .list-certification-panel {
    padding: 1rem;
  }
  .list-certification-panel__header {
    grid-template-columns: 2.15rem minmax(0, 1fr);
  }
  .list-certification-panel__icon {
    width: 2.15rem;
    height: 2.15rem;
  }
  .list-certification-panel__badge {
    grid-column: 2;
    justify-self: start;
    margin-top: -0.25rem;
  }
  .list-certification-input {
    grid-template-columns: 1fr;
  }
  .list-certification-input .button-secondary {
    width: 100%;
  }
}

/* Wallet visual reconstruction pass: compact hierarchy, intentional density, and
   content-sized surfaces. Keep this final layer narrow so legacy page styles do not
   recreate the oversized card wall. */
.wallet-page {
  background:
    radial-gradient(ellipse 46% 28% at 76% 2%, rgba(21, 188, 143, 0.09), transparent 70%),
    radial-gradient(ellipse 38% 24% at 16% 34%, rgba(13, 93, 76, 0.045), transparent 72%),
    linear-gradient(180deg, #080c10 0%, #070a0d 38rem, #070a0d 100%);
}
.wallet-page .wallet-shell {
  width: min(calc(100% - clamp(2rem, 4vw, 5rem)), 100rem);
  padding-block: clamp(1.65rem, 2.8vw, 2.35rem) 2.75rem;
}
.wallet-heading {
  padding-bottom: 1rem;
}
.wallet-heading h1 {
  margin-top: 0.34rem;
  font-size: clamp(2.35rem, 3.3vw, 3.55rem);
  line-height: 0.96;
}
.wallet-heading > p:last-child {
  margin-top: 0.56rem;
  font-size: 0.78rem;
  line-height: 1.4;
}
.wallet-kpis {
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 0.62rem;
}
.wallet-kpi {
  min-height: 5.95rem;
  align-items: center;
  gap: 0.66rem;
  padding: 0.78rem 0.82rem;
  border-radius: 0.62rem;
}
.wallet-kpi p {
  color: #aab6bd;
  font-size: 0.54rem;
  font-weight: 720;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}
.wallet-kpi strong {
  margin-top: 0.28rem;
  font-size: clamp(1.08rem, 1.4vw, 1.42rem);
  letter-spacing: -0.04em;
}
.wallet-kpi > div > span {
  margin-top: 0.26rem;
  font-size: 0.54rem;
}
.wallet-kpi .kpi-icon-tile {
  width: 1.92rem;
  height: 1.92rem;
  border-radius: 0.42rem;
}
.wallet-kpi--featured {
  border-color: rgba(42, 218, 168, 0.64);
  background: linear-gradient(145deg, rgba(13, 45, 39, 0.9), rgba(9, 23, 24, 0.98));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.04),
    0 0 22px rgba(18, 192, 149, 0.07);
}
.wallet-kpi--featured p {
  color: #38d9a9;
}
.wallet-kpi--featured::after {
  right: 0.85rem;
  bottom: 0.85rem;
  width: 4.8rem;
  height: 1.2rem;
  opacity: 0.58;
}
.wallet-row {
  gap: 0.7rem;
  margin-top: 0.7rem;
}
.wallet-row--primary {
  grid-template-columns: minmax(0, 1.03fr) minmax(0, 0.99fr) minmax(0, 1.17fr);
  align-items: start;
}
.wallet-row--history {
  grid-template-columns: minmax(0, 1.68fr) minmax(20rem, 0.92fr);
  align-items: start;
}
.wallet-side-stack {
  gap: 0.7rem;
}
.wallet-panel {
  min-height: 0;
  border-color: rgba(130, 158, 170, 0.16);
  border-radius: 0.68rem;
  background: linear-gradient(145deg, rgba(17, 24, 30, 0.96), rgba(9, 14, 18, 0.98));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.025),
    0 12px 26px rgba(0, 0, 0, 0.14);
}
.wallet-panel--bank,
.wallet-panel--move,
.wallet-panel--status,
.wallet-panel--movements,
.wallet-panel--timeline,
.wallet-panel--insights {
  min-height: 0;
}
.wallet-panel__head {
  min-height: 2.85rem;
  padding: 0.68rem 0.9rem 0.48rem;
}
.wallet-panel__head h2 {
  gap: 0.48rem;
  font-size: 0.68rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}
.wallet-panel__head h2 > span {
  width: 1.38rem;
  height: 1.38rem;
  border-radius: 0.34rem;
}
.wallet-panel__head h2 svg {
  width: 0.72rem;
  height: 0.72rem;
}
.wallet-panel__body {
  padding: 0 0.9rem 0.82rem;
}
.wallet-bank-panel-body {
  min-height: 0;
}
.wallet-bank-empty {
  min-height: 4.9rem;
  gap: 0.72rem;
  padding: 0.45rem 0 0.25rem;
}
.wallet-bank-empty__icon {
  display: grid;
  width: 2rem;
  height: 2rem;
  flex: 0 0 auto;
  place-items: center;
  border: 1px solid rgba(45, 213, 165, 0.18);
  border-radius: 0.48rem;
  background: rgba(28, 183, 142, 0.1);
  color: #39d9aa;
}
.wallet-bank-empty__icon svg {
  width: 1rem;
  height: 1rem;
}
.wallet-bank-empty > div > strong {
  font-size: 0.72rem;
}
.wallet-bank-empty p {
  max-width: 21rem;
  margin-top: 0.3rem;
  font-size: 0.59rem;
  line-height: 1.4;
}
.wallet-bank-empty__halo {
  display: none;
}
.wallet-banks {
  gap: 0;
}
.wallet-banks li {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 0.62rem;
  align-items: center;
  padding: 0.5rem 0 0.58rem;
  border-bottom: 1px solid rgba(136, 163, 174, 0.12);
}
.wallet-bank-card__meta {
  grid-column: 1 / -1;
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem 0.8rem;
  padding: 0.52rem 0 0.05rem;
  color: #819099;
  font-size: 0.53rem;
}
.wallet-bank-card__meta span {
  display: inline-flex;
  align-items: center;
  gap: 0.28rem;
}
.wallet-bank-card__meta svg {
  width: 0.68rem;
  height: 0.68rem;
  color: #30d9a6;
}
.wallet-bank-connect {
  margin-top: 0.58rem;
  padding-top: 0;
}
.wallet-bank-connect > button {
  min-height: 2.05rem;
  padding-inline: 0.72rem;
  font-size: 0.59rem;
}
.wallet-bank-connect__note {
  margin-top: 0.42rem;
  color: #85939c;
  font-size: 0.53rem;
  line-height: 1.35;
}
.wallet-bank-reassurance {
  flex-wrap: wrap;
  gap: 0.45rem 0.72rem;
  margin-top: 0.58rem;
  padding-top: 0.48rem;
}
.wallet-bank-reassurance span {
  font-size: 0.48rem;
}
.wallet-move-tabs {
  margin-bottom: 0.62rem;
}
.wallet-move-tabs button {
  min-height: 1.85rem;
  font-size: 0.58rem;
}
.wallet-funding-selector {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 0.48rem;
  align-items: center;
  min-height: 2.1rem;
  padding: 0.38rem 0.52rem;
  border: 1px solid rgba(139, 166, 177, 0.14);
  border-radius: 0.38rem;
  background: rgba(7, 12, 16, 0.46);
}
.wallet-funding-selector__label {
  color: #84939b;
  font-size: 0.5rem;
  font-weight: 720;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}
.wallet-funding-selector__value {
  display: inline-flex;
  min-width: 0;
  align-items: center;
  gap: 0.35rem;
  overflow: hidden;
  color: #dfe8eb;
  font-size: 0.6rem;
  font-weight: 650;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.wallet-funding-selector__value svg {
  width: 0.78rem;
  height: 0.78rem;
  flex: 0 0 auto;
  color: #31d9a7;
}
.wallet-funding-selector > svg {
  width: 0.68rem;
  height: 0.68rem;
  color: #8898a0;
  transform: rotate(90deg);
}
.wallet-funding-selector:not(.is-ready) {
  border-style: dashed;
}
.wallet-move-form {
  gap: 0.46rem;
  margin-top: 0;
}
.wallet-move-form label {
  gap: 0.28rem;
  font-size: 0.55rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}
.wallet-move-form input {
  min-height: 2.35rem;
  margin-top: 0.1rem;
  padding-inline: 0.62rem;
  border-color: rgba(139, 166, 177, 0.16);
  background: rgba(7, 12, 16, 0.64);
  font-size: 0.72rem;
  font-variant-numeric: tabular-nums;
}
.wallet-move-form > p {
  min-height: 0;
  padding: 0.12rem 0;
  border: 0;
  background: transparent;
  font-size: 0.55rem;
  line-height: 1.35;
}
.wallet-move-form > button,
.wallet-verify-button {
  min-height: 2.15rem;
  border-radius: 0.38rem;
  font-size: 0.59rem;
}
.wallet-move-note,
.wallet-move-success {
  margin-top: 0.42rem;
  font-size: 0.53rem;
}
.wallet-provider-status {
  gap: 0;
}
.wallet-provider-status > div {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  min-height: 2.7rem;
  align-items: center;
  padding: 0.34rem 0;
  border: 0;
  border-top: 1px solid rgba(136, 163, 174, 0.1);
  border-radius: 0;
  background: transparent;
}
.wallet-provider-status > div:first-child {
  border-top: 0;
}
.wallet-provider-status dt {
  min-width: 0;
  gap: 0.42rem;
}
.wallet-provider-status dt > span:first-child {
  width: 1.42rem;
  height: 1.42rem;
  flex: 0 0 auto;
  border-radius: 0.34rem;
  background: rgba(121, 145, 158, 0.08);
}
.wallet-provider-status dt strong {
  font-size: 0.58rem;
}
.wallet-provider-status dt small {
  max-width: 18rem;
  margin-top: 0.1rem;
  font-size: 0.49rem;
}
.wallet-provider-status dd {
  flex: 0 0 auto;
}
.wallet-status {
  min-height: 1.1rem;
  padding: 0.08rem 0.36rem;
  font-size: 0.49rem;
}
.wallet-verify-button {
  margin-top: 0.48rem;
}
.wallet-movement-filters {
  margin-bottom: 0.42rem;
}
.wallet-movement-filters button {
  min-height: 1.45rem;
  font-size: 0.51rem;
}
.wallet-panel--movements .wallet-panel__body {
  padding-bottom: 0.7rem;
}
.wallet-table-wrap {
  border: 0;
  border-radius: 0;
}
.wallet-table th {
  height: 1.8rem;
  padding: 0 0.45rem;
  color: #7e8d96;
  font-size: 0.48rem;
  letter-spacing: 0.08em;
}
.wallet-table td {
  height: 2.25rem;
  padding: 0.34rem 0.45rem;
  border-top-color: rgba(136, 163, 174, 0.1);
  font-size: 0.56rem;
}
.wallet-movements-empty,
.wallet-empty {
  min-height: 7.5rem;
}
.wallet-empty {
  border: 0;
  border-radius: 0.45rem;
  background: rgba(7, 12, 16, 0.3);
}
.wallet-empty > svg {
  width: 1.15rem;
  height: 1.15rem;
}
.wallet-empty strong {
  font-size: 0.64rem;
}
.wallet-empty p {
  margin-top: 0.16rem;
  font-size: 0.54rem;
}
.wallet-panel--timeline {
  min-height: 9.7rem;
}
.wallet-timeline {
  gap: 0;
  padding: 0.72rem 0.12rem 0.22rem;
}
.wallet-timeline__step {
  padding-top: 2.05rem;
}
.wallet-timeline__step::before {
  top: 0.72rem;
  background: linear-gradient(90deg, rgba(43, 216, 169, 0.72), rgba(111, 137, 145, 0.24));
}
.wallet-timeline__step > span {
  width: 1.25rem;
  height: 1.25rem;
  border-color: rgba(137, 163, 172, 0.4);
  font-size: 0.48rem;
}
.wallet-timeline__step.is-complete > span,
.wallet-timeline__step.is-active > span {
  border-color: #2bd9a7;
  background: rgba(26, 197, 151, 0.14);
  box-shadow: 0 0 12px rgba(33, 218, 164, 0.24);
}
.wallet-timeline__step strong {
  font-size: 0.58rem;
}
.wallet-timeline__step small {
  margin-top: 0.2rem;
  font-size: 0.51rem;
}
.wallet-panel--insights {
  min-height: 9.1rem;
}
.wallet-insight-summary {
  min-height: 4.5rem;
  border: 1px solid rgba(136, 163, 174, 0.11);
  border-radius: 0.42rem;
}
.wallet-insight-summary dt,
.wallet-insight-summary small {
  font-size: 0.5rem;
}
.wallet-insight-summary dd {
  margin-top: 0.24rem;
  font-size: 0.75rem;
}
.wallet-panel--insights .wallet-empty {
