  .wallet-row--primary {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .wallet-panel--status {
    grid-column: 1 / -1;
  }
  .wallet-row--history {
    grid-template-columns: minmax(0, 1.45fr) minmax(18rem, 0.85fr);
  }
