@media (max-width: 899px) {
  .wallet-row--primary,
  .wallet-row--history {
    grid-template-columns: 1fr;
  }
  .wallet-panel--status {
    grid-column: auto;
  }
  .wallet-side-stack {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 599px) {
  .wallet-page .wallet-shell {
    width: calc(100% - 1.25rem);
    padding-top: 1.25rem;
  }
  .wallet-heading h1 {
    font-size: clamp(2.18rem, 11vw, 2.85rem);
  }
  .wallet-kpis {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.5rem;
  }
  .wallet-kpi {
    min-height: 5.4rem;
    gap: 0.48rem;
    padding: 0.68rem;
  }
  .wallet-kpi--featured {
    grid-column: 1 / -1;
  }
  .wallet-kpi strong {
    font-size: 1.05rem;
  }
  .wallet-panel__head,
  .wallet-panel__body {
    padding-inline: 0.78rem;
  }
  .wallet-bank-card__meta {
    font-size: 0.49rem;
  }
  .wallet-timeline {
    padding-inline: 0.05rem;
  }
