  text-align: left;
}
.admin-review-workspace-media > img,
.admin-review-workspace-media > span {
  display: grid;
  width: 100%;
  height: 7.2rem;
  place-items: center;
  overflow: hidden;
  border: 1px solid #2a4853;
  border-radius: 0.35rem;
  background: #08151c;
  color: #40d9b5;
}
.admin-review-workspace-media > img {
