/* Authoritative review-queue workspace. The compact table mirrors the staff
 * workflow: metrics, filters, then the actionable records. */
.admin-review-queue {
  gap: 1.1rem;
}
.admin-review-queue-heading {
  align-items: end;
}
.admin-review-queue-heading h2 {
  margin-top: 0.35rem;
  font-size: clamp(1.65rem, 2.4vw, 2.2rem);
}
.admin-review-refresh,
.admin-review-clear-filters,
.admin-review-more-filters {
  display: inline-flex;
  align-items: center;
