.collector-detail-current p {
  grid-column: 1 / 3;
  margin: 0;
  color: #a9bbc1;
  font-size: 0.68rem;
  line-height: 1.45;
}
.collector-detail-current .collector-button {
  grid-column: 3;
  grid-row: 1 / 3;
}
.collector-detail-current--action_required {
  border-color: rgba(214, 167, 73, 0.35);
  background: rgba(120, 84, 21, 0.1);
}
.collector-detail-current--action_required > span {
  color: #efc55c;
}
.collector-detail-glance__grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.6rem;
}
.collector-detail-glance__grid > .collector-detail-value {
  padding: 0.65rem;
  border: 1px solid #20343d;
  border-radius: 0.45rem;
  background: rgba(5, 13, 18, 0.55);
}
.collector-detail-glance__grid .collector-detail-value strong {
  font-size: 0.78rem;
}
.collector-detail-next strong {
  color: #38dfb5;
  font-size: 0.8rem;
  text-transform: uppercase;
}
.collector-detail-next p {
  margin: 0.35rem 0 0.7rem;
  color: #a8bbc2;
  font-size: 0.7rem;
  line-height: 1.5;
}
.collector-detail-next .collector-button {
  justify-self: start;
}
.collector-detail-tab-stack {
  display: grid;
  gap: 0.8rem;
}
.collector-detail-tab-stack > .collector-detail-panel {
  min-height: 0;
  padding: 0.9rem;
}
.collector-detail-rail {
  display: grid;
  align-content: start;
  gap: 0.8rem;
}
.collector-detail-rail-card {
  display: grid;
  gap: 0.55rem;
  min-width: 0;
}
.collector-detail-rail-row {
  display: flex;
  justify-content: space-between;
  gap: 0.7rem;
  padding: 0.6rem 0.65rem;
  border: 1px solid #20343d;
  border-radius: 0.42rem;
  background: rgba(6, 15, 20, 0.55);
}
.collector-detail-rail-row span {
  color: #9aadb6;
  font-size: 0.65rem;
}
.collector-detail-rail-row strong {
  color: #edf6f4;
  font-size: 0.68rem;
  text-align: right;
}
.collector-detail-rail-card > .collector-button {
  width: 100%;
  justify-content: center;
}
.collector-detail-milestone__label,
.collector-detail-related-action strong,
.collector-detail-no-action strong {
  color: #35deb5;
  font-size: 0.78rem;
}
.collector-detail-rail-card p {
  margin: 0;
  color: #9db1ba;
  font-size: 0.68rem;
  line-height: 1.5;
}
.collector-detail-related-action {
  display: grid;
  gap: 0.35rem;
  padding: 0.7rem;
  border: 1px solid #20343d;
  border-radius: 0.45rem;
}
.collector-detail-related-action .collector-button {
  width: auto;
  justify-self: start;
}
.collector-detail-no-action {
  display: grid;
  gap: 0.35rem;
  padding: 0.3rem 0;
}
@media (max-width: 1120px) {
  .collector-detail-layout {
    grid-template-columns: minmax(0, 1fr);
  }
  .collector-detail-rail {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .collector-detail-rail-card:last-child {
    grid-column: 1 / -1;
  }
}
@media (max-width: 760px) {
  .collector-detail-heading {
    flex-direction: column;
  }
  .collector-detail-heading__actions {
    width: 100%;
  }
  .collector-detail-heading__actions .collector-button:first-child {
    flex: 1;
    justify-content: center;
  }
  .collector-detail-summary-card {
    grid-template-columns: 5.4rem minmax(0, 1fr);
  }
  .collector-detail-summary-card__image {
    width: 5.4rem;
    height: 7.2rem;
  }
  .collector-detail-identity-grid {
    grid-column: 1 / -1;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .collector-detail-journey ol {
    grid-template-columns: 1fr;
    gap: 0.55rem;
  }
  .collector-detail-journey li {
    grid-template-columns: 1.5rem minmax(0, 1fr) auto;
    justify-items: start;
    text-align: left;
  }
  .collector-detail-journey li:not(:last-child)::after {
    top: 1.55rem;
    left: 0.72rem;
    width: 1px;
    height: 0.55rem;
  }
  .collector-detail-journey li strong {
    max-width: none;
  }
  .collector-detail-current {
    grid-template-columns: minmax(0, 1fr);
  }
  .collector-detail-current p,
  .collector-detail-current .collector-button {
    grid-column: 1;
  }
  .collector-detail-current .collector-button {
    grid-row: auto;
    justify-self: start;
  }
  .collector-detail-glance__grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .collector-detail-rail {
    grid-template-columns: 1fr;
  }
  .collector-detail-rail-card:last-child {
    grid-column: auto;
  }
}
@media (max-width: 480px) {
  .collector-detail-summary-card {
    grid-template-columns: 4.5rem minmax(0, 1fr);
    gap: 0.7rem;
    padding: 0.7rem;
  }
  .collector-detail-summary-card__image {
    width: 4.5rem;
    height: 6.2rem;
  }
  .collector-detail-value strong {
    font-size: 1.05rem;
  }
  .collector-detail-identity-grid {
    gap: 0.55rem;
  }
  .collector-detail-glance__grid {
    grid-template-columns: 1fr;
  }
}

