  border-left: 1px solid #263741;
  padding-left: 1rem;
}
.admin-user-identity-card h3 {
  margin-bottom: 0.7rem;
  color: #94a9b5;
  font-size: 0.58rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}
.admin-user-identity-card p {
  overflow: hidden;
  margin: 0.45rem 0;
  color: #d8e5e3;
  font-size: 0.66rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.admin-user-detail-tabs {
  overflow-x: auto;
  flex-wrap: nowrap;
}
.admin-user-detail-tabs button {
  white-space: nowrap;
}
.admin-user-detail-main {
  display: grid;
  min-width: 0;
  grid-template-columns: minmax(0, 1fr) 17rem;
  gap: 1rem;
}
.admin-user-detail-main main {
  min-width: 0;
}
.admin-detail-overview-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1rem;
}
.admin-detail-lower-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1rem;
  margin-top: 1rem;
}
.admin-detail-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.7rem;
  border-bottom: 1px solid rgba(54, 72, 83, 0.55);
