}
.admin-detail-row span {
  min-width: 0;
  color: #a7b8c0;
  font-size: 0.64rem;
}
.admin-detail-row strong {
  min-width: 0;
  color: #eaf5f2;
  font-size: 0.68rem;
  text-align: right;
}
.admin-detail-row strong.is-positive {
  color: #42dfbd;
}
.admin-detail-row strong.is-warning {
  color: #eab653;
}
.admin-detail-row strong.is-info {
  color: #45bde9;
}
.admin-detail-link {
  display: flex;
  width: 100%;
  align-items: center;
  justify-content: center;
  gap: 0.35rem;
  margin-top: 0.8rem;
  border: 1px solid #2a424c;
  border-radius: 0.35rem;
  padding: 0.55rem;
  color: #42dfbd;
  font-size: 0.62rem;
}
.admin-detail-link svg {
  width: 0.75rem;
}
.admin-order-side {
  display: grid;
  width: 2.6rem;
  height: 1.6rem;
  flex: 0 0 auto;
  place-items: center;
  border-radius: 0.25rem;
  font-size: 0.54rem;
}
.admin-order-side--buy {
  background: rgba(36, 210, 169, 0.13);
  color: #42dfbd;
}
.admin-order-side--sell {
  background: rgba(234, 87, 79, 0.13);
  color: #ef746d;
}
.admin-detail-assets {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.5rem;
}
.admin-detail-asset {
  display: grid;
  min-width: 0;
  gap: 0.25rem;
}
.admin-detail-asset > span {
  display: grid;
  min-height: 4rem;
  place-items: center;
  border: 1px solid #2c424c;
  border-radius: 0.35rem;
  background: #09151c;
  color: #41dcb7;
  font-size: 0.7rem;
  font-weight: 700;
}
.admin-detail-asset strong,
.admin-detail-asset small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.admin-detail-asset strong {
  color: #dceae7;
  font-size: 0.58rem;
}
.admin-detail-asset small {
  color: #8fa3ae;
  font-size: 0.54rem;
}
.admin-detail-asset--more {
  place-items: center;
}
.admin-detail-role-list {
  display: grid;
  gap: 0.5rem;
}
.admin-detail-role-list > div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.7rem;
  border-bottom: 1px solid #263741;
  padding: 0.65rem 0;
}
.admin-detail-role-list small {
  color: #8fa3ae;
  font-size: 0.58rem;
}
.admin-user-detail-rail {
  display: grid;
  align-content: start;
  gap: 1rem;
  min-width: 0;
}
.admin-detail-action {
  display: flex;
  width: 100%;
  align-items: center;
  gap: 0.5rem;
  margin-top: 0.45rem;
  border: 1px solid #2a424c;
  border-radius: 0.35rem;
  padding: 0.6rem;
  color: #d9e8e5;
  font-size: 0.62rem;
  text-align: left;
}
.admin-detail-action:hover {
  border-color: #1ed2aa;
  color: #42dfbd;
}
.admin-detail-action:disabled {
  cursor: not-allowed;
  opacity: 0.45;
}
.admin-detail-action svg {
  width: 0.85rem;
}
.admin-activity-row {
  display: grid;
  grid-template-columns: 1rem minmax(0, 1fr) auto;
  gap: 0.45rem;
  align-items: center;
  border-bottom: 1px solid #263741;
  padding: 0.65rem 0;
}
.admin-activity-row svg {
  width: 0.8rem;
  color: #42dfbd;
}
.admin-activity-row span {
  min-width: 0;
  overflow: hidden;
  color: #dce9e7;
  font-size: 0.62rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.admin-activity-row small {
  color: #8fa3ae;
  font-size: 0.55rem;
  white-space: nowrap;
}
.admin-record-list {
  display: grid;
  gap: 0.35rem;
}
.admin-record {
  display: grid;
  grid-template-columns: 2.6rem minmax(0, 1fr) auto 0.8rem;
  gap: 0.75rem;
  align-items: center;
  border-bottom: 1px solid #263741;
  padding: 0.7rem 0;
}
.admin-record:last-child {
  border-bottom: 0;
}
.admin-record-icon {
  display: grid;
  width: 2.6rem;
  height: 3.2rem;
  place-items: center;
  border: 1px solid #2d4650;
  border-radius: 0.42rem;
  background: #071217;
  color: #41dcb7;
}
.admin-record-icon svg {
  width: 1rem;
  height: 1rem;
}
.admin-record strong,
.admin-record small {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.admin-record strong {
  color: #eef7f4;
  font-size: 0.72rem;
}
.admin-record small {
  margin-top: 0.2rem;
  color: #8ea1ad;
  font-size: 0.59rem;
}
.admin-record-status {
  border: 1px solid #31505a;
  border-radius: 999px;
  padding: 0.3rem 0.45rem;
  color: #52dfbe;
  font-size: 0.55rem;
  white-space: nowrap;
}
.admin-record > svg {
  width: 0.8rem;
  color: #8096a3;
}
.admin-record-actions {
  display: flex;
  min-width: 0;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 0.45rem;
}
.admin-empty {
  display: grid;
  min-height: 7rem;
  place-items: center;
  align-content: center;
  gap: 0.5rem;
  padding: 1.2rem;
  text-align: center;
}
.admin-empty svg {
  width: 1.35rem;
  height: 1.35rem;
  color: #4bd8b8;
}
.admin-empty p {
  max-width: 28rem;
  color: #8ea2ae;
  font-size: 0.68rem;
  line-height: 1.5;
}
.admin-integration-grid,
.admin-settings-links {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.7rem;
}
.admin-integration {
  display: grid;
  min-width: 0;
  gap: 0.45rem;
  border: 1px solid #2b3d47;
  border-radius: 0.45rem;
  padding: 0.8rem;
}
.admin-integration svg {
  width: 1rem;
  color: #41dcb7;
}
.admin-integration strong {
  color: #edf6f3;
  font-size: 0.7rem;
}
.admin-integration span {
  color: #8ea1ad;
  font-size: 0.6rem;
}
.admin-settings-links button {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  border: 1px solid #2b3d47;
  border-radius: 0.45rem;
  padding: 0.8rem;
  color: #d8e7e5;
  font-size: 0.68rem;
  text-align: left;
}
.admin-settings-links button svg:first-child {
  width: 0.95rem;
  color: #42dcb8;
}
.admin-settings-links button svg:last-child {
  width: 0.75rem;
  margin-left: auto;
  color: #8097a4;
}
.admin-console-state {
  display: grid;
  min-height: 70vh;
  place-content: center;
  justify-items: center;
  gap: 0.7rem;
  padding: 2rem;
  text-align: center;
}
.admin-console-state > svg {
  width: 2rem;
  height: 2rem;
  color: #42dcb8;
}
.admin-console-state h1 {
  color: #f1f8f5;
  font-family: var(--font-display);
  font-size: 1.35rem;
}
.admin-console-state p {
  max-width: 28rem;
  color: #91a4b0;
  font-size: 0.75rem;
  line-height: 1.5;
}
.admin-console-state button {
  border-radius: 0.4rem;
  padding: 0.55rem 0.8rem;
  background: #20cfa8;
  color: #06130f;
  font-size: 0.68rem;
  font-weight: 750;
}
@media (max-width: 1200px) {
  .admin-kpi-grid--six {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .admin-pipeline--full {
    grid-template-columns: repeat(5, minmax(0, 1fr));
  }
  .admin-dashboard-grid--four {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 920px) {
  .admin-console-shell {
    display: block;
  }
  .admin-console-sidebar {
    position: fixed;
    z-index: 80;
    width: min(18rem, calc(100vw - 2rem));
    transform: translateX(-105%);
    transition: transform 180ms ease;
  }
  .admin-console-sidebar.is-open {
    transform: translateX(0);
  }
  .admin-console-close {
    display: grid;
    place-items: center;
    color: #dce9e7;
  }
  .admin-console-close svg,
  .admin-console-menu svg {
    width: 1.1rem;
    height: 1.1rem;
  }
  .admin-console-scrim {
    position: fixed;
    z-index: 70;
    inset: 0;
    background: rgba(0, 0, 0, 0.62);
  }
  .admin-console-topbar {
    grid-template-columns: auto minmax(0, 1fr);
    padding: 0 1rem;
  }
  .admin-console-menu {
    display: grid;
    place-items: center;
    color: #dce9e7;
  }
  .admin-console-search {
    display: none;
  }
  .admin-console-content {
    padding: 1.3rem 1rem 2rem;
  }
  .admin-kpi-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .admin-dashboard-grid {
    grid-template-columns: 1fr;
  }
  .admin-dashboard-grid--four {
    grid-template-columns: 1fr;
  }
  .admin-accounts-layout {
    grid-template-columns: 1fr;
  }
  .admin-accounts-rail {
    display: none;
  }
  .admin-accounts-rail.is-open {
    display: grid;
  }
  .admin-user-identity-card {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .admin-user-identity-card > div:not(:first-child) {
    border-left: 0;
    padding-left: 0;
  }
  .admin-user-detail-main {
    grid-template-columns: 1fr;
  }
  .admin-user-detail-rail {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .admin-detail-overview-grid,
  .admin-detail-lower-grid {
    grid-template-columns: 1fr;
  }
  .admin-integration-grid,
  .admin-settings-links {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 520px) {
  .admin-console-heading {
    display: grid;
  }
  .admin-live-badge {
    width: fit-content;
  }
  .admin-kpi-grid {
    gap: 0.5rem;
  }
  .admin-kpi {
    padding: 0.65rem;
  }
  .admin-pipeline {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .admin-pipeline > div,
  .admin-pipeline > button {
    border-left: 0;
    border-top: 1px solid #2c3c46;
    padding: 0.55rem 0.35rem;
  }
  .admin-record {
    grid-template-columns: 2.5rem minmax(0, 1fr) 0.8rem;
  }
  .admin-record-status {
    display: none;
  }
  .admin-user-detail-heading {
    display: grid;
    align-items: start;
  }
  .admin-user-detail-actions {
    justify-content: flex-start;
  }
  .admin-user-identity-card {
    grid-template-columns: 1fr;
  }
  .admin-user-detail-rail {
    grid-template-columns: 1fr;
  }
  .admin-integration-grid,
  .admin-settings-links,
  .admin-quick-actions {
    grid-template-columns: 1fr;
  }
}

