.admin-status-pill--restricted,
.admin-status-pill--suspended {
  border-color: rgba(239, 177, 71, 0.5);
  color: #f2be5e;
}
.admin-inline-action {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  color: #45dcba;
  font-size: 0.6rem;
  white-space: nowrap;
}
.admin-inline-action svg {
  width: 0.75rem;
  height: 0.75rem;
}
.admin-pagination {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  color: #8ea2ae;
  font-size: 0.62rem;
}
.admin-pagination button {
  display: inline-flex;
  align-items: center;
  gap: 0.2rem;
  color: #45dcba;
  font-size: 0.62rem;
}
.admin-pagination button:disabled {
  color: #556b76;
  cursor: not-allowed;
}
.admin-back-link {
  display: inline-flex;
  width: fit-content;
  align-items: center;
  gap: 0.3rem;
  color: #45dcba;
  font-size: 0.65rem;
}
.admin-back-link svg {
  width: 0.8rem;
}
.admin-user-hero {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 0.9rem;
  border: 1px solid #263741;
  border-radius: 0.55rem;
  padding: 1rem;
  background: linear-gradient(145deg, rgba(16, 27, 35, 0.97), rgba(8, 15, 21, 0.97));
}
.admin-user-hero > div {
  min-width: 0;
  flex: 1;
}
.admin-user-hero h2 {
  margin-top: 0.25rem;
  color: #f4f8f7;
  font-family: var(--font-display);
  font-size: 1.35rem;
}
.admin-user-hero > div > span {
  display: block;
  overflow: hidden;
  color: #91a5b1;
  font-size: 0.67rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.admin-user-avatar {
  display: grid;
  width: 3rem;
  height: 3rem;
  flex: 0 0 auto;
  place-items: center;
  border-radius: 50%;
  background: #1b7e6c;
  color: #06130f;
}
.admin-user-avatar svg {
  width: 1.25rem;
}
.admin-tabs {
  display: flex;
  min-width: 0;
  gap: 0.25rem;
  overflow-x: auto;
  border-bottom: 1px solid #263741;
}
.admin-tabs button {
  flex: 0 0 auto;
  border-bottom: 2px solid transparent;
  padding: 0.6rem 0.5rem;
  color: #8197a4;
  font-size: 0.62rem;
}
.admin-tabs button.is-active {
  border-bottom-color: #42dcb8;
  color: #e7f4f0;
}
.admin-kpi-grid--compact .admin-kpi {
  min-height: 5.2rem;
}
.admin-record--case {
  grid-template-columns: 2.6rem minmax(0, 1fr) auto auto;
}
.admin-console-topbar {
  position: relative;
}
.admin-search-results {
  position: absolute;
  z-index: 5;
  top: calc(100% - 0.4rem);
  right: 2rem;
  width: min(22rem, calc(100% - 4rem));
  border: 1px solid #2a3b45;
  border-radius: 0.45rem;
  background: #0a131a;
  box-shadow: 0 12px 28px rgba(0, 0, 0, 0.35);
}
.admin-search-results a {
  display: grid;
  gap: 0.15rem;
  padding: 0.65rem 0.75rem;
  border-bottom: 1px solid #263741;
}
.admin-search-results a:last-child {
  border-bottom: 0;
}
.admin-search-results small {
  color: #45dcba;
  font-size: 0.52rem;
  text-transform: uppercase;
}
.admin-search-results strong {
  overflow: hidden;
  color: #eff7f5;
  font-size: 0.65rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.admin-search-results span {
  overflow: hidden;
  color: #8ea2ae;
  font-size: 0.58rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.admin-integration small {
  color: #8ea2ae;
  font-size: 0.57rem;
}

/* Control Center overview: keep each workstream compact, aligned, and scannable. */
.admin-console-heading--overview {
  padding: 0.35rem 0.15rem 0.15rem;
}
.admin-overview-heading-meta {
  display: grid;
  justify-items: end;
  gap: 0.45rem;
}
.admin-overview-heading-meta small {
  color: #718793;
  font-size: 0.56rem;
}
.admin-dashboard-grid {
  align-items: start;
}
.admin-panel {
  height: fit-content;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.11);
}
.admin-panel--attention,
.admin-panel--activity {
  background: linear-gradient(145deg, rgba(15, 29, 38, 0.98), rgba(7, 16, 23, 0.98));
}
.admin-panel--status,
.admin-panel--cases {
  background: linear-gradient(145deg, rgba(12, 25, 33, 0.98), rgba(7, 16, 23, 0.98));
}
.admin-panel--attention .admin-panel-heading,
.admin-panel--status .admin-panel-heading,
.admin-panel--activity .admin-panel-heading,
.admin-panel--cases .admin-panel-heading,
.admin-panel--insight .admin-panel-heading {
  padding-bottom: 0.65rem;
  border-bottom: 1px solid rgba(49, 72, 83, 0.75);
}
.admin-panel--pipeline {
  padding: 1rem 1.15rem 1.1rem;
  background: linear-gradient(105deg, rgba(14, 30, 38, 0.98), rgba(8, 18, 25, 0.98));
}
.admin-panel--pipeline .admin-panel-heading {
  margin-bottom: 0.9rem;
}
.admin-panel--pipeline .admin-pipeline > button,
.admin-panel--pipeline .admin-pipeline > div {
  min-height: 4.8rem;
  padding-inline: 0.8rem;
}
.admin-panel--cases .admin-empty {
  min-height: 7.5rem;
  align-content: center;
}
.admin-panel--activity .admin-record-list {
  gap: 0;
}
.admin-panel--activity .admin-record {
  padding-block: 0.7rem;
}
.admin-panel--insight {
  min-height: 12rem;
}
@media (max-width: 920px) {
  .admin-overview-heading-meta {
    justify-items: start;
  }
}
@media (max-width: 620px) {
  .admin-overview-heading-meta {
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: space-between;
  }
  .admin-panel--pipeline {
    padding-inline: 0.8rem;
  }
}
@media (max-width: 920px) {
  .admin-user-hero {
    align-items: flex-start;
    flex-wrap: wrap;
  }
  .admin-user-hero > .admin-status-pill {
    margin-left: 3.9rem;
  }
  .admin-search-results {
    right: 1rem;
    width: calc(100% - 2rem);
  }
}
@media (max-width: 620px) {
  .admin-table-wrap {
    border: 0;
    overflow: visible;
  }
  .admin-table {
    min-width: 0;
  }
  .admin-table thead {
    display: none;
  }
  .admin-table,
  .admin-table tbody,
  .admin-table tr,
  .admin-table td {
    display: block;
    width: 100%;
  }
  .admin-table tr {
    border: 1px solid #263741;
    border-radius: 0.55rem;
    margin-bottom: 0.5rem;
    padding: 0.35rem 0;
  }
  .admin-table td {
    display: flex;
    justify-content: space-between;
    gap: 0.7rem;
    border: 0;
    padding: 0.35rem 0.65rem;
  }
  .admin-table td::before {
    color: #7f96a4;
    content: attr(data-label);
    font-size: 0.54rem;
    text-transform: uppercase;
  }
  .admin-record--case {
    grid-template-columns: 2.6rem minmax(0, 1fr) auto;
  }
  .admin-record--case .admin-inline-action {
    grid-column: 2 / -1;
    justify-self: start;
  }
  .admin-user-hero > .admin-status-pill {
    margin-left: 0;
  }
}

/* Admin console foundation: compact hierarchy, readable actions, and predictable responsive sizing. */
.admin-console-nav {
  gap: 0.8rem;
}
.admin-console-nav-group {
  display: grid;
  gap: 0.22rem;
}
.admin-console-nav-label {
  padding: 0.15rem 0.62rem 0.25rem;
  color: #6f8794;
  font-size: 0.53rem;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}
.admin-console-nav button {
  padding: 0.66rem 0.62rem;
  font-size: 0.72rem;
}
.admin-console-heading--overview {
  align-items: center;
}
.admin-kpi-grid--overview {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}
.admin-kpi--warning > span {
  background: rgba(239, 187, 86, 0.14);
  color: #f1bb55;
}
.admin-kpi--positive > span {
  background: rgba(55, 220, 180, 0.14);
  color: #47dfbd;
}
.admin-kpi em {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.admin-quick-actions-bar {
  display: flex;
  min-width: 0;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.45rem;
  border: 1px solid #263741;
  border-radius: 0.55rem;
  padding: 0.6rem 0.75rem;
  background: rgba(13, 24, 31, 0.8);
}
.admin-quick-actions-bar > span {
  margin-right: auto;
  color: #8ea1ad;
  font-size: 0.62rem;
  font-weight: 700;
}
.admin-quick-actions-bar button {
  display: inline-flex;
  min-width: 0;
  align-items: center;
  gap: 0.35rem;
  border: 1px solid #2d4650;
  border-radius: 0.4rem;
  padding: 0.45rem 0.58rem;
  color: #d8e7e5;
  font-size: 0.6rem;
}
.admin-quick-actions-bar button:hover {
  border-color: #39dcb5;
  color: #5ee7c6;
  background: rgba(29, 208, 169, 0.08);
}
.admin-quick-actions-bar svg {
  width: 0.78rem;
  height: 0.78rem;
  color: #43dcb8;
}
.admin-quick-actions-bar svg:last-child {
  width: 0.68rem;
  margin-left: 0.1rem;
}
.admin-attention {
  grid-template-columns: 1rem minmax(0, 1fr) auto;
}
.admin-attention .admin-inline-action {
  display: inline-flex;
  min-width: max-content;
  align-items: center;
  gap: 0.2rem;
  border: 1px solid #31505a;
  border-radius: 999px;
  padding: 0.3rem 0.45rem;
  color: #4adfbd;
  font-size: 0.55rem;
}
.admin-attention .admin-inline-action:hover {
  border-color: #49dfbd;
  background: rgba(29, 208, 169, 0.08);
}
.admin-attention .admin-inline-action svg {
  width: 0.65rem;
  height: 0.65rem;
}
.admin-status-badge {
  border: 1px solid transparent;
  border-radius: 999px;
  padding: 0.28rem 0.42rem;
  font-size: 0.55rem;
  font-weight: 700;
  white-space: nowrap;
}
.admin-status-badge--positive {
  border-color: rgba(55, 220, 180, 0.4);
  color: #51dfc0;
}
.admin-status-badge--warning {
  border-color: rgba(239, 187, 86, 0.45);
  color: #f1bd5b;
}
.admin-status-badge--muted {
  border-color: #36505b;
  color: #9aadb7;
}
.admin-pipeline > button,
.admin-pipeline > div {
  min-height: 4.4rem;
}
.admin-dashboard-grid--two {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
@media (max-width: 1200px) {
  .admin-kpi-grid--overview {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 920px) {
  .admin-dashboard-grid--two {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 620px) {
  .admin-console-nav-label {
    padding-left: 0.45rem;
  }
  .admin-console-heading--overview {
    align-items: start;
  }
  .admin-quick-actions-bar {
    align-items: stretch;
  }
  .admin-quick-actions-bar > span {
    width: 100%;
  }
  .admin-quick-actions-bar button {
    flex: 1 1 calc(50% - 0.45rem);
    justify-content: center;
  }
  .admin-attention {
    grid-template-columns: 1rem minmax(0, 1fr);
    align-items: start;
  }
  .admin-attention .admin-inline-action {
    grid-column: 2;
    justify-self: start;
    margin-top: 0.2rem;
  }
}

/* Admin control center: operational density without turning the page into a card wall. */
.admin-control-center {
  max-width: 1520px;
  margin: 0 auto;
  gap: 0.8rem;
}
.admin-control-summary-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.65rem;
}
.admin-control-summary {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 0.7rem;
  align-items: center;
  min-width: 0;
  padding: 0.8rem;
  border: 1px solid #263741;
  border-radius: 0.55rem;
  background: linear-gradient(145deg, rgba(16, 27, 35, 0.98), rgba(8, 15, 21, 0.98));
  color: #edf7f4;
  text-align: left;
}
.admin-control-summary:hover {
  border-color: rgba(64, 220, 182, 0.55);
  background: rgba(18, 41, 45, 0.94);
}
.admin-control-summary-icon {
  display: grid;
  width: 2.1rem;
  height: 2.1rem;
  place-items: center;
  border-radius: 0.45rem;
  background: rgba(64, 220, 182, 0.12);
  color: #45dfbd;
}
.admin-control-summary-icon svg {
  width: 1rem;
  height: 1rem;
}
.admin-control-summary-copy {
  display: grid;
  min-width: 0;
  gap: 0.12rem;
}
.admin-control-summary-copy small {
  color: #9cafb7;
  font-size: 0.58rem;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}
.admin-control-summary-copy strong {
  font-size: 1.3rem;
  line-height: 1;
}
.admin-control-summary-copy em {
  overflow: hidden;
  color: #8ca0aa;
  font-size: 0.59rem;
  font-style: normal;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.admin-control-summary > svg {
  width: 0.85rem;
  color: #4adfbd;
}
.admin-control-summary--critical .admin-control-summary-icon {
  background: rgba(239, 137, 133, 0.12);
  color: #ef8985;
}
.admin-control-summary--warning .admin-control-summary-icon {
  background: rgba(239, 187, 86, 0.14);
  color: #f1bb55;
}
.admin-control-summary--limited .admin-control-summary-icon {
  background: rgba(140, 160, 170, 0.13);
  color: #a5b6bc;
}
.admin-control-workspace-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.65fr) minmax(18rem, 0.85fr);
  gap: 0.8rem;
}
.admin-control-queue,
.admin-control-health,
.admin-finance-band,
.admin-pipeline-panel {
  padding: 0.8rem;
}
.admin-priority-list {
  display: grid;
  min-width: 0;
}
.admin-priority-row {
  display: grid;
  grid-template-columns:
    0.45rem minmax(5.8rem, 0.7fr) minmax(0, 2fr) 3.2rem minmax(5.2rem, 0.75fr)
    auto;
  gap: 0.55rem;
  align-items: center;
  min-width: 0;
  padding: 0.55rem 0;
  border-bottom: 1px solid rgba(54, 72, 83, 0.55);
}
.admin-priority-row:last-child {
  border-bottom: 0;
}
.admin-priority-severity {
  width: 0.42rem;
  height: 0.42rem;
  border-radius: 50%;
  background: #57dcb9;
}
.admin-priority-severity.is-high,
.admin-priority-severity.is-critical {
  background: #ef8985;
  box-shadow: 0 0 0.35rem rgba(239, 137, 133, 0.35);
}
.admin-priority-severity.is-medium,
.admin-priority-severity.is-warning {
  background: #f1bb55;
}
.admin-priority-type {
  overflow: hidden;
  color: #4adfbd;
  font-size: 0.52rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.admin-priority-main {
  display: grid;
  min-width: 0;
  gap: 0.15rem;
}
.admin-priority-main strong,
.admin-priority-main small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.admin-priority-main strong {
  color: #eaf4f2;
  font-size: 0.66rem;
}
.admin-priority-main small,
.admin-priority-age,
.admin-priority-owner {
  overflow: hidden;
  color: #8fa3ad;
  font-size: 0.58rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.admin-priority-row > button {
  border: 1px solid #31505a;
  border-radius: 0.3rem;
  padding: 0.3rem 0.45rem;
  color: #65dfc3;
  font-size: 0.56rem;
  white-space: nowrap;
}
.admin-priority-row > button:hover {
  border-color: #45dfbd;
  background: rgba(64, 220, 182, 0.08);
}
.admin-control-health .admin-status-row {
  padding: 0.48rem 0;
}
.admin-control-health-footer {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 0.2rem 0.5rem;
  margin-top: 0.5rem;
  padding-top: 0.6rem;
  border-top: 1px solid rgba(54, 72, 83, 0.55);
  color: #8fa3ad;
  font-size: 0.59rem;
}
.admin-control-health-footer strong {
  color: #f1bb55;
}
.admin-control-health-footer small {
  grid-column: 1 / -1;
  color: #6f8794;
  font-size: 0.53rem;
}
.admin-finance-band {
  padding-bottom: 0.7rem;
}
.admin-finance-grid {
  display: grid;
  grid-template-columns: repeat(8, minmax(0, 1fr));
}
.admin-finance-metric {
  min-width: 0;
  padding: 0.42rem 0.55rem;
  border-right: 1px solid rgba(54, 72, 83, 0.55);
}
.admin-finance-metric:last-child {
  border-right: 0;
}
.admin-finance-metric span,
.admin-finance-metric small {
  display: block;
  overflow: hidden;
  color: #91a5ae;
  font-size: 0.52rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.admin-finance-metric strong {
  display: block;
  margin: 0.25rem 0;
  overflow: hidden;
  color: #f1f7f4;
  font-size: 0.85rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.admin-finance-metric small {
  color: #6e8793;
}
.admin-finance-limited {
  margin: -0.15rem 0 0.35rem;
  color: #f1bb55;
  font-size: 0.61rem;
}
.admin-finance-warning {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  margin-top: 0.6rem;
  padding: 0.55rem 0.65rem;
  border: 1px solid rgba(239, 137, 133, 0.35);
  border-radius: 0.35rem;
  color: #efaaa5;
  font-size: 0.61rem;
}
.admin-finance-warning svg {
  width: 0.8rem;
  flex: 0 0 auto;
}
.admin-finance-warning button {
  display: inline-flex;
  align-items: center;
  gap: 0.2rem;
  margin-left: auto;
  color: #f3b5ad;
  font-size: 0.58rem;
  white-space: nowrap;
}
.admin-finance-warning button svg {
  width: 0.65rem;
}
.admin-pipeline-detailed {
  display: grid;
  grid-template-columns: repeat(10, minmax(0, 1fr));
  gap: 0.35rem;
}
.admin-pipeline-detailed button {
  display: grid;
  min-width: 0;
  gap: 0.25rem;
  padding: 0.55rem 0.5rem;
  border-left: 1px solid #2c3c46;
  color: #dceae7;
  text-align: left;
}
.admin-pipeline-detailed button:hover {
  background: rgba(29, 208, 169, 0.07);
}
.admin-pipeline-detailed button.is-bottleneck {
  background: rgba(239, 187, 86, 0.08);
}
.admin-pipeline-detailed span,
.admin-pipeline-detailed small,
.admin-pipeline-detailed em {
  overflow: hidden;
  color: #91a5ae;
  font-size: 0.55rem;
  font-style: normal;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.admin-pipeline-detailed strong {
  font-size: 1.05rem;
}
.admin-pipeline-detailed em {
  color: #f1bb55;
}
.admin-control-lower-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.45fr) minmax(18rem, 0.85fr);
  gap: 0.8rem;
}
.admin-control-activity-list,
.admin-control-cases {
  display: grid;
}
.admin-control-activity-list button,
.admin-control-cases button {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 0.55rem;
  align-items: center;
  padding: 0.5rem 0;
  border-bottom: 1px solid rgba(54, 72, 83, 0.55);
  color: #dceae7;
  text-align: left;
}
.admin-control-activity-list button:last-child,
.admin-control-cases button:last-child {
  border-bottom: 0;
}
.admin-control-activity-list button > svg {
  width: 0.85rem;
  color: #48dcb9;
}
.admin-control-activity-list span,
.admin-control-cases span {
  display: grid;
  min-width: 0;
  gap: 0.15rem;
}
.admin-control-activity-list strong,
.admin-control-cases strong {
  overflow: hidden;
  font-size: 0.65rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.admin-control-activity-list small,
.admin-control-cases em,
.admin-control-activity-list time,
.admin-control-cases small {
  overflow: hidden;
  color: #8fa3ad;
  font-size: 0.56rem;
  font-style: normal;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.admin-control-activity-list time {
  color: #6e8793;
}
.admin-control-cases small {
  color: #ef9b92;
  text-transform: uppercase;
}
.admin-control-cases svg {
  width: 0.75rem;
  color: #43dcb8;
