.list-panel header h2 {
  color: #f6f8fb;
  font-size: 0.92rem;
  font-weight: 650;
}
.list-panel header p {
  margin-top: 0.18rem;
  color: var(--color-subtle);
  font-size: 0.68rem;
}
.list-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.62rem;
  margin-top: 0.85rem;
}
.list-field {
  display: grid;
  gap: 0.28rem;
  position: relative;
  color: #dfe5ec;
  font-size: 0.7rem;
}
.list-field b {
  color: #ff7b87;
}
.list-field input,
.list-field select,
.list-field textarea {
  min-width: 0;
  border: 1px solid rgba(162, 178, 194, 0.24);
  border-radius: 0.38rem;
  background: rgba(6, 10, 15, 0.45);
  padding: 0.46rem 0.55rem;
  color: #f4f7fa;
  font-size: 0.75rem;
  outline: none;
}
.list-field textarea {
  resize: vertical;
}
.list-field input:focus,
.list-field select:focus,
.list-field textarea:focus {
  border-color: var(--color-accent);
  box-shadow: 0 0 0 2px rgba(34, 211, 165, 0.12);
}
.list-field small,
.list-inline-note {
  color: var(--color-muted);
  font-size: 0.63rem;
}
.list-span-full {
  grid-column: 1/-1;
}
.list-upload-unavailable {
  display: flex;
  gap: 0.72rem;
  align-items: center;
  min-height: 5.5rem;
  margin-top: 0.8rem;
  padding: 0.75rem;
  border: 1px dashed rgba(171, 186, 201, 0.25);
  border-radius: 0.5rem;
}
.list-upload-unavailable > span {
  display: grid;
  flex: 0 0 auto;
  width: 2.1rem;
  height: 2.1rem;
  place-items: center;
  border-radius: 0.5rem;
  background: rgba(8, 125, 103, 0.16);
  color: var(--color-accent);
}
.list-upload-unavailable svg {
  width: 1.1rem;
}
.list-upload-unavailable strong {
  color: #fff;
  font-size: 0.72rem;
}
.list-upload-unavailable p,
.list-media-policy {
  margin-top: 0.18rem;
  color: var(--color-subtle);
  font-size: 0.67rem;
  line-height: 1.45;
}
.list-media-policy {
  margin-top: 0.55rem;
}
.list-term {
  display: flex;
  gap: 0.55rem;
  padding: 0.75rem 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.065);
}
.list-term:last-child {
  border-bottom: 0;
}
.list-term svg {
  flex: 0 0 auto;
  width: 1rem;
  margin-top: 0.1rem;
  color: var(--color-accent);
}
.list-term strong {
  color: #f5f7fa;
  font-size: 0.73rem;
}
.list-term p {
  margin-top: 0.14rem;
  color: var(--color-subtle);
  font-size: 0.67rem;
  line-height: 1.45;
}
.list-status-note {
  margin: 0.7rem 0;
  color: var(--color-subtle);
  font-size: 0.72rem;
}
.list-resume-link {
  display: flex;
  gap: 0.3rem;
  align-items: center;
  color: var(--color-accent);
  font-size: 0.7rem;
}
.list-resume-link[disabled],
.list-resume-link.is-disabled {
  pointer-events: none;
  color: var(--color-muted);
}
.list-resume-link svg {
  width: 0.85rem;
}
.list-preview-image {
  display: grid;
  min-height: 12.9rem;
  place-items: center;
  gap: 0.35rem;
  margin-top: 0.8rem;
  border: 1px dashed rgba(171, 186, 201, 0.25);
  border-radius: 0.5rem;
  color: var(--color-subtle);
  font-size: 0.72rem;
  text-align: center;
}
.list-preview-image svg {
  width: 2.1rem;
  height: 2.1rem;
  color: #7e8b9c;
}
.list-preview-copy {
  display: grid;
  gap: 0.16rem;
  padding-top: 0.75rem;
}
.list-preview-copy p {
  color: #f5f7fa;
  font-size: 0.83rem;
  font-weight: 600;
}
.list-preview-copy span,
.list-preview-copy small {
  color: var(--color-subtle);
  font-size: 0.68rem;
}
.list-preview-copy small {
  color: var(--color-warning);
}
.list-checklist {
  display: grid;
  gap: 0.65rem;
  margin-top: 0.8rem;
}
.list-checklist li {
  display: flex;
  gap: 0.55rem;
  align-items: center;
  min-height: 2.4rem;
}
.list-checklist li > svg,
.list-checklist li > span {
  display: grid;
  flex: 0 0 auto;
  width: 1.25rem;
  height: 1.25rem;
  place-items: center;
  border: 1px solid #728093;
  border-radius: 0.32rem;
  color: #041410;
}
.list-checklist li.is-done > svg {
  border-color: var(--color-accent);
  background: var(--color-accent);
}
.list-checklist li strong {
  display: block;
  color: #f3f6fa;
  font-size: 0.7rem;
}
.list-checklist li small {
  display: block;
  margin-top: 0.08rem;
  color: var(--color-subtle);
  font-size: 0.63rem;
}
.list-save-error {
  display: flex;
  gap: 0.45rem;
  align-items: center;
  margin: 0.7rem 0;
  color: var(--color-negative);
  font-size: 0.73rem;
}
.list-save-error svg {
  width: 1rem;
}
.list-action-bar {
  position: fixed;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  gap: 0.72rem;
  min-height: 4.7rem;
  padding: 0.7rem max(2rem, calc((100vw - 1280px) / 2));
  border-top: 1px solid var(--color-border-strong);
  background: rgba(7, 10, 14, 0.96);
  backdrop-filter: blur(12px);
}
.list-action-bar > div {
  display: grid;
  flex: 1;
  gap: 0.15rem;
}
.list-action-bar strong {
  color: #fff;
  font-size: 0.75rem;
}
.list-action-bar span {
  color: var(--color-subtle);
  font-size: 0.67rem;
}
.list-cancel,
.list-action-bar button {
  display: inline-flex;
  gap: 0.35rem;
  align-items: center;
  justify-content: center;
  min-height: 2.3rem;
  border-radius: 0.42rem;
  padding: 0 0.85rem;
  font-size: 0.73rem;
  font-weight: 650;
}
.list-cancel {
  border: 1px solid var(--color-border-strong);
  color: #fff;
}
.list-action-bar button {
  border: 1px solid var(--color-accent);
  background: var(--color-accent);
  color: #041510;
}
.list-action-bar button svg {
  width: 0.85rem;
}
.list-action-bar button:disabled {
  cursor: not-allowed;
  opacity: 0.45;
}
@media (max-width: 1280px) {
  .list-grid {
    grid-template-columns: minmax(28rem, 1.4fr) minmax(16rem, 0.8fr);
  }
  .list-preview-stack {
    grid-column: 1/-1;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .list-preview-image {
    min-height: 8rem;
  }
}
@media (max-width: 920px) {
  .list-shell {
    grid-template-columns: 1fr;
  }
  .list-sidebar {
    position: static;
    min-height: auto;
    padding: 1.2rem;
    border-right: 0;
    border-bottom: 1px solid var(--color-border);
  }
  .list-sidebar ol {
    grid-template-columns: repeat(4, minmax(0, 1fr));
    margin: 1rem 0 0;
  }
  .list-sidebar li {
    grid-template-columns: 1.45rem minmax(0, 1fr);
    min-height: 3.45rem;
    padding: 0.48rem;
  }
  .list-sidebar li small,
  .list-sidebar > p:not(.page-kicker),
  .list-help,
  .list-drafts {
    display: none;
  }
  .list-workspace {
    padding: 1.35rem 1.1rem 5.4rem;
  }
  .list-grid {
    grid-template-columns: minmax(0, 1fr);
  }
  .list-preview-stack {
    grid-column: auto;
  }
}
@media (max-width: 620px) {
  .list-workspace {
    padding-inline: 0.8rem;
  }
  .list-form-grid,
  .list-preview-stack {
    grid-template-columns: 1fr;
  }
  .list-sidebar ol {
    grid-template-columns: 1fr 1fr;
  }
  .list-sidebar li {
    min-height: 2.75rem;
  }
  .list-sidebar li strong {
    font-size: 0.68rem;
  }
  .list-action-bar {
    padding: 0.55rem 0.8rem;
  }
  .list-action-bar > div {
    display: none;
  }
  .list-cancel,
  .list-action-bar button {
    flex: 1;
  }
}
.account-shell {
  width: min(calc(100% - 3rem), 96rem);
  padding-block: 2.15rem 3rem;
}
.account-heading {
  min-height: 7.9rem;
  padding: 0.2rem 0 1.35rem;
}
.account-heading h1 {
  margin-top: 0.44rem;
  font-family: var(--font-display);
  font-size: clamp(2.55rem, 4.1vw, 4.28rem);
  font-weight: 750;
  line-height: 0.98;
  letter-spacing: -0.06em;
}
.account-heading > p:last-child {
  margin-top: 0.67rem;
  color: var(--color-subtle);
  font-size: 0.92rem;
}
.account-layout {
  display: grid;
  grid-template-columns: minmax(13.75rem, 15rem) minmax(0, 1fr);
  gap: 1.5rem;
  align-items: start;
}
.account-sidebar,
.account-kpi,
.account-panel {
  border: 1px solid rgba(158, 174, 194, 0.15);
  border-radius: 0.78rem;
  background: linear-gradient(145deg, rgba(22, 27, 35, 0.97), rgba(13, 17, 23, 0.98));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.025),
    0 14px 32px rgba(0, 0, 0, 0.16);
}
.account-sidebar {
  position: sticky;
  top: 5.5rem;
  padding: 0.7rem;
}
.account-sidebar nav {
  display: grid;
  gap: 0.15rem;
}
.account-sidebar__item {
  display: flex;
  min-height: 2.55rem;
  align-items: center;
  gap: 0.7rem;
  padding: 0.5rem 0.62rem;
  border-left: 2px solid transparent;
  border-radius: 0.35rem;
  color: #eef2f7;
  font-size: 0.83rem;
  transition:
    background 0.18s ease,
    color 0.18s ease;
}
.account-sidebar__item svg {
  width: 1rem;
  height: 1rem;
  color: var(--color-subtle);
}
.account-sidebar__item:hover,
.account-sidebar__item.is-active {
  border-left-color: var(--color-accent);
  background: rgba(67, 82, 99, 0.2);
  color: white;
}
.account-sidebar__item.is-active svg {
  color: var(--color-accent);
}
.account-sidebar__item.is-unavailable {
  cursor: not-allowed;
  opacity: 0.58;
}
.account-sidebar__item.is-unavailable:hover {
  border-left-color: transparent;
  background: none;
}
.account-sidebar__section {
  padding: 0.8rem 0.62rem 0.25rem;
  color: var(--color-muted);
  font-size: 0.64rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.account-sidebar__help {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  margin-top: 1.2rem;
  padding: 0.75rem;
  border: 1px solid var(--color-border-strong);
  border-radius: 0.56rem;
  color: #fff;
}
.account-sidebar__help svg {
  color: var(--color-accent);
}
.account-sidebar__help span {
  display: grid;
  gap: 0.14rem;
  font-size: 0.75rem;
}
.account-sidebar__help small {
  color: var(--color-accent);
  font-size: 0.7rem;
}
.account-content {
  display: grid;
  gap: 1rem;
  min-width: 0;
}
.account-kpis {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.8rem;
}
.account-kpi {
  display: flex;
  min-height: 7.5rem;
  gap: 0.8rem;
  padding: 1rem;
  color: inherit;
}
.account-kpi > div {
  min-width: 0;
}
.account-kpi[href]:hover {
  border-color: rgba(34, 211, 165, 0.38);
  transform: translateY(-1px);
}
.account-kpi__icon {
  display: grid;
  flex: 0 0 auto;
  width: 2.75rem;
  height: 2.75rem;
  place-items: center;
  border: 1px solid rgba(20, 233, 193, 0.22);
  border-radius: 0.62rem;
  background: rgba(8, 125, 103, 0.16);
  color: var(--color-accent);
}
.account-kpi__icon svg {
  width: 1.18rem;
  height: 1.18rem;
}
.account-kpi p {
  color: #d8dce4;
  font-size: 0.78rem;
}
.account-kpi strong {
  display: block;
  margin-top: 0.25rem;
  color: #f7f9fc;
  font-size: 1.3rem;
  line-height: 1.18;
}
.account-kpi small {
  display: block;
  margin-top: 0.35rem;
  color: var(--color-subtle);
  font-size: 0.72rem;
  overflow-wrap: break-word;
}
.account-main-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.5fr) minmax(21rem, 0.95fr);
  gap: 0.85rem;
}
.account-panel {
  min-width: 0;
  padding: 1rem 1.1rem;
}
.account-panel--profile,
.account-panel--linked {
  min-height: 19.4rem;
}
.account-panel--security,
.account-panel--actions {
  min-height: 19.4rem;
}
.account-panel__heading h2 {
  color: #f4f7fb;
  font-size: 1rem;
  font-weight: 650;
}
.account-panel__heading p {
  margin-top: 0.25rem;
  color: var(--color-subtle);
  font-size: 0.75rem;
}
.account-panel__heading-row {
  display: flex;
  align-items: start;
  justify-content: space-between;
  gap: 0.8rem;
}
.account-edit-profile {
  flex: 0 0 auto;
  border: 1px solid var(--color-border-strong);
  border-radius: 0.42rem;
  padding: 0.38rem 0.62rem;
  color: #fff;
  font-size: 0.7rem;
}
.account-edit-profile:hover {
  border-color: var(--color-accent);
  color: var(--color-accent);
}
.account-profile-form {
  display: grid;
  gap: 0.47rem;
}
.account-profile-form label {
  display: grid;
  gap: 0.22rem;
  color: var(--color-subtle);
  font-size: 0.68rem;
}
.account-profile-form input {
  min-width: 0;
  border: 1px solid var(--color-border-strong);
  border-radius: 0.38rem;
  background: rgba(4, 7, 11, 0.55);
  padding: 0.35rem 0.45rem;
  color: #fff;
  font-size: 0.76rem;
}
.account-username-input,
.username-input {
  display: flex;
  min-width: 0;
  align-items: stretch;
  border: 1px solid var(--color-border-strong);
  border-radius: 0.38rem;
  background: rgba(4, 7, 11, 0.55);
}
.account-username-input b,
.username-input b {
  display: grid;
  flex: 0 0 auto;
  width: 2rem;
  place-items: center;
  border-right: 1px solid var(--color-border-strong);
  color: var(--color-accent);
  font-size: 0.82rem;
}
.account-username-input input,
.username-input .form-control {
  min-width: 0;
  flex: 1;
  border: 0;
  background: transparent;
}
.account-profile-form p {
  color: var(--color-subtle);
  font-size: 0.7rem;
}
.account-profile-form p strong {
  color: #fff;
}
.account-profile-form button {
  justify-self: start;
  border-radius: 0.42rem;
  background: var(--color-accent);
  padding: 0.4rem 0.65rem;
  color: #06100d;
  font-size: 0.7rem;
  font-weight: 700;
}
.account-profile-form button:disabled {
  opacity: 0.6;
}
.account-form-error {
  color: var(--color-negative);
  font-size: 0.68rem;
}

/* Collector workspace: a contained operating surface, separate from Account and
   public collector presentation. */
.collector-workspace-shell {
  display: grid;
  min-height: 100vh;
  grid-template-columns: 15rem minmax(0, 1fr);
  background: radial-gradient(circle at 68% 0, rgba(13, 102, 85, 0.13), transparent 33rem), #05080c;
}
.collector-workspace-sidebar {
  position: sticky;
  top: 0;
  display: flex;
  height: 100vh;
  min-width: 0;
  flex-direction: column;
  border-right: 1px solid #26313b;
  background: linear-gradient(180deg, #080d13, #071017 72%, #05090e);
}
.collector-workspace-sidebar__brand {
  display: flex;
  height: 4.65rem;
  align-items: center;
  justify-content: space-between;
  padding: 0 1.45rem;
  border-bottom: 1px solid #26313b;
