}
.collector-workspace-sidebar__label {
  margin: 1.7rem 1.5rem 0.7rem;
  color: #8e9aac;
  font-size: 0.61rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
