.collector-workspace-nav {
  display: grid;
  gap: 0.15rem;
  padding: 0 0.75rem;
}
.collector-workspace-nav button,
.collector-workspace-sidebar__link {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 0.8rem;
  border-radius: 0.45rem;
