}
.account-access-list {
  display: grid;
  margin-top: 0.92rem;
}
.account-access-list li {
  display: grid;
  grid-template-columns: 1.25rem minmax(0, 1fr) auto;
  gap: 0.58rem;
  align-items: center;
  min-height: 3.2rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.065);
}
.account-access-list li:last-child {
  border-bottom: 0;
}
.account-access-list li > div {
  display: grid;
  min-width: 0;
  gap: 0.12rem;
}
.account-access-list strong {
  color: #f5f7fa;
  font-size: 0.78rem;
  font-weight: 600;
}
.account-access-list small {
