/* Step 2 card-details composition: three clear groups, one compact guided form. */
.list-step--details {
  padding-top: clamp(1.35rem, 3vw, 2rem);
}
.list-details-header {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(15rem, 18rem);
  gap: 1.5rem;
  align-items: start;
  padding-bottom: 1.25rem;
  border-bottom: 1px solid rgba(148, 172, 184, 0.14);
}
.list-details-header > div > p:last-child {
  max-width: 39rem;
}
.list-why-ask {
  display: flex;
  gap: 0.75rem;
  padding: 0.8rem 0.9rem;
  border: 1px solid rgba(31, 214, 167, 0.27);
  border-radius: 0.65rem;
  background: rgba(13, 71, 61, 0.18);
}
.list-why-ask__icon {
  display: grid;
  flex: 0 0 1.7rem;
  width: 1.7rem;
  height: 1.7rem;
  place-items: center;
  border-radius: 999px;
  color: #061b16;
  background: #24d5a5;
  box-shadow: 0 0 1rem rgba(34, 211, 165, 0.28);
}
.list-why-ask__icon svg {
  width: 0.9rem;
  height: 0.9rem;
}
.list-why-ask strong {
  display: block;
  color: #e6f4f1;
  font-size: 0.78rem;
}
.list-why-ask ul {
  display: grid;
  gap: 0.25rem;
  margin-top: 0.45rem;
  padding: 0;
  list-style: none;
}
.list-why-ask li {
  color: #a4b5bc;
  font-size: 0.68rem;
  line-height: 1.35;
}
.list-why-ask li::before {
  margin-right: 0.35rem;
  color: #2bdcad;
  content: "•";
}
.list-details-section {
  padding-top: 1.1rem;
}
.list-details-section + .list-details-section {
  margin-top: 1.05rem;
  border-top: 1px solid rgba(148, 172, 184, 0.14);
}
.list-details-section h3 {
  display: flex;
  gap: 0.5rem;
  align-items: center;
  margin: 0;
  color: #edf7f5;
  font-size: 0.8rem;
  letter-spacing: -0.01em;
}
.list-details-section h3 > span {
  display: inline-grid;
  width: 1.2rem;
  height: 1.2rem;
  place-items: center;
  border: 1px solid rgba(34, 211, 165, 0.7);
  border-radius: 999px;
  color: #29dbaa;
  font-size: 0.62rem;
  font-weight: 800;
}
.list-details-section h3 small {
  margin-left: 0.2rem;
  color: #82959e;
  font-size: 0.66rem;
  font-weight: 500;
}
.list-details-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.85rem 1.05rem;
  margin-top: 0.85rem;
}
.list-grading-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.85rem 1.05rem;
  margin-top: 0.85rem;
}
.list-details-grid > label,
.list-grading-grid > label {
  min-width: 0;
}
.list-step--details .list-field-label {
  min-height: 1.2rem;
}
.list-step--details .list-field-tooltip {
  display: inline-grid;
  width: 1.05rem;
  height: 1.05rem;
  margin: 0;
  padding: 0;
  place-items: center;
  border: 0;
  color: #38dcb2;
