}
.list-step--details .list-field-tooltip:hover,
.list-step--details .list-field-tooltip:focus-visible {
  color: #b7ffeb;
  outline: 2px solid rgba(56, 220, 178, 0.45);
  outline-offset: 2px;
}
.list-step--details .list-field-tooltip svg {
  width: 0.9rem;
  height: 0.9rem;
}
.list-step--details .list-field-help {
  min-height: 1.05rem;
}
.list-step--details select:disabled,
.list-step--details input:disabled {
  color: #71838d;
  border-color: rgba(148, 172, 184, 0.16);
  background: rgba(7, 14, 19, 0.58);
  cursor: not-allowed;
}

@media (max-width: 860px) {
  .list-details-header {
    grid-template-columns: 1fr;
  }
  .list-why-ask {
    max-width: 28rem;
  }
  .list-grading-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .list-grading-grid > label:last-child {
    grid-column: 1 / -1;
  }
}
@media (max-width: 560px) {
  .list-details-grid,
  .list-grading-grid {
    grid-template-columns: 1fr;
  }
  .list-grading-grid > label:last-child {
    grid-column: auto;
  }
  .list-why-ask {
    max-width: none;
  }
  .list-details-section h3 {
    align-items: flex-start;
  }
  .list-details-section h3 small {
    margin-top: 0.15rem;
  }
}

/* Listing Step 1: the quick identification path is the primary action, while
   manual entry stays visible and intentionally small for first-time users. */
.list-guided-card {
  overflow: hidden;
}
.list-step {
  padding: clamp(1.35rem, 3.5vw, 2.25rem);
}
.list-step > h2 {
  font-size: clamp(1.7rem, 3vw, 2.25rem);
}
.list-step > p {
  font-size: 0.92rem;
}
.list-start-faster {
  display: grid;
  gap: 1.15rem;
  margin-top: 1.7rem;
  padding: 1.15rem 1.2rem 1.2rem;
  border: 1px solid rgba(34, 211, 165, 0.55);
  border-radius: 0.8rem;
  background: linear-gradient(135deg, rgba(20, 83, 72, 0.32), rgba(7, 20, 23, 0.9));
  box-shadow:
    inset 0 1px 0 rgba(108, 255, 214, 0.05),
    0 1rem 2.5rem rgba(0, 0, 0, 0.12);
}
.list-start-faster__intro {
  display: grid;
  grid-template-columns: 3.15rem minmax(0, 1fr);
  gap: 0.9rem;
  align-items: center;
}
.list-start-faster__icon {
  display: grid;
  width: 3.15rem;
  height: 3.15rem;
  place-items: center;
  border: 1px solid rgba(61, 238, 190, 0.45);
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #54f2c5, #0ba784 72%);
