.list-start-faster h3 {
  margin: 0.3rem 0 0;
  color: #edf9f5;
  font-size: 1rem;
}
.list-start-faster__intro p:last-child {
  margin: 0.32rem 0 0;
  color: #a5b7ba;
  font-size: 0.78rem;
  line-height: 1.45;
}
.list-start-faster__action {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 0.7rem;
  align-items: center;
}
.list-start-faster__input-wrap {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 0.6rem;
  min-height: 2.8rem;
