  box-shadow: 0 0 0 3px rgba(34, 211, 165, 0.12);
}
.list-start-faster__action .button-primary {
  display: inline-flex;
  gap: 0.4rem;
  align-items: center;
  min-height: 2.8rem;
  padding-inline: 1rem;
  font-size: 0.78rem;
}
.list-start-faster__action .button-primary svg {
  width: 0.9rem;
}
.list-import-result {
  display: grid;
  gap: 0.45rem;
