  display: grid;
  gap: 0.25rem;
  margin: 0.2rem 0 0;
}
.list-import-result dl > div {
  display: grid;
  grid-template-columns: 7rem minmax(0, 1fr);
  gap: 0.5rem;
}
.list-import-result dt {
