}
.list-simple-fields label {
  font-size: 0.76rem;
}
.list-simple-fields input,
.list-simple-fields select {
  min-height: 2.8rem;
  font-size: 0.82rem;
}
.list-next-steps {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 1rem;
  align-items: center;
  margin-top: 1.35rem;
