  color: #a9bbc0;
  font-size: 0.76rem;
  line-height: 1.45;
}
.list-ai-review-title-row {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  flex-wrap: wrap;
}
.list-ai-review-badge,
.list-ai-review-status {
  display: inline-flex;
  align-items: center;
  min-height: 1.5rem;
  padding: 0 0.55rem;
  border: 1px solid rgba(39, 220, 176, 0.42);
  border-radius: 999px;
  color: #62e7c1;
  font-size: 0.62rem;
  white-space: nowrap;
}
.list-ai-review-status {
  border-color: rgba(151, 177, 188, 0.25);
  color: #b8c9ce;
}
.list-ai-review-status.is-complete {
  border-color: rgba(39, 220, 176, 0.42);
  color: #62e7c1;
}
.list-ai-result {
  margin-top: 0.9rem;
  padding: 0.9rem;
}
.list-ai-result__top {
  display: grid;
  grid-template-columns: 6.5rem minmax(0, 1fr) auto;
  gap: 0.9rem;
  align-items: center;
  padding-bottom: 0.9rem;
  border-bottom: 1px solid rgba(151, 177, 188, 0.14);
}
.list-ai-score-ring {
  display: grid;
