}
.list-ai-score-ring span {
  margin-top: 0.2rem;
  color: #92a9af;
  font-size: 0.62rem;
}
.list-ai-eyebrow {
  color: #7e969e;
  font-size: 0.62rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.list-ai-result__summary h3 {
  margin: 0.22rem 0 0;
  color: #21dab0;
  font-size: 1.25rem;
}
.list-ai-result__summary p {
  max-width: 24rem;
  margin: 0.35rem 0 0;
  color: #aabcc0;
  font-size: 0.7rem;
  line-height: 1.45;
}
.list-ai-result__confidence {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  margin-top: 0.65rem;
  color: #90a6ad;
  font-size: 0.66rem;
}
.list-ai-result__confidence svg {
  width: 0.95rem;
  color: #22d7ac;
}
.list-ai-result__confidence strong {
  margin-left: auto;
  color: #e6f9f2;
  font-weight: 500;
}
.list-ai-score-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 0.5rem;
  margin-top: 0.85rem;
}
.list-ai-score-card {
  min-width: 0;
  padding: 0.65rem;
  border: 1px solid rgba(151, 177, 188, 0.15);
  border-radius: 0.5rem;
  background: rgba(17, 33, 40, 0.48);
}
.list-ai-score-card > span,
.list-ai-score-card em {
  display: block;
  color: #91a5ac;
  font-size: 0.59rem;
  font-style: normal;
}
.list-ai-score-card strong {
  display: block;
  margin-top: 0.32rem;
  color: #f0fcf8;
  font-size: 1.05rem;
}
.list-ai-score-card strong small {
  color: #8ea4ab;
  font-size: 0.6rem;
  font-weight: 400;
}
.list-ai-score-card em {
  margin-top: 0.25rem;
  color: #5de0b9;
  font-size: 0.57rem;
}
.list-ai-visual-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.55rem;
  margin-top: 0.85rem;
}
.list-ai-visual-card {
  min-width: 0;
  padding: 0.55rem;
  border: 1px solid rgba(151, 177, 188, 0.15);
  border-radius: 0.5rem;
  background: rgba(5, 14, 19, 0.55);
}
.list-ai-visual-card > div:first-child {
  display: grid;
  gap: 0.15rem;
  margin-bottom: 0.45rem;
}
.list-ai-visual-card > div:first-child strong {
  color: #e7f6f1;
  font-size: 0.66rem;
}
.list-ai-visual-card > div:first-child span {
  color: #8299a1;
  font-size: 0.56rem;
}
.list-ai-visual-card > button {
  display: block;
  position: relative;
  width: 100%;
  padding: 0;
  overflow: hidden;
  border: 0;
  border-radius: 0.35rem;
  background: #081218;
  cursor: zoom-in;
}
.list-ai-visual-card > button img {
  display: block;
  width: 100%;
  height: 8.4rem;
  object-fit: contain;
}
.list-ai-visual-card__expand {
  position: absolute;
  right: 0.35rem;
  bottom: 0.35rem;
  display: inline-flex;
  align-items: center;
  gap: 0.2rem;
  padding: 0.22rem 0.32rem;
  border-radius: 0.25rem;
  background: rgba(3, 8, 12, 0.78);
  color: #effff9;
  font-size: 0.55rem;
}
.list-ai-visual-card__expand svg {
  width: 0.7rem;
}
.list-ai-visual-card__empty {
  display: grid;
  min-height: 8.4rem;
  place-items: center;
  align-content: center;
  gap: 0.35rem;
  color: #78909a;
  font-size: 0.58rem;
  text-align: center;
}
.list-ai-visual-card__empty svg {
  width: 1rem;
  color: #2dd3aa;
}
.list-ai-details {
  margin-top: 0.85rem;
  border-top: 1px solid rgba(151, 177, 188, 0.14);
}
.list-ai-details summary {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  padding-top: 0.75rem;
  color: #61e6bf;
  font-size: 0.68rem;
  cursor: pointer;
  list-style: none;
}
.list-ai-details summary::-webkit-details-marker {
  display: none;
}
.list-ai-details summary svg {
  width: 0.75rem;
}
.list-ai-details dl {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.45rem 1rem;
  margin: 0.75rem 0 0;
}
.list-ai-details dt {
  color: #78909a;
  font-size: 0.58rem;
}
.list-ai-details dd {
  margin: 0.12rem 0 0;
  color: #d4e6e4;
  font-size: 0.65rem;
}
.list-ai-details ul {
  margin: 0.75rem 0 0;
  padding-left: 1rem;
  color: #f2c38b;
  font-size: 0.64rem;
}
.list-ai-disclaimer {
  display: flex;
  gap: 0.45rem;
  align-items: flex-start;
  margin-top: 0.85rem;
  padding: 0.65rem 0.7rem;
  border: 1px solid rgba(72, 197, 174, 0.2);
  border-radius: 0.45rem;
  background: rgba(25, 115, 94, 0.1);
}
.list-ai-disclaimer svg {
  flex: 0 0 auto;
  width: 0.95rem;
  color: #32d6ab;
}
.list-ai-disclaimer p {
  margin: 0;
  color: #a8c4c1;
  font-size: 0.62rem;
  line-height: 1.45;
}
.list-ai-ready,
.list-ai-graded-panel {
  display: flex;
  gap: 0.85rem;
  margin-top: 0.9rem;
  padding: 1rem;
  align-items: flex-start;
}
.list-ai-ready__icon {
  display: grid;
  flex: 0 0 auto;
  width: 2.3rem;
  height: 2.3rem;
  place-items: center;
  border-radius: 0.6rem;
  background: rgba(29, 200, 160, 0.12);
  color: #39dbb1;
}
.list-ai-ready__icon svg {
  width: 1.1rem;
}
.list-ai-ready h3,
.list-ai-graded-panel h3 {
  margin: 0;
  color: #ecfaf6;
  font-size: 1rem;
}
.list-ai-ready p,
.list-ai-graded-panel p {
  margin: 0.4rem 0 0;
  color: #a8bbc0;
  font-size: 0.72rem;
  line-height: 1.5;
}
.list-ai-ready small {
  display: block;
  margin-top: 0.55rem;
  color: #869ca4;
  font-size: 0.62rem;
}
.list-ai-actions {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
  margin-top: 0.9rem;
}
.list-ai-actions .button-primary,
.list-ai-actions .button-secondary {
  min-height: 2.5rem;
  padding: 0 0.8rem;
  font-size: 0.7rem;
}
.list-ai-state {
  display: grid;
  justify-items: start;
  gap: 0.4rem;
  margin-top: 0.9rem;
  padding: 1.2rem;
}
.list-ai-state__icon {
  width: 1.55rem;
  color: #36d9af;
}
.list-ai-state--warning {
  border-color: rgba(232, 175, 99, 0.3);
}
.list-ai-state--warning .list-ai-state__icon {
  color: #efbf7d;
}
.list-ai-state h3 {
  margin: 0;
  color: #ecfaf6;
  font-size: 1rem;
}
.list-ai-state p {
  max-width: 38rem;
  margin: 0;
  color: #a9bbc0;
  font-size: 0.72rem;
  line-height: 1.5;
}
.list-ai-state__technical {
  color: #8299a1;
  font-size: 0.58rem;
}
.list-ai-graded-panel dl {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.55rem;
  margin: 0.85rem 0 0;
}
.list-ai-graded-panel dt {
  color: #81969e;
  font-size: 0.58rem;
}
.list-ai-graded-panel dd {
  margin: 0.15rem 0 0;
  color: #e0f1ed;
  font-size: 0.68rem;
}
.list-ai-help-panel {
  padding: 0.85rem;
}
.list-ai-help-panel p {
  margin: 0.55rem 0 0;
  color: #a9bbc0;
  font-size: 0.67rem;
  line-height: 1.5;
}
.list-ai-help-panel ul {
  display: grid;
  gap: 0.45rem;
  margin: 0.7rem 0 0;
  padding: 0;
  list-style: none;
}
.list-ai-help-panel li {
  position: relative;
  padding-left: 1rem;
  color: #c9d9da;
  font-size: 0.64rem;
  line-height: 1.35;
}
.list-ai-help-panel li::before {
  position: absolute;
  top: 0.38rem;
  left: 0;
  width: 0.35rem;
  height: 0.35rem;
  border-radius: 50%;
  background: #2dd3aa;
  content: "";
}
.list-ai-lightbox {
  position: fixed;
  inset: 0;
  z-index: 80;
  display: grid;
  place-items: center;
  padding: 1rem;
  background: rgba(1, 5, 8, 0.88);
}
.list-ai-lightbox__inner {
  position: relative;
  width: min(54rem, 100%);
  padding: 1rem;
  border: 1px solid rgba(97, 230, 191, 0.28);
  border-radius: 0.8rem;
  background: #071118;
  box-shadow: 0 2rem 5rem rgba(0, 0, 0, 0.5);
}
.list-ai-lightbox__inner img {
  display: block;
  width: 100%;
  max-height: 80vh;
  object-fit: contain;
  border-radius: 0.45rem;
}
.list-ai-lightbox__inner p {
  margin: 0.6rem 0 0;
  color: #c8ddda;
  font-size: 0.72rem;
}
.list-ai-lightbox__close {
  position: absolute;
  top: 0.45rem;
  right: 0.45rem;
  z-index: 1;
  display: grid;
  width: 2rem;
  height: 2rem;
  place-items: center;
  border: 1px solid rgba(216, 242, 237, 0.25);
  border-radius: 50%;
  background: rgba(3, 9, 12, 0.8);
  color: #eafff8;
  cursor: pointer;
}
.list-ai-lightbox__close svg {
  width: 1rem;
}
@media (max-width: 1120px) {
  .list-ai-review-layout {
    grid-template-columns: minmax(12rem, 0.7fr) minmax(0, 1.6fr);
  }
  .list-ai-review-right {
    grid-column: 1 / -1;
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}
@media (max-width: 760px) {
  .list-ai-review-layout {
    grid-template-columns: 1fr;
  }
  .list-ai-review-right {
    grid-column: auto;
    grid-template-columns: 1fr;
  }
  .list-ai-score-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .list-ai-score-card:last-child {
    grid-column: 1 / -1;
  }
}
@media (max-width: 520px) {
  .list-ai-review-header {
    display: block;
  }
  .list-ai-review-status {
    margin-top: 0.65rem;
  }
  .list-ai-result__top {
    grid-template-columns: 5.5rem minmax(0, 1fr);
  }
  .list-ai-result__top > .list-ai-review-status {
    grid-column: 1 / -1;
    width: fit-content;
  }
  .list-ai-score-ring {
    width: 5rem;
    height: 5rem;
  }
  .list-ai-score-ring strong {
    font-size: 1.35rem;
  }
  .list-ai-visual-grid {
    grid-template-columns: 1fr;
  }
  .list-ai-visual-card > button img,
  .list-ai-visual-card__empty {
    height: 12rem;
    min-height: 12rem;
  }
  .list-ai-graded-panel dl {
    grid-template-columns: 1fr;
  }
  .list-ai-actions {
    display: grid;
  }
  .list-ai-actions button {
    width: 100%;
    justify-content: center;
  }
}

/* Final cascade for the Step 2 card-details composition. */
.list-step--details {
  padding-top: clamp(1.35rem, 3vw, 2rem);
}
.list-details-header {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(15rem, 18rem);
  gap: 1.5rem;
  align-items: start;
  padding-bottom: 1.25rem;
  border-bottom: 1px solid rgba(148, 172, 184, 0.14);
}
.list-details-header > div > p:last-child {
  max-width: 39rem;
}
.list-why-ask {
  display: flex;
  gap: 0.75rem;
  padding: 0.8rem 0.9rem;
  border: 1px solid rgba(31, 214, 167, 0.27);
  border-radius: 0.65rem;
  background: rgba(13, 71, 61, 0.18);
}
.list-why-ask__icon {
  display: grid;
  flex: 0 0 1.7rem;
  width: 1.7rem;
  height: 1.7rem;
  place-items: center;
  border-radius: 999px;
  color: #061b16;
  background: #24d5a5;
  box-shadow: 0 0 1rem rgba(34, 211, 165, 0.28);
}
.list-why-ask__icon svg {
  width: 0.9rem;
  height: 0.9rem;
}
.list-why-ask strong {
  display: block;
  color: #e6f4f1;
  font-size: 0.78rem;
}
.list-why-ask ul {
  display: grid;
  gap: 0.25rem;
  margin-top: 0.45rem;
  padding: 0;
  list-style: none;
}
.list-why-ask li {
  color: #a4b5bc;
  font-size: 0.68rem;
  line-height: 1.35;
}
.list-why-ask li::before {
  margin-right: 0.35rem;
  color: #2bdcad;
  content: "•";
}
.list-details-section {
  padding-top: 1.1rem;
}
.list-details-section + .list-details-section {
  margin-top: 1.05rem;
  border-top: 1px solid rgba(148, 172, 184, 0.14);
}
.list-details-section h3 {
  display: flex;
  gap: 0.5rem;
  align-items: center;
  margin: 0;
  color: #edf7f5;
  font-size: 0.8rem;
  letter-spacing: -0.01em;
}
.list-details-section h3 > span {
  display: inline-grid;
  width: 1.2rem;
  height: 1.2rem;
  place-items: center;
  border: 1px solid rgba(34, 211, 165, 0.7);
  border-radius: 999px;
  color: #29dbaa;
  font-size: 0.62rem;
  font-weight: 800;
}
.list-details-section h3 small {
  margin-left: 0.2rem;
  color: #82959e;
  font-size: 0.66rem;
  font-weight: 500;
}
.list-details-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.85rem 1.05rem;
  margin-top: 0.85rem;
}
.list-grading-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.85rem 1.05rem;
  margin-top: 0.85rem;
}
.list-details-grid > label,
.list-grading-grid > label {
  min-width: 0;
}
.list-step--details .list-field-label {
  min-height: 1.2rem;
}
.list-step--details .list-field-tooltip {
  display: inline-grid;
  width: 1.05rem;
  height: 1.05rem;
  margin: 0;
  padding: 0;
  place-items: center;
  border: 0;
  color: #38dcb2;
  background: transparent;
  cursor: help;
}
.list-step--details .list-field-tooltip:hover,
.list-step--details .list-field-tooltip:focus-visible {
  color: #b7ffeb;
  outline: 2px solid rgba(56, 220, 178, 0.45);
  outline-offset: 2px;
}
.list-step--details .list-field-tooltip svg {
  width: 0.9rem;
  height: 0.9rem;
}
.list-step--details .list-field-help {
  min-height: 1.05rem;
}
.list-step--details select:disabled,
.list-step--details input:disabled {
  color: #71838d;
  border-color: rgba(148, 172, 184, 0.16);
  background: rgba(7, 14, 19, 0.58);
  cursor: not-allowed;
}
@media (max-width: 860px) {
  .list-details-header {
    grid-template-columns: 1fr;
  }
  .list-why-ask {
    max-width: 28rem;
  }
  .list-grading-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .list-grading-grid > label:last-child {
    grid-column: 1 / -1;
  }
}
@media (max-width: 560px) {
  .list-details-grid,
  .list-grading-grid {
    grid-template-columns: 1fr;
  }
  .list-grading-grid > label:last-child {
    grid-column: auto;
  }
  .list-why-ask {
    max-width: none;
  }
  .list-details-section h3 {
    align-items: flex-start;
  }
  .list-details-section h3 small {
    margin-top: 0.15rem;
  }
}
.account-action-required,
.account-temporarily-unavailable {
  padding: 0.25rem 0.5rem;
  border-radius: 999px;
  font-size: 0.66rem;
  font-weight: 700;
}
.account-action-required {
  background: rgba(251, 191, 36, 0.12);
  color: #f4c85c;
}
.account-temporarily-unavailable {
  background: rgba(148, 163, 184, 0.14);
  color: #cbd5e1;
}
.account-security-row:last-child,
.account-linked-row:last-child,
.account-session-list li:last-child,
.account-activity-list li:last-child,
.account-danger-row:last-child {
