/* Asset detail polish: make the collectible the hero and keep the next action obvious. */
.asset-detail-page .asset-redesign-media {
  background:
    radial-gradient(circle at 50% 45%, rgb(34 211 165 / 0.13), transparent 42%),
    linear-gradient(145deg, rgb(12 34 36 / 0.98), rgb(5 13 18 / 0.99));
}
.asset-detail-page .asset-redesign-media .asset-showcase {
  min-height: 35rem;
  background:
    radial-gradient(ellipse 48% 54% at 50% 78%, rgb(34 211 165 / 0.21), transparent 70%),
    radial-gradient(circle at 22% 18%, rgb(117 255 218 / 0.08), transparent 38%),
    linear-gradient(180deg, rgb(8 19 24 / 0.95), rgb(2 10 14 / 0.99));
}
.asset-detail-page .asset-media-caption__hint {
  color: #a4c4c2;
  font-size: 0.68rem;
  font-weight: 500;
}
.asset-card-stage {
  position: absolute;
  z-index: 3;
  top: 1.2rem;
  bottom: 1.6rem;
  left: 50%;
  width: min(76%, 20rem);
  perspective: 1100px;
  transform: translateX(-50%);
}
.asset-card-flip__inner {
  position: relative;
  width: 100%;
  height: 100%;
  transform-style: preserve-3d;
  transition: transform 720ms cubic-bezier(0.22, 0.72, 0.18, 1);
}
.asset-card-stage.is-flipped .asset-card-flip__inner {
  transform: rotateY(180deg);
}
.asset-card-face {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  overflow: hidden;
  border: 1px solid rgb(177 250 226 / 0.18);
  border-radius: 0.55rem;
  background: linear-gradient(155deg, rgb(11 25 29 / 0.98), rgb(2 9 13 / 0.98));
  box-shadow:
    0 22px 45px rgb(0 0 0 / 0.34),
    0 0 34px rgb(34 211 165 / 0.12);
  backface-visibility: hidden;
}
.asset-card-face::after {
  position: absolute;
  inset: 0;
  border: 1px solid rgb(255 255 255 / 0.06);
  border-radius: inherit;
  content: "";
  pointer-events: none;
}
.asset-card-face img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  padding: 0.45rem;
}
.asset-card-face > span {
  position: absolute;
  right: 0.55rem;
  bottom: 0.55rem;
  z-index: 1;
  border: 1px solid rgb(34 211 165 / 0.28);
  border-radius: 999px;
  padding: 0.25rem 0.45rem;
  color: #b8f9e5;
  background: rgb(4 18 19 / 0.84);
  font-family: var(--font-mono);
  font-size: 0.55rem;
  font-weight: 800;
  letter-spacing: 0.11em;
  text-transform: uppercase;
}
.asset-card-face--back {
  transform: rotateY(180deg);
}
.asset-card-flip-button {
  position: absolute;
  z-index: 5;
  top: 0.7rem;
  right: 0.7rem;
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  min-height: 2rem;
  border: 1px solid rgb(177 250 226 / 0.26);
  border-radius: 999px;
  padding: 0.35rem 0.58rem;
  color: #d8f8ed;
  background: rgb(4 15 18 / 0.8);
  font-size: 0.65rem;
  font-weight: 750;
  backdrop-filter: blur(8px);
  cursor: pointer;
  transition:
    border-color 170ms ease,
    background 170ms ease,
    transform 170ms ease;
}
.asset-card-flip-button:hover,
.asset-card-flip-button:focus-visible {
  border-color: rgb(34 211 165 / 0.7);
  background: rgb(12 67 59 / 0.84);
  transform: translateY(-1px);
}
.asset-card-flip-button svg {
  width: 0.85rem;
  height: 0.85rem;
  color: #38dcb2;
}
.asset-readiness-actions {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.6rem;
  margin-top: 1rem;
}
.asset-readiness-actions > div {
  display: grid;
  gap: 0.25rem;
  border: 1px solid rgb(126 163 169 / 0.15);
  border-radius: 0.7rem;
  padding: 0.75rem;
  background: rgb(4 12 17 / 0.34);
}
.asset-readiness-actions strong {
  color: #eaf8f3;
  font-size: 0.8rem;
}
.asset-readiness-actions span {
  color: #8fa8ae;
  font-size: 0.67rem;
  line-height: 1.4;
}
.asset-readiness-actions > div:first-child {
  border-color: rgb(34 211 165 / 0.25);
  background: rgb(21 103 82 / 0.12);
}
.asset-redesign .asset-how-it-works__grid {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}
.asset-redesign .asset-order-actions {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.65rem;
}
.asset-redesign .asset-order-actions a {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.7rem;
  min-height: 4.1rem;
  border: 1px solid rgb(126 163 169 / 0.22);
  border-radius: 0.7rem;
  padding: 0.7rem 0.8rem;
  text-decoration: none;
  transition:
    border-color 170ms ease,
    background 170ms ease,
    transform 170ms ease;
}
.asset-redesign .asset-order-actions a:hover,
.asset-redesign .asset-order-actions a:focus-visible {
  border-color: rgb(34 211 165 / 0.65);
  background: rgb(22 105 84 / 0.16);
  transform: translateY(-1px);
}
.asset-redesign .asset-order-actions a.is-buy {
  border-color: rgb(34 211 165 / 0.38);
  background: rgb(22 105 84 / 0.12);
}
.asset-redesign .asset-order-actions .is-disabled {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 0.7rem;
  min-height: 4.1rem;
  border: 1px solid rgb(126 163 169 / 0.14);
  border-radius: 0.7rem;
  padding: 0.7rem 0.8rem;
  background: rgb(10 18 23 / 0.7);
  cursor: not-allowed;
  opacity: 0.62;
}
.asset-redesign .asset-order-actions .is-disabled strong,
.asset-redesign .asset-order-actions .is-disabled small {
  color: #8fa8ae;
}
.asset-redesign .asset-order-actions .is-disabled span {
  display: grid;
  gap: 0.2rem;
}
.asset-redesign .asset-order-actions a span {
  display: grid;
  gap: 0.2rem;
}
.asset-redesign .asset-order-actions a strong {
  color: #eaf8f3;
  font-size: 0.85rem;
}
.asset-redesign .asset-order-actions a small {
  color: #8fa8ae;
  font-size: 0.68rem;
}
.asset-redesign .asset-order-actions a svg {
  width: 0.9rem;
  color: #38dcb2;
}
.asset-redesign-grid--activity {
  grid-template-columns: minmax(0, 1.05fr) minmax(18rem, 0.95fr);
}
.asset-redesign-grid--activity > .asset-recent-trades,
.asset-market-note {
  min-width: 0;
  border: 1px solid rgb(103 150 157 / 0.24);
  border-radius: 1rem;
  background: linear-gradient(145deg, rgb(14 30 36 / 0.94), rgb(7 14 19 / 0.98));
  box-shadow: 0 18px 45px rgb(0 0 0 / 0.14);
}
.asset-market-note {
  padding: 1.2rem;
}
.asset-market-note h2 {
  margin: 0;
  color: #eff8f5;
  font-size: 1.25rem;
  letter-spacing: -0.035em;
}
.asset-market-note > p:not(.asset-section-label) {
  margin: 0.55rem 0 0;
  color: #a7bdc0;
  font-size: 0.82rem;
  line-height: 1.55;
}
.asset-market-note__steps {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.5rem;
  margin-top: 1rem;
}
.asset-market-note__steps span {
  display: grid;
  gap: 0.35rem;
  border-top: 1px solid rgb(34 211 165 / 0.3);
  padding-top: 0.5rem;
  color: #dff9f0;
  font-size: 0.72rem;
  font-weight: 700;
}
.asset-market-note__steps b {
  color: #38dcb2;
  font-family: var(--font-mono);
  font-size: 0.58rem;
}
@media (max-width: 900px) {
  .asset-redesign .asset-how-it-works__grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .asset-redesign-grid--activity {
    grid-template-columns: minmax(0, 1fr);
  }
}

/* Physical intake authority fields: keep the queue scannable while making
   custody blockers and staff actions visually distinct. */
.physical-intake-summary > button {
  display: grid;
  min-width: 0;
  gap: 0.18rem;
  border: 1px solid #203d49;
  border-radius: 0.45rem;
  padding: 0.65rem 0.75rem;
  background: linear-gradient(135deg, #0b1b23, #08141b);
  color: inherit;
  text-align: left;
}
.physical-intake-summary > button:hover,
.physical-intake-summary > button:focus-visible {
  border-color: #27d7b0;
  background: linear-gradient(135deg, #102b31, #0a1b21);
}
.physical-intake-summary > button small {
  overflow: hidden;
  color: #6d8a91;
  font-size: 0.52rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.physical-intake-fixture-badge {
  display: inline-flex;
  margin-left: 0.2rem;
  border: 1px solid #6f4f18;
  border-radius: 999px;
  padding: 0.08rem 0.28rem;
  color: #ffc45b;
  font-size: 0.48rem;
  font-style: normal;
  letter-spacing: 0.06em;
  vertical-align: middle;
}
.physical-intake-issue,
.physical-intake-no-issue {
  display: inline-flex;
  max-width: 100%;
  overflow: hidden;
  border-radius: 999px;
  padding: 0.22rem 0.36rem;
  font-size: 0.55rem;
  font-weight: 700;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.physical-intake-issue-high {
  border: 1px solid #713442;
  background: #29151d;
  color: #ff8b8b;
}
.physical-intake-issue-medium {
  border: 1px solid #73551f;
  background: #281e0d;
  color: #ffc65d;
}
.physical-intake-issue-low {
  border: 1px solid #295660;
  background: #0d252b;
  color: #8adbd0;
}
.physical-intake-no-issue {
  color: #6dcab1;
}
.physical-intake-history {
  display: grid;
  gap: 0.4rem;
  margin: 0.65rem 0 0;
  padding: 0;
  list-style: none;
}
.physical-intake-history li {
  display: grid;
  gap: 0.08rem;
  border-left: 1px solid #2d5960;
  padding-left: 0.5rem;
}
.physical-intake-history strong {
  color: #b8ddd5;
  font-size: 0.58rem;
}
.physical-intake-history small {
  color: #708b92;
  font-size: 0.52rem;
}
.physical-intake-table {
  min-width: 1220px;
}
.physical-intake-table th:nth-child(7) {
  width: 10%;
}
.physical-intake-table th:nth-child(8) {
  width: 11%;
}

@media (max-width: 900px) {
  .physical-intake-summary {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}
@media (max-width: 640px) {
  .asset-detail-page .asset-redesign-media .asset-showcase {
    min-height: 25rem;
  }
  .asset-card-stage {
    width: min(72%, 17rem);
  }
  .asset-readiness-actions,
  .asset-redesign .asset-order-actions {
    grid-template-columns: minmax(0, 1fr);
  }
  .asset-redesign .asset-how-it-works__grid {
    grid-template-columns: minmax(0, 1fr);
  }
}
@media (prefers-reduced-motion: reduce) {
  .asset-card-flip__inner {
    transition: none;
  }
  .asset-card-stage.is-flipped .asset-card-flip__inner {
    transform: rotateY(180deg);
  }
}

@media (max-width: 360px) {
  .approved-home .featured-market-hero--charizard .charizard-showcase__facts {
    grid-template-columns: 1fr;
  }
}

/* Review workstation refresh: keep the queue visual, compact and identity-first. */
.admin-review-summary-strip {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  border: 1px solid #243742;
  border-radius: 0.55rem;
  padding: 0.85rem 1rem;
  background: #0b1921;
}
.admin-review-summary-strip strong {
  display: block;
  color: #f0f8f5;
  font-size: 1rem;
}
.admin-review-summary-strip span {
  display: block;
  margin-top: 0.2rem;
  color: #91a6af;
  font-size: 0.65rem;
}
.admin-review-summary-actions {
  display: flex;
  gap: 0.35rem;
  flex-wrap: wrap;
}
.admin-review-summary-actions button {
  border: 1px solid #2b4651;
  border-radius: 0.3rem;
  padding: 0.45rem 0.6rem;
  color: #9eb2ba;
  font-size: 0.6rem;
}
.admin-review-summary-actions button.is-active,
.admin-review-summary-actions button:hover {
  border-color: #1ed2aa;
  color: #45dfbe;
  background: rgba(29, 210, 170, 0.08);
}
.admin-review-queue-layout--single {
  display: block;
}
.admin-review-select {
  flex: 0 0 auto;
}
.admin-review-toolbar .admin-select select {
  max-width: 11rem;
}
.admin-review-more-filters {
  border: 1px solid #2c424c;
  border-radius: 0.35rem;
  padding: 0.48rem 0.6rem;
  color: #8fa4ad;
  font-size: 0.6rem;
}
.admin-review-thumb small {
  padding: 0.2rem;
  color: #8fa4ad;
  font-size: 0.5rem;
  line-height: 1.2;
  text-align: center;
}
.admin-review-id {
  color: #8da4ad;
  font-family: var(--font-mono);
  font-size: 0.62rem;
  font-weight: 500;
}
.admin-review-missing-media {
  display: grid;
  place-items: center;
  min-height: 3rem;
  padding: 0.75rem;
  color: #8da4ad;
  font-size: 0.65rem;
  text-align: center;
