.admin-review-console-shell .admin-console-nav a {
  display: flex;
  min-width: 0;
  align-items: center;
  border-radius: 0.42rem;
  padding: 0.66rem 0.62rem;
  color: #91a3b1;
  font-size: 0.72rem;
  text-decoration: none;
