.admin-review-console-topbar {
  grid-template-columns: minmax(0, 1fr) auto;
}
.admin-review-back-link {
  border: 1px solid #2b4651;
  border-radius: 0.35rem;
  padding: 0.5rem 0.7rem;
  color: #45dfbe;
  font-size: 0.65rem;
  text-decoration: none;
}
.admin-review-detail {
