}
.admin-review-detail .admin-review-layout {
  grid-template-columns: minmax(0, 1fr);
}
.admin-review-detail .admin-review-top-grid {
  grid-template-columns: minmax(0, 1.5fr) minmax(15rem, 1fr) minmax(15rem, 0.9fr);
