.admin-review-change-options {
  display: grid;
  gap: 0.35rem;
}
.admin-review-change-options label {
  color: #dbe9e5;
  font-size: 0.65rem;
}
.admin-review-change-options input {
  accent-color: #1ed2aa;
}
.admin-review-tab-stack {
  display: grid;
  gap: 0.75rem;
}
.admin-review-empty-state {
