  .admin-review-summary-strip {
    align-items: flex-start;
    flex-direction: column;
  }
  .admin-review-detail .admin-review-top-grid {
    grid-template-columns: 1fr;
  }
  .admin-review-ai-summary {
    align-items: flex-start;
    flex-direction: column;
  }
  .admin-review-console-topbar {
    padding: 0 1rem;
  }
  .admin-review-back-link {
    display: none;
  }
}
@media (max-width: 1100px) {
  .portfolio-overview-content {
    grid-template-columns: minmax(0, 1.35fr) minmax(0, 1fr);
  }
  .portfolio-overview-content > .portfolio-panel--holdings {
    grid-column: 1 / -1;
  }
  .portfolio-page--approved .portfolio-kpis {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}
@media (max-width: 760px) {
  .portfolio-page--approved .portfolio-kpis {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .portfolio-page--approved .portfolio-summary-kpi:last-child {
    grid-column: 1 / -1;
  }
  .portfolio-overview-content,
  .portfolio-overview-bottom {
    grid-template-columns: 1fr;
  }
  .portfolio-overview-content > .portfolio-panel--holdings {
    grid-column: auto;
  }
  .portfolio-page--approved .portfolio-overview-content .portfolio-panel {
    min-height: 0;
  }
  .portfolio-recent-order {
    grid-template-columns: minmax(0, 1fr) auto auto;
    gap: 0.45rem;
  }
  .portfolio-recent-order > .portfolio-order-asset {
    grid-column: 1 / -1;
  }
  .portfolio-recent-order > span:nth-child(4) {
    display: none;
  }
  .portfolio-page--approved .portfolio-table--holdings td:nth-child(n) {
    width: auto;
  }
}

