.portfolio-page {
  position: relative;
  isolation: isolate;
  min-height: 100vh;
  overflow: hidden;
  padding: 9px 0 36px;
  background:
    radial-gradient(circle at 51% 2%, rgba(17, 79, 64, 0.12), transparent 34%),
    radial-gradient(circle at 4% 46%, rgba(7, 70, 57, 0.08), transparent 31%),
    linear-gradient(180deg, #050a0e 0%, #061015 52%, #050b0f 100%);
