}

.portfolio-table-wrap td:last-child > a svg,
.portfolio-table-wrap td:last-child > button svg {
  width: 11px;
  height: 11px;
}

.portfolio-table-wrap td:last-child > button {
  width: 23px;
  height: 28px;
  margin-left: 10px;
  color: #2bdca7;
  vertical-align: middle;
}

.portfolio-analytics-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 18px;
  margin-top: 18px;
}

.portfolio-analytics-grid > article {
  height: 203px;
  padding: 16px 20px 0;
}

.portfolio-allocation-panel > div,
.portfolio-performance-panel > div {
  display: grid;
  min-height: 126px;
  align-items: center;
  grid-template-columns: 120px 1fr;
  gap: 12px;
}

.portfolio-allocation-donut {
  position: relative;
  width: 108px;
  height: 108px;
  border-radius: 50%;
  background: conic-gradient(
    #4ed5ab 0 38.1%,
    #72cbd0 38.1% 57.4%,
    #8752cc 57.4% 89%,
    #d9d73c 89% 100%
  );
  box-shadow: 0 0 28px rgba(55, 215, 170, 0.07);
  animation: portfolio-donut-in 800ms cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

.portfolio-allocation-donut::after {
  position: absolute;
  inset: 8px;
  border-radius: 50%;
  background: #081116;
  box-shadow: inset 0 2px 10px rgba(0, 0, 0, 0.72);
  content: "";
}

.portfolio-allocation-donut span {
  position: absolute;
  z-index: 1;
  inset: 0;
  display: grid;
  place-content: center;
  color: rgba(167, 180, 187, 0.75);
  font-size: 7px;
  text-align: center;
}

.portfolio-allocation-donut strong {
  display: block;
  margin-bottom: 3px;
  color: rgba(235, 240, 242, 0.96);
  font-size: 13px;
}

.portfolio-allocation-panel ul {
  display: grid;
  gap: 13px;
}

.portfolio-allocation-panel li {
  display: grid;
  grid-template-columns: 8px minmax(0, 1fr) auto auto;
  align-items: center;
  gap: 8px;
  font-size: 8px;
}

.portfolio-allocation-panel li i {
  width: 8px;
  height: 8px;
  border-radius: 50%;
}

.portfolio-allocation-panel li i.is-lime {
  background: #d7dc4c;
}

.portfolio-allocation-panel li i.is-cyan {
  background: #72cbd0;
}

.portfolio-allocation-panel li i.is-violet {
  background: #8752cc;
}

.portfolio-allocation-panel li i.is-purple {
  background: #6e38b8;
}

.portfolio-allocation-panel li strong {
  font-weight: 600;
}

.portfolio-allocation-panel li small {
  min-width: 42px;
  color: rgba(146, 162, 170, 0.75);
  text-align: right;
}

.portfolio-analytics-grid article > a {
  display: flex;
  height: 39px;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border-top: 1px solid rgba(139, 167, 177, 0.09);
  color: rgba(184, 195, 201, 0.78);
  font-size: 8px;
}

.portfolio-analytics-grid article > a svg {
  width: 9px;
  height: 9px;
  color: #2bdca7;
}

.portfolio-performance-panel > div {
  grid-template-columns: 1.08fr 0.92fr;
}

.portfolio-performance-panel dl {
  display: grid;
  gap: 11px;
}

.portfolio-performance-panel dl > div {
  display: grid;
  grid-template-columns: 1fr auto auto;
  gap: 13px;
  font-size: 8px;
}

.portfolio-performance-panel dt {
  color: rgba(163, 177, 185, 0.76);
}

.portfolio-performance-panel dd:nth-child(2) {
  color: #d4dc46;
}

.portfolio-performance-panel dd:nth-child(3) {
  color: #2bdca7;
}

.portfolio-performance-spark {
  height: 67px;
  filter: drop-shadow(0 0 6px rgba(43, 220, 167, 0.11));
}

.portfolio-health-panel ul {
  min-height: 126px;
  padding-top: 10px;
}

.portfolio-health-panel li {
  display: grid;
  min-height: 29px;
  grid-template-columns: 14px minmax(0, 1fr) auto 69px;
  align-items: center;
  gap: 8px;
  border-bottom: 1px solid rgba(139, 167, 177, 0.06);
  font-size: 8px;
}

.portfolio-health-panel li:last-child {
  border-bottom: 0;
}

.portfolio-health-panel li > svg {
  width: 10px;
  height: 10px;
  color: rgba(43, 220, 167, 0.42);
}

.portfolio-health-panel li > span {
  color: rgba(165, 179, 186, 0.78);
}

.portfolio-health-panel li > strong {
  font-size: 10px;
}

.portfolio-health-panel li > em {
  justify-self: end;
  padding: 3px 7px;
  border-radius: 5px;
  font-size: 7px;
  font-style: normal;
}

.portfolio-health-panel li > em.is-mint {
  background: rgba(39, 208, 158, 0.1);
  color: #2bdca7;
}

.portfolio-health-panel li > em.is-lime {
  background: rgba(205, 216, 55, 0.1);
  color: #d6db4c;
}

.portfolio-health-panel li > em.is-coral {
  background: rgba(236, 74, 80, 0.11);
  color: #f05b60;
}

@keyframes portfolio-donut-in {
  from {
    opacity: 0;
    transform: rotate(-45deg) scale(0.86);
  }
  to {
    opacity: 1;
    transform: rotate(0) scale(1);
  }
}

@media (max-width: 1100px) {
