    padding-inline: 15px;
  }
  .portfolio-kpi:nth-child(3),
  .portfolio-kpi:nth-child(5) {
    border-left: 0;
  }
  .portfolio-kpi:nth-child(3),
  .portfolio-kpi:nth-child(4),
  .portfolio-kpi:nth-child(5),
