    height: 48px;
  }
  .portfolio-mini-donut::after {
    width: 37px;
    height: 37px;
    margin: 5.5px;
  }
  .portfolio-overview-grid {
    margin-top: 15px;
  }
  .portfolio-equity-panel {
    height: 300px;
  }
  .portfolio-equity-chart {
    height: 204px;
    padding-right: 14px;
  }
  .portfolio-periods {
    gap: 8px;
  }
  .portfolio-alerts-panel {
    height: auto;
  }
  .portfolio-alerts-panel li {
    min-height: 64px;
    grid-template-columns: 30px minmax(0, 1fr);
  }
  .portfolio-alerts-panel li p {
    overflow: visible;
    white-space: normal;
  }
  .portfolio-alerts-panel time {
    display: none;
  }
  .portfolio-investments > header {
    height: 43px;
  }
  .portfolio-table-wrap {
    overflow: visible;
    border: 0;
    background: transparent;
    box-shadow: none;
  }
  .portfolio-table-wrap table,
  .portfolio-table-wrap tbody,
  .portfolio-table-wrap tr,
  .portfolio-table-wrap td {
    display: block;
    width: 100%;
    min-width: 0;
  }
  .portfolio-table-wrap thead {
    display: none;
  }
  .portfolio-table-wrap tbody {
    display: grid;
    gap: 10px;
  }
  .portfolio-table-wrap tbody tr {
    display: grid;
    height: auto;
    grid-template-columns: 1fr 1fr;
    overflow: hidden;
    padding: 14px;
    border: 1px solid rgba(132, 163, 174, 0.17);
    border-radius: 8px;
    background: linear-gradient(145deg, rgba(11, 21, 27, 0.97), rgba(5, 12, 16, 0.99));
  }
  .portfolio-table-wrap tbody tr:hover {
    transform: translateY(-2px);
  }
  .portfolio-table-wrap td {
    padding: 10px 4px;
