@media (prefers-reduced-motion: reduce) {
  .portfolio-mini-donut,
  .portfolio-allocation-donut {
    animation: none;
  }
}

@layer base {
  html,
  body {
    background-color: var(--color-background);
    color: var(--color-foreground);
    font-family: var(--font-sans);
    -webkit-font-smoothing: antialiased;
    text-rendering: optimizeLegibility;
  }
  body {
    overflow-x: hidden;
  }
  * {
    border-color: var(--color-border);
  }
  *:focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
  }
  button,
  a,
  input,
  select,
  textarea {
    -webkit-tap-highlight-color: transparent;
  }
  ::selection {
    background: rgba(34, 211, 165, 0.28);
    color: #08090c;
  }
  img {
    max-width: 100%;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
  }
}

@utility tabular {
  font-variant-numeric: tabular-nums;
}

.site-shell {
  width: min(calc(100% - 3rem), 90rem);
  margin-inline: auto;
}

@media (max-width: 640px) {
  .site-shell {
    width: min(100% - 2rem, 74.25rem);
  }
}

.page-shell {
  width: min(calc(100% - 3rem), 90rem);
  margin-inline: auto;
}

.page-kicker {
  color: var(--color-accent);
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.page-title {
  font-family: var(--font-display);
  font-size: clamp(2.35rem, 4.2vw, 4.6rem);
  font-weight: 750;
  line-height: 0.96;
  letter-spacing: -0.055em;
}

.premium-surface {
  border: 1px solid var(--color-border);
  border-radius: 0.9rem;
  background: linear-gradient(145deg, rgba(20, 25, 32, 0.94), rgba(9, 13, 18, 0.98));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.045),
    0 20px 48px rgba(0, 0, 0, 0.22);
}

/* Shared customer-facing form, loading, and responsive state treatment. */
.auth-shell {
  width: min(calc(100% - 2rem), 72rem);
  margin-inline: auto;
  display: grid;
  gap: 2.5rem;
  padding-block: clamp(3.5rem, 8vw, 6rem);
}

/* Secure signup and onboarding: shares the dark Slice shell, with a focused editorial
 * treatment for account creation rather than a standalone application aesthetic. */
.signup-page {
  width: min(calc(100% - 3rem), 72rem);
  margin-inline: auto;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(23rem, 24rem);
  gap: clamp(2.5rem, 5vw, 5rem);
  align-items: start;
  min-height: calc(100vh - 13rem);
  padding-block: clamp(3rem, 6vw, 5.25rem);
}

.signup-hero {
  position: relative;
  max-width: 36rem;
  min-height: clamp(31rem, 37vw, 34rem);
  isolation: isolate;
}
.signup-hero > :not(.signup-collectible) {
  position: relative;
  z-index: 1;
}
.signup-hero__title {
  margin-top: 0.75rem;
  font-family: var(--font-display);
  font-size: clamp(3rem, 4.6vw, 4.5rem);
  font-weight: 750;
  line-height: 0.92;
  letter-spacing: -0.068em;
}
.signup-hero__title span {
  color: var(--color-accent);
  display: block;
}
.signup-hero__copy {
  max-width: 26rem;
  margin-top: 1.25rem;
