  gap: 0.75rem;
}
.signup-benefits__icon,
.onboarding-step__icon {
  display: flex;
  width: 2.5rem;
  height: 2.5rem;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  border: 1px solid color-mix(in srgb, var(--color-accent) 26%, var(--color-border));
  border-radius: 0.7rem;
  color: var(--color-accent);
  background: color-mix(in srgb, var(--color-accent) 7%, var(--color-surface));
}
.signup-benefits__icon svg,
.onboarding-step__icon svg {
  width: 1.2rem;
  height: 1.2rem;
  stroke-width: 1.8;
}
.signup-benefits strong,
.signup-benefits small {
