}
.signup-collectible img {
  display: block;
  width: 100%;
  height: auto;
  object-fit: contain;
  -webkit-mask-image: radial-gradient(
    ellipse 82% 76% at 67% 58%,
    #000 42%,
    rgba(0, 0, 0, 0.94) 58%,
    rgba(0, 0, 0, 0.52) 75%,
    transparent 100%
  );
  mask-image: radial-gradient(
    ellipse 82% 76% at 67% 58%,
    #000 42%,
    rgba(0, 0, 0, 0.94) 58%,
    rgba(0, 0, 0, 0.52) 75%,
    transparent 100%
  );
