.onboarding-progress li > span {
  display: grid;
  width: 1.45rem;
  height: 1.45rem;
  place-items: center;
  z-index: 1;
  border: 1px solid var(--color-border-strong);
  border-radius: 999px;
  background: var(--color-background);
  font-size: 0.68rem;
}
.onboarding-progress li[data-active="true"],
.onboarding-progress li[data-complete="true"] {
  color: var(--color-foreground);
}
.onboarding-progress li[data-active="true"] > span,
.onboarding-progress li[data-complete="true"] > span {
  border-color: var(--color-accent);
  background: var(--color-accent);
  color: var(--color-background);
}
.onboarding-progress svg {
  width: 0.8rem;
  height: 0.8rem;
}
.onboarding-step {
  display: grid;
  justify-items: center;
  max-width: 30rem;
  margin-inline: auto;
  text-align: center;
}
.onboarding-step__icon {
  width: 4.6rem;
  height: 4.6rem;
  margin-bottom: 1.15rem;
  border-radius: 999px;
  box-shadow: 0 0 34px color-mix(in srgb, var(--color-accent) 17%, transparent);
}
.onboarding-step__icon svg {
  width: 2rem;
  height: 2rem;
}
.onboarding-step h1 {
  margin-top: 0.4rem;
  font-family: var(--font-display);
  font-size: clamp(1.9rem, 5vw, 2.75rem);
  font-weight: 740;
  letter-spacing: -0.06em;
}
.onboarding-step__lead {
  max-width: 26rem;
  margin-top: 0.55rem;
  color: var(--color-subtle);
  font-size: 0.88rem;
  line-height: 1.55;
}
.onboarding-step__body {
  display: grid;
  width: min(100%, 25rem);
  gap: 0.85rem;
  margin-top: 1.55rem;
  text-align: left;
}
.onboarding-step__body .form-field > span {
  font-size: 0.78rem;
  font-weight: 600;
}
.onboarding-callout {
  display: flex;
  align-items: flex-start;
  gap: 0.55rem;
  border: 1px solid var(--color-border);
  border-radius: 0.65rem;
  padding: 0.75rem;
  color: var(--color-subtle);
  font-size: 0.76rem;
  line-height: 1.45;
}
.onboarding-callout svg {
  width: 1rem;
  flex: 0 0 auto;
  color: var(--color-accent);
}
.onboarding-link {
  justify-self: center;
  padding: 0.3rem 0.6rem;
  font-size: 0.78rem;
}
.onboarding-link:disabled {
  color: var(--color-subtle);
  cursor: not-allowed;
}
.onboarding-otp {
  text-align: center;
  font-family: var(--font-mono);
  font-size: 1.35rem;
  letter-spacing: 0.52em;
}
.onboarding-checklist,
.onboarding-finish {
  display: grid;
  gap: 0.6rem;
  margin: 0;
  padding: 0;
  list-style: none;
  color: var(--color-subtle);
  font-size: 0.8rem;
}
.onboarding-checklist li,
.onboarding-finish li {
  display: flex;
  align-items: center;
  gap: 0.55rem;
}
.onboarding-checklist svg,
.onboarding-finish li[data-complete="true"] svg {
  width: 1rem;
  height: 1rem;
  color: var(--color-accent);
}
.onboarding-finish li[data-complete="false"] {
  opacity: 0.78;
}
.authenticator-setup {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 1rem;
  align-items: center;
  border: 1px solid var(--color-border);
  border-radius: 0.7rem;
  padding: 1rem;
}
.authenticator-setup svg {
  width: 8.1rem;
  height: 8.1rem;
  border-radius: 0.3rem;
  background: white;
  padding: 0.25rem;
}
.authenticator-setup p {
  margin-bottom: 0.45rem;
  color: var(--color-subtle);
  font-size: 0.72rem;
  line-height: 1.4;
}
.authenticator-setup code,
.recovery-codes code {
  overflow-wrap: anywhere;
  border-radius: 0.35rem;
  background: var(--color-background);
  padding: 0.45rem 0.55rem;
  color: var(--color-foreground);
  font-size: 0.7rem;
}
.onboarding-copy,
.recovery-actions {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  margin-top: 0.6rem;
  color: var(--color-accent);
  font-size: 0.72rem;
  font-weight: 700;
}
.onboarding-copy svg,
.recovery-actions svg {
  width: 0.9rem;
  height: 0.9rem;
}
.recovery-codes {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.45rem;
  border: 1px solid var(--color-border);
  border-radius: 0.7rem;
  padding: 0.7rem;
}
.recovery-actions {
  justify-content: center;
}
.secondary-action {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  border: 1px solid var(--color-border-strong);
  border-radius: 0.45rem;
  padding: 0.5rem 0.65rem;
  color: var(--color-foreground);
  font-size: 0.72rem;
}
.onboarding-error {
  width: min(100%, 30rem);
  margin: 0 auto 1rem;
  text-align: center;
}

