}

.international-phone-input {
  display: grid;
  gap: 0.7rem;
}

.international-phone-input__country,
.international-phone-input__number {
  display: grid;
  gap: 0.42rem;
}

.international-phone-input__country > span,
.international-phone-input__number > span {
  color: var(--color-subtle);
  font-size: 0.78rem;
  font-weight: 600;
}

.international-phone-input select {
  appearance: auto;
}

.international-phone-input small {
  color: var(--color-muted);
  font-size: 0.72rem;
  line-height: 1.45;
}

.form-control {
  width: 100%;
  min-height: 2.9rem;
  border: 1px solid var(--color-border);
  border-radius: 0.5rem;
  background: var(--color-background);
  padding: 0.7rem 0.75rem;
  color: var(--color-foreground);
  font-size: 0.875rem;
  transition:
    border-color 160ms ease,
    box-shadow 160ms ease;
}

.form-control:focus {
  border-color: color-mix(in srgb, var(--color-accent) 68%, var(--color-border));
  outline: 0;
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--color-accent) 16%, transparent);
}

.form-error {
  border-left: 2px solid var(--color-destructive);
  color: var(--color-destructive);
  font-size: 0.875rem;
  padding-left: 0.65rem;
}

.customer-state {
  border: 1px solid var(--color-border);
  border-radius: 1rem;
  background: var(--color-elevated);
  padding: clamp(1.5rem, 4vw, 2rem);
}

.customer-skeleton {
  border-radius: 0.6rem;
  background: linear-gradient(
    100deg,
    var(--color-surface) 28%,
    var(--color-elevated) 45%,
    var(--color-surface) 62%
  );
  background-size: 220% 100%;
  animation: slice-skeleton 1.4s ease-in-out infinite;
}

@keyframes slice-skeleton {
  to {
    background-position: -220% 0;
  }
}

@media (min-width: 768px) {
  .auth-shell {
    grid-template-columns: minmax(0, 0.9fr) minmax(0, 1.1fr);
    align-items: center;
  }
}

@media (max-width: 767px) {
  .auth-card {
    max-width: none;
    justify-self: stretch;
  }
}

@media (max-width: 640px) {
  .page-shell {
    width: min(calc(100% - 2rem), 90rem);
  }
}

/* ---------------------------------------------------------------- shared */

.skip-link {
  position: absolute;
  left: -9999px;
  z-index: 100;
  padding: 0.65rem 1rem;
  border-radius: 0 0 8px 0;
  background: var(--color-accent);
  color: #06231b;
  font-size: 13px;
  font-weight: 600;
}
.skip-link:focus {
  left: 0;
  top: 0;
}

.primary-action {
  background: linear-gradient(135deg, #2fe0b2 0%, #17bd8f 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.32),
    0 6px 16px rgba(34, 211, 165, 0.14);
  transition:
    transform 180ms cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 180ms ease,
    filter 180ms ease;
}
.primary-action:hover {
  filter: brightness(1.04);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.38),
    0 9px 22px rgba(34, 211, 165, 0.22);
  transform: translateY(-1px);
}
.primary-action:active {
  transform: translateY(0) scale(0.99);
}

.secondary-action {
  background: rgba(255, 255, 255, 0.015);
  transition:
    transform 180ms cubic-bezier(0.22, 1, 0.36, 1),
    background-color 180ms ease,
    border-color 180ms ease;
}
.secondary-action:hover {
  border-color: rgba(255, 255, 255, 0.28);
  background: rgba(255, 255, 255, 0.05);
  transform: translateY(-1px);
}

.panel,
.featured-panel {
  min-width: 0;
  background: var(--surface-raised);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.06),
    var(--shadow-soft);
}
.featured-panel {
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.08),
    var(--shadow-lifted);
}

.grade-chip {
  display: inline-flex;
  align-items: center;
  padding: 0.15rem 0.5rem;
  border: 1px solid var(--color-border-strong);
  border-radius: 999px;
  background: var(--color-surface);
  color: var(--color-subtle);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.02em;
}

.range-control {
  padding: 0.18rem 0.55rem;
  border: 1px solid transparent;
  border-radius: 999px;
  font-size: 8.5px;
  font-weight: 600;
  transition:
    color 160ms ease,
    background-color 160ms ease,
    border-color 160ms ease;
}
.range-control:hover {
  color: var(--color-foreground);
}
.range-control--active {
  border-color: var(--color-border-strong);
  background: var(--color-surface);
  color: var(--color-foreground);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08);
}

/* ------------------------------------------------------------ navigation */

.nav-link {
  position: relative;
  transition:
    color 160ms ease,
    background-color 160ms ease;
}
.nav-link::after {
  position: absolute;
  right: 0.75rem;
  bottom: 0.15rem;
  left: 0.75rem;
  height: 2px;
  border-radius: 99px;
  background: var(--color-accent);
  content: "";
  opacity: 0;
  transform: scaleX(0.4);
  transition:
    opacity 160ms ease,
    transform 200ms cubic-bezier(0.22, 1, 0.36, 1);
}
.nav-link:hover {
  color: var(--color-foreground);
}
.nav-link--active::after {
  opacity: 1;
  transform: scaleX(1);
}

.header-icon {
  transition:
    background-color 160ms ease,
    color 160ms ease;
}
.header-icon:hover {
  background: rgba(255, 255, 255, 0.05);
  color: var(--color-foreground);
}
.header-icon__badge {
  position: absolute;
  top: 7px;
  right: 8px;
  width: 6px;
  height: 6px;
  border: 1.5px solid var(--color-background);
  border-radius: 999px;
  background: var(--color-accent);
}

.market-tape__item {
  transition: color 160ms ease;
}
.market-tape__item:hover {
  color: var(--color-accent);
}
.market-tape__dot {
  width: 5px;
  height: 5px;
  border-radius: 999px;
  background: var(--color-positive);
  animation: tape-pulse 2.4s ease-in-out infinite;
}

/* ------------------------------------------------------------------ hero */

.home-hero {
  background-image:
    radial-gradient(ellipse 42% 70% at 54% 52%, rgba(34, 211, 165, 0.07), transparent 72%),
    linear-gradient(rgba(255, 255, 255, 0.012) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.012) 1px, transparent 1px);
  background-size:
    auto,
    64px 64px,
    64px 64px;
}
.home-hero__inner {
  display: grid;
  align-items: start;
  gap: 2.5rem;
  padding-block: 0.625rem;
}
@media (min-width: 1280px) {
  .home-hero__inner {
    grid-template-columns: 21rem minmax(0, 1fr);
    gap: clamp(2.5rem, 3vw, 4rem);
    padding-block: 1.5rem;
  }
  .hero-copy {
    padding-top: 0.3rem;
  }
}
.hero-copy > * {
  animation: rise-in 520ms cubic-bezier(0.22, 1, 0.36, 1) both;
}
.hero-copy > :nth-child(2) {
  animation-delay: 60ms;
}
.hero-copy > :nth-child(3) {
  animation-delay: 120ms;
}
.hero-copy > :nth-child(4) {
  animation-delay: 180ms;
}
.hero-copy > :nth-child(5) {
  animation-delay: 240ms;
}

/* ------------------------------------------------- hero asset module */

/* Two sibling panels — no shared enclosure, no divider. */
.hero-module {
  display: grid;
  width: 100%;
  max-width: 48rem;
  justify-items: center;
  gap: 2rem;
}

/* Shared API/mock featured presentation. The data source changes the content, never the layout. */
.featured-market-hero {
  display: grid;
  width: 100%;
  max-width: 42.1875rem;
  justify-items: center;
  gap: 1rem;
}
.featured-showcase,
.featured-static-panel {
  width: 100%;
  border: 1px solid rgba(155, 181, 194, 0.16);
  border-radius: 10px;
  background:
    radial-gradient(circle at 76% 0%, rgba(35, 123, 101, 0.14), transparent 43%),
    linear-gradient(180deg, #131a21 0%, #090e12 100%);
  box-shadow:
    inset 0 1px 0 rgba(222, 255, 249, 0.055),
    0 22px 46px rgba(0, 0, 0, 0.42);
}
.featured-showcase {
  position: relative;
  display: grid;
  min-height: 14.5rem;
  max-width: 14rem;
  place-items: center;
  padding: 0.65rem;
  overflow: hidden;
  isolation: isolate;
}
.featured-showcase::after {
  position: absolute;
  right: -12%;
  bottom: -20%;
  left: -12%;
  height: 50%;
  z-index: 0;
  background: radial-gradient(ellipse at center, rgba(34, 211, 165, 0.25), transparent 68%);
  content: "";
  filter: blur(18px);
  pointer-events: none;
}
.featured-showcase__surface {
  position: relative;
  z-index: 1;
  display: grid;
  width: 100%;
  height: 100%;
  min-height: 0;
  place-items: center;
  overflow: hidden;
  border: 1px solid rgba(151, 255, 226, 0.16);
  border-radius: 10px;
  background:
    linear-gradient(
      108deg,
      rgba(255, 255, 255, 0.045),
      transparent 13% 86%,
      rgba(82, 232, 193, 0.035)
    ),
    linear-gradient(180deg, rgba(12, 19, 24, 0.94) 0%, rgba(5, 13, 16, 0.98) 100%);
  box-shadow:
    inset 0 0 0 5px rgba(5, 13, 17, 0.68),
    inset 0 0 0 6px rgba(121, 255, 219, 0.09),
    inset 0 -38px 55px rgba(8, 89, 67, 0.2);
}
.featured-showcase__surface::before {
  position: absolute;
  top: 0;
  left: 50%;
  width: 165%;
  height: 34%;
  background: linear-gradient(
    108deg,
    transparent 32%,
    rgba(255, 255, 255, 0.045) 46%,
    rgba(106, 255, 219, 0.055) 49%,
    transparent 62%
  );
  content: "";
  transform: translateX(-72%);
  pointer-events: none;
}
.featured-showcase__surface::after {
  position: absolute;
  right: -8%;
  bottom: -12%;
  left: -8%;
  height: 48%;
  background: radial-gradient(ellipse at 50% 100%, rgba(34, 211, 165, 0.18), transparent 66%);
  content: "";
  filter: blur(18px);
  pointer-events: none;
}
.featured-showcase__image {
  position: absolute;
  top: 0.375rem;
  left: 50%;
  z-index: 2;
  display: block;
  width: auto;
  height: calc(100% - 0.75rem);
  max-width: calc(100% - 1rem);
  max-height: none;
  object-fit: contain;
  filter: saturate(1.04) contrast(1.02);
  transform: translateX(-50%);
}
.featured-showcase__pedestal {
  position: absolute;
  bottom: 0.55rem;
  left: 50%;
  z-index: 2;
  width: 88%;
  height: 1.05rem;
  border: 1px solid rgba(34, 211, 165, 0.72);
  border-radius: 50%;
  background: rgba(2, 15, 13, 0.38);
  box-shadow:
    0 0 18px rgba(34, 211, 165, 0.2),
    inset 0 1px 7px rgba(84, 255, 211, 0.22);
  transform: translateX(-50%);
}
.featured-showcase__badge {
  position: absolute;
  bottom: 0.3rem;
  left: 50%;
  z-index: 3;
  display: grid;
  width: 5.35rem;
  height: 1.8rem;
  grid-template-columns: 1fr;
  align-items: center;
  overflow: hidden;
  border: 1px solid rgba(154, 184, 196, 0.28);
  border-radius: 0.22rem;
  background: linear-gradient(135deg, #14252b, #080f12 55%, #152c30);
  box-shadow: 0 5px 12px rgba(0, 0, 0, 0.4);
  color: #d9f6ed;
  transform: translateX(-50%);
}
.featured-showcase__badge > span {
  display: grid;
  justify-items: center;
  gap: 0.02rem;
  line-height: 1;
}
.featured-showcase__badge b {
  font-size: 0.45rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.featured-showcase__badge small {
  color: #9cb3b0;
  font-size: 0.35rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}
.featured-static-panel {
  display: flex;
  min-height: 14.5rem;
  max-width: 26.75rem;
  flex-direction: column;
  padding: 0.75rem;
}
.featured-static-panel h2 {
  margin-top: 0.15rem;
  font-family: var(--font-display);
  font-size: 1.05rem;
  font-weight: 750;
  letter-spacing: -0.045em;
  line-height: 1.05;
}
.featured-static-panel__subtitle {
  margin-top: 0.05rem;
  color: var(--color-subtle);
  font-size: 0.72rem;
  line-height: 1.1;
}
.featured-static-panel__price {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-top: 0.45rem;
}
.featured-static-panel__price strong {
  font-family: var(--font-display);
  font-size: 1.35rem;
  letter-spacing: -0.05em;
  line-height: 1;
}
.featured-static-panel__price span {
  color: var(--color-accent);
  font-size: 0.76rem;
  font-weight: 750;
}
.featured-static-panel__price small {
  color: var(--color-subtle);
  font-size: inherit;
  font-weight: 600;
}
.featured-static-panel__chart {
  position: relative;
  flex: 0 0 4.75rem;
  height: 4.75rem;
  margin-top: 0.35rem;
  overflow: hidden;
  border-top: 1px solid rgba(137, 167, 180, 0.1);
  border-bottom: 1px solid rgba(137, 167, 180, 0.1);
  background:
    linear-gradient(rgba(143, 172, 186, 0.055) 1px, transparent 1px),
    linear-gradient(90deg, rgba(143, 172, 186, 0.035) 1px, transparent 1px);
  background-size:
    100% 2.5rem,
    4.5rem 100%;
}
.featured-static-panel__chart svg {
  display: block;
  width: 100%;
  height: 100%;
}
.featured-static-panel__price-label {
  position: absolute;
  right: 0.35rem;
  color: var(--color-muted);
  font-size: 0.58rem;
  font-weight: 650;
}
.featured-static-panel__price-label--high {
  top: 0.28rem;
}
.featured-static-panel__price-label--upper-middle {
  top: 1.35rem;
}
.featured-static-panel__price-label--middle {
  top: 2.5rem;
}
.featured-static-panel__price-label--low {
  bottom: 0.28rem;
}
.featured-static-panel__ranges {
  display: flex;
  flex: none;
  align-items: center;
  justify-content: space-between;
  gap: 0.35rem;
  margin-top: 0.15rem;
  color: var(--color-muted);
  font-size: 0.56rem;
  font-weight: 700;
}
.featured-static-panel__ranges span {
  display: grid;
  min-width: 1.65rem;
  min-height: 1rem;
  place-items: center;
  border-radius: 999px;
}
.featured-static-panel__ranges .is-active {
  border: 1px solid rgba(133, 166, 178, 0.18);
  background: rgba(255, 255, 255, 0.06);
  color: var(--color-foreground);
}
.featured-static-panel__stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.7rem;
  margin-top: auto;
  border-top: 1px solid rgba(137, 167, 180, 0.12);
  padding-top: 0.42rem;
}
.featured-static-panel__stats div {
  min-width: 0;
}
.featured-static-panel__stats dt {
  color: var(--color-muted);
  font-size: 0.5rem;
  font-weight: 650;
  letter-spacing: 0.045em;
  text-transform: uppercase;
}
.featured-static-panel__stats dd {
  margin: 0.16rem 0 0;
  color: var(--color-foreground);
  font-size: 0.65rem;
  font-weight: 700;
  line-height: 1.3;
}
.hero-copy__headline span {
  display: block;
}
.featured-market-panel {
  min-height: 20.5rem;
  height: auto;
}
.featured-market-panel__heading {
  display: flex;
  min-height: 3.35rem;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.75rem;
}
.featured-market-panel__status {
  flex: none;
  padding: 0.24rem 0.44rem;
  border: 1px solid rgba(66, 224, 170, 0.22);
  border-radius: 999px;
  background: rgba(24, 166, 122, 0.1);
  color: var(--color-accent);
  font-size: 0.63rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.featured-market-panel__value-row {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 0.75rem;
  padding-top: 0.7rem;
}
.featured-market-panel__value-row > div {
  display: grid;
  gap: 0.16rem;
}
.featured-market-panel__value-row span:first-child,
.featured-market-panel__chart-header > span,
.featured-market-panel__facts dt {
  color: var(--color-muted);
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
.featured-market-panel__value-row strong {
  font-family: var(--font-display);
  font-size: 1.35rem;
  letter-spacing: -0.04em;
}
.featured-market-panel__value-row .is-positive,
.featured-market-panel__value-row .is-negative {
  padding-bottom: 0.14rem;
  font-size: 0.75rem;
  font-weight: 700;
}
.featured-market-panel__value-row .is-positive {
  color: var(--color-accent);
}
.featured-market-panel__value-row .is-negative {
  color: #fb7185;
}
.featured-market-panel__chart-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  margin-top: 0.85rem;
}
.featured-market-panel__ranges {
  display: inline-flex;
  max-width: 100%;
  overflow-x: auto;
  border: 1px solid rgba(137, 167, 180, 0.16);
  border-radius: 0.45rem;
}
.featured-market-panel__ranges button {
  min-width: 1.75rem;
  min-height: 1.6rem;
  padding: 0 0.32rem;
  border: 0;
  background: transparent;
  color: var(--color-muted);
  font-size: 0.62rem;
  font-weight: 700;
}
.featured-market-panel__ranges button:hover,
.featured-market-panel__ranges button:focus-visible,
.featured-market-panel__ranges button.is-active {
  background: rgba(31, 208, 156, 0.14);
  color: var(--color-accent);
}
.featured-market-panel__chart {
  display: grid;
  min-height: 6.6rem;
  place-items: center;
  margin-top: 0.34rem;
  border-radius: 0.55rem;
  background: linear-gradient(180deg, rgba(13, 30, 30, 0.38), rgba(6, 11, 14, 0.06));
}
.featured-market-panel__chart .price-chart {
  width: 100%;
}
.featured-market-panel__history-empty {
  display: grid;
  max-width: 15rem;
  place-items: center;
  gap: 0.42rem;
  color: var(--color-subtle);
  font-size: 0.75rem;
  line-height: 1.4;
  text-align: center;
}
.featured-market-panel__history-empty svg {
  width: 1.2rem;
  height: 1.2rem;
  color: var(--color-accent);
}
.featured-market-panel__facts {
  display: flex;
  flex-wrap: wrap;
  gap: 0.42rem 1rem;
  margin-top: 0.6rem;
}
.featured-market-panel__facts div {
  display: grid;
  gap: 0.1rem;
}
.featured-market-panel__facts dd {
  margin: 0;
  color: var(--color-foreground);
  font-size: 0.75rem;
  font-weight: 650;
}
.featured-market-panel__cta {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  margin-top: auto;
  padding-top: 0.72rem;
  color: var(--color-accent);
  font-size: 0.8rem;
  font-weight: 700;
}
.featured-market-panel__cta:hover {
  text-decoration: underline;
}
.featured-market-panel__empty {
  display: grid;
  flex: 1;
  align-content: center;
  gap: 0.6rem;
  padding: 1.25rem 0 0.25rem;
}
.featured-market-panel__empty p {
  max-width: 20rem;
  color: var(--color-subtle);
  font-size: 0.86rem;
  line-height: 1.55;
}
@media (min-width: 768px) {
  .featured-market-hero {
    grid-template-columns: minmax(13rem, 14rem) minmax(0, 26.75rem);
    align-items: stretch;
    gap: 1.4375rem;
  }
  .featured-showcase,
  .featured-static-panel {
    height: 14.5rem;
  }
  .featured-showcase,
  .featured-static-panel {
    max-width: none;
  }
}
@media (min-width: 1280px) {
  .hero-module {
    grid-template-columns: 17.5rem 28.75rem;
    gap: 1.75rem;
  }
  .featured-market-hero {
    max-width: 42.1875rem;
  }
}
@media (min-width: 1800px) {
  .home-hero__inner {
    grid-template-columns: 24rem minmax(58rem, 1fr);
    gap: 3rem;
  }
  /* Keep the editorial asset module at its approved art-directed size on
     ultrawide displays.  Expanding it here made the artwork and chart read
     like a second hero instead of the compact paired showcase. */
  .hero-module {
    max-width: 48rem;
    grid-template-columns: 17.5rem 28.75rem;
    gap: 1.75rem;
  }
  .featured-market-hero {
    max-width: 42.1875rem;
    grid-template-columns: 14rem minmax(0, 26.75rem);
    gap: 1.4375rem;
  }
}

/* Right-hand analytics panel. */
.hero-panel {
  display: flex;
  width: 100%;
  max-width: 28.75rem;
  flex-direction: column;
  border: 1px solid rgba(155, 181, 194, 0.14);
  border-radius: 14px;
  background:
    radial-gradient(circle at 86% 0%, rgba(38, 75, 74, 0.12), transparent 42%),
    linear-gradient(180deg, #12181e 0%, #0a0e12 100%);
  box-shadow:
    inset 0 1px 0 rgba(220, 255, 247, 0.035),
    0 22px 46px rgba(0, 0, 0, 0.42);
}
@media (min-width: 1280px) {
  .hero-panel {
    height: 20.5rem;
  }
}

/* small abstract category tokens — no photographic avatars */
.hero-token {
  display: grid;
  width: 1.35rem;
  height: 1.35rem;
  place-items: center;
  border: 2px solid var(--color-background);
  border-radius: 999px;
  background: linear-gradient(145deg, #253038, #10151a);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.12);
  color: var(--color-accent);
  font-size: 6px;
  font-weight: 700;
  letter-spacing: -0.03em;
}

/* --------------------------------------------------- collectible vault */
/* Vault, inset surface, slab, pedestal, badge. Light and glow are pseudo-elements. */

.showcase {
  position: relative;
  width: 100%;
  max-width: 17.5rem;
  padding: 0.5rem;
  border: 1px solid rgba(155, 181, 194, 0.16);
  border-radius: 14px;
  background:
    radial-gradient(circle at 50% 100%, rgba(24, 151, 115, 0.1), transparent 45%),
    linear-gradient(180deg, #131a21 0%, #090e12 100%);
  box-shadow:
    inset 0 1px 0 rgba(222, 255, 249, 0.05),
    0 22px 46px rgba(0, 0, 0, 0.42);
  transition:
    transform 200ms cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 200ms ease;
}
@media (min-width: 1280px) {
  .showcase {
    height: 20.5rem;
  }
}
@media (min-width: 1800px) {
  .showcase {
    max-width: 20rem;
  }
  .hero-panel {
    max-width: 38rem;
  }
}
.showcase:hover {
  transform: translateY(-2px);
  box-shadow: 0 28px 56px rgba(0, 0, 0, 0.48);
}

.showcase__surface {
  position: relative;
  display: flex;
  height: 100%;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  gap: 0;
  padding: 0.5rem;
  border: 1px solid rgba(151, 255, 226, 0.16);
  border-radius: 10px;
  background:
    linear-gradient(
      108deg,
      rgba(255, 255, 255, 0.045),
      transparent 13% 86%,
      rgba(82, 232, 193, 0.035)
    ),
    linear-gradient(180deg, rgba(12, 19, 24, 0.94) 0%, rgba(5, 13, 16, 0.98) 100%);
  box-shadow:
    inset 0 0 0 5px rgba(5, 13, 17, 0.68),
    inset 0 0 0 6px rgba(121, 255, 219, 0.09),
    inset 0 -38px 55px rgba(8, 89, 67, 0.2);
}
.showcase__surface::before {
  position: absolute;
  top: 0;
  left: 50%;
  width: 165%;
  height: 34%;
  background: linear-gradient(
    108deg,
    transparent 32%,
    rgba(255, 255, 255, 0.045) 46%,
    rgba(106, 255, 219, 0.055) 49%,
    transparent 62%
  );
  content: "";
  transform: translateX(-72%);
  pointer-events: none;
  animation: vault-reflection 8s cubic-bezier(0.22, 1, 0.36, 1) 900ms infinite;
}
.showcase__surface::after {
  position: absolute;
  right: -8%;
  bottom: -12%;
  left: -8%;
  height: 48%;
  background: radial-gradient(ellipse at 50% 100%, rgba(34, 211, 165, 0.18), transparent 66%);
  content: "";
  filter: blur(18px);
  pointer-events: none;
}

.showcase__slab {
  position: relative;
  z-index: 1;
  display: block;
  width: auto;
  height: auto;
  max-width: 82%;
  /* always leave room for the pedestal so the slab can never be clipped */
  max-height: 97%;
  border-radius: 3px;
  object-fit: contain;
  box-shadow: 0 16px 30px rgba(0, 0, 0, 0.5);
  filter: saturate(1.04) contrast(1.02);
  transform: translateY(-0.45rem);
  image-rendering: auto;
}

.showcase__pedestal {
  position: absolute;
  bottom: 0.55rem;
  left: 50%;
  z-index: 1;
  width: 88%;
  height: 1.05rem;
  flex: none;
  border-radius: 50%;
  border: 1px solid rgba(34, 211, 165, 0.72);
  background: rgba(2, 15, 13, 0.38);
  box-shadow:
    0 0 18px rgba(34, 211, 165, 0.2),
    inset 0 1px 7px rgba(84, 255, 211, 0.22);
  transform: translateX(-50%);
}

/* Engraved grading plaque integrated into the illuminated pedestal. */
.showcase__badge {
  position: absolute;
  bottom: 0.3rem;
  left: 50%;
  z-index: 3;
  display: grid;
  width: 6.25rem;
  height: 2.15rem;
  grid-template-columns: 1fr 1.08fr;
  align-items: center;
  padding: 0.28rem 0.55rem;
  border: 1px solid rgba(151, 188, 181, 0.28);
  border-radius: 0.4rem;
  background:
    linear-gradient(115deg, rgba(255, 255, 255, 0.045), transparent 28%),
    linear-gradient(180deg, rgba(25, 32, 34, 0.98), rgba(6, 10, 12, 0.99));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.11),
    inset 0 -1px 0 rgba(34, 211, 165, 0.12),
    0 8px 18px rgba(0, 0, 0, 0.52),
    0 0 16px rgba(34, 211, 165, 0.08);
  color: var(--color-foreground);
  transform: translateX(-50%);
}
.showcase__badge::before {
  position: absolute;
  top: 50%;
  left: 0.22rem;
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: rgba(176, 206, 200, 0.48);
  box-shadow: 5.56rem 0 rgba(176, 206, 200, 0.48);
  content: "";
  transform: translateY(-50%);
}
.showcase__badge-service,
.showcase__badge-result {
  display: flex;
  min-width: 0;
  height: 100%;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  line-height: 1;
}
.showcase__badge-result {
  border-left: 1px solid rgba(158, 190, 184, 0.18);
}
.showcase__badge-label {
  background: linear-gradient(90deg, #ef6262 0 31%, #e8edf0 34% 63%, #5a98e8 67%);
  background-clip: text;
  color: transparent;
  font-family: var(--font-display);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.06em;
}
.showcase__badge-certification,
.showcase__badge-description {
  margin-top: 0.18rem;
  color: var(--color-muted);
  font-size: 5.5px;
  font-weight: 650;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}
.showcase__badge-grade {
  font-family: var(--font-display);
  font-size: 14px;
  font-weight: 750;
  letter-spacing: -0.045em;
}

.showcase__placeholder {
  display: grid;
  width: 70%;
  aspect-ratio: 2 / 3;
  place-items: center;
  border: 1px dashed var(--color-border-strong);
  border-radius: 6px;
}

/* --------------------------------------------------------- market strip */

.market-strip {
  background: linear-gradient(180deg, rgba(21, 26, 33, 0.7), rgba(9, 12, 16, 0.7));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.035);
}
.market-overview-section {
  padding-top: 1.25rem;
}
.market-strip__cell {
  padding: 0.75rem 1rem;
  transition: background-color 160ms ease;
}
.market-strip__cell:hover {
  background: rgba(255, 255, 255, 0.022);
}
.market-strip__cell--divided {
  border-top: 1px solid var(--color-border);
}
@media (min-width: 640px) {
  .market-strip__cell--divided:nth-child(2n) {
    border-top: 0;
    border-left: 1px solid var(--color-border);
  }
}
@media (min-width: 1280px) {
  .market-strip__cell--divided {
    border-top: 0;
    border-left: 1px solid var(--color-border);
  }
}

/* ----------------------------------------------------------- asset card */

.asset-card {
  background: var(--surface-raised);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.06),
    var(--shadow-soft);
  transition:
    transform 200ms cubic-bezier(0.22, 1, 0.36, 1),
    border-color 200ms ease,
    box-shadow 200ms ease;
}
.trending-section li {
  --card-accent: 34 211 165;
}
.trending-section li:nth-child(2) {
  --card-accent: 30 191 232;
}
.trending-section li:nth-child(4) {
  --card-accent: 217 70 239;
}
.trending-section li:nth-child(5) {
  --card-accent: 55 132 255;
}
.trending-section li:nth-child(6) {
  --card-accent: 244 63 94;
}
.asset-card--compact {
  padding: 0.375rem;
  border-color: rgb(var(--card-accent, 34 211 165) / 0.16);
  border-radius: 0.8rem;
  background:
    radial-gradient(circle at 50% 0%, rgb(var(--card-accent, 34 211 165) / 0.11), transparent 42%),
    linear-gradient(180deg, rgba(19, 25, 31, 0.98), rgba(11, 15, 20, 0.99));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.055),
    0 12px 26px rgba(0, 0, 0, 0.24);
}
.asset-card:hover {
  border-color: rgb(var(--card-accent, 34 211 165) / 0.38);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.1),
    0 0 0 1px rgb(var(--card-accent, 34 211 165) / 0.06),
    var(--shadow-lifted);
  transform: translateY(-4px);
}
.asset-card__image {
  position: relative;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 0.55rem;
  background: var(--color-surface);
  box-shadow:
    inset 0 0 0 1px rgb(var(--card-accent, 34 211 165) / 0.05),
    0 8px 18px rgba(0, 0, 0, 0.24);
}
.asset-card__image::after {
  position: absolute;
  inset: 50% 0 0;
  background: linear-gradient(180deg, transparent, rgba(4, 6, 8, 0.68));
  content: "";
  pointer-events: none;
}
.asset-card__image img {
  filter: saturate(0.96) contrast(1.025);
  transition:
    filter 300ms ease,
    transform 300ms cubic-bezier(0.22, 1, 0.36, 1);
}
.asset-card:hover .asset-card__image img {
  filter: saturate(1.05) contrast(1.035);
  transform: scale(1.035);
}
.asset-card__grade {
  padding: 0.18rem 0.5rem;
  border: 1px solid var(--color-border-strong);
  border-radius: 6px;
  background: rgba(8, 9, 12, 0.78);
  color: var(--color-foreground);
  font-size: 10px;
  font-weight: 700;
  backdrop-filter: blur(4px);
}
.asset-card--compact .asset-card__grade {
  padding: 0.15rem 0.4rem;
  border-color: rgb(var(--card-accent, 34 211 165) / 0.28);
  border-radius: 0.4rem;
  background: rgba(5, 9, 12, 0.74);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.06);
  color: rgba(255, 255, 255, 0.88);
  font-size: 8.5px;
  letter-spacing: 0.015em;
}
.asset-card--compact .asset-card__bookmark svg {
  width: 0.7rem;
  height: 0.7rem;
}
@media (min-width: 1280px) {
  .asset-card--compact {
    height: 15.5rem;
  }
  .asset-card--compact .asset-card__image {
    aspect-ratio: auto;
    flex: 0 0 9rem;
  }
}
.asset-card__title {
  display: -webkit-box;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}
.asset-card__bookmark {
  opacity: 0.85;
  transition:
    opacity 160ms ease,
    background-color 160ms ease,
    border-color 160ms ease;
  backdrop-filter: blur(4px);
}
.asset-card:hover .asset-card__bookmark,
.asset-card__bookmark:focus-visible,
.asset-card__bookmark[aria-pressed="true"] {
  opacity: 1;
}

/* -------------------------------------------------------------- panels */

@media (min-width: 1280px) {
  .home-intelligence-grid {
    grid-template-columns: 25.875rem 24.25rem 1fr;
  }
  .home-intelligence-grid .panel {
    height: 19rem;
    overflow: hidden;
  }
}
@media (min-width: 1800px) {
  .home-intelligence-grid {
    grid-template-columns: 1.08fr 1fr 0.94fr;
  }
}

.movers-tab--active {
  background: var(--color-elevated);
  box-shadow:
    0 2px 8px rgba(0, 0, 0, 0.26),
    inset 0 1px 0 rgba(255, 255, 255, 0.08);
}
.mover-row {
  position: relative;
  transition: background-color 160ms ease;
}
.mover-row:hover {
  background: rgba(255, 255, 255, 0.035);
}

.feature-card {
  background: linear-gradient(180deg, rgba(22, 27, 34, 0.75), rgba(13, 16, 21, 0.75));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.045);
  transition:
    transform 180ms cubic-bezier(0.22, 1, 0.36, 1),
    border-color 180ms ease;
}
.feature-card:hover {
  border-color: rgba(34, 211, 165, 0.24);
  transform: translateY(-3px);
}
.feature-card__icon {
  background: rgba(34, 211, 165, 0.1);
  transition: box-shadow 180ms ease;
}
.feature-card:hover .feature-card__icon {
  box-shadow: 0 6px 18px rgba(34, 211, 165, 0.18);
}

/* ----------------------------------------------------------------- CTA */

.home-cta {
  background:
    radial-gradient(circle at 88% 120%, rgba(34, 211, 165, 0.14), transparent 42%),
    linear-gradient(115deg, #101a1c 0%, #0a0d11 58%, #09160f 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.07),
    var(--shadow-soft);
}
.home-cta::before {
  position: absolute;
  inset: auto -6% -70% 30%;
  height: 170%;
  border: 1px solid rgba(34, 211, 165, 0.16);
  border-radius: 50%;
  content: "";
  pointer-events: none;
}
.cta-fan {
  position: relative;
  height: 130px;
}
.cta-card {
  position: absolute;
  top: 0;
  width: 92px;
  height: 124px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 8px;
  object-fit: cover;
  box-shadow: 0 12px 26px rgba(0, 0, 0, 0.42);
}
.cta-card--left {
  left: 0;
  transform: rotate(-14deg);
  opacity: 0.85;
}
.cta-card--mid {
  left: 62px;
  z-index: 2;
  transform: rotate(2deg);
}
.cta-card--right {
  left: 124px;
  transform: rotate(15deg);
  opacity: 0.9;
}

/* -------------------------------------------------------------- footer */

.footer-link {
  transition: color 160ms ease;
}
.footer-link:hover {
  color: var(--color-accent);
}
.social-chip {
  border: 1px solid var(--color-border);
  background: rgba(255, 255, 255, 0.02);
}

/* --------------------------------------------------------------- chart */

.price-chart__area {
  animation: fade-in 520ms ease-out both;
}
.price-chart__line {
  stroke-dasharray: 1400;
  animation: draw-in 700ms cubic-bezier(0.22, 1, 0.36, 1) both;
}
.price-chart__dot {
  animation: fade-in 200ms ease-out 560ms both;
  filter: drop-shadow(0 0 7px currentColor) drop-shadow(0 0 2px #ffffff);
}

/* The homepage is built against a 1672px artboard. On very wide or zoomed-out
   desktop canvases, convert the remaining pixel type utilities to the same rem
   scale as the panels so typography and spacing grow together. */
@media (min-width: 1800px) {
  .text-\[6\.5px\] {
    font-size: 0.40625rem;
  }
  .text-\[7px\] {
    font-size: 0.4375rem;
  }
  .text-\[8px\] {
    font-size: 0.5rem;
  }
  .text-\[8\.5px\] {
    font-size: 0.53125rem;
  }
  .text-\[9px\] {
    font-size: 0.5625rem;
  }
  .text-\[9\.5px\] {
    font-size: 0.59375rem;
  }
  .text-\[10px\] {
    font-size: 0.625rem;
  }
  .text-\[11px\] {
    font-size: 0.6875rem;
  }
  .text-\[11\.5px\] {
    font-size: 0.71875rem;
  }
  .text-\[12px\] {
    font-size: 0.75rem;
  }
  .text-\[12\.5px\] {
    font-size: 0.78125rem;
  }
  .text-\[13px\] {
    font-size: 0.8125rem;
  }
  .text-\[14px\] {
    font-size: 0.875rem;
  }
  .text-\[15px\] {
    font-size: 0.9375rem;
  }
  .text-\[17px\] {
    font-size: 1.0625rem;
  }
  .text-\[19px\] {
    font-size: 1.1875rem;
  }
  .text-\[20px\] {
    font-size: 1.25rem;
  }
  .text-\[22px\] {
    font-size: 1.375rem;
  }
  .text-\[23px\] {
    font-size: 1.4375rem;
  }
  .text-\[28px\] {
    font-size: 1.75rem;
  }
}

/* ---------------------------------------------------------- animations */

@keyframes rise-in {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
@keyframes fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@keyframes draw-in {
  from {
    stroke-dashoffset: 1400;
  }
  to {
    stroke-dashoffset: 0;
  }
}
@keyframes shimmer {
  from {
    background-position: 200% 0;
  }
  to {
    background-position: -200% 0;
  }
}
@keyframes tape-pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.35;
  }
}

@keyframes vault-reflection {
  0%,
  62% {
    opacity: 0;
    transform: translateX(-72%);
  }
  70% {
    opacity: 0.65;
  }
  84% {
    opacity: 0;
    transform: translateX(10%);
  }
  100% {
    opacity: 0;
    transform: translateX(10%);
  }
}

/* ======================================================= Markets page */

.markets-page {
  min-height: 100vh;
  padding-bottom: 4rem;
  background:
    radial-gradient(ellipse 42% 17% at 96% 3%, rgba(0, 230, 171, 0.18), transparent 72%),
    radial-gradient(ellipse 36% 15% at 2% 5%, rgba(0, 203, 165, 0.085), transparent 74%),
    var(--color-background);
}
.markets-shell {
  width: min(calc(100% - 3rem), 85.75rem);
  margin-inline: auto;
}
body:has(.markets-page) .site-shell {
  width: min(calc(100% - 3rem), 85.75rem);
  margin-inline: auto;
}
@media (min-width: 1280px) {
  body:has(.markets-page) header form[role="search"] {
    max-width: 27.5rem;
  }
  body:has(.markets-page) header form[role="search"] input {
    height: 2.25rem;
    border-radius: 0.55rem;
    background: linear-gradient(180deg, rgba(14, 20, 26, 0.92), rgba(8, 13, 18, 0.92));
    box-shadow:
      inset 0 1px 2px rgba(0, 0, 0, 0.32),
      inset 0 1px 0 rgba(255, 255, 255, 0.025);
  }
}
.markets-header {
  display: grid;
  grid-template-columns: 500px minmax(0, 1fr);
  align-items: center;
  gap: 40px;
  padding: 34px 0 30px;
}
.markets-intro-copy {
  min-width: 0;
}
.markets-eyebrow {
  color: var(--color-accent);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}
.markets-intro-copy h1 {
  margin-top: 0.75rem;
  font-family: var(--font-display);
  font-size: clamp(34px, 2.7vw, 46px);
  font-weight: 750;
  line-height: 1;
  letter-spacing: -0.055em;
}
.markets-intro-copy > p:last-child {
  margin-top: 0.85rem;
  color: var(--color-subtle);
  font-size: 14px;
}
.markets-summary-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.75rem;
}
.markets-summary-card {
  position: relative;
  display: flex;
  min-width: 0;
  min-height: 102px;
  align-items: stretch;
  justify-content: space-between;
  overflow: hidden;
  padding: 1rem;
  border: 1px solid rgba(151, 179, 191, 0.16);
  border-radius: 0.72rem;
  background:
    radial-gradient(circle at 92% 0%, rgba(34, 211, 165, 0.055), transparent 42%),
    linear-gradient(145deg, rgba(19, 26, 33, 0.96), rgba(8, 13, 17, 0.98));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.06),
    inset 0 -1px 0 rgba(0, 0, 0, 0.26),
    0 14px 32px rgba(0, 0, 0, 0.2);
  transition:
    border-color 180ms ease,
    transform 180ms ease;
}
.markets-summary-card:hover {
  border-color: rgba(34, 211, 165, 0.3);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.075),
    0 18px 38px rgba(0, 0, 0, 0.24);
  transform: translateY(-2px);
}
.markets-summary-card > div {
  position: relative;
  z-index: 1;
  display: flex;
  min-width: 0;
  flex-direction: column;
}
.markets-summary-label {
  overflow: hidden;
  color: color-mix(in srgb, var(--color-subtle) 82%, transparent);
  font-size: 10px;
  line-height: 1.2;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.markets-summary-card strong {
  margin-top: 0.55rem;
  font-family: var(--font-display);
  font-size: 23px;
  font-weight: 750;
  line-height: 1;
  letter-spacing: -0.04em;
}
.markets-summary-card .is-positive,
.markets-summary-card .is-negative {
  margin-top: auto;
  padding-top: 0.65rem;
  font-size: 9px;
  font-weight: 700;
}
.markets-summary-spark {
  position: absolute;
  right: 0.75rem;
  bottom: 0.8rem;
  width: 68px;
  height: 32px;
}
.markets-summary-icon {
  position: absolute;
  top: -2.65rem;
  right: 0;
  width: 14px;
  height: 14px;
  color: rgba(34, 211, 165, 0.42);
}

.markets-quick-rail {
  display: grid;
  grid-template-columns: repeat(8, minmax(135px, 1fr));
  gap: 0.75rem;
  overflow-x: auto;
  padding: 4px 0;
  border-top: 1px solid rgba(34, 211, 165, 0.14);
  border-bottom: 1px solid rgba(34, 211, 165, 0.14);
  scrollbar-width: none;
}
.markets-quick-rail::-webkit-scrollbar {
  display: none;
