  box-shadow: 0 16px 30px rgb(var(--market-card-accent) / 0.24);
  transform: translateY(-2px);
}
.market-card-cta:hover svg {
  transform: translateX(3px);
}
.market-investment-card.is-compact .market-card-media {
  height: 225px;
}
.market-investment-card.is-compact .market-card-heading h2 {
  font-size: 1.2rem;
}
.market-investment-card.is-compact .market-card-valuation strong {
  font-size: 1.65rem;
