@media (max-width: 799px) {
  .market-card-media {
    height: 280px;
  }
  .market-card-body {
    padding: 1rem;
  }
}

@media (max-width: 559px) {
  .market-card-media,
  .market-investment-card.is-compact .market-card-media {
    height: min(78vw, 390px);
  }
  .market-card-valuation {
    gap: 0.7rem;
  }
  .market-card-reference {
    padding-left: 0.7rem;
  }
  .market-card-valuation strong {
    font-size: clamp(1.55rem, 8vw, 2rem);
