/* ================================================= Premium art direction
   A shared material and lighting pass. These layers deliberately preserve every
   component's geometry while changing the perceived depth of the interface. */

body::before {
  position: fixed;
  inset: 0;
  z-index: 100;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.62'/%3E%3C/svg%3E");
  background-size: 180px 180px;
  content: "";
  opacity: 0.018;
  mix-blend-mode: soft-light;
  pointer-events: none;
}

header[role="banner"],
body > div > div > header {
  background:
    linear-gradient(180deg, rgba(9, 13, 17, 0.94), rgba(6, 9, 12, 0.9)), rgba(8, 9, 12, 0.9);
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.025),
    0 16px 40px rgba(0, 0, 0, 0.18);
  backdrop-filter: blur(22px) saturate(1.12);
}

body:has(.home-hero) main {
  overflow-x: clip;
  background:
    radial-gradient(ellipse 58% 24% at 52% 5%, rgba(26, 184, 137, 0.075), transparent 72%),
    radial-gradient(ellipse 42% 18% at 8% 31%, rgba(22, 116, 92, 0.04), transparent 74%),
    radial-gradient(ellipse 42% 18% at 93% 52%, rgba(27, 156, 119, 0.045), transparent 76%),
    linear-gradient(180deg, #080a0d 0%, #07090c 54%, #090b0e 100%);
}

.home-hero {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  background-image:
    radial-gradient(ellipse 34% 58% at 50% 48%, rgba(29, 215, 163, 0.12), transparent 72%),
    radial-gradient(ellipse 24% 48% at 76% 48%, rgba(19, 139, 108, 0.075), transparent 75%),
    linear-gradient(rgba(255, 255, 255, 0.012) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.012) 1px, transparent 1px),
    linear-gradient(180deg, rgba(9, 12, 15, 0.32), rgba(5, 8, 11, 0.08));
  background-size:
    auto,
    auto,
    64px 64px,
    64px 64px,
    auto;
}
.home-hero::before {
  position: absolute;
  top: -32%;
  left: 35%;
  z-index: -1;
  width: 46rem;
  height: 46rem;
  border-radius: 50%;
  background: rgba(32, 221, 168, 0.065);
  content: "";
  filter: blur(105px);
  pointer-events: none;
}
.home-hero::after {
  position: absolute;
  right: -14%;
  bottom: -55%;
  z-index: -1;
  width: 42rem;
  height: 32rem;
  border-radius: 50%;
  background: rgba(18, 138, 105, 0.055);
  content: "";
  filter: blur(120px);
  pointer-events: none;
}

.showcase {
  border-color: rgba(143, 203, 185, 0.2);
  background:
    radial-gradient(ellipse at 50% 92%, rgba(35, 225, 169, 0.19), transparent 52%),
    linear-gradient(145deg, rgba(25, 35, 42, 0.98), rgba(6, 12, 15, 0.995));
  box-shadow:
    inset 0 1px 0 rgba(228, 255, 247, 0.09),
    inset 0 -1px 0 rgba(0, 0, 0, 0.48),
    0 30px 72px rgba(0, 0, 0, 0.52),
    0 0 54px rgba(27, 211, 157, 0.055);
}
.showcase__surface {
  border-color: rgba(139, 244, 215, 0.2);
  background:
    linear-gradient(
      112deg,
      rgba(255, 255, 255, 0.07),
      transparent 12% 84%,
      rgba(101, 245, 204, 0.045)
    ),
    radial-gradient(ellipse at 50% 82%, rgba(30, 224, 164, 0.18), transparent 53%),
    linear-gradient(180deg, rgba(13, 22, 27, 0.98), rgba(3, 11, 13, 0.995));
  box-shadow:
    inset 0 0 0 5px rgba(3, 10, 13, 0.72),
    inset 0 0 0 6px rgba(132, 255, 223, 0.12),
    inset 0 -54px 72px rgba(11, 110, 80, 0.28),
    inset 0 1px 0 rgba(255, 255, 255, 0.08);
}
.showcase__slab {
  filter: saturate(1.08) contrast(1.055) brightness(1.025);
  box-shadow:
    0 24px 46px rgba(0, 0, 0, 0.64),
    0 0 32px rgba(50, 237, 181, 0.08);
}
.showcase__pedestal {
  box-shadow:
    0 0 32px rgba(34, 211, 165, 0.34),
    0 -12px 44px rgba(34, 211, 165, 0.11),
    inset 0 1px 9px rgba(103, 255, 217, 0.34);
}

.hero-panel,
.premium-surface,
.panel,
.feature-card,
.market-strip,
.asset-card {
  border-color: rgba(146, 174, 185, 0.15);
  background:
    radial-gradient(circle at 88% 0%, rgba(45, 113, 103, 0.07), transparent 35%),
    linear-gradient(145deg, rgba(21, 27, 34, 0.96), rgba(8, 12, 17, 0.985));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.062),
    inset 0 -1px 0 rgba(0, 0, 0, 0.32),
    0 22px 52px rgba(0, 0, 0, 0.26);
}
.hero-panel {
  border-color: rgba(150, 187, 193, 0.18);
  background:
    radial-gradient(ellipse at 72% 10%, rgba(35, 156, 129, 0.11), transparent 48%),
    linear-gradient(145deg, rgba(20, 29, 36, 0.98), rgba(7, 12, 16, 0.99));
  box-shadow:
    inset 0 1px 0 rgba(230, 255, 249, 0.075),
    inset 0 -1px 0 rgba(0, 0, 0, 0.42),
    0 30px 70px rgba(0, 0, 0, 0.43),
    0 0 52px rgba(34, 211, 165, 0.04);
  backdrop-filter: blur(16px) saturate(1.08);
}

.market-overview-section,
.trending-section,
body:has(.home-hero) main > section {
  position: relative;
}
.market-overview-section::before,
.trending-section::before {
  position: absolute;
  inset: -4rem -7rem;
  z-index: -1;
  border-radius: 50%;
  background: radial-gradient(ellipse, rgba(23, 129, 101, 0.045), transparent 68%);
  content: "";
  filter: blur(34px);
  pointer-events: none;
}
.market-strip {
  backdrop-filter: blur(14px) saturate(1.08);
}
.market-strip__cell {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.012), transparent);
}

.asset-card--compact {
  border-color: rgb(var(--card-accent, 34 211 165) / 0.2);
  background:
    radial-gradient(ellipse at 50% 8%, rgb(var(--card-accent, 34 211 165) / 0.16), transparent 45%),
    linear-gradient(155deg, rgba(20, 27, 33, 0.99), rgba(7, 11, 15, 0.995));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.07),
    inset 0 -1px 0 rgba(0, 0, 0, 0.36),
    0 22px 42px rgba(0, 0, 0, 0.3),
    0 0 32px rgb(var(--card-accent, 34 211 165) / 0.035);
}
.asset-card__image {
  background:
    radial-gradient(circle at 50% 42%, rgb(var(--card-accent, 34 211 165) / 0.14), transparent 58%),
    linear-gradient(180deg, rgba(10, 15, 20, 0.92), rgba(3, 7, 10, 0.98));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.07),
    inset 0 -28px 48px rgba(0, 0, 0, 0.24),
    0 15px 30px rgba(0, 0, 0, 0.32);
}
.asset-card__image img {
  filter: saturate(1.035) contrast(1.06) brightness(1.02);
}
.asset-card:hover {
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.09),
    0 28px 58px rgba(0, 0, 0, 0.39),
    0 0 42px rgb(var(--card-accent, 34 211 165) / 0.07);
}

.markets-page {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  background:
    radial-gradient(ellipse 52% 24% at 94% 3%, rgba(20, 202, 151, 0.21), transparent 70%),
    radial-gradient(ellipse 44% 20% at 3% 5%, rgba(19, 145, 111, 0.11), transparent 72%),
    radial-gradient(ellipse 42% 32% at 58% 42%, rgba(26, 125, 101, 0.045), transparent 74%),
    linear-gradient(180deg, #080b0e 0%, #06090c 48%, #080a0d 100%);
}
.markets-page::before {
  position: absolute;
  top: -18rem;
  right: -16rem;
  z-index: -1;
  width: 58rem;
  height: 58rem;
  border-radius: 50%;
  background: rgba(20, 221, 160, 0.07);
  content: "";
  filter: blur(115px);
  pointer-events: none;
}
.markets-page::after {
  position: absolute;
  top: 29rem;
  left: 27%;
  z-index: -1;
  width: 48rem;
  height: 36rem;
  border-radius: 50%;
  background: rgba(20, 141, 108, 0.04);
  content: "";
  filter: blur(130px);
  pointer-events: none;
}
.markets-header,
.markets-quick-rail,
.markets-workspace {
  position: relative;
  z-index: 1;
}
.markets-header::after {
  position: absolute;
  inset: 3rem 5% -2rem 34%;
  z-index: -1;
  border-radius: 50%;
  background: radial-gradient(ellipse, rgba(26, 184, 139, 0.065), transparent 68%);
  content: "";
  filter: blur(38px);
  pointer-events: none;
}

.markets-summary-card {
  backdrop-filter: blur(14px) saturate(1.1);
}
.markets-summary-card::after {
  position: absolute;
  inset: 0.02rem 0.65rem auto;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.105), transparent);
  content: "";
  pointer-events: none;
}
.markets-summary-spark path,
.market-strip path {
  filter: drop-shadow(0 0 5px color-mix(in srgb, currentColor 46%, transparent));
}

.markets-quick-rail {
  background: linear-gradient(90deg, transparent, rgba(11, 30, 26, 0.38) 48%, transparent);
}
.markets-filter-panel {
  backdrop-filter: blur(18px) saturate(1.08);
}

.market-investment-card {
  backdrop-filter: blur(12px) saturate(1.06);
}
.market-investment-card::after {
  position: absolute;
  inset: 0;
  z-index: 0;
  border-radius: inherit;
  background:
    linear-gradient(
      112deg,
      rgba(255, 255, 255, 0.018),
      transparent 14% 82%,
      rgb(var(--market-card-accent) / 0.018)
    ),
    radial-gradient(ellipse at 50% 25%, rgb(var(--market-card-accent) / 0.055), transparent 48%);
  content: "";
  pointer-events: none;
}
.market-card-media::before {
  position: absolute;
  top: -25%;
  left: -38%;
  z-index: 2;
  width: 54%;
  height: 150%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.075), transparent);
  content: "";
  opacity: 0.34;
  transform: rotate(14deg);
  transition:
    left 700ms cubic-bezier(0.22, 1, 0.36, 1),
    opacity 300ms ease;
  pointer-events: none;
}
.market-investment-card:hover .market-card-media::before,
.market-investment-card:focus-within .market-card-media::before {
  left: 92%;
  opacity: 0.5;
}
.market-card-glow {
  box-shadow: 0 0 58px rgb(var(--market-card-accent) / 0.07);
  transition:
    opacity 320ms ease,
    transform 420ms cubic-bezier(0.22, 1, 0.36, 1),
    filter 320ms ease;
}
.market-investment-card:hover .market-card-glow,
.market-investment-card:focus-within .market-card-glow {
  filter: blur(42px);
  transform: translateX(-50%) scale(1.08);
}
.market-card-media img {
  filter: saturate(1.07) contrast(1.085) brightness(1.025)
    drop-shadow(0 20px 28px rgba(0, 0, 0, 0.44));
}
.market-investment-card:hover .market-card-media img {
  filter: saturate(1.11) contrast(1.095) brightness(1.045)
    drop-shadow(0 22px 30px rgba(0, 0, 0, 0.48));
  transform: scale(1.02);
}
.market-card-cta,
.primary-action,
.secondary-action {
  transform: translateZ(0);
  transition-timing-function: cubic-bezier(0.22, 1, 0.36, 1);
}

.price-chart__line {
  filter: drop-shadow(0 0 4px color-mix(in srgb, currentColor 55%, transparent));
}
.price-chart__area {
  filter: saturate(1.08);
}

@media (max-width: 799px) {
  body::before {
    opacity: 0.012;
  }
  .home-hero::before,
  .markets-page::before {
    opacity: 0.7;
  }
  .market-card-media::before {
    display: none;
  }
}

/* Orders — new approved homepage-theme density and truthful empty-state refinement. */
.orders-page .orders-shell {
  width: min(calc(100% - clamp(2rem, 4vw, 5rem)), 96rem);
  max-width: none;
  padding-block: clamp(1.7rem, 2.8vw, 2.45rem) 3.25rem;
}
.orders-heading {
  min-height: 0;
  padding: 0 0 1.15rem;
}
.orders-heading h1 {
  font-size: clamp(2.55rem, 3.7vw, 3.85rem);
  line-height: 0.96;
}
.orders-heading > p:last-child {
  max-width: 36rem;
  margin-top: 0.5rem;
  font-size: 0.84rem;
}
.orders-layout {
  grid-template-columns: minmax(0, 2.2fr) minmax(21.25rem, 0.92fr);
  gap: 0.82rem;
}
.orders-layout__main,
.orders-layout__side {
  gap: 0.82rem;
}
.orders-kpis {
  gap: 0.72rem;
}
.orders-kpi,
.orders-panel {
  border-color: rgba(130, 158, 170, 0.2);
  border-radius: 0.72rem;
  background: linear-gradient(145deg, rgba(19, 25, 31, 0.97), rgba(10, 15, 19, 0.98));
}
.orders-kpi {
  min-height: 7.55rem;
  gap: 0.62rem;
  padding: 0.84rem;
}
.orders-kpi__icon {
  width: 2.42rem;
  height: 2.42rem;
  border-radius: 0.56rem;
}
.orders-kpi__icon svg {
  width: 1rem;
  height: 1rem;
}
.orders-kpi p {
  font-size: 0.65rem;
}
.orders-kpi strong {
  margin-top: 0.18rem;
  font-size: 1.28rem;
}
.orders-kpi > div > span {
  margin-top: 0.22rem;
  font-size: 0.61rem;
}
.orders-kpi button {
  margin-top: 0.52rem;
  font-size: 0.63rem;
}
.orders-panel--table {
  min-height: 20rem;
}
.orders-panel--filled {
  min-height: 13.75rem;
}
.orders-panel--book {
  min-height: 16.35rem;
}
.orders-panel--activity {
  min-height: 15.65rem;
}
.orders-panel--help {
  min-height: 10.15rem;
}
.orders-tabs {
  min-height: 3.56rem;
  gap: 0.1rem;
  padding-top: 0.2rem;
}
.orders-tabs > button {
  min-height: 3.22rem;
  padding-inline: 0.58rem;
  font-size: 0.68rem;
}
.orders-filter,
.orders-sort {
  display: inline-flex;
  min-height: 2.04rem;
  align-items: center;
  gap: 0.35rem;
  border: 1px solid rgba(158, 174, 194, 0.17);
  border-radius: 0.42rem;
  background: rgba(21, 27, 35, 0.8);
  padding-left: 0.45rem;
  color: #a4aebb;
  font-size: 0.64rem;
}
.orders-filter {
  margin-left: auto;
}
.orders-filter svg {
  width: 0.75rem;
  height: 0.75rem;
}
.orders-filter select,
.orders-sort select {
  min-height: 2rem;
  border: 0;
  border-left: 1px solid rgba(158, 174, 194, 0.1);
  border-radius: 0;
  background: transparent;
  padding: 0 0.45rem;
  color: #d5dbe4;
  font-size: 0.64rem;
}
.orders-sort {
  margin-left: 0.25rem;
}
.orders-table th {
  padding-top: 0.44rem;
  font-size: 0.62rem;
}
.orders-table td {
  padding-block: 0.6rem;
}
.orders-table__empty-row td {
  min-height: 4.65rem;
  padding: 1rem 0.5rem !important;
}
.orders-table__empty-row strong,
.orders-table__empty-row span {
  display: block;
}
.orders-table__empty-row strong {
  color: #dce3ea;
  font-size: 0.75rem;
  font-weight: 650;
}
.orders-table__empty-row span {
  margin-top: 0.28rem;
  color: #808b99;
  font-size: 0.65rem;
}
.orders-depth {
  min-height: 7.15rem;
}
.orders-book-empty {
  position: relative;
  display: grid;
  min-height: 10.1rem;
  align-items: center;
  overflow: hidden;
  border-bottom: 1px solid rgba(158, 174, 194, 0.12);
}
.orders-book-empty__grid {
  position: absolute;
  inset: 0.35rem 0 1.55rem;
  display: grid;
  grid-template-rows: repeat(4, 1fr);
  opacity: 0.65;
}
.orders-book-empty__grid span {
  border-top: 1px dashed rgba(158, 174, 194, 0.11);
}
.orders-book-empty__mid {
  z-index: 1;
  display: grid;
  justify-items: center;
  gap: 0.36rem;
  padding-inline: 1rem;
  text-align: center;
}
.orders-book-empty__mid strong {
  color: #dfe5ec;
  font-size: 0.75rem;
}
.orders-book-empty__mid span {
  color: #7f8a98;
  font-size: 0.64rem;
}
.orders-book-empty__labels {
  position: absolute;
  right: 0;
  bottom: 0.48rem;
  left: 0;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  color: #7f8a98;
  font-size: 0.58rem;
}
.orders-book-empty__labels span:nth-child(2) {
  text-align: center;
}
.orders-book-empty__labels span:last-child {
  color: #b76570;
  text-align: right;
}
.orders-book-empty__labels span:first-child {
  color: #39c7aa;
}
.orders-activity-empty {
  display: flex;
  min-height: 7.5rem;
  align-items: center;
  justify-content: center;
  gap: 0.65rem;
  color: #7f8a98;
  text-align: left;
}
.orders-activity-empty > span {
  display: grid;
  width: 2.25rem;
  height: 2.25rem;
  place-items: center;
  border: 1px solid rgba(158, 174, 194, 0.14);
  border-radius: 0.56rem;
  background: rgba(30, 38, 47, 0.5);
  color: #abb8c5;
}
.orders-activity-empty svg {
  width: 1rem;
  height: 1rem;
}
.orders-activity-empty strong {
  display: block;
  color: #dfe5ec;
  font-size: 0.73rem;
  font-weight: 650;
}
.orders-activity-empty p {
  margin-top: 0.25rem;
  font-size: 0.64rem;
}
.orders-help__link {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  margin-top: 0.62rem;
  color: var(--color-accent);
  font-size: 0.66rem;
  font-weight: 700;
}
.orders-help__link svg {
  width: 0.8rem;
  height: 0.8rem;
}
@media (max-width: 1280px) {
  .orders-kpis {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}
@media (max-width: 920px) {
  .orders-layout {
    grid-template-columns: minmax(0, 1fr);
  }
  .orders-layout__side {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .orders-panel--help {
    min-height: auto;
  }
}
@media (max-width: 700px) {
  .orders-kpis {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 520px) {
  .orders-page .orders-shell {
    width: min(100% - 1.25rem, 96rem);
  }
  .orders-kpis {
    grid-template-columns: minmax(0, 1fr);
  }
  .orders-filter {
    margin-left: 0;
  }
  .orders-filter span,
  .orders-sort > :first-child {
    display: none;
  }
  .orders-tabs {
    align-items: flex-end;
  }
}

/* =================================================
   Premium art direction — second material pass
   ================================================= */

body > div > div > header::after {
  position: absolute;
  right: 7%;
  bottom: -1px;
  left: 7%;
  height: 1px;
  background: linear-gradient(
    90deg,
    transparent,
    rgba(41, 234, 178, 0.06) 24%,
    rgba(255, 255, 255, 0.075) 50%,
    rgba(41, 234, 178, 0.06) 76%,
    transparent
  );
  content: "";
  pointer-events: none;
}

.showcase {
  outline: 1px solid rgba(77, 228, 184, 0.055);
  outline-offset: -5px;
}
.showcase::after {
  position: absolute;
  inset: 12% 10% 4%;
  z-index: 0;
  border-radius: 42% 42% 18% 18%;
  background: radial-gradient(ellipse at 50% 77%, rgba(28, 238, 169, 0.17), transparent 58%);
  content: "";
  filter: blur(19px);
  pointer-events: none;
}
.showcase__surface,
.showcase__slab,
.showcase__pedestal {
  z-index: 1;
}
.hero-panel .price-chart__line {
  filter: drop-shadow(0 0 5px rgba(30, 235, 170, 0.54));
}
.hero-panel .price-chart__area {
  filter: saturate(1.17) brightness(1.03);
}

.market-strip {
  background:
    linear-gradient(180deg, rgba(18, 27, 33, 0.88), rgba(6, 11, 15, 0.94)),
    radial-gradient(ellipse at 50% -40%, rgba(36, 218, 164, 0.09), transparent 62%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.07),
    inset 0 -1px 0 rgba(0, 0, 0, 0.56),
    0 18px 50px rgba(0, 0, 0, 0.26),
    0 0 48px rgba(25, 172, 129, 0.025);
}
.market-strip__item {
  position: relative;
  isolation: isolate;
}
.market-strip__item::after {
  position: absolute;
  inset: 0;
  z-index: -1;
  background: radial-gradient(ellipse at 82% 72%, rgba(34, 210, 160, 0.035), transparent 48%);
  content: "";
  pointer-events: none;
}

.asset-card__image {
  isolation: isolate;
}
.asset-card__image::before {
  position: absolute;
  inset: 0;
  z-index: 2;
  border-radius: inherit;
  background:
    linear-gradient(
      118deg,
      rgba(255, 255, 255, 0.07),
      transparent 16% 72%,
      rgba(255, 255, 255, 0.025)
    ),
    radial-gradient(
      ellipse at 50% 104%,
      rgb(var(--card-accent, 34 211 165) / 0.13),
      transparent 54%
    );
  content: "";
  pointer-events: none;
}

.markets-workspace {
  isolation: isolate;
}
.markets-workspace::before {
  position: absolute;
  top: 5rem;
  left: 46%;
  z-index: -1;
  width: 62rem;
  height: 48rem;
  border-radius: 50%;
  background: rgba(19, 151, 114, 0.035);
  content: "";
  filter: blur(120px);
  pointer-events: none;
  transform: translateX(-50%);
}
.markets-filter-panel {
  background:
    linear-gradient(150deg, rgba(17, 27, 33, 0.95), rgba(7, 13, 17, 0.97)),
    radial-gradient(ellipse at 42% 0%, rgba(52, 207, 162, 0.06), transparent 48%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.07),
    inset 0 0 0 1px rgba(74, 223, 180, 0.015),
    0 30px 72px rgba(0, 0, 0, 0.34),
    0 0 50px rgba(14, 108, 82, 0.025);
}

