  background: linear-gradient(180deg, rgba(25, 34, 40, 0.88), rgba(8, 14, 18, 0.92));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.075),
    0 6px 15px rgba(0, 0, 0, 0.28);
  color: rgba(205, 215, 220, 0.72);
  font-size: 7.5px;
  line-height: 1;
  backdrop-filter: blur(10px) saturate(1.02);
}
.market-grade-badge strong {
  color: #f5f8f9;
  font-size: 9px;
  font-weight: 760;
  font-variant-numeric: tabular-nums;
}

.market-card-body h2 {
  margin-top: 31px;
}
.market-card-grade {
  color: rgba(153, 169, 178, 0.78);
  letter-spacing: 0.005em;
}

.market-detailed-media {
  position: relative;
  background:
    radial-gradient(ellipse at 50% 54%, rgb(var(--market-stage-light) / 0.11), transparent 68%),
    linear-gradient(180deg, rgba(9, 15, 19, 0.94), rgba(4, 9, 12, 0.98));
}
.market-detailed-media .market-grade-badge {
  right: 6px;
  bottom: 6px;
}
.market-detailed-category {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  margin-top: 6px;
  color: rgba(162, 178, 187, 0.7);
  font-size: 8.5px;
}
.market-detailed-category svg {
  width: 12px;
  height: 12px;
  stroke-width: 1.7;
}
.market-detailed-identity .market-detailed-category + h2 {
  margin-top: 0.35rem;
}

@media (max-width: 559px) {
  .market-card-media {
    height: min(74vw, 310px);
  }
  .market-category-chip {
