  }
}

/* =================================================
   Marketplace asset card specification
   The card geometry below translates the approved annotated card directly:
   display stage first, then identity, valuation, market data, ownership and CTA.
   ================================================= */

.market-asset-grid {
  align-items: stretch;
  gap: 22px;
}

.market-investment-card {
  border: 1px solid rgba(133, 159, 165, 0.15);
  border-radius: 16px;
  background:
    radial-gradient(ellipse 86% 42% at 50% 18%, rgba(34, 211, 165, 0.045), transparent 72%),
    linear-gradient(152deg, rgba(14, 22, 27, 0.995), rgba(4, 9, 12, 0.998) 72%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.095),
    inset 0 0 0 1px rgba(255, 255, 255, 0.012),
    0 24px 54px rgba(0, 0, 0, 0.34),
    0 0 34px rgba(34, 211, 165, 0.025);
  transform: translateZ(0);
  transition:
    border-color 340ms cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 340ms cubic-bezier(0.22, 1, 0.36, 1),
    transform 340ms cubic-bezier(0.22, 1, 0.36, 1);
}

.market-investment-card::before {
  inset: 0 18px auto;
  z-index: 8;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.18), transparent);
}

.market-investment-card::after {
  position: absolute;
  inset: 0;
  z-index: 0;
  border-radius: inherit;
  background:
    linear-gradient(
      118deg,
      rgba(255, 255, 255, 0.038),
      transparent 18% 76%,
      rgba(255, 255, 255, 0.012)
    ),
    radial-gradient(ellipse 75% 30% at 50% 2%, rgba(34, 211, 165, 0.045), transparent 78%);
  content: "";
  pointer-events: none;
}

.market-investment-card:hover,
.market-investment-card:focus-within {
  border-color: rgba(34, 211, 165, 0.32);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.14),
    inset 0 0 0 1px rgba(34, 211, 165, 0.035),
    0 36px 78px rgba(0, 0, 0, 0.46),
    0 0 42px rgba(34, 211, 165, 0.065);
  transform: translateY(-6px);
}

.market-asset-grid:not(.is-compact) .market-investment-card:first-child {
  border-color: rgba(133, 159, 165, 0.15);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.095),
    inset 0 0 0 1px rgba(255, 255, 255, 0.012),
    0 24px 54px rgba(0, 0, 0, 0.34),
    0 0 34px rgba(34, 211, 165, 0.025);
}

.market-status-badge {
  top: auto;
  bottom: 37px;
  left: 12px;
  z-index: 12;
  min-height: 20px;
  gap: 4px;
  padding-inline: 7px;
  border: 1px solid rgb(var(--market-card-accent) / 0.24);
  border-radius: 6px;
  background:
    linear-gradient(
      180deg,
      rgb(var(--market-card-accent) / 0.2),
      rgb(var(--market-card-accent) / 0.12)
    ),
    rgba(7, 13, 16, 0.82);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.08),
    0 4px 10px rgba(0, 0, 0, 0.18);
  font-size: 8px;
  letter-spacing: -0.005em;
  backdrop-filter: blur(16px) saturate(1.18);
}

.market-status-badge svg {
  width: 9px;
  height: 9px;
  stroke-width: 1.8;
}

.market-bookmark {
  top: 12px;
  right: 12px;
  z-index: 14;
  width: 28px;
  height: 28px;
  border-color: rgba(185, 207, 215, 0.18);
  border-radius: 7px;
  background: linear-gradient(180deg, rgba(14, 22, 27, 0.9), rgba(5, 11, 15, 0.94));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.075),
    0 7px 16px rgba(0, 0, 0, 0.24);
  opacity: 0.72;
  backdrop-filter: blur(16px) saturate(1.1);
  transition:
    opacity 220ms ease,
    color 220ms ease,
    border-color 220ms ease,
    background 220ms ease,
    box-shadow 220ms ease,
    transform 220ms ease;
}

.market-bookmark svg {
  width: 13px;
  height: 13px;
  transition: transform 220ms cubic-bezier(0.22, 1, 0.36, 1);
}

.market-investment-card:hover .market-bookmark,
.market-investment-card:focus-within .market-bookmark,
.market-bookmark.is-saved {
  opacity: 1;
}

.market-bookmark:hover,
.market-bookmark.is-saved {
  border-color: rgba(34, 211, 165, 0.58);
  background: linear-gradient(180deg, rgba(34, 211, 165, 0.14), rgba(6, 13, 16, 0.96));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.1),
    0 0 24px rgba(34, 211, 165, 0.14);
  transform: translateY(-1px);
}

.market-bookmark:hover svg {
  transform: scale(1.08);
}

.market-card-media {
  z-index: 1;
  width: 100%;
  height: auto;
  aspect-ratio: 0.91;
  margin: 0;
  border: 0;
  border-radius: 15px 15px 0 0;
  background:
    radial-gradient(
      ellipse 68% 68% at 50% 48%,
      rgb(var(--market-stage-light) / 0.075),
      transparent 66%
    ),
    radial-gradient(
      ellipse 80% 20% at 50% 94%,
      rgb(var(--market-stage-light) / 0.09),
      transparent 72%
    ),
    linear-gradient(180deg, rgba(5, 11, 15, 0.88), rgba(1, 6, 8, 0.985));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.075),
    inset 0 -42px 58px rgba(0, 0, 0, 0.32),
    0 18px 34px rgba(0, 0, 0, 0.22);
}

.market-card-media::before {
  position: absolute;
  inset: 0;
  z-index: 4;
  border-radius: inherit;
  background:
    linear-gradient(
      115deg,
      rgba(255, 255, 255, 0.055),
      transparent 18% 74%,
      rgba(255, 255, 255, 0.02)
    ),
    radial-gradient(circle at 50% 70%, transparent 40%, rgba(0, 0, 0, 0.24) 100%);
  content: "";
  pointer-events: none;
}

.market-card-media::after {
  inset: 0;
  z-index: 3;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.012), transparent 58%, rgba(1, 5, 7, 0.88)),
    radial-gradient(
      ellipse 58% 9% at 50% 92%,
      rgb(var(--market-stage-light) / 0.16),
      transparent 74%
    );
}

.market-card-media .market-card-glow {
  top: 22%;
  width: 62%;
  height: 62%;
  background: rgb(var(--market-stage-light) / 0.1);
  box-shadow:
    0 0 52px rgb(var(--market-stage-light) / 0.055),
    0 0 92px rgb(var(--market-stage-light) / 0.025);
  filter: blur(42px);
  transition:
    opacity 320ms ease,
    filter 320ms ease,
    transform 320ms cubic-bezier(0.22, 1, 0.36, 1);
}

.market-card-media img,
.market-card-media.profile-graded-slab img,
.market-card-media.profile-raw-card img,
.market-card-media.profile-sealed-product img,
.market-card-media.profile-memorabilia img {
  z-index: 2;
  inset: 9px 12px 10px;
  width: calc(100% - 24px);
  height: calc(100% - 19px);
  padding: 0;
  border-radius: 7px;
  object-fit: contain;
  filter: saturate(0.98) contrast(1.06) brightness(1.01)
    drop-shadow(0 24px 30px rgba(0, 0, 0, 0.48));
  transform: scale(1);
}

.market-investment-card:hover .market-card-media img,
.market-investment-card:focus-within .market-card-media img,
.market-investment-card:hover .market-card-media.profile-raw-card img,
.market-investment-card:focus-within .market-card-media.profile-raw-card img {
  filter: saturate(1.02) contrast(1.08) brightness(1.025)
    drop-shadow(0 28px 34px rgba(0, 0, 0, 0.54));
  transform: scale(1.012);
}

.market-investment-card:hover .market-card-glow,
.market-investment-card:focus-within .market-card-glow {
  filter: blur(46px);
  transform: translateX(-50%) scale(1.04);
}

.market-category-chip {
  top: auto;
  bottom: 12px;
  left: 12px;
  z-index: 10;
  max-width: calc(100% - 100px);
  min-height: 20px;
  gap: 4px;
  padding-inline: 6px;
  border-color: rgba(180, 203, 211, 0.12);
  border-radius: 6px;
  background: linear-gradient(180deg, rgba(22, 31, 36, 0.72), rgba(7, 13, 16, 0.74));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.045),
    0 4px 10px rgba(0, 0, 0, 0.17);
  color: rgba(210, 220, 224, 0.76);
  font-size: 7.5px;
  font-weight: 560;
  backdrop-filter: blur(10px) saturate(1.02);
}

.market-category-chip svg {
  width: 10px;
  height: 10px;
  color: rgba(205, 217, 221, 0.6);
  stroke-width: 1.7;
}

.market-card-media .market-grade-badge {
  top: auto;
  right: 12px;
  bottom: 12px;
  z-index: 11;
  display: inline-flex;
  width: auto;
  min-width: 38px;
  min-height: 20px;
  align-items: center;
  justify-content: center;
  gap: 3px;
  padding: 0 6px;
  border: 1px solid rgb(var(--market-stage-light) / 0.28);
  border-radius: 6px;
  background:
    linear-gradient(180deg, rgba(12, 20, 24, 0.88), rgba(3, 9, 12, 0.94)),
    rgb(var(--market-stage-light) / 0.08);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.1),
    0 8px 18px rgba(0, 0, 0, 0.25),
    0 0 14px rgb(var(--market-stage-light) / 0.04);
  text-align: center;
  backdrop-filter: blur(18px) saturate(1.08);
}

.market-card-media .market-grade-company {
  color: rgba(194, 205, 211, 0.82);
  font-size: 6.5px;
  font-weight: 650;
  letter-spacing: 0.03em;
}

.market-card-media .market-grade-badge strong {
  color: #f6f8f8;
  font-family: var(--font-display);
  font-size: 10.5px;
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.025em;
}

.market-card-media .market-grade-badge small {
  display: none;
}

.market-card-body {
  z-index: 5;
  margin-top: 0;
  padding: 21px 20px 20px;
  border-top: 1px solid rgba(167, 192, 200, 0.045);
  background:
    linear-gradient(180deg, rgba(11, 18, 22, 0.98), rgba(4, 9, 12, 0.995)),
    radial-gradient(ellipse at 50% 0%, rgba(34, 211, 165, 0.035), transparent 60%);
}

.market-card-heading {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 24px;
  align-items: start;
  gap: 10px;
}

.market-card-heading > .market-bookmark {
  position: static;
  width: 24px;
  height: 24px;
  border-color: transparent;
  border-radius: 6px;
  background: transparent;
  box-shadow: inset 0 0 0 1px rgba(176, 198, 205, 0.08);
  opacity: 0.62;
}

.market-card-heading > .market-bookmark:hover,
.market-card-heading > .market-bookmark.is-saved {
  border-color: rgba(34, 211, 165, 0.24);
  background: rgba(34, 211, 165, 0.055);
  box-shadow: inset 0 0 0 1px rgba(34, 211, 165, 0.06);
}

.market-card-body h2 {
  display: -webkit-box;
  min-height: 2.26em;
  margin-top: 0;
  overflow: hidden;
  color: rgba(246, 248, 249, 0.98);
  font-size: clamp(18px, 1.25vw, 21px);
  font-weight: 680;
  line-height: 1.13;
  letter-spacing: -0.036em;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.market-card-grade {
  min-height: 1.3em;
  margin-top: 9px;
  color: rgba(73, 207, 165, 0.88);
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.008em;
}

.market-card-value {
  align-items: center;
  gap: 8px;
  margin-top: 22px;
}

.market-card-value strong {
  min-width: 0;
  font-size: clamp(28px, 2vw, 33px);
  font-weight: 700;
  letter-spacing: -0.045em;
}

.market-card-value > span {
  flex: 0 0 auto;
  gap: 4px;
  margin-left: auto;
  font-size: 10px;
}

.market-card-value > span.is-positive {
  color: #35dca8;
}

.market-card-value > span.is-negative {
  color: #f0646d;
}

.market-card-value svg {
  width: 13px;
  height: 13px;
}

.market-card-value small {
  margin-left: 1px;
  font-size: 8.5px;
}

.market-card-metrics {
  gap: 0;
  margin-top: 22px;
}

.market-card-metrics > div {
  padding: 0 8px;
  border-left-color: rgba(155, 180, 189, 0.12);
}

.market-card-metrics > div:first-child {
  padding-left: 0;
}

.market-card-metrics > div:last-child {
  padding-right: 0;
}

.market-card-metrics dt {
  color: rgba(132, 150, 159, 0.82);
  font-size: 9.5px;
}

.market-card-metrics dd {
  margin-top: 6px;
  font-size: 11.5px;
  font-weight: 670;
}

.market-ownership {
  margin-top: 22px;
}

.market-ownership > span {
  height: 6px;
  background: rgba(157, 178, 187, 0.105);
}

.market-ownership > span > span {
  position: relative;
  background: linear-gradient(90deg, #38d7a7 0%, #1ebf8f 100%);
  box-shadow:
    0 0 14px rgba(34, 211, 165, 0.2),
    inset 0 1px 0 rgba(255, 255, 255, 0.24);
  transition:
    width 700ms cubic-bezier(0.22, 1, 0.36, 1),
    filter 260ms ease;
}

.market-investment-card:hover .market-ownership > span > span {
  filter: brightness(1.12) saturate(1.06);
}

.market-ownership > div {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin-top: 8px;
}

.market-ownership small {
  display: block;
  margin-top: 0;
  color: rgba(138, 154, 163, 0.85);
  font-size: 9.5px;
}

.market-card-cta {
  min-height: 43px;
  margin-top: 22px;
  border-color: rgba(167, 192, 200, 0.11);
  border-radius: 9px;
  background: linear-gradient(180deg, rgba(17, 25, 30, 0.72), rgba(7, 13, 17, 0.82));
  font-size: 11px;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.045),
    0 6px 14px rgba(0, 0, 0, 0.12);
}

.market-card-cta svg {
  width: 14px;
  height: 14px;
  margin-left: 5px;
  color: var(--color-accent);
  transition: transform 240ms cubic-bezier(0.22, 1, 0.36, 1);
}

.market-card-cta:hover {
  border-color: rgba(34, 211, 165, 0.3);
  background: linear-gradient(180deg, rgba(34, 211, 165, 0.07), rgba(7, 14, 17, 0.9));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.07),
    0 10px 22px rgba(0, 0, 0, 0.2);
  transform: translateY(-1px);
}

.market-card-cta:hover svg {
  transform: translateX(4px);
}

.market-investment-card.is-compact .market-card-media {
  height: auto;
  aspect-ratio: 1.1;
}

.market-investment-card.is-compact .market-card-media .market-grade-badge {
  width: auto;
  min-height: 18px;
}

.market-investment-card.is-compact .market-card-media .market-grade-badge strong {
  font-size: 9.5px;
}

.market-investment-card.is-compact .market-category-chip {
  max-width: calc(100% - 92px);
  min-height: 19px;
  font-size: 7px;
}

.market-investment-card.is-compact .market-card-body {
  padding: 17px 15px;
}

.market-investment-card.is-compact .market-card-body h2 {
  min-height: 2.26em;
  font-size: 14px;
}

.market-investment-card.is-compact .market-card-value {
  margin-top: 16px;
}

.market-investment-card.is-compact .market-card-value strong {
  font-size: 22px;
}

.market-investment-card.is-compact .market-ownership {
  margin-top: 16px;
}

.market-detailed-media .market-grade-badge {
  right: 6px;
  bottom: 6px;
  display: inline-flex;
  width: auto;
  min-height: 22px;
  gap: 4px;
  padding: 0 7px;
}

.market-detailed-media .market-grade-badge small {
  display: none;
}

/* The filter rail should organize the market, not read as another dominant card. */
.markets-filter-panel {
  border-color: rgba(148, 177, 187, 0.095);
  background:
    radial-gradient(circle at 12% 0%, rgba(34, 211, 165, 0.022), transparent 30%),
    linear-gradient(155deg, rgba(13, 21, 26, 0.88), rgba(5, 11, 14, 0.94));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.03),
    0 16px 38px rgba(0, 0, 0, 0.16);
}

.markets-category-search input {
  border-color: rgba(154, 180, 189, 0.09);
  background: rgba(3, 9, 12, 0.62);
  box-shadow: inset 0 1px 8px rgba(0, 0, 0, 0.16);
}

.markets-category-section button.is-selected {
  border-color: rgba(34, 211, 165, 0.1);
  background: rgba(34, 211, 165, 0.045);
  box-shadow: none;
}

.markets-category-section button.is-selected::before {
  background: rgba(34, 211, 165, 0.76);
  box-shadow: none;
}

.markets-filter-accordion {
  border-top-color: rgba(148, 177, 187, 0.075);
}

@media (max-width: 1099px) {
  .market-card-body h2 {
    font-size: 19px;
  }
}

@media (max-width: 799px) {
  .market-asset-grid,
  .market-asset-grid.is-compact {
    gap: 16px;
  }

  .market-card-media,
  .market-investment-card.is-compact .market-card-media {
    height: auto;
    aspect-ratio: 0.9;
  }
}

@media (max-width: 559px) {
  .market-card-media,
  .market-investment-card.is-compact .market-card-media {
    height: auto;
    aspect-ratio: 0.92;
  }

  .market-card-body,
  .market-investment-card.is-compact .market-card-body {
    padding: 20px 18px 18px;
  }

  .market-card-body h2,
  .market-investment-card.is-compact .market-card-body h2 {
    min-height: 0;
    font-size: 20px;
  }

  .market-card-value strong,
  .market-investment-card.is-compact .market-card-value strong {
    font-size: 30px;
  }

  .market-card-metrics dt {
    font-size: 9px;
  }

  .market-card-metrics dd {
    font-size: 11px;
  }
}

/* =================================================
   Marketplace premium hierarchy pass
   A single final layer intentionally owns the large-screen composition,
   status language and card hierarchy after the historical refinement passes.
   ================================================= */

.markets-shell,
body:has(.markets-page) .site-shell {
  width: min(calc(100% - clamp(2rem, 4vw, 5rem)), 100rem);
}

.markets-page {
  background:
    radial-gradient(ellipse 58% 22% at 50% 2%, rgba(25, 182, 138, 0.115), transparent 72%),
    radial-gradient(ellipse 48% 28% at 63% 35%, rgba(18, 121, 94, 0.055), transparent 74%),
    radial-gradient(ellipse 40% 24% at 18% 55%, rgba(17, 102, 82, 0.03), transparent 72%),
    linear-gradient(180deg, #080c0f 0%, #06090c 32rem, #070a0d 100%);
}

.markets-page::before {
  top: -25rem;
  right: auto;
  left: 50%;
  width: 70rem;
  height: 54rem;
  background: rgba(29, 211, 159, 0.05);
  filter: blur(132px);
  transform: translateX(-50%);
}

.markets-page::after {
  top: 34rem;
  left: 50%;
  width: 72rem;
  height: 48rem;
  background: rgba(18, 139, 105, 0.038);
  filter: blur(145px);
  transform: translateX(-50%);
}

.markets-header {
  grid-template-columns: minmax(480px, 0.88fr) minmax(0, 1.62fr);
  gap: clamp(2rem, 3vw, 3.75rem);
  padding-block: 42px 34px;
}

.markets-header::after {
  inset: 1rem 10% -2rem 20%;
  background: radial-gradient(ellipse, rgba(25, 165, 126, 0.062), transparent 70%);
}

.markets-intro-copy h1 {
  display: flex;
  flex-wrap: nowrap;
  gap: 0.06em 0.2em;
  max-width: 690px;
  margin-top: 0.8rem;
  font-size: clamp(38px, 2.75vw, 48px);
  font-weight: 720;
  line-height: 1.02;
  letter-spacing: -0.038em;
}

.markets-intro-copy h1 span {
  display: inline-block;
  white-space: nowrap;
}

.markets-intro-copy > p:last-child {
