  gap: 11px;
  margin-bottom: 18px;
  padding-bottom: 9px;
  border-bottom: 1px solid rgba(151, 181, 190, 0.075);
}

.markets-toolbar-count {
  font-size: 12px;
}

.markets-result-search {
