}

.markets-result-search input,
.markets-sort-control,
.markets-view-control {
  border-color: rgba(148, 178, 188, 0.13);
  background: rgba(7, 13, 17, 0.72);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.026);
}

.markets-result-search input,
.markets-sort-control {
  min-height: 39px;
}

.markets-result-search input,
.markets-sort-control select,
.markets-view-control button {
  font-size: 11px;
}

.markets-filter-panel {
  border-color: rgba(148, 177, 187, 0.075);
  background:
    radial-gradient(circle at 12% 0%, rgba(34, 211, 165, 0.02), transparent 30%),
