  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.026),
    0 14px 34px rgba(0, 0, 0, 0.14);
}

.markets-filter-header {
  padding: 1.2rem 1.1rem 1.05rem;
}

.markets-filter-header h2 {
  font-size: 16px;
}

.markets-category-search {
  margin-inline: 1.1rem;
  margin-bottom: 1rem;
}

.markets-category-search input {
  height: 40px;
  font-size: 11px;
}

.markets-category-section {
  padding: 0.45rem 1.1rem 1.05rem;
}

.markets-category-section h3,
.markets-filter-accordion > button {
  font-size: 12px;
}

.markets-category-section button {
  min-height: 39px;
  font-size: 11px;
}

.markets-category-section button > span:last-child {
  font-size: 10px;
}

.markets-filter-accordion {
  margin-inline: 1.1rem;
}

.market-asset-grid {
  gap: 22px;
}

.market-investment-card {
  border-color: rgba(139, 165, 173, 0.13);
  background:
    radial-gradient(
      ellipse 78% 40% at 50% 18%,
      rgb(var(--market-card-accent) / 0.045),
      transparent 72%
    ),
    linear-gradient(152deg, rgba(13, 21, 25, 0.975), rgba(4, 9, 12, 0.995) 74%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.075),
    0 20px 48px rgba(0, 0, 0, 0.28),
    0 0 32px rgb(var(--market-card-accent) / 0.018);
}

.market-investment-card:hover,
.market-investment-card:focus-within {
  border-color: rgb(var(--market-card-accent) / 0.34);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.12),
    0 32px 72px rgba(0, 0, 0, 0.42),
    0 0 46px rgb(var(--market-card-accent) / 0.075);
  transform: translateY(-5px);
}

.market-asset-grid:not(.is-compact)
  .market-investment-card:first-child:not(:hover):not(:focus-within) {
  border-color: rgba(139, 165, 173, 0.13);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.075),
    0 20px 48px rgba(0, 0, 0, 0.28),
    0 0 32px rgb(var(--market-card-accent) / 0.018);
}

.market-asset-grid:not(.is-compact) .market-investment-card:first-child:hover,
.market-asset-grid:not(.is-compact) .market-investment-card:first-child:focus-within {
  border-color: rgb(var(--market-card-accent) / 0.34);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.12),
    0 32px 72px rgba(0, 0, 0, 0.42),
    0 0 46px rgb(var(--market-card-accent) / 0.075);
}

.market-card-media {
  background:
    radial-gradient(
      ellipse 66% 64% at 50% 46%,
      rgb(var(--market-stage-light) / 0.08),
      transparent 66%
    ),
    radial-gradient(
      ellipse 78% 18% at 50% 93%,
      rgb(var(--market-stage-light) / 0.1),
      transparent 72%
    ),
    linear-gradient(180deg, rgba(5, 11, 15, 0.9), rgba(1, 6, 8, 0.99));
}

.market-card-media::before {
  background:
    linear-gradient(
      112deg,
      rgba(255, 255, 255, 0.045),
      transparent 17% 76%,
      rgba(255, 255, 255, 0.015)
    ),
    radial-gradient(circle at 50% 47%, transparent 38%, rgba(0, 0, 0, 0.38) 100%),
    linear-gradient(180deg, rgba(1, 5, 7, 0.06), transparent 52%, rgba(1, 5, 7, 0.2));
}

.market-card-media img,
.market-card-media.profile-graded-slab img,
.market-card-media.profile-raw-card img,
.market-card-media.profile-sealed-product img,
.market-card-media.profile-memorabilia img {
  inset: 12px 14px 11px;
  width: calc(100% - 28px);
  height: calc(100% - 23px);
  filter: saturate(0.93) contrast(1.07) brightness(1.01)
    drop-shadow(0 24px 30px rgba(0, 0, 0, 0.48));
}

.market-investment-card:hover .market-card-media img,
.market-investment-card:focus-within .market-card-media img {
  filter: saturate(1) contrast(1.09) brightness(1.03) drop-shadow(0 28px 34px rgba(0, 0, 0, 0.54));
}

.market-status-badge {
  --market-status-rgb: var(--market-card-accent);
  min-height: 22px;
  gap: 5px;
  padding-inline: 8px;
  overflow: hidden;
  border-color: rgb(var(--market-status-rgb) / 0.66);
  background:
    linear-gradient(115deg, rgba(255, 255, 255, 0.18), transparent 30%),
    linear-gradient(
      180deg,
      rgb(var(--market-status-rgb) / 0.78),
      rgb(var(--market-status-rgb) / 0.4)
    ),
    rgba(5, 10, 13, 0.92);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.27),
    inset 0 -1px 0 rgb(var(--market-status-rgb) / 0.28),
    0 5px 13px rgba(0, 0, 0, 0.3),
    0 0 18px rgb(var(--market-status-rgb) / 0.22);
  color: #f5fffc;
  font-size: 8.5px;
  font-weight: 760;
  text-shadow: 0 1px 4px rgba(0, 0, 0, 0.38);
}

.market-status-badge.is-green {
  --market-status-rgb: 25 213 154;
}

.market-status-badge.is-blue {
  --market-status-rgb: 24 164 239;
}

.market-status-badge.is-purple {
  --market-status-rgb: 184 70 235;
}

.market-status-badge.is-orange {
  --market-status-rgb: 239 137 31;
}

.market-status-badge.is-red {
  --market-status-rgb: 235 55 78;
}

.market-investment-card:hover .market-status-badge,
.market-investment-card:focus-within .market-status-badge {
  border-color: rgb(var(--market-status-rgb) / 0.86);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.32),
    0 7px 18px rgba(0, 0, 0, 0.32),
    0 0 24px rgb(var(--market-status-rgb) / 0.32);
  filter: brightness(1.08) saturate(1.08);
}

.market-category-chip,
.market-card-media .market-grade-badge {
  border-color: rgba(181, 202, 209, 0.105);
  background: rgba(5, 11, 14, 0.76);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.035),
    0 4px 10px rgba(0, 0, 0, 0.18);
}

.market-card-body {
  padding: 22px 20px 20px;
}

.market-card-heading {
  grid-template-columns: minmax(0, 1fr) 26px;
  gap: 12px;
}

.market-card-heading > .market-bookmark {
  width: 26px;
  height: 26px;
  border-color: rgba(176, 198, 205, 0.08);
  background: rgba(255, 255, 255, 0.012);
  box-shadow: inset 0 0 0 1px rgba(176, 198, 205, 0.06);
  color: rgba(194, 207, 213, 0.72);
  opacity: 0.82;
}

.market-card-heading > .market-bookmark svg {
  width: 14px;
  height: 14px;
}

.market-card-body h2 {
  font-size: clamp(18px, 1.18vw, 21px);
  font-weight: 660;
  letter-spacing: -0.032em;
}

.market-card-grade {
  margin-top: 10px;
  font-size: 11px;
}

.market-card-value {
  gap: 10px;
  margin-top: 20px;
}

.market-card-value strong {
  font-size: clamp(24px, 1.6vw, 29px);
  font-weight: 690;
  letter-spacing: -0.04em;
}

.market-card-value > span {
  font-size: 11px;
}

.market-card-value small {
  font-size: 9px;
}

.market-card-metrics {
  margin-top: 20px;
}

.market-card-metrics dt {
  color: rgba(149, 166, 175, 0.88);
  font-size: 10.5px;
}

.market-card-metrics dd {
  margin-top: 6px;
  font-size: 12.5px;
}

.market-ownership {
  margin-top: 20px;
}

.market-ownership small {
  color: rgba(153, 169, 177, 0.88);
  font-size: 10.5px;
}

.market-card-cta {
  min-height: 42px;
  margin-top: 20px;
  border-color: rgba(169, 194, 201, 0.09);
  background: rgba(255, 255, 255, 0.012);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.025);
  color: rgba(222, 230, 233, 0.82);
  font-size: 11.5px;
}

.market-card-cta:hover {
  border-color: rgba(34, 211, 165, 0.28);
  background: rgba(34, 211, 165, 0.055);
  color: #f5fffc;
}

@media (max-width: 1439px) {
  .markets-shell,
  body:has(.markets-page) .site-shell {
    width: min(calc(100% - 3rem), 85.75rem);
  }

  .markets-header {
    grid-template-columns: minmax(460px, 0.82fr) minmax(0, 1.38fr);
  }
}

@media (max-width: 1099px) {
  .markets-header {
    grid-template-columns: 1fr;
  }

  .markets-workspace {
    display: block;
  }
}

@media (max-width: 799px) {
  .markets-shell,
  body:has(.markets-page) .site-shell {
    width: calc(100% - 32px);
  }

  .markets-header {
    padding-block: 2rem 1.4rem;
  }

  .markets-intro-copy h1 {
    flex-wrap: wrap;
    gap: 0.05em 0.16em;
    font-size: clamp(32px, 8vw, 42px);
  }

  .markets-toolbar {
    padding-bottom: 12px;
  }
}

@media (max-width: 559px) {
  .markets-intro-copy h1 {
    display: block;
    font-size: 34px;
  }

  .markets-intro-copy h1 span {
    margin-right: 0.16em;
  }

  .market-card-value strong {
    font-size: 27px;
  }
}

/* =================================================
   Collectors page — reference implementation
   ================================================= */

.collectors-page {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  padding-bottom: 3rem;
  background:
    radial-gradient(ellipse 52% 18% at 74% 2%, rgba(20, 170, 130, 0.075), transparent 70%),
    radial-gradient(ellipse 42% 24% at 35% 32%, rgba(20, 125, 98, 0.04), transparent 74%),
    linear-gradient(180deg, #070b0e 0%, #060a0d 42%, #071014 100%);
}

.collectors-page::before,
.collectors-page::after {
  position: absolute;
  z-index: -1;
  border-radius: 50%;
  content: "";
  filter: blur(140px);
  pointer-events: none;
}

.collectors-page::before {
  top: -22rem;
  left: 48%;
  width: 62rem;
  height: 54rem;
  background: rgba(26, 199, 149, 0.045);
}

.collectors-page::after {
  top: 34rem;
  right: -18rem;
  width: 58rem;
  height: 64rem;
  background: rgba(23, 143, 111, 0.032);
}

.collectors-shell,
body:has(.collectors-page) .site-shell {
  width: min(calc(100% - clamp(2rem, 5vw, 5.5rem)), 92rem);
  margin-inline: auto;
}

.collectors-kicker {
  color: #20d59e;
  font-size: 10px;
  font-weight: 760;
  letter-spacing: 0.17em;
  line-height: 1;
  text-transform: uppercase;
}

.collectors-hero {
  display: grid;
  grid-template-columns: minmax(310px, 0.78fr) minmax(0, 1.72fr);
  align-items: center;
  gap: clamp(2.5rem, 4vw, 5rem);
  padding-block: 47px 32px;
  border-bottom: 1px solid rgba(146, 175, 185, 0.055);
}

.collectors-hero-copy h1 {
  max-width: 430px;
  margin-top: 13px;
  font-family: var(--font-display);
  font-size: clamp(42px, 3.3vw, 55px);
  font-weight: 720;
  line-height: 0.96;
  letter-spacing: -0.055em;
}

.collectors-hero-copy > p:last-child {
  max-width: 420px;
  margin-top: 17px;
  color: rgba(175, 190, 198, 0.84);
  font-size: 13px;
  line-height: 1.6;
}

.collectors-hero-metrics {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 18px;
}

.collectors-metric-card {
  position: relative;
  min-width: 0;
  min-height: 178px;
  overflow: hidden;
  padding: 22px 22px 19px;
  border: 1px solid rgba(146, 176, 186, 0.15);
  border-radius: 14px;
  background:
    linear-gradient(118deg, rgba(255, 255, 255, 0.026), transparent 26%),
    linear-gradient(155deg, rgba(18, 28, 34, 0.94), rgba(6, 12, 16, 0.98));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.065),
    0 22px 48px rgba(0, 0, 0, 0.25);
}

.collectors-metric-card::after {
  position: absolute;
  inset: 0.02rem 1rem auto;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.11), transparent);
  content: "";
}

.collectors-metric-label {
  display: block;
  color: rgba(173, 187, 196, 0.78);
  font-size: 10px;
  font-weight: 630;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.collectors-metric-card > strong {
  display: block;
  margin-top: 13px;
  font-family: var(--font-display);
  font-size: 29px;
  font-weight: 700;
  letter-spacing: -0.04em;
}

.collectors-metric-card > svg {
  position: absolute;
  top: 22px;
  right: 21px;
  width: 28px;
  height: 28px;
  stroke-width: 1.55;
  filter: drop-shadow(0 0 12px currentColor);
}

.collectors-metric-chart {
  position: absolute;
  right: 19px;
  bottom: 20px;
  left: 20px;
  height: 54px;
  opacity: 0.95;
}

.collectors-metric-card.is-emerald {
  color: #24dba4;
}

.collectors-metric-card.is-violet {
  color: #a88bff;
}

.collectors-metric-card.is-amber {
  color: #f3bd28;
}

.collectors-metric-card > strong,
.collectors-metric-card .collectors-metric-label {
  color: var(--color-foreground);
}

.collectors-metric-chart path,
.collector-profile-chart path {
  stroke-dasharray: 180;
  stroke-dashoffset: 180;
  animation: collector-line-draw 1.15s cubic-bezier(0.22, 1, 0.36, 1) forwards;
  filter: drop-shadow(0 0 4px currentColor);
}

.collectors-filter-bar {
  display: flex;
  align-items: flex-start;
  gap: 22px;
  padding-block: 14px 18px;
  border-bottom: 1px solid rgba(146, 175, 185, 0.055);
}

.collectors-search {
  position: relative;
  display: block;
  width: 52px;
  min-width: 52px;
  height: 42px;
  overflow: hidden;
  border: 1px solid rgba(145, 174, 184, 0.13);
  border-radius: 8px;
  background: rgba(10, 18, 22, 0.76);
  transition:
    width 300ms cubic-bezier(0.22, 1, 0.36, 1),
    border-color 200ms ease,
    box-shadow 200ms ease;
}

.collectors-search:focus-within,
.collectors-search:has(input:not(:placeholder-shown)) {
  width: 230px;
  border-color: rgba(34, 211, 165, 0.34);
  box-shadow: 0 0 0 3px rgba(34, 211, 165, 0.055);
}

.collectors-search svg {
  position: absolute;
  top: 50%;
  left: 18px;
  width: 15px;
  height: 15px;
  color: rgba(172, 188, 196, 0.82);
  transform: translateY(-50%);
  pointer-events: none;
}

.collectors-search input {
  width: 228px;
  height: 40px;
  padding: 0 12px 0 48px;
  background: transparent;
  color: var(--color-foreground);
  font-size: 11px;
  outline: 0;
}

.collectors-filter-list {
  display: flex;
  min-width: 0;
  flex: 1;
  flex-wrap: wrap;
  gap: 9px 10px;
}

.collectors-filter-list button {
  min-height: 42px;
  padding-inline: 15px;
  border: 1px solid rgba(146, 175, 185, 0.14);
  border-radius: 8px;
  background: rgba(8, 15, 19, 0.62);
  color: rgba(176, 190, 198, 0.84);
  font-size: 10.5px;
  font-weight: 540;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.022);
  transition:
    color 200ms ease,
    background 240ms ease,
    border-color 200ms ease,
    box-shadow 240ms ease,
    transform 200ms ease;
}

.collectors-filter-list button:hover {
  border-color: rgba(34, 211, 165, 0.25);
  color: #eefaf6;
  transform: translateY(-1px);
}

.collectors-filter-list button.is-active {
  border-color: rgba(34, 211, 165, 0.72);
  background: linear-gradient(135deg, #28dda9, #0bbd87);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.3),
    0 7px 20px rgba(15, 203, 143, 0.17);
  color: #041712;
  font-weight: 700;
}

.collectors-spotlight {
  display: grid;
  grid-template-columns: minmax(0, 1.47fr) minmax(340px, 0.99fr);
  gap: 20px;
  padding-top: 18px;
}

.featured-collector-card,
.collectors-leaderboard,
.collector-profile-card {
  position: relative;
  overflow: hidden;
  border: 1px solid rgba(145, 176, 186, 0.14);
  border-radius: 15px;
  background:
    radial-gradient(ellipse 70% 35% at 10% 0%, rgba(31, 174, 132, 0.055), transparent 70%),
    linear-gradient(150deg, rgba(16, 27, 33, 0.95), rgba(5, 12, 16, 0.985));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.058),
    0 22px 50px rgba(0, 0, 0, 0.24);
}

.featured-collector-card {
  min-width: 0;
  padding: 23px 21px 16px;
}

.featured-collector-glow {
  position: absolute;
  top: -10rem;
  left: -7rem;
  width: 28rem;
  height: 24rem;
  border-radius: 50%;
  background: rgba(30, 205, 151, 0.055);
  filter: blur(70px);
  pointer-events: none;
}

.featured-collector-header {
  position: relative;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
}

.featured-collector-header .collectors-kicker {
  display: inline-flex;
  align-items: center;
  gap: 10px;
}

.featured-collector-header .collectors-kicker svg {
  width: 15px;
  height: 15px;
}

.featured-return-card {
  display: grid;
  min-width: 127px;
  min-height: 58px;
  place-content: center end;
  padding: 7px 11px;
  border: 1px solid rgba(145, 174, 184, 0.08);
  border-radius: 9px;
  background: rgba(6, 13, 16, 0.43);
  text-align: right;
}

.featured-return-card span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: #28dfa7;
  font-size: 16px;
  font-weight: 700;
}

.featured-return-card span svg {
  width: 14px;
  height: 14px;
}

.featured-return-card small {
  margin-top: 3px;
  color: rgba(143, 159, 168, 0.78);
  font-size: 8px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.featured-collector-identity {
  position: relative;
  display: flex;
  align-items: center;
  gap: 20px;
  margin-top: -13px;
}

.collector-avatar {
  display: grid;
  width: 42px;
  height: 42px;
  flex: 0 0 auto;
  place-items: center;
  border: 1px solid rgba(34, 211, 165, 0.08);
  border-radius: 50%;
  background: linear-gradient(145deg, rgba(22, 77, 65, 0.72), rgba(6, 43, 36, 0.85));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.05);
  color: #20d59e;
  font-family: var(--font-display);
  font-size: 17px;
  font-weight: 700;
}

.collector-avatar.is-featured {
  width: 72px;
  height: 72px;
