  transform: translateY(-6px);
}

.collector-profile-card > header {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
}

.collector-profile-card > header a {
  display: block;
  overflow: hidden;
  font-family: var(--font-display);
  font-size: 13px;
  font-weight: 680;
  letter-spacing: -0.025em;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.collector-profile-card > header small {
  display: block;
  margin-top: 2px;
  color: rgba(141, 159, 168, 0.82);
  font-size: 9px;
}

.collector-public-status {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  align-self: start;
  color: #29dca6;
  font-size: 9px;
}

.collector-public-status svg {
  width: 11px;
  height: 11px;
}

.collector-profile-copy {
  margin-top: 13px;
}

.collector-profile-copy strong {
  display: block;
  overflow: hidden;
  font-size: 10.5px;
  font-weight: 650;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.collector-profile-copy p {
  display: -webkit-box;
  min-height: 2.7em;
  margin-top: 4px;
  overflow: hidden;
  color: rgba(180, 192, 199, 0.82);
  font-size: 9.5px;
  line-height: 1.35;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.collector-profile-chart {
  height: 34px;
  margin-top: 11px;
  color: #25dba4;
}

.collector-profile-stats {
  display: grid;
  grid-template-columns: 1.15fr 1fr 0.85fr;
  gap: 8px;
  margin-top: 8px;
}

.collector-profile-stats dt {
  font-size: 7px;
}

.collector-profile-stats dd {
  margin-top: 4px;
  font-size: 11.5px;
}

.collector-mini-strip {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr)) 42px;
  gap: 5px;
  margin-top: 12px;
}

.collector-mini-holding,
.collector-more-assets {
  position: relative;
  min-width: 0;
  height: 57px;
  overflow: hidden;
  border: 1px solid rgba(151, 181, 190, 0.16);
  border-radius: 5px;
  background: rgba(4, 10, 13, 0.72);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04);
  transition:
    transform 220ms cubic-bezier(0.22, 1, 0.36, 1),
    border-color 180ms ease,
    box-shadow 220ms ease;
}

.collector-mini-holding:hover {
  z-index: 2;
  border-color: rgba(34, 211, 165, 0.36);
  box-shadow: 0 8px 18px rgba(0, 0, 0, 0.3);
  transform: translateY(-3px) scale(1.035);
}

.collector-mini-holding img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: saturate(0.94) contrast(1.06);
}

.collector-mini-holding span {
  position: absolute;
  top: 3px;
  right: 3px;
  padding: 2px 3px;
  border: 1px solid rgba(220, 230, 233, 0.2);
  border-radius: 3px;
  background: rgba(3, 8, 11, 0.84);
  color: #f1f5f6;
  font-size: 5.5px;
  font-weight: 700;
  line-height: 1.05;
  text-align: center;
  white-space: pre-line;
}

.collector-more-assets {
  display: grid;
  place-items: center;
  color: #eef5f3;
  font-size: 11px;
  font-weight: 650;
}

.collector-more-assets:hover {
  border-color: rgba(34, 211, 165, 0.3);
  color: #31dfa9;
}

.collectors-empty-state {
  display: grid;
  min-height: 24rem;
  place-items: center;
  place-content: center;
  gap: 10px;
  text-align: center;
}

.collectors-empty-state > svg {
  width: 28px;
  height: 28px;
  color: var(--color-accent);
}

.collectors-empty-state h2 {
  font-family: var(--font-display);
  font-size: 22px;
}

.collectors-empty-state p {
  color: var(--color-subtle);
  font-size: 12px;
}

.collectors-empty-state button {
  margin-top: 8px;
  padding: 10px 15px;
  border: 1px solid rgba(34, 211, 165, 0.28);
  border-radius: 7px;
  color: var(--color-accent);
  font-size: 11px;
}

@keyframes collector-line-draw {
  to {
    stroke-dashoffset: 0;
  }
}

@media (max-width: 819px) {
  .collectors-hero {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .collectors-hero-copy h1 {
    max-width: none;
  }

  .collectors-spotlight {
    grid-template-columns: 1fr;
  }

  .collectors-leaderboard {
    min-height: 440px;
  }

  .collectors-directory-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 819px) {
  .collectors-shell,
  body:has(.collectors-page) .site-shell {
    width: calc(100% - 2rem);
  }

  .collectors-hero-metrics {
    grid-template-columns: 1fr;
  }

  .collectors-metric-card {
    min-height: 140px;
  }

  .collectors-filter-bar {
    display: block;
  }

  .collectors-search,
  .collectors-search:focus-within,
  .collectors-search:has(input:not(:placeholder-shown)) {
    width: 100%;
  }

  .collectors-search input {
    width: 100%;
  }

  .collectors-filter-list {
    margin-top: 10px;
  }

  .featured-collector-stats {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 14px 0;
  }

  .featured-collector-stats > div:nth-child(4) {
    padding-left: 0;
    border-left: 0;
  }

  .collectors-directory-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 599px) {
  .collectors-page {
    padding-bottom: 2rem;
  }

  .collectors-hero {
    padding-block: 32px 24px;
  }

  .collectors-hero-copy h1 {
    font-size: 40px;
  }

  .collectors-hero-copy > p:last-child {
    font-size: 12px;
  }

  .collectors-filter-list {
    flex-wrap: nowrap;
    overflow-x: auto;
    padding-bottom: 4px;
  }

  .collectors-filter-list button {
    flex: 0 0 auto;
  }

  .featured-collector-card,
  .collectors-leaderboard {
    padding: 18px 15px 14px;
  }

  .featured-return-card {
    min-width: 104px;
  }

  .featured-collector-identity {
    align-items: flex-start;
    margin-top: 14px;
  }

  .collector-avatar.is-featured {
    width: 58px;
    height: 58px;
    font-size: 23px;
  }

  .featured-collector-identity h2 {
    font-size: 22px;
  }

  .featured-collector-actions {
    display: grid;
    grid-template-columns: 1fr 1fr;
  }

  .featured-collector-actions a,
  .featured-collector-actions button {
    min-width: 0;
    padding-inline: 10px;
  }

  .featured-collector-stats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .featured-collector-stats > div:nth-child(odd) {
    padding-left: 0;
    border-left: 0;
  }

  .featured-collector-stats > div:nth-child(4) {
    padding-left: 14px;
    border-left: 1px solid rgba(151, 181, 190, 0.09);
  }

  .featured-holdings-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .featured-holding-media {
    height: 150px;
  }

  .collectors-directory-grid {
    grid-template-columns: 1fr;
  }

  .collector-profile-card {
    min-height: 320px;
  }
}

