  color: rgba(190, 232, 218, 0.94);
  font-size: 8px;
  font-weight: 620;
}
.public-collector-page {
  min-height: 0;
  padding-bottom: 4rem;
  background:
    radial-gradient(ellipse 48% 20% at 67% 0, rgba(22, 180, 132, 0.065), transparent 70%), #070b0e;
}
.public-collector-hero {
  border-bottom: 1px solid rgba(146, 175, 185, 0.09);
  background: linear-gradient(150deg, rgba(12, 22, 27, 0.86), rgba(5, 10, 13, 0.82));
}
.public-collector-hero .collectors-shell {
  padding-block: 28px 30px;
}
.public-collector-back {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: rgba(174, 192, 199, 0.82);
  font-size: 10px;
}
.public-collector-back svg {
  width: 13px;
  height: 13px;
}
.public-collector-hero-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(280px, 0.85fr);
  gap: clamp(22px, 4vw, 56px);
  align-items: end;
  margin-top: 22px;
}
.public-collector-identity {
  display: flex;
  align-items: center;
  gap: 17px;
  margin-top: 22px;
}
.public-collector-hero-grid .public-collector-identity {
  margin-top: 0;
}
.public-collector-identity > div > span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: #28dca6;
  font-size: 9px;
  font-weight: 650;
}
.public-collector-identity > div > span svg {
  width: 13px;
  height: 13px;
}
.public-collector-identity h1 {
  margin-top: 6px;
  font-family: var(--font-display);
  font-size: clamp(30px, 3vw, 45px);
  font-weight: 700;
  letter-spacing: -0.05em;
}
.public-collector-identity p {
  margin-top: 3px;
  color: #28dca6;
  font-size: 12px;
}
.public-collector-bio {
  max-width: 680px;
  margin-top: 18px;
  color: rgba(184, 198, 205, 0.88);
  font-size: 13px;
  line-height: 1.6;
}
.public-collector-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  max-width: 620px;
  margin-top: 20px;
  padding-top: 16px;
  border-top: 1px solid rgba(146, 175, 185, 0.1);
}
.public-collector-stats > div {
  min-width: 0;
  padding-inline: 14px;
  border-left: 1px solid rgba(146, 175, 185, 0.1);
}
.public-collector-stats > div:first-child {
  padding-left: 0;
  border-left: 0;
}
.public-collector-stats dt {
  color: rgba(144, 160, 168, 0.83);
  font-size: 8px;
  font-weight: 650;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}
.public-collector-stats dd {
  margin-top: 5px;
  font-size: 14px;
  font-weight: 680;
}
.public-collector-stats dd.is-positive {
  color: #29dba5;
}
.public-collector-hero-catalogue {
  min-width: 0;
  padding: 17px;
  border: 1px solid rgba(145, 176, 186, 0.14);
  border-radius: 12px;
  background:
    radial-gradient(ellipse 80% 50% at 75% 0%, rgba(34, 211, 165, 0.07), transparent 72%),
    linear-gradient(150deg, rgba(15, 25, 30, 0.94), rgba(5, 11, 15, 0.985));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.04),
    0 14px 34px rgba(0, 0, 0, 0.19);
}
.public-collector-hero-catalogue h2 {
  margin-top: 7px;
  font-family: var(--font-display);
  font-size: 18px;
  font-weight: 680;
  letter-spacing: -0.035em;
}
.public-collector-hero-rail {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
  margin-top: 15px;
}
.public-collector-hero-rail .collector-mini-holding {
  height: 112px;
}
.public-collector-hero-catalogue > a {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  margin-top: 14px;
  color: #29dba5;
  font-size: 10px;
  font-weight: 650;
}
.public-collector-hero-catalogue > a svg {
  width: 13px;
  height: 13px;
}
.public-collector-hero.is-listings h1 {
  margin-top: 9px;
  font-family: var(--font-display);
  font-size: clamp(31px, 3vw, 45px);
  font-weight: 700;
  letter-spacing: -0.05em;
}
.public-collector-hero.is-listings p:last-child {
  max-width: 600px;
  margin-top: 9px;
  color: rgba(178, 194, 201, 0.82);
  font-size: 12px;
}
.public-collector-listings {
  padding-top: 29px;
}
.public-collector-section-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 16px;
}
.public-collector-section-heading h2 {
  margin-top: 8px;
  font-family: var(--font-display);
  font-size: 23px;
  font-weight: 680;
  letter-spacing: -0.04em;
}
.public-collector-section-heading > a {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: #29dba5;
  font-size: 10px;
  font-weight: 650;
}
.public-collector-section-heading > a svg {
  width: 13px;
  height: 13px;
}
.public-collector-assets-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 14px;
  margin-top: 17px;
}
.public-collector-asset-card {
  overflow: hidden;
  border: 1px solid rgba(145, 176, 186, 0.14);
  border-radius: 11px;
  background: linear-gradient(150deg, rgba(15, 25, 30, 0.94), rgba(5, 11, 15, 0.985));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.04),
    0 14px 34px rgba(0, 0, 0, 0.19);
  transition:
    transform 0.24s ease,
    border-color 0.24s ease;
}
.public-collector-asset-card:hover {
  border-color: rgba(34, 211, 165, 0.35);
  transform: translateY(-4px);
}
.public-collector-asset-media {
  display: grid;
  height: 175px;
  place-items: center;
  overflow: hidden;
  background:
    radial-gradient(ellipse at 50% 87%, rgba(34, 211, 165, 0.14), transparent 64%), #071014;
}
.public-collector-asset-media img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  padding: 9px;
}
.public-collector-asset-media svg {
  width: 25px;
  color: rgba(34, 211, 165, 0.64);
}
.public-collector-asset-card > div:last-child {
  padding: 12px;
}
.public-collector-asset-card p {
  color: #2bdca7;
  font-size: 8px;
  font-weight: 650;
  letter-spacing: 0.11em;
  text-transform: uppercase;
}
.public-collector-asset-card h3 {
  display: -webkit-box;
  min-height: 2.4em;
  margin-top: 6px;
  overflow: hidden;
  font-size: 11px;
  font-weight: 670;
  line-height: 1.2;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}
.public-collector-asset-card strong {
  display: block;
  margin-top: 9px;
  font-size: 13px;
}
.public-collector-privacy-note {
  margin-top: 22px;
  color: rgba(152, 169, 178, 0.82);
  font-size: 10px;
  line-height: 1.6;
}
.public-collector-activity {
  margin-top: 30px;
  padding-top: 26px;
  border-top: 1px solid rgba(146, 175, 185, 0.1);
}
.public-collector-activity h2 {
  margin-top: 8px;
  font-family: var(--font-display);
  font-size: 23px;
  font-weight: 680;
  letter-spacing: -0.04em;
}
.public-collector-activity-empty {
  display: flex;
  align-items: center;
  gap: 13px;
  margin-top: 15px;
  padding: 17px;
  border: 1px solid rgba(146, 175, 185, 0.12);
  border-radius: 11px;
  background: linear-gradient(135deg, rgba(14, 25, 30, 0.88), rgba(7, 13, 17, 0.98));
}
.public-collector-activity-empty > svg {
  flex: 0 0 auto;
  width: 23px;
  height: 23px;
  color: rgba(43, 220, 167, 0.8);
}
.public-collector-activity-empty h3 {
  font-size: 11px;
  font-weight: 670;
}
.public-collector-activity-empty p {
  margin-top: 5px;
  color: rgba(157, 177, 184, 0.85);
  font-size: 10px;
  line-height: 1.5;
}
@media (max-width: 819px) {
  .collector-discovery-panel {
    min-height: 0;
  }
  .public-collector-hero-grid {
    grid-template-columns: 1fr;
  }
  .public-collector-assets-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 599px) {
  .featured-collector-stats.has-3-stats {
    gap: 0;
  }
  .featured-collector-stats.has-3-stats > div {
    padding-inline: 8px;
  }
  .featured-collector-stats.has-3-stats > div:first-child {
    padding-left: 0;
  }
  .public-collector-hero .collectors-shell {
    padding-block: 22px 24px;
  }
  .public-collector-identity {
    align-items: flex-start;
    gap: 12px;
  }
  .public-collector-identity .collector-avatar.is-featured {
    width: 55px;
    height: 55px;
    font-size: 21px;
  }
  .public-collector-stats {
    max-width: none;
  }
  .public-collector-stats > div {
    padding-inline: 8px;
  }
  .public-collector-section-heading {
    align-items: flex-start;
    flex-direction: column;
  }
  .public-collector-assets-grid {
    grid-template-columns: 1fr;
  }
  .public-collector-asset-media {
    height: 215px;
  }
  .public-collector-hero-catalogue {
    padding: 14px;
  }
}

/* =================================================
   Wallet — customer cash and movement dashboard
   ================================================= */

.wallet-page {
  min-height: calc(100vh - 4.75rem);
  background:
    radial-gradient(ellipse 44% 23% at 78% 3%, rgba(20, 191, 144, 0.065), transparent 72%),
    linear-gradient(180deg, #080c10 0%, #070a0d 46rem, #070a0d 100%);
}

.wallet-page .wallet-shell {
  width: min(calc(100% - clamp(2rem, 4vw, 5rem)), 96rem);
  max-width: none;
  padding-block: clamp(2.1rem, 3.3vw, 3.2rem) 3.3rem;
}

.wallet-heading {
  min-height: 0;
  padding-bottom: 1.25rem;
}

.wallet-heading h1 {
  margin-top: 0.42rem;
  color: #f5f7f8;
  font-size: clamp(2.65rem, 4.05vw, 4rem);
  font-weight: 750;
  letter-spacing: -0.06em;
  line-height: 0.95;
}

.wallet-heading > p:last-child {
  max-width: 33rem;
  margin-top: 0.8rem;
  color: #aab5c0;
  font-size: 0.85rem;
  line-height: 1.55;
}

.wallet-kpis {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.8rem;
}

.wallet-kpi,
.wallet-panel {
  border-color: rgba(130, 158, 170, 0.2);
  border-radius: 0.72rem;
  background: linear-gradient(145deg, rgba(19, 25, 31, 0.97), rgba(10, 15, 19, 0.98));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.035),
    0 13px 30px rgba(0, 0, 0, 0.16);
}

.wallet-kpi {
  position: relative;
  min-height: 6.65rem;
  padding: 1rem 1.05rem;
}

.wallet-kpi > div:last-child {
  min-width: 0;
}

.wallet-kpi p {
  color: #b0bac4;
  font-size: 0.62rem;
}

.wallet-kpi strong {
  display: block;
  margin-top: 0.4rem;
  color: #eff3f5;
  font-size: clamp(1.22rem, 1.65vw, 1.52rem);
  font-weight: 740;
  font-variant-numeric: tabular-nums;
}

.wallet-kpi > div > span {
  display: block;
  overflow: hidden;
  margin-top: 0.35rem;
  color: #87939f;
  font-size: 0.61rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.wallet-row {
  display: grid;
  gap: 0.8rem;
  margin-top: 0.8rem;
}

.wallet-row--primary {
  grid-template-columns: minmax(18rem, 1.15fr) minmax(17rem, 0.88fr) minmax(22rem, 1.23fr);
  align-items: stretch;
}

.wallet-row--history {
  grid-template-columns: minmax(0, 1.75fr) minmax(20rem, 0.95fr);
  align-items: start;
}

.wallet-side-stack {
  display: grid;
  gap: 0.8rem;
}

.wallet-panel {
  overflow: hidden;
}

.wallet-panel__head {
  display: flex;
  min-height: 3.4rem;
  align-items: center;
  justify-content: space-between;
  gap: 0.8rem;
  padding: 0.88rem 1.1rem 0.62rem;
}

.wallet-panel__head h2 {
  display: flex;
  align-items: center;
  gap: 0.58rem;
  color: #eef2f5;
  font-size: 0.9rem;
  font-weight: 720;
}

.wallet-panel__head h2 > span {
  display: grid;
  width: 1.55rem;
  height: 1.55rem;
  place-items: center;
  border-radius: 0.4rem;
  background: rgba(30, 194, 151, 0.1);
  color: #31dfa9;
}

.wallet-panel__head h2 svg {
  width: 0.82rem;
  height: 0.82rem;
}

.wallet-panel__head > span {
  color: #31dfa9;
  font-size: 0.6rem;
  font-weight: 700;
}

.wallet-panel__body {
  padding: 0 1.1rem 1rem;
}

.wallet-panel--bank,
.wallet-panel--move,
.wallet-panel--status {
  min-height: 17.55rem;
}

.wallet-bank-panel-body {
  display: flex;
  min-height: 14.1rem;
  flex-direction: column;
}

.wallet-bank-empty {
  position: relative;
  display: flex;
  min-height: 8.4rem;
  align-items: center;
  overflow: hidden;
}

.wallet-bank-empty > div > strong {
  color: #eef2f5;
  font-size: 0.9rem;
  font-weight: 720;
}

.wallet-bank-empty p {
  max-width: 16.4rem;
  margin-top: 0.48rem;
  color: #98a4af;
  font-size: 0.68rem;
  line-height: 1.52;
}

.wallet-bank-empty__halo {
  position: absolute;
  top: 50%;
  right: 1rem;
  display: grid;
  width: 7rem;
  aspect-ratio: 1;
  place-items: center;
  border: 1px solid rgba(48, 221, 169, 0.12);
  border-radius: 50%;
  background:
    radial-gradient(circle at 50% 68%, rgba(20, 220, 162, 0.3), transparent 8%),
    radial-gradient(circle at 50% 50%, rgba(18, 126, 104, 0.09), transparent 65%);
  color: rgba(156, 188, 192, 0.58);
  transform: translateY(-50%);
}

.wallet-bank-empty__halo::before,
.wallet-bank-empty__halo::after {
  position: absolute;
  border: 1px solid rgba(48, 221, 169, 0.13);
  border-radius: 50%;
  content: "";
}

.wallet-bank-empty__halo::before {
  inset: 0.8rem;
}
.wallet-bank-empty__halo::after {
  inset: -0.6rem;
  opacity: 0.35;
}

.wallet-bank-empty__halo svg {
  width: 2.2rem;
  height: 2.2rem;
}

.wallet-bank-empty__halo i {
  position: absolute;
  right: -0.1rem;
  bottom: 0.1rem;
  width: 1.75rem;
  height: 1.75rem;
  border: 1px solid rgba(48, 221, 169, 0.36);
  border-radius: 50%;
  background: #0e1d20;
}

.wallet-bank-empty__halo i::before,
.wallet-bank-empty__halo i::after {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 0.62rem;
  height: 1px;
  background: #31dfa9;
  content: "";
  transform: translate(-50%, -50%);
}

.wallet-bank-empty__halo i::after {
  transform: translate(-50%, -50%) rotate(90deg);
}

.wallet-banks {
  display: grid;
  gap: 0.55rem;
}

.wallet-banks li {
  padding: 0.55rem 0 0.7rem;
}

.wallet-bank-connect {
  margin-top: auto;
  padding-top: 0.4rem;
}

.wallet-bank-connect > button,
.wallet-move-form > button,
.wallet-verify-button {
  display: inline-flex;
  min-height: 2.3rem;
  align-items: center;
  justify-content: center;
  gap: 0.46rem;
  border-radius: 0.42rem;
  background: linear-gradient(105deg, #1bd9a1, #25d8bd);
  color: #04251f;
  font-size: 0.65rem;
  font-weight: 750;
}

.wallet-bank-connect > button {
  min-width: 8rem;
}

.wallet-bacs-setup {
  display: grid;
  gap: 0.7rem;
  padding: 0.75rem;
  border: 1px solid rgba(27, 217, 161, 0.22);
  border-radius: 0.55rem;
  background: rgba(11, 24, 28, 0.72);
}

.wallet-bacs-setup strong {
  color: #e9fbf5;
  font-size: 0.72rem;
}

.wallet-bacs-setup p {
  margin-top: 0.25rem;
  color: #91a39f;
  font-size: 0.64rem;
  line-height: 1.45;
}

.wallet-bacs-setup .wallet-bank-actions {
  display: flex;
  justify-content: flex-end;
  gap: 0.5rem;
}

.wallet-bacs-setup .wallet-bank-actions button {
  display: inline-flex;
  min-height: 2.2rem;
  align-items: center;
  justify-content: center;
  gap: 0.35rem;
  border-radius: 0.42rem;
  padding: 0 0.7rem;
  background: rgba(141, 159, 174, 0.12);
  color: #d5e0e5;
  font-size: 0.64rem;
  font-weight: 700;
}

.wallet-bacs-setup .wallet-bank-actions button[type="submit"] {
  background: linear-gradient(105deg, #1bd9a1, #25d8bd);
  color: #04251f;
}

.wallet-bacs-setup .wallet-bank-actions button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.wallet-bank-connect svg,
.wallet-move-form > button svg,
.wallet-verify-button svg {
  width: 0.85rem;
  height: 0.85rem;
}

.wallet-bank-reassurance {
  display: flex;
  gap: 0.65rem;
  margin-top: 0.7rem;
  padding-top: 0.62rem;
  border-top: 1px solid rgba(136, 163, 174, 0.11);
}

.wallet-bank-reassurance span {
  display: inline-flex;
  min-width: 0;
  align-items: center;
  gap: 0.28rem;
  color: #8995a0;
  font-size: 0.51rem;
  white-space: nowrap;
}

.wallet-bank-reassurance svg {
  width: 0.67rem;
  height: 0.67rem;
  color: #2edda8;
}

.wallet-move-tabs,
.wallet-movement-filters {
  border-color: rgba(139, 166, 177, 0.18);
  border-radius: 0.42rem;
  background: rgba(7, 12, 16, 0.45);
}

.wallet-move-tabs button {
  min-height: 2.1rem;
  color: #9ca8b4;
  font-size: 0.63rem;
}

.wallet-move-tabs button.is-active {
  background: rgba(13, 133, 103, 0.19);
  box-shadow: inset 0 0 0 1px rgba(37, 218, 166, 0.28);
  color: #2de0aa;
}

.wallet-move-form {
  gap: 0.55rem;
  margin-top: 0.65rem;
}

.wallet-move-form label {
  gap: 0.3rem;
  color: #b6c0c9;
  font-size: 0.6rem;
}

.wallet-move-form input {
  min-height: 2.2rem;
  border-color: rgba(139, 166, 177, 0.18);
  border-radius: 0.4rem;
  background: rgba(7, 12, 16, 0.58);
  font-size: 0.68rem;
}

.wallet-move-form > p {
  min-height: 2.2rem;
  padding: 0.48rem 0.58rem;
  border-color: rgba(139, 166, 177, 0.13);
  border-radius: 0.4rem;
  color: #8a96a1;
  font-size: 0.59rem;
}

.wallet-move-form > button {
  width: 100%;
  min-height: 2.3rem;
}

.wallet-move-note,
.wallet-move-success {
  margin-top: 0.52rem;
  color: #87939e;
  font-size: 0.58rem;
  text-align: center;
}

.wallet-move-note.is-locked {
  color: #d4aa5d;
}
.wallet-move-success {
  color: #30dfa9;
}

.wallet-provider-status {
  display: grid;
  gap: 0.45rem;
}

.wallet-provider-status > div {
  min-height: 3.3rem;
  padding: 0.5rem 0.55rem;
  border: 1px solid rgba(136, 163, 174, 0.12);
  border-radius: 0.42rem;
  background: rgba(7, 12, 16, 0.25);
}

.wallet-provider-status dt,
.wallet-provider-status dd {
  display: flex;
  align-items: center;
}

.wallet-provider-status dt {
  gap: 0.52rem;
}

.wallet-provider-status dt > span:first-child {
  display: grid;
  width: 1.55rem;
  height: 1.55rem;
  place-items: center;
  border-radius: 0.36rem;
  background: rgba(121, 145, 158, 0.1);
  color: #b8c3cc;
}

.wallet-provider-status dt svg {
  width: 0.72rem;
  height: 0.72rem;
}

.wallet-provider-status dt strong,
.wallet-provider-status dt small {
  display: block;
}

.wallet-provider-status dt strong {
  color: #dfe5e9;
  font-size: 0.62rem;
  font-weight: 680;
}

.wallet-provider-status dt small {
  max-width: 15rem;
  overflow: hidden;
  margin-top: 0.15rem;
  color: #8995a0;
  font-size: 0.52rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.wallet-provider-status dd {
  gap: 0.45rem;
}

.wallet-provider-status dd > svg {
  width: 0.7rem;
  height: 0.7rem;
  color: #3adbaa;
}

.wallet-status {
  min-height: 1.2rem;
  padding: 0.1rem 0.33rem;
