}

.wallet-empty span {
  display: inline-flex;
  margin-top: 0.55rem;
}

.wallet-empty a {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  color: #31dfa9;
  font-size: 0.58rem;
  font-weight: 720;
}

.wallet-panel--insights,
.wallet-panel--activity {
  min-height: 8.35rem;
}

.wallet-insight-summary {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  min-height: 4.3rem;
  align-items: center;
  border: 1px solid rgba(136, 163, 174, 0.1);
  border-radius: 0.46rem;
  background: rgba(7, 12, 16, 0.22);
}

.wallet-insight-summary > div {
  min-width: 0;
  padding: 0 0.65rem;
  border-left: 1px solid rgba(136, 163, 174, 0.1);
  text-align: center;
}

.wallet-insight-summary > div:first-child {
  border-left: 0;
}

.wallet-insight-summary dt,
.wallet-insight-summary small {
  display: block;
  overflow: hidden;
  color: #88949f;
  font-size: 0.51rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.wallet-insight-summary dd {
  overflow: hidden;
  margin-top: 0.3rem;
  color: #e5ebef;
  font-size: 0.8rem;
  font-weight: 730;
  font-variant-numeric: tabular-nums;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.wallet-insight-summary small {
  margin-top: 0.22rem;
}

.wallet-panel--insights .wallet-empty,
.wallet-panel--activity .wallet-empty {
