  border-top: 1px solid rgba(136, 163, 174, 0.1);
}

.wallet-activity li:first-child {
  border-top: 0;
}

.wallet-activity li > span:first-child {
  display: grid;
  width: 1.65rem;
  height: 1.65rem;
  place-items: center;
  border-radius: 0.38rem;
}

.wallet-activity li > span.is-deposit {
  background: rgba(26, 206, 155, 0.12);
  color: #2cdda8;
}
.wallet-activity li > span.is-withdrawal {
  background: rgba(236, 92, 105, 0.11);
  color: #f18590;
}
.wallet-activity li > span:first-child svg {
  width: 0.76rem;
  height: 0.76rem;
}

.wallet-activity strong,
.wallet-activity p {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.wallet-activity strong {
  color: #e3e9ed;
  font-size: 0.61rem;
  font-weight: 690;
}
.wallet-activity p {
  margin-top: 0.14rem;
  color: #84909c;
  font-size: 0.53rem;
}
.wallet-activity > li > span:last-child {
  font-size: 0.6rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}
.wallet-activity .is-credit {
  color: #2cdda8;
}
.wallet-activity .is-debit {
  color: #f18590;
}

@media (max-width: 1199px) {
  .wallet-row--primary {
    grid-template-columns: minmax(18rem, 1fr) minmax(17rem, 1fr);
  }
  .wallet-panel--status {
    grid-column: 1 / -1;
  }
  .wallet-row--history {
    grid-template-columns: minmax(0, 1.4fr) minmax(18rem, 0.9fr);
  }
}

@media (max-width: 899px) {
  .wallet-page .wallet-shell {
    width: min(calc(100% - 2rem), 50rem);
  }
  .wallet-kpis {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .wallet-row--primary,
  .wallet-row--history {
    grid-template-columns: 1fr;
  }
  .wallet-panel--status {
    grid-column: auto;
  }
  .wallet-side-stack {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 599px) {
  .wallet-page .wallet-shell {
    width: calc(100% - 1.5rem);
    padding-top: 1.65rem;
  }
  .wallet-heading h1 {
    font-size: clamp(2.35rem, 11.8vw, 3.18rem);
  }
  .wallet-kpis,
  .wallet-side-stack {
    grid-template-columns: 1fr;
  }
  .wallet-panel__head,
  .wallet-panel__body {
    padding-inline: 0.85rem;
  }
  .wallet-bank-empty__halo {
    right: 0.35rem;
    width: 5.8rem;
  }
  .wallet-bank-reassurance {
    flex-wrap: wrap;
  }
  .wallet-table-wrap {
    overflow-x: auto;
  }
  .wallet-table {
    min-width: 31rem;
  }
}

/* =================================================
   Governance — ownership-weighted proposal dashboard
   ================================================= */

.governance-page {
  min-height: calc(100vh - 4.75rem);
  background:
    radial-gradient(ellipse 44% 22% at 77% 5%, rgba(20, 191, 144, 0.075), transparent 71%),
    linear-gradient(180deg, #080c10 0%, #070a0d 44rem, #070a0d 100%);
}

.governance-page .governance-shell {
  width: min(calc(100% - clamp(2rem, 4vw, 5rem)), 96rem);
  max-width: none;
  padding-block: clamp(2.25rem, 3.7vw, 3.5rem) 3.5rem;
}

.governance-hero {
  display: grid;
  grid-template-columns: minmax(0, 0.98fr) minmax(28rem, 0.96fr);
  gap: clamp(1.25rem, 4vw, 4.25rem);
  align-items: end;
  padding-bottom: 1.35rem;
}

.governance-hero h1 {
  margin-top: 0.45rem;
  color: #f4f6f8;
  font-size: clamp(2.75rem, 4vw, 4.25rem);
  font-weight: 750;
  letter-spacing: -0.065em;
  line-height: 0.94;
}

.governance-hero h1 span {
  color: #29dca6;
}

.governance-hero > div > p:last-of-type {
  max-width: 34rem;
  margin-top: 1rem;
  color: #aeb8c3;
  font-size: 0.88rem;
  line-height: 1.65;
}

.governance-hero__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.7rem;
  margin-top: 1.25rem;
}

.governance-primary-action,
.governance-secondary-action {
  display: inline-flex;
  min-height: 2.32rem;
  align-items: center;
  gap: 0.62rem;
  padding: 0.56rem 0.88rem;
  border-radius: 0.43rem;
  font-size: 0.7rem;
  font-weight: 730;
  transition:
    filter 160ms ease,
    background-color 160ms ease,
    transform 160ms ease;
}

.governance-primary-action {
  background: linear-gradient(105deg, #1ed9a1, #26d7bd);
  color: #04231e;
}

.governance-primary-action:hover,
.governance-secondary-action:hover {
  filter: brightness(1.09);
  transform: translateY(-1px);
}

.governance-secondary-action {
  border: 1px solid rgba(139, 167, 177, 0.25);
  background: rgba(13, 18, 23, 0.7);
  color: #d9e0e5;
}

.governance-primary-action svg,
.governance-secondary-action svg,
.governance-information-strip svg,
.governance-creation a svg,
.governance-creation button svg,
.governance-row-actions a svg,
.governance-load-more svg,
.governance-about a svg {
  width: 0.9rem;
  height: 0.9rem;
}

.governance-eligibility,
.governance-kpi,
.governance-panel,
.governance-creation,
.governance-information-strip {
  border: 1px solid rgba(130, 158, 170, 0.2);
  border-radius: 0.72rem;
  background: linear-gradient(145deg, rgba(19, 25, 31, 0.97), rgba(10, 15, 19, 0.98));
