.governance-empty {
  display: flex;
  min-height: 10.8rem;
  align-items: center;
  justify-content: center;
  gap: 0.75rem;
  margin: 0 1.1rem 1rem;
  border: 1px dashed rgba(139, 168, 181, 0.14);
  border-radius: 0.58rem;
  color: #30dca7;
}

.governance-empty > svg {
  width: 1.35rem;
  height: 1.35rem;
}

.governance-empty strong {
  display: block;
  color: #e4e9ed;
  font-size: 0.68rem;
}

.governance-empty p {
  max-width: 12rem;
  margin-top: 0.22rem;
  color: #8995a0;
  font-size: 0.58rem;
  line-height: 1.5;
}

.governance-panel--about {
  display: flex;
  min-height: 9.25rem;
  gap: 0.82rem;
  padding: 1.15rem;
}

.governance-panel--about > span {
  flex: 0 0 auto;
  width: 2.4rem;
  height: 2.4rem;
  border-radius: 0.58rem;
}

.governance-panel--about > span svg {
  width: 1.1rem;
  height: 1.1rem;
}

.governance-panel--about h2 {
  color: #edf1f4;
  font-size: 0.78rem;
  font-weight: 720;
}

.governance-panel--about p {
  max-width: 17rem;
  margin-top: 0.42rem;
  color: #919da8;
  font-size: 0.61rem;
  line-height: 1.55;
}

.governance-panel--about a,
.governance-creation > a {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  margin-top: 0.78rem;
  color: #30dfa9;
  font-size: 0.62rem;
  font-weight: 720;
}

.governance-creation {
  display: grid;
  grid-template-columns: minmax(14rem, 0.82fr) minmax(0, 1.5fr);
  gap: 1.1rem 2rem;
  align-items: center;
  margin-top: 0.8rem;
  padding: 1.1rem 1.25rem;
}

.governance-creation h2 {
  margin-top: 0.3rem;
  color: #edf1f4;
  font-size: 0.92rem;
  font-weight: 720;
}

.governance-creation > div > p:last-child {
  margin-top: 0.4rem;
  color: #8e9ba6;
  font-size: 0.62rem;
  line-height: 1.55;
}

.governance-creation > p,
.governance-creation > a {
  grid-column: 2;
  margin-top: -0.7rem;
  color: #f18b95;
  font-size: 0.62rem;
}

.governance-creation > a {
  color: #30dfa9;
}

.governance-creation form {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr) auto;
  gap: 0.65rem;
  align-items: end;
}

.governance-creation label {
  display: grid;
  gap: 0.32rem;
  color: #aeb8c2;
  font-size: 0.58rem;
  font-weight: 650;
}

.governance-creation select,
.governance-creation input {
  min-width: 0;
  height: 2.25rem;
  border: 1px solid rgba(139, 166, 177, 0.19);
  border-radius: 0.38rem;
  background: rgba(7, 11, 15, 0.58);
  color: #e5eaf0;
  font-size: 0.66rem;
}

.governance-creation select {
  padding: 0 0.55rem;
}

.governance-creation input {
  padding: 0 0.65rem;
}

.governance-creation button {
  display: inline-flex;
  height: 2.25rem;
  align-items: center;
  gap: 0.48rem;
  padding: 0 0.75rem;
  border-radius: 0.4rem;
  background: linear-gradient(105deg, #1bd9a1, #27d7bd);
  color: #04231f;
  font-size: 0.63rem;
  font-weight: 740;
}

.governance-information-strip {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 0.7rem;
  align-items: center;
  margin-top: 0.8rem;
  padding: 0.75rem 1.05rem;
}

.governance-information-strip > svg {
  color: #aebbc5;
}

.governance-information-strip p {
  color: #9da9b4;
  font-size: 0.64rem;
  line-height: 1.45;
}

.governance-information-strip a {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  color: #31dfa9;
  font-size: 0.62rem;
  font-weight: 720;
  white-space: nowrap;
}

.governance-error {
  display: flex;
  gap: 1rem;
  align-items: center;
  padding: 2rem;
}

.governance-error > svg {
  width: 1.75rem;
  height: 1.75rem;
  color: #f18b95;
}

.governance-error h2 {
  color: #edf1f4;
  font-size: 0.98rem;
  font-weight: 720;
}

.governance-error p {
  margin-top: 0.3rem;
  color: #919da8;
  font-size: 0.7rem;
}

.governance-error button {
  margin-top: 0.7rem;
  color: #30dfa9;
  font-size: 0.67rem;
  font-weight: 720;
}

@media (max-width: 1199px) {
  .governance-hero {
    grid-template-columns: minmax(0, 1fr) minmax(23rem, 0.85fr);
  }
  .governance-kpis {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .governance-layout {
    grid-template-columns: minmax(0, 1.8fr) minmax(16rem, 0.9fr);
  }
}

@media (max-width: 899px) {
  .governance-page .governance-shell {
    width: min(calc(100% - 2rem), 50rem);
  }
  .governance-hero,
  .governance-layout,
  .governance-creation {
    grid-template-columns: 1fr;
  }
  .governance-eligibility {
    max-width: 42rem;
  }
  .governance-layout__side {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  }
  .governance-creation > p,
  .governance-creation > a {
    grid-column: auto;
    margin-top: 0;
  }
}

@media (max-width: 599px) {
  .governance-page .governance-shell {
    width: calc(100% - 1.5rem);
    padding-top: 1.7rem;
  }
  .governance-hero h1 {
    font-size: clamp(2.45rem, 12vw, 3.25rem);
  }
  .governance-eligibility {
    grid-template-columns: auto minmax(0, 1fr);
    padding: 1rem;
  }
  .governance-eligibility__seal {
    width: 4.3rem;
    height: 4.3rem;
    border-width: 0.48rem;
  }
  .governance-eligibility__rules {
    grid-column: 1 / -1;
    min-height: auto;
    padding: 0.75rem 0 0;
    border-top: 1px solid rgba(139, 164, 175, 0.12);
    border-left: 0;
  }
  .governance-kpis,
  .governance-layout__side {
    grid-template-columns: 1fr;
  }
  .governance-kpi {
    min-height: 5rem;
  }
  .governance-tabs {
    overflow-x: auto;
    padding-inline: 0.85rem;
  }
  .governance-tabs button {
    flex: 0 0 auto;
    padding-inline: 0.58rem;
  }
  .governance-panel__head,
  .governance-panel--activity .governance-panel__head {
    padding-inline: 0.85rem;
  }
  .governance-activity {
    padding-inline: 0.85rem;
  }
  .governance-creation {
    padding: 1rem;
  }
  .governance-creation form {
    grid-template-columns: 1fr;
  }
  .governance-creation button {
    width: fit-content;
  }
  .governance-information-strip {
    grid-template-columns: auto minmax(0, 1fr);
    align-items: start;
  }
  .governance-information-strip a {
    grid-column: 2;
  }
}

/* =================================================
   Asset detail page — reference implementation
   ================================================= */

.asset-detail-page {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  padding-bottom: 34px;
  background:
    radial-gradient(ellipse 34% 18% at 38% 4%, rgba(44, 69, 92, 0.12), transparent 72%),
    radial-gradient(ellipse 30% 30% at 82% 44%, rgba(17, 137, 103, 0.045), transparent 75%),
    linear-gradient(180deg, #060b0e 0%, #071014 55%, #070c10 100%);
}

.asset-detail-page::before {
  position: absolute;
  z-index: -1;
  inset: 0;
  background-image:
    linear-gradient(rgba(255, 255, 255, 0.012) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.012) 1px, transparent 1px);
  background-size: 72px 72px;
  mask-image: linear-gradient(to bottom, black, transparent 66%);
  content: "";
  pointer-events: none;
}

body:has(.asset-detail-page) header.sticky > .site-shell {
  height: 54px;
}

.asset-detail-shell {
  width: min(calc(100% - clamp(2rem, 4.6vw, 4.5rem)), 96rem);
  margin-inline: auto;
}

.asset-breadcrumbs {
  display: flex;
  min-height: 40px;
  align-items: center;
  gap: 11px;
  overflow: hidden;
  color: rgba(160, 174, 184, 0.78);
  font-size: 10px;
  white-space: nowrap;
}

.asset-breadcrumbs a {
  transition: color 180ms ease;
}

.asset-breadcrumbs a:hover {
  color: #2bdba6;
}

.asset-breadcrumbs > span:last-child {
  overflow: hidden;
  text-overflow: ellipsis;
}

.asset-workspace {
  display: block;
}

.asset-primary-column {
  min-width: 0;
}

.asset-hero {
  display: grid;
  grid-template-columns: minmax(270px, 0.9fr) minmax(360px, 1.36fr) minmax(280px, 0.92fr);
  gap: 18px;
  align-items: stretch;
}

.asset-showcase,
.asset-summary,
.asset-market-stats,
.asset-price-panel,
.asset-ai-panel,
.asset-ownership-panel,
.asset-holders-panel,
.asset-order-book,
.asset-recent-trades,
.asset-details-panel,
.asset-similar-card,
.asset-valuation-panel {
  border: 1px solid rgba(143, 172, 183, 0.16);
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.018), transparent 26%),
    linear-gradient(155deg, rgba(11, 21, 27, 0.94), rgba(3, 10, 14, 0.985));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.055),
    0 18px 42px rgba(0, 0, 0, 0.22);
}

.asset-showcase {
  position: relative;
  min-height: 410px;
  overflow: hidden;
  border-radius: 10px;
  background:
    radial-gradient(ellipse 46% 54% at 50% 69%, rgba(22, 224, 159, 0.17), transparent 70%),
    radial-gradient(circle at 56% 28%, rgba(111, 80, 176, 0.1), transparent 48%),
    linear-gradient(180deg, rgba(9, 16, 21, 0.96), rgba(2, 10, 12, 0.99));
}

.asset-showcase::after {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(112deg, transparent 36%, rgba(255, 255, 255, 0.034) 46%, transparent 54%),
    radial-gradient(circle at 50% 110%, rgba(24, 226, 161, 0.16), transparent 42%);
  content: "";
  pointer-events: none;
}

.asset-showcase > img {
  position: absolute;
  z-index: 3;
  top: 18px;
  bottom: 14px;
  left: 50%;
  width: min(78%, 292px);
  height: 374px;
  object-fit: contain;
  filter: saturate(1.05) contrast(1.04) drop-shadow(0 24px 26px rgba(0, 0, 0, 0.66));
  transform: translateX(-50%);
  transition:
    transform 420ms cubic-bezier(0.22, 1, 0.36, 1),
    filter 300ms ease;
}

.market-card-media-image {
  position: relative;
  z-index: 2;
  width: 100%;
  height: 100%;
  object-fit: contain;
  padding: 9px;
  filter: drop-shadow(0 16px 15px rgba(0, 0, 0, 0.48));
}

.asset-showcase:hover > img {
  filter: saturate(1.09) contrast(1.06) drop-shadow(0 30px 32px rgba(0, 0, 0, 0.7));
  transform: translateX(-50%) scale(1.018);
}

.asset-slab-light {
  position: absolute;
  z-index: 1;
  bottom: 3px;
  left: 50%;
  width: 286px;
  height: 74px;
  border-radius: 50%;
  background: rgba(25, 231, 164, 0.25);
  filter: blur(28px);
  transform: translateX(-50%);
}

.asset-pedestal {
  position: absolute;
  z-index: 2;
  bottom: -7px;
  left: 50%;
  width: 248px;
  height: 28px;
  border: 1px solid rgba(30, 230, 166, 0.3);
  border-radius: 50% 50% 12px 12px;
  background: linear-gradient(180deg, rgba(18, 87, 70, 0.8), rgba(2, 12, 14, 0.98));
  box-shadow:
    0 -5px 18px rgba(32, 224, 162, 0.24),
    0 7px 28px rgba(0, 0, 0, 0.7);
  transform: translateX(-50%);
}

.asset-particles {
  position: absolute;
  inset: 0;
}

.asset-particles i {
  position: absolute;
  width: 2px;
  height: 2px;
  border-radius: 50%;
  background: #31e2ad;
  box-shadow: 0 0 8px #27dea7;
  opacity: 0.78;
  animation: asset-particle-float 4.8s ease-in-out infinite alternate;
}

.asset-particles i:nth-child(1) {
  top: 20%;
  left: 18%;
}
.asset-particles i:nth-child(2) {
  top: 43%;
  left: 14%;
  animation-delay: -1s;
}
.asset-particles i:nth-child(3) {
  top: 63%;
  left: 17%;
  animation-delay: -2s;
}
.asset-particles i:nth-child(4) {
  top: 30%;
  left: 78%;
  animation-delay: -3s;
}
.asset-particles i:nth-child(5) {
  top: 55%;
  left: 83%;
  animation-delay: -0.5s;
}
.asset-particles i:nth-child(6) {
  top: 70%;
  left: 79%;
  animation-delay: -2.5s;
}
.asset-particles i:nth-child(7) {
  top: 16%;
  left: 66%;
  animation-delay: -1.5s;
}
.asset-particles i:nth-child(8) {
  top: 74%;
  left: 34%;
  animation-delay: -3.5s;
}
.asset-particles i:nth-child(9) {
  top: 37%;
  left: 28%;
  animation-delay: -0.8s;
}
.asset-particles i:nth-child(10) {
  top: 83%;
  left: 68%;
  animation-delay: -2.2s;
}
.asset-particles i:nth-child(11) {
  top: 12%;
  left: 42%;
  animation-delay: -4s;
}

.asset-live-badge {
  position: absolute;
  z-index: 6;
  top: 11px;
  left: 11px;
  padding: 5px 9px;
  border: 1px solid rgba(25, 224, 162, 0.8);
  border-radius: 4px;
  color: #2ae1ab;
  font-family: var(--font-mono);
  font-size: 9px;
  line-height: 1;
  text-transform: uppercase;
}

.asset-grade-badge {
  position: absolute;
  z-index: 6;
  top: 14px;
  right: 14px;
  display: grid;
  width: 78px;
  min-height: 104px;
  padding: 8px 6px;
  place-content: center;
  border: 1px solid rgba(199, 212, 219, 0.28);
  border-radius: 7px;
  background: rgba(7, 12, 17, 0.84);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.09),
    0 15px 28px rgba(0, 0, 0, 0.34);
  text-align: center;
  backdrop-filter: blur(10px);
}

.asset-grade-badge small {
  color: #6f9ac7;
  font-size: 10px;
  font-weight: 700;
}

.asset-grade-badge strong {
  margin-top: 1px;
  font-family: var(--font-display);
  font-size: 26px;
  line-height: 1;
}

.asset-showcase-image {
  position: absolute;
  z-index: 3;
  inset: 72px 34px 42px;
  display: grid;
  place-items: center;
  border: 1px dashed rgba(143, 172, 183, 0.22);
  border-radius: 9px;
  background: rgba(3, 12, 15, 0.46);
  color: rgba(172, 188, 196, 0.76);
  font-size: 11px;
  text-align: center;
}

.asset-grade-badge > span {
  margin-top: 4px;
  color: rgba(205, 215, 220, 0.88);
  font-size: 8px;
  line-height: 1.2;
}

.asset-grade-badge em {
  margin-top: 6px;
  color: rgba(230, 236, 239, 0.9);
  font-family: var(--font-mono);
  overflow: hidden;
  font-size: 6px;
  font-style: normal;
  text-transform: uppercase;
}

.asset-watch-button {
  position: absolute;
  z-index: 6;
  top: 128px;
  right: 14px;
  display: grid;
  width: 78px;
  height: 54px;
  place-items: center;
  align-content: center;
  gap: 3px;
  border: 1px solid rgba(190, 207, 214, 0.23);
  border-radius: 7px;
  background: rgba(5, 11, 15, 0.76);
  color: rgba(233, 239, 241, 0.92);
  font-size: 9px;
  transition:
    border-color 180ms ease,
    background 180ms ease,
    transform 180ms ease;
}

.asset-watch-button svg {
  width: 16px;
  height: 16px;
}
.asset-watch-button:hover,
.asset-watch-button[aria-pressed="true"] {
  border-color: rgba(36, 220, 165, 0.52);
  background: rgba(24, 104, 82, 0.32);
  transform: translateY(-1px);
}

.asset-category-pill {
  position: absolute;
  z-index: 7;
  bottom: 10px;
  left: 10px;
  display: inline-flex;
  height: 33px;
  align-items: center;
  gap: 7px;
  padding: 0 12px;
  border: 1px solid rgba(166, 194, 201, 0.18);
  border-radius: 17px;
  background: rgba(5, 13, 17, 0.8);
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.28);
  font-size: 10px;
  backdrop-filter: blur(10px);
}

.asset-category-pill i {
  width: 13px;
  height: 13px;
  border: 4px solid #eef2f3;
  border-top-color: #e23c44;
  border-radius: 50%;
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.5);
}

.asset-summary {
  min-width: 0;
  display: flex;
  min-height: 410px;
  flex-direction: column;
  justify-content: space-between;
  padding: 24px;
  border-radius: 10px;
}

.asset-summary-top {
  display: grid;
  min-height: 228px;
  grid-template-columns: minmax(0, 1fr) 168px;
  gap: 20px;
}

.asset-identity-row {
  display: flex;
  align-items: center;
  gap: 9px;
  font-family: var(--font-mono);
  font-size: 9px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.asset-identity-row > span {
  color: #25dba4;
  font-weight: 700;
}
.asset-identity-row > i {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: rgba(173, 188, 195, 0.6);
}
.asset-identity-row > strong {
  color: rgba(233, 238, 240, 0.94);
  font-size: 8px;
}
.asset-identity-row > em {
  padding: 4px 7px;
  border: 1px solid rgba(35, 221, 167, 0.72);
  border-radius: 3px;
  color: #27dca6;
  font-size: 8px;
  font-style: normal;
}

.asset-description h1 {
  margin-top: 9px;
  font-family: var(--font-display);
  font-size: clamp(26px, 2vw, 34px);
  font-weight: 690;
  line-height: 1.03;
  letter-spacing: -0.042em;
}

.asset-grade-line {
  margin-top: 8px;
  color: rgba(182, 194, 201, 0.82);
  font-size: 12px;
}

.asset-description-copy {
  max-width: 450px;
  margin-top: 14px;
  color: rgba(189, 200, 206, 0.88);
  font-size: 13px;
  line-height: 1.58;
}

.asset-trade-summary > span,
.asset-owned-summary > span {
  color: rgba(151, 168, 177, 0.82);
  font-family: var(--font-mono);
  font-size: 8px;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.asset-trade-summary > strong {
  display: block;
  margin-top: 6px;
  font-family: var(--font-display);
  font-size: 31px;
  line-height: 1;
}

.asset-trade-summary > em {
  display: block;
  margin-top: 8px;
  color: #27dca6;
  font-family: var(--font-mono);
  font-size: 9px;
  font-style: normal;
  font-weight: 600;
}

.asset-buy-action,
.asset-sell-action {
  display: grid;
  width: 100%;
  height: 32px;
  place-items: center;
  margin-top: 12px;
  border-radius: 6px;
  font-size: 10px;
  font-weight: 700;
  transition:
    transform 180ms ease,
    filter 180ms ease,
    box-shadow 180ms ease;
}

.asset-buy-action {
  border: 1px solid #1fd39e;
  background: linear-gradient(135deg, #2ce1ac, #12be8a);
  box-shadow: 0 8px 20px rgba(22, 202, 145, 0.15);
  color: #031611;
}

.asset-sell-action {
  margin-top: 8px;
  border: 1px solid rgba(238, 70, 75, 0.85);
  color: #ff5b5e;
}

.asset-buy-action:hover,
.asset-sell-action:hover {
  transform: translateY(-1px);
  filter: brightness(1.06);
}

.asset-owned-summary {
  height: 59px;
  margin-top: 10px;
}
.asset-owned-summary > span {
  line-height: 1;
}
.asset-owned-summary > strong {
  display: block;
  margin-top: 4px;
  font-size: 12px;
  line-height: 1;
}
.asset-owned-summary > div {
  height: 5px;
  margin-top: 5px;
  overflow: hidden;
  border-radius: 3px;
  background: rgba(160, 177, 185, 0.13);
}
.asset-owned-summary > div i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: #2ddfac;
  box-shadow: 0 0 12px rgba(45, 223, 172, 0.5);
  animation: asset-progress-grow 0.8s ease both;
}
.asset-owned-summary > small {
  display: block;
  margin-top: 5px;
  color: rgba(151, 166, 175, 0.82);
  font-size: 9px;
  line-height: 1;
}

.asset-ranking-strip {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  min-height: 76px;
  margin-top: 24px;
  overflow: hidden;
  border: 1px solid rgba(143, 172, 183, 0.14);
  border-radius: 7px;
  background: rgba(7, 14, 18, 0.58);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.035);
}

.asset-ranking-strip > dl {
