    padding-block: 27px 18px;
  }

  .collectors-hero-copy h1 {
    font-size: 38px;
    line-height: 0.98;
  }

  .collectors-hero-copy > p:last-child {
    margin-top: 14px;
    font-size: 12.5px;
    line-height: 1.55;
  }

  .collectors-hero-metrics {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 12px;
    margin-right: 0;
    overflow: visible;
    padding: 2px 0 0;
  }

  .collectors-hero-metrics::-webkit-scrollbar,
  .featured-holdings-grid::-webkit-scrollbar,
  .collectors-filter-list::-webkit-scrollbar {
    display: none;
  }

  .collectors-metric-card {
    min-height: 112px;
    flex: none;
    padding: 17px 18px 14px;
  }

  .collectors-metric-card:last-child {
    grid-column: 1 / -1;
  }

  .collectors-metric-card > strong {
    margin-top: 10px;
    font-size: 25px;
  }

  .collectors-metric-card > svg {
    top: 17px;
    right: 17px;
    width: 23px;
    height: 23px;
  }

  .collectors-metric-chart {
    right: 17px;
    bottom: 12px;
    left: 17px;
    height: 37px;
  }

  .collectors-filter-bar {
    padding-block: 11px 13px;
  }

  .collectors-search,
  .collectors-search input {
    height: 38px;
  }

  .collectors-filter-list {
    margin-top: 8px;
  }

  .collectors-filter-list button {
    min-height: 35px;
    padding-inline: 13px;
  }

  .collectors-spotlight {
    gap: 13px;
    padding-top: 13px;
  }

  .featured-holdings-grid {
    display: flex;
    margin-right: -15px;
    overflow-x: auto;
    padding: 1px 15px 7px 0;
    scroll-snap-type: x mandatory;
  }

  .featured-holding-card {
    flex: 0 0 152px;
    scroll-snap-align: start;
  }

  .featured-holding-media {
    height: 132px;
  }

  .collectors-leaderboard {
    min-height: 360px;
  }

  .collectors-leaderboard li {
    min-height: 52px;
  }

  .collectors-directory {
    padding-top: 22px;
  }

  .collector-profile-card {
    min-height: 292px;
    padding: 14px;
  }

  .collector-profile-copy p {
    min-height: 2.65em;
    font-size: 10px;
  }

  .collector-profile-chart {
    height: 29px;
    margin-top: 8px;
  }

  .collector-mini-strip {
    margin-top: 9px;
  }

  .collector-mini-holding,
  .collector-more-assets {
    height: 53px;
  }
}

/* FSQA-003: a persistent, roomy search field is more usable than an icon-only
   field that relies on focus expansion to expose its text area. */
.collectors-search,
.collectors-search:focus-within,
.collectors-search:has(input:not(:placeholder-shown)) {
  width: min(100%, 360px);
  min-width: min(100%, 360px);
}

.collectors-search input {
  width: 100%;
}

@media (max-width: 640px) {
  .collectors-search,
  .collectors-search:focus-within,
  .collectors-search:has(input:not(:placeholder-shown)) {
    width: 100%;
    min-width: 0;
  }
}

/* Authenticated dashboard: dense, dark financial workspace with data-driven empty states. */
.dashboard-page {
  min-height: calc(100vh - 4.75rem);
  background:
    radial-gradient(circle at 76% 5%, rgba(0, 229, 190, 0.08), transparent 26rem),
    linear-gradient(180deg, #080b0f 0%, var(--color-background) 44rem);
}

.dashboard-shell {
  padding-block: 1.25rem 2.5rem;
}

.dashboard-heading {
  position: relative;
  overflow: hidden;
  min-height: 7.8rem;
  padding: 0.25rem 0 1.25rem;
}
.dashboard-heading__title {
  position: relative;
  z-index: 1;
  margin-top: 0.45rem;
  font-family: var(--font-display);
  font-size: clamp(2.65rem, 4vw, 4.25rem);
  font-weight: 750;
  line-height: 0.98;
  letter-spacing: -0.06em;
}
.dashboard-heading__copy {
  position: relative;
  z-index: 1;
  margin-top: 0.6rem;
  color: var(--color-subtle);
  font-size: 0.94rem;
}
.dashboard-heading__waves {
  position: absolute;
  right: -5rem;
  top: -3.4rem;
  width: min(53vw, 48rem);
  height: 15rem;
  opacity: 0.7;
  background: repeating-radial-gradient(
    106% 100% at 17% 100%,
    transparent 0 1.55rem,
    rgba(14, 223, 184, 0.12) 1.6rem 1.66rem,
    transparent 1.7rem 2.25rem
  );
  mask-image: linear-gradient(90deg, transparent 0%, #000 28%, #000 82%, transparent 100%);
  pointer-events: none;
}

.dashboard-kpis {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1rem;
}
.dashboard-kpi,
.dashboard-panel {
  border: 1px solid rgba(158, 174, 194, 0.15);
  border-radius: 0.82rem;
  background: linear-gradient(145deg, rgba(23, 28, 36, 0.96), rgba(14, 18, 24, 0.96));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.025),
    0 14px 32px rgba(0, 0, 0, 0.16);
}
.dashboard-kpi {
  display: flex;
  min-height: 7.35rem;
  gap: 0.85rem;
  align-items: flex-start;
  padding: 1rem 1.1rem;
}
.dashboard-kpi--loading {
  align-items: center;
}
.dashboard-icon-box {
  display: grid;
  flex: 0 0 auto;
  width: 3rem;
  height: 3rem;
  place-items: center;
  border: 1px solid rgba(20, 233, 193, 0.26);
  border-radius: 0.68rem;
  background: radial-gradient(circle at 32% 30%, rgba(12, 214, 176, 0.2), rgba(10, 52, 49, 0.3));
  color: var(--color-accent);
}
.dashboard-icon-box svg {
  width: 1.26rem;
  height: 1.26rem;
  stroke-width: 1.7;
}
.dashboard-kpi__label {
  color: #aab3c1;
  font-size: 0.78rem;
  font-weight: 600;
}
.dashboard-kpi__value {
  display: block;
  overflow: hidden;
  margin-top: 0.38rem;
  color: var(--color-foreground);
  font-size: clamp(1.32rem, 1.7vw, 1.6rem);
  font-weight: 700;
  letter-spacing: -0.035em;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.dashboard-kpi__detail {
  overflow: hidden;
  margin-top: 0.48rem;
  color: #7d8797;
  font-size: 0.7rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.dashboard-kpis__error {
  grid-column: 1 / -1;
  min-height: 7.35rem;
}

.dashboard-row {
  display: grid;
  gap: 1rem;
  margin-top: 1rem;
}
.dashboard-row--three {
  grid-template-columns: minmax(0, 1.08fr) minmax(0, 0.92fr) minmax(0, 1.08fr);
}
.dashboard-row--lower {
  grid-template-columns: minmax(16rem, 0.9fr) minmax(0, 1.16fr) minmax(16rem, 1fr);
}
.dashboard-panel {
  display: flex;
  min-width: 0;
  min-height: 16.6rem;
  flex-direction: column;
  overflow: hidden;
}
.dashboard-row--lower .dashboard-panel {
  min-height: 16.2rem;
}
.dashboard-panel__head {
  display: flex;
  min-height: 3.55rem;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.9rem 1.1rem 0.65rem;
}
.dashboard-panel__head h2 {
  display: flex;
  align-items: center;
  gap: 0.58rem;
  color: var(--color-foreground);
  font-size: 0.94rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}
.dashboard-panel__title-icon {
  color: var(--color-accent);
}
.dashboard-panel__title-icon svg {
  width: 1.06rem;
  height: 1.06rem;
  stroke-width: 1.75;
}
.dashboard-panel__action {
  flex: 0 0 auto;
  color: var(--color-accent);
  font-size: 0.72rem;
  font-weight: 700;
}
.dashboard-panel__action:hover,
.dashboard-panel__footer:hover {
  color: #6bf3d4;
}
.dashboard-panel__body {
  min-height: 0;
  flex: 1;
  padding: 0 1.1rem 0.8rem;
}
.dashboard-panel__subheading {
  margin: -0.2rem 0 0.55rem;
  color: var(--color-accent);
  font-size: 0.69rem;
  font-weight: 700;
}
.dashboard-panel__footer {
  display: flex;
  min-height: 2.28rem;
  align-items: center;
  gap: 0.45rem;
  border-top: 1px solid rgba(158, 174, 194, 0.11);
  padding: 0.48rem 1.1rem;
  color: #b9c1ce;
  font-size: 0.76rem;
  font-weight: 600;
}
.dashboard-panel__footer svg {
  width: 0.9rem;
  height: 0.9rem;
}
.dashboard-panel__empty {
  display: grid;
  min-height: 8.3rem;
  place-items: center;
  border: 1px dashed rgba(158, 174, 194, 0.14);
  border-radius: 0.6rem;
  color: #8993a2;
  font-size: 0.78rem;
  text-align: center;
}
.dashboard-panel__error {
  display: grid;
  min-height: 8rem;
  place-content: center;
  gap: 0.65rem;
  color: #aeb6c2;
  font-size: 0.8rem;
  text-align: center;
}
.dashboard-panel__error button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  color: var(--color-accent);
  font-size: 0.78rem;
  font-weight: 700;
}
.dashboard-panel__error button svg {
  width: 0.88rem;
  height: 0.88rem;
}

.dashboard-table-wrap {
  overflow-x: auto;
}
.dashboard-table {
  width: 100%;
  min-width: 28rem;
  border-collapse: collapse;
  color: #d8dde5;
  font-size: 0.71rem;
}
.dashboard-table--holdings {
  min-width: 0;
  table-layout: fixed;
}
.dashboard-table--holdings th:first-child {
  width: 38%;
}
.dashboard-table th {
  padding: 0.32rem 0.14rem 0.52rem;
  color: #7f8998;
  font-size: 0.59rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-align: left;
  text-transform: uppercase;
}
.dashboard-table td {
  max-width: 10rem;
  overflow: hidden;
  border-top: 1px solid rgba(158, 174, 194, 0.095);
  padding: 0.48rem 0.14rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.dashboard-table td:first-child,
.dashboard-table th:first-child {
  padding-left: 0;
}
.dashboard-order-side,
.dashboard-order-status {
  display: inline-flex;
  align-items: center;
  min-height: 1.35rem;
  border-radius: 0.3rem;
  padding: 0.14rem 0.38rem;
  font-size: 0.63rem;
  font-weight: 700;
}
.dashboard-order-side.is-buy,
.dashboard-order-status {
  border: 1px solid rgba(12, 219, 169, 0.2);
  background: rgba(9, 176, 137, 0.13);
  color: #20dcb4;
}
.dashboard-order-side.is-sell {
  border: 1px solid rgba(246, 99, 112, 0.2);
  background: rgba(197, 53, 68, 0.13);
  color: #ff7883;
}

.dashboard-activity-list,
.dashboard-transaction-list,
.dashboard-market-list {
  display: grid;
}
.dashboard-activity-list li,
.dashboard-transaction-list li,
.dashboard-market-list li {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 0.65rem;
  border-top: 1px solid rgba(158, 174, 194, 0.095);
  padding: 0.56rem 0;
}
.dashboard-activity-list li:first-child,
.dashboard-transaction-list li:first-child,
.dashboard-market-list li:first-child {
  border-top: 0;
}
.dashboard-activity-list strong,
.dashboard-transaction-list strong,
.dashboard-market-list strong {
  display: block;
  overflow: hidden;
  color: #e7eaf0;
  font-size: 0.72rem;
  font-weight: 650;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.dashboard-activity-list span:not(.dashboard-activity-icon),
.dashboard-transaction-list span:not(.dashboard-activity-icon),
.dashboard-market-list span:not(.dashboard-asset-placeholder) {
  display: block;
  overflow: hidden;
  margin-top: 0.13rem;
  color: #7f8998;
  font-size: 0.64rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.dashboard-activity-icon,
.dashboard-asset-placeholder {
  display: grid;
  flex: 0 0 auto;
  width: 1.9rem;
  height: 1.9rem;
  place-items: center;
  border-radius: 0.45rem;
}
.dashboard-activity-icon.is-credit {
  background: rgba(5, 158, 122, 0.17);
  color: #23d9b4;
}
.dashboard-activity-icon.is-debit {
  background: rgba(190, 57, 69, 0.17);
  color: #ff7781;
}
.dashboard-activity-icon svg,
.dashboard-asset-placeholder svg {
  width: 0.9rem;
  height: 0.9rem;
  stroke-width: 1.85;
}
.dashboard-asset-placeholder {
  border: 1px solid rgba(158, 174, 194, 0.14);
  background: #1d2630;
  color: #a2adba;
}
.dashboard-asset-placeholder--small {
  width: 1.7rem;
  height: 1.7rem;
}
.dashboard-asset-placeholder img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
}

.dashboard-panel--allocation .dashboard-panel__body {
  display: flex;
  align-items: center;
}
.dashboard-allocation-empty {
  display: flex;
  width: 100%;
  min-height: 8rem;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  color: #8993a2;
  text-align: left;
}
.dashboard-allocation-ring {
  display: grid;
  flex: 0 0 auto;
  width: 5.3rem;
  height: 5.3rem;
  place-items: center;
  border: 0.82rem solid #303a48;
  border-top-color: rgba(20, 233, 193, 0.8);
  border-right-color: rgba(58, 133, 238, 0.68);
  border-radius: 50%;
  color: #98a2b2;
}
.dashboard-allocation-ring svg {
  width: 1.4rem;
  height: 1.4rem;
}
.dashboard-allocation-empty strong {
  display: block;
  color: #dce1e8;
  font-size: 0.75rem;
}
.dashboard-allocation-empty p {
  max-width: 12rem;
  margin-top: 0.32rem;
  font-size: 0.67rem;
  line-height: 1.45;
}

@media (max-width: 1180px) {
  .dashboard-row--three,
  .dashboard-row--lower {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .dashboard-row--three > :last-child,
  .dashboard-row--lower > :last-child {
    grid-column: 1 / -1;
  }
}
@media (max-width: 900px) {
  .dashboard-kpis {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .dashboard-heading__waves {
    right: -12rem;
    width: 68vw;
    opacity: 0.45;
  }
}
@media (max-width: 680px) {
  .dashboard-shell {
    padding-block: 1.1rem 1.8rem;
  }
  .dashboard-heading {
    min-height: 0;
    padding-bottom: 1.05rem;
  }
  .dashboard-heading__title {
    font-size: clamp(2.4rem, 12vw, 3.1rem);
  }
  .dashboard-heading__copy {
    max-width: 20rem;
    font-size: 0.86rem;
    line-height: 1.5;
  }
  .dashboard-heading__waves {
    display: none;
  }
  .dashboard-kpis,
  .dashboard-row--three,
  .dashboard-row--lower {
    grid-template-columns: minmax(0, 1fr);
  }
  .dashboard-row--three > :last-child,
  .dashboard-row--lower > :last-child {
    grid-column: auto;
  }
  .dashboard-kpi {
    min-height: 6.6rem;
  }
  .dashboard-panel {
    min-height: 15.5rem;
  }
  .dashboard-panel__head,
  .dashboard-panel__body,
  .dashboard-panel__footer {
    padding-inline: 0.88rem;
  }
}

/* Portfolio overview v2: a compact, consumer-first hierarchy.  This block
   intentionally sits last so older dashboard variants cannot reintroduce
   oversized cards or the one-holding blank-state gap. */
.portfolio-page.portfolio-page--approved .portfolio-shell {
  width: min(calc(100% - 3rem), 108rem);
  padding-block: 1.85rem 3.75rem;
}

.portfolio-page.portfolio-page--approved .portfolio-heading {
  display: grid;
  min-height: 0;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: end;
  gap: 1.5rem;
  padding-bottom: 1.15rem;
}

.portfolio-page.portfolio-page--approved .portfolio-heading h1 {
  font-size: clamp(2.1rem, 3.6vw, 3.65rem);
  line-height: 0.98;
}

.portfolio-page.portfolio-page--approved .portfolio-heading > div > p:last-child {
  max-width: 34rem;
  margin-top: 0.55rem;
  font-size: 0.88rem;
}

.portfolio-page.portfolio-page--approved .portfolio-heading__overview-actions {
  display: grid;
  justify-items: end;
  gap: 0.55rem;
}

.portfolio-page.portfolio-page--approved .portfolio-kpis {
  grid-template-columns: minmax(0, 1.25fr) repeat(2, minmax(0, 1fr));
  gap: 0.8rem;
  margin-bottom: 0.9rem;
}

.portfolio-page.portfolio-page--approved .portfolio-summary-kpi {
  min-height: 6.7rem;
  border-radius: 0.78rem;
  padding: 0.9rem 1rem;
}

.portfolio-page.portfolio-page--approved .portfolio-summary-kpi--primary {
  border-color: rgba(35, 217, 180, 0.28);
  background: linear-gradient(145deg, rgba(11, 38, 39, 0.96), rgba(12, 22, 28, 0.98));
}

.portfolio-page.portfolio-page--approved .portfolio-kpi__content strong {
  font-size: clamp(1.35rem, 2vw, 1.95rem);
}

.portfolio-page.portfolio-page--approved .portfolio-kpi__content span {
  color: #9aabb0;
  font-size: 0.66rem;
}

.portfolio-page.portfolio-page--approved .portfolio-overview-content {
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.38fr);
  grid-template-rows: auto auto;
  align-items: start;
  gap: 0.9rem;
  margin-top: 0;
}

.portfolio-page.portfolio-page--approved .portfolio-overview-content > .portfolio-panel--holdings {
  grid-row: 1 / span 2;
}

.portfolio-page.portfolio-page--approved .portfolio-overview-content .portfolio-panel {
  min-height: 0;
}

.portfolio-page.portfolio-page--approved .portfolio-overview-content .portfolio-panel--holdings {
  min-height: 0;
}

.portfolio-page.portfolio-page--approved .portfolio-overview-bottom {
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.05fr);
  gap: 0.9rem;
  margin-top: 0.9rem;
}

.portfolio-page.portfolio-page--approved .portfolio-overview-discovery {
  margin-top: 0.9rem;
}

.portfolio-page.portfolio-page--approved .portfolio-overview-discovery .portfolio-panel {
  min-height: 0;
}

.portfolio-page.portfolio-page--approved .portfolio-panel {
  border-radius: 0.82rem;
}

.portfolio-page.portfolio-page--approved .portfolio-panel__head {
  min-height: 3.35rem;
  padding: 0.85rem 1.05rem 0.62rem;
}

.portfolio-page.portfolio-page--approved .portfolio-panel__body {
  padding: 0 1.05rem 1.05rem;
}

.portfolio-page.portfolio-page--approved .portfolio-panel--hero-performance {
  overflow: visible;
}

.portfolio-page.portfolio-page--approved .portfolio-panel--hero-performance .portfolio-panel__body {
  overflow: visible;
}

.portfolio-page.portfolio-page--approved .portfolio-performance-hero {
  display: flex;
  min-height: 0;
  flex-direction: column;
  gap: 0.7rem;
}

.portfolio-page.portfolio-page--approved .portfolio-performance-hero__value > span {
  font-size: 0.62rem;
  letter-spacing: 0.04em;
}

.portfolio-page.portfolio-page--approved .portfolio-performance-hero__value > strong {
  margin-top: 0.22rem;
  font-size: clamp(1.55rem, 2.5vw, 2.15rem);
}

.portfolio-page.portfolio-page--approved .portfolio-performance-chart {
  padding-top: 0.3rem;
}

.portfolio-page.portfolio-page--approved .portfolio-performance-chart__plot,
.portfolio-page.portfolio-page--approved .portfolio-performance-chart__plot svg {
  min-height: 12.25rem;
  height: 12.25rem;
}

.portfolio-page.portfolio-page--approved .portfolio-performance-periods {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0 1rem;
  margin-top: 0.1rem;
