.portfolio-page.portfolio-page--approved .portfolio-performance-periods > div {
  padding: 0.5rem 0;
}

.portfolio-page.portfolio-page--approved .portfolio-performance-chart__legend {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr)) minmax(7rem, auto);
  gap: 0.65rem;
  align-items: center;
  margin-top: 0.2rem;
  color: #8799a1;
  font-size: 0.62rem;
