.portfolio-page.portfolio-page--approved .portfolio-performance-chart__legend i.is-cash {
  background: #3d8fe8;
}

.portfolio-page.portfolio-page--approved .portfolio-performance-chart__legend span {
  display: grid;
  min-width: 0;
  gap: 0.12rem;
  overflow: visible;
  white-space: normal;
}

.portfolio-page.portfolio-page--approved .portfolio-performance-chart__legend strong {
  color: #e2ece9;
  font-size: 0.68rem;
  font-weight: 700;
  white-space: nowrap;
}

.portfolio-page.portfolio-page--approved .portfolio-performance-chart__legend small {
  color: #82949d;
