  }

  .portfolio-page.portfolio-page--approved .portfolio-compact-holding__action {
    grid-column: 2;
    justify-self: start;
  }
}

@media (max-width: 900px) {
  .portfolio-page.portfolio-page--approved .portfolio-heading {
    grid-template-columns: 1fr;
    align-items: start;
  }

  .portfolio-page.portfolio-page--approved .portfolio-heading__overview-actions {
    justify-items: start;
  }

  .portfolio-page.portfolio-page--approved .portfolio-overview-content,
  .portfolio-page.portfolio-page--approved .portfolio-overview-bottom {
    grid-template-columns: 1fr;
    grid-template-rows: auto;
  }

  .portfolio-page.portfolio-page--approved
    .portfolio-overview-content
