    grid-row: auto;
  }
}

@media (max-width: 680px) {
  .portfolio-page.portfolio-page--approved .portfolio-shell {
    width: calc(100% - 1.25rem);
    padding-block: 1.15rem 2.5rem;
  }

  .portfolio-page.portfolio-page--approved .portfolio-kpis {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .portfolio-page.portfolio-page--approved .portfolio-summary-kpi--primary {
    grid-column: 1 / -1;
  }

  .portfolio-page.portfolio-page--approved .portfolio-compact-holding {
    grid-template-columns: 1fr;
    gap: 0.7rem;
  }

  .portfolio-page.portfolio-page--approved .portfolio-compact-holding__metrics {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .portfolio-page.portfolio-page--approved .portfolio-compact-holding__action {
    grid-column: auto;
    justify-self: stretch;
    justify-content: center;
  }

  .portfolio-page.portfolio-page--approved .portfolio-performance-periods {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .portfolio-page.portfolio-page--approved .portfolio-performance-chart__legend {
    grid-template-columns: 1fr 1fr;
  }

  .portfolio-page.portfolio-page--approved .portfolio-performance-chart__legend-total {
    grid-column: 1 / -1;
    justify-content: flex-start;
    border-top: 1px solid rgba(143, 168, 178, 0.14);
    border-left: 0;
    padding: 0.55rem 0 0;
  }

  .portfolio-page.portfolio-page--approved .portfolio-performance-chart__legend-total span {
    text-align: left;
  }

  .portfolio-page.portfolio-page--approved .portfolio-market-watch {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 480px) {
  .portfolio-page.portfolio-page--approved .portfolio-kpis {
    grid-template-columns: 1fr;
  }

  .portfolio-page.portfolio-page--approved .portfolio-summary-kpi--primary {
    grid-column: auto;
  }

  .portfolio-page.portfolio-page--approved .portfolio-compact-holding__metrics {
    gap: 0.45rem;
  }

  .portfolio-page.portfolio-page--approved .portfolio-compact-holding__metrics dd {
    font-size: 0.72rem;
  }
}

/* Bank-link security step-up dialog. The dialog is intentionally compact so
   the destructive action stays clear on desktop and mobile alike. */
.wallet-bank-dialog-backdrop {
  position: fixed;
  z-index: 100;
  inset: 0;
  display: grid;
  overflow-y: auto;
  place-items: center;
  padding: 1rem;
  background: rgba(2, 6, 9, 0.78);
  backdrop-filter: blur(10px);
}
.wallet-bank-dialog {
  width: min(100%, 31rem);
  border: 1px solid rgba(49, 219, 171, 0.25);
  border-radius: 0.85rem;
  background: linear-gradient(150deg, #18232b, #0d141a 78%);
  box-shadow:
    0 24px 80px rgba(0, 0, 0, 0.48),
    inset 0 1px 0 rgba(255, 255, 255, 0.04);
  color: #e9f0f1;
  padding: 1.15rem;
}
.wallet-bank-dialog > header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
}
.wallet-bank-dialog h2 {
  margin-top: 0.25rem;
  font-size: 1.22rem;
  letter-spacing: -0.035em;
}
.wallet-bank-dialog__close {
  width: 2rem;
  height: 2rem;
  border: 1px solid rgba(158, 174, 194, 0.18);
  border-radius: 0.4rem;
  color: #aebbc1;
  font-size: 1.35rem;
  line-height: 1;
}
.wallet-bank-dialog__account {
  margin-top: 0.95rem;
  border: 1px solid rgba(158, 174, 194, 0.13);
  border-radius: 0.45rem;
  background: rgba(4, 10, 14, 0.35);
  padding: 0.62rem 0.7rem;
  color: #d9e6e6;
  font-size: 0.72rem;
  font-weight: 700;
}
.wallet-bank-dialog__intro {
  margin-top: 0.92rem;
  color: #aab9bd;
  font-size: 0.73rem;
  line-height: 1.5;
}
.wallet-bank-dialog__consequences {
  display: grid;
  gap: 0.48rem;
  margin-top: 0.85rem;
  padding-left: 1.1rem;
  color: #c4d0d2;
  font-size: 0.7rem;
  line-height: 1.4;
}
.wallet-bank-dialog__check {
  display: flex;
  align-items: flex-start;
  gap: 0.55rem;
  margin-top: 1rem;
  color: #e5eeee;
  font-size: 0.72rem;
  line-height: 1.4;
}
.wallet-bank-dialog__check input {
  width: 1rem;
  height: 1rem;
  flex: 0 0 auto;
  accent-color: #18d5a7;
}
.wallet-bank-dialog__field {
  display: grid;
  gap: 0.38rem;
  margin-top: 1rem;
  color: #c9d6d8;
  font-size: 0.7rem;
  font-weight: 700;
}
.wallet-bank-dialog__field input {
  min-height: 2.65rem;
  border: 1px solid rgba(158, 174, 194, 0.22);
  border-radius: 0.46rem;
  background: #0b1217;
  padding: 0 0.7rem;
  color: #eef7f7;
  font-size: 0.84rem;
}
.wallet-bank-dialog__error {
  margin-top: 0.75rem;
  color: #ff9da4;
  font-size: 0.7rem;
  line-height: 1.4;
}
.wallet-bank-dialog > footer,
.wallet-bank-dialog form > footer {
  display: flex;
  justify-content: flex-end;
  gap: 0.55rem;
  margin-top: 1.15rem;
}
.wallet-bank-dialog__secondary,
.wallet-bank-dialog__danger {
  min-height: 2.45rem;
  border-radius: 0.44rem;
  padding: 0 0.85rem;
  font-size: 0.7rem;
  font-weight: 750;
}
.wallet-bank-dialog__secondary {
  border: 1px solid rgba(158, 174, 194, 0.2);
  color: #b9c7ca;
}
.wallet-bank-dialog__danger {
  background: linear-gradient(135deg, #ff7a86, #e95268);
  color: #27090e;
}
.wallet-bank-dialog__danger:disabled,
.wallet-bank-dialog__secondary:disabled,
.wallet-bank-dialog__close:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}
@media (max-width: 640px) {
  .wallet-bank-dialog-backdrop {
    align-items: end;
    padding: 0;
  }
  .wallet-bank-dialog {
    width: 100%;
    border-radius: 1rem 1rem 0 0;
    padding: 1rem;
  }
  .wallet-bank-dialog > footer,
  .wallet-bank-dialog form > footer {
    display: grid;
    grid-template-columns: 1fr 1fr;
  }
  .wallet-bank-dialog__secondary,
  .wallet-bank-dialog__danger {
    width: 100%;
  }
}

.approved-home__illustrative-terms {
  display: grid;
  gap: 0.22rem;
  margin-top: 0.65rem;
  padding-top: 0.55rem;
  border-top: 1px solid rgba(142, 168, 180, 0.12);
}

.approved-home__illustrative-terms span {
  color: #8faaa7;
  font-size: 0.54rem;
  font-weight: 760;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.approved-home__illustrative-terms small {
  color: #687482;
  font-size: 0.52rem;
  text-transform: uppercase;
}

/* Authenticated portfolio: preserves the approved investment-workspace composition. */
.portfolio-page {
  min-height: calc(100vh - 4.75rem);
  background: linear-gradient(180deg, #080b0f 0%, var(--color-background) 42rem);
}
.portfolio-shell {
  padding-block: 2.25rem 2.8rem;
}
.portfolio-heading {
  display: flex;
  min-height: 7rem;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1rem;
  padding-bottom: 1.35rem;
}
.portfolio-heading h1 {
  margin-top: 0.45rem;
  font-family: var(--font-display);
  font-size: clamp(2.6rem, 4.2vw, 4.35rem);
  font-weight: 750;
  line-height: 0.98;
  letter-spacing: -0.06em;
}
.portfolio-heading > div > p:last-child {
  margin-top: 0.65rem;
  color: var(--color-subtle);
  font-size: 0.92rem;
}
.portfolio-periods {
  display: flex;
  overflow: hidden;
  border: 1px solid rgba(158, 174, 194, 0.15);
  border-radius: 0.55rem;
  background: rgba(21, 27, 35, 0.8);
}
.portfolio-periods button {
  min-width: 2.8rem;
  padding: 0.56rem 0.6rem;
  border-left: 1px solid rgba(158, 174, 194, 0.1);
  color: #687383;
  font-size: 0.7rem;
  font-weight: 700;
}
.portfolio-periods button:first-child {
  border-left: 0;
}
.portfolio-periods button:disabled {
  cursor: not-allowed;
  opacity: 0.78;
}

.portfolio-kpis {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.9rem;
}
.portfolio-kpi,
.portfolio-panel {
  border: 1px solid rgba(158, 174, 194, 0.15);
  border-radius: 0.78rem;
  background: linear-gradient(145deg, rgba(22, 27, 35, 0.97), rgba(13, 17, 23, 0.98));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.025),
    0 14px 32px rgba(0, 0, 0, 0.16);
}
.portfolio-kpi {
  display: flex;
  min-height: 7.3rem;
  gap: 0.86rem;
  align-items: flex-start;
  padding: 1rem 1.1rem;
}
.portfolio-kpi--loading {
  align-items: center;
}
.portfolio-kpi p {
  color: #aab3c1;
  font-size: 0.76rem;
  font-weight: 600;
}
.portfolio-kpi strong {
  display: block;
  overflow: hidden;
  margin-top: 0.35rem;
  color: var(--color-foreground);
  font-size: clamp(1.3rem, 1.8vw, 1.62rem);
  font-weight: 700;
  letter-spacing: -0.035em;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.portfolio-kpi > div > span {
  display: block;
  overflow: hidden;
  margin-top: 0.48rem;
  color: #7f8998;
  font-size: 0.68rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.portfolio-kpis__error {
  grid-column: 1 / -1;
}

.portfolio-row {
  display: grid;
  gap: 0.9rem;
  margin-top: 0.9rem;
}
.portfolio-row--insight {
  grid-template-columns: minmax(0, 0.98fr) minmax(0, 1.02fr);
}
.portfolio-row--detail {
  grid-template-columns: minmax(0, 1.95fr) minmax(18rem, 0.8fr);
}
.portfolio-panel {
  display: flex;
  min-width: 0;
  min-height: 17.45rem;
  flex-direction: column;
  overflow: hidden;
}
.portfolio-panel--holdings,
.portfolio-panel--transactions {
  min-height: 22.4rem;
}
.portfolio-panel__head {
  display: flex;
  min-height: 3.55rem;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.94rem 1.15rem 0.62rem;
}
.portfolio-panel__head h2 {
  color: var(--color-foreground);
  font-size: 0.94rem;
  font-weight: 700;
  letter-spacing: -0.025em;
}
.portfolio-panel__head a {
  display: inline-flex;
  align-items: center;
  gap: 0.42rem;
  color: var(--color-accent);
  font-size: 0.72rem;
  font-weight: 700;
}
.portfolio-panel__head a svg {
  width: 0.88rem;
  height: 0.88rem;
}
.portfolio-panel__body {
  min-height: 0;
  flex: 1;
  padding: 0 1.15rem 1rem;
}
.portfolio-panel__empty {
  display: grid;
  min-height: 11rem;
  place-items: center;
  border: 1px dashed rgba(158, 174, 194, 0.14);
  border-radius: 0.58rem;
  color: #8993a2;
  font-size: 0.78rem;
  text-align: center;
}
.portfolio-panel__error {
  display: grid;
  min-height: 11rem;
  place-content: center;
  gap: 0.7rem;
  color: #abb5c2;
  font-size: 0.8rem;
  text-align: center;
}
.portfolio-panel__error button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.42rem;
  color: var(--color-accent);
  font-size: 0.77rem;
  font-weight: 700;
}
.portfolio-panel__error svg {
  width: 0.9rem;
  height: 0.9rem;
}

.portfolio-allocation {
  display: grid;
  height: 100%;
  grid-template-columns: minmax(8.8rem, 0.76fr) minmax(0, 1.24fr);
  gap: 1.3rem;
  align-items: center;
}
.portfolio-donut {
  display: grid;
  aspect-ratio: 1;
  width: min(12.2rem, 100%);
  place-items: center;
  border-radius: 50%;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.04);
}
.portfolio-donut > div {
  display: grid;
  width: 61%;
  aspect-ratio: 1;
  place-content: center;
  border-radius: 50%;
  background: #11161e;
  box-shadow: 0 0 0 1px rgba(158, 174, 194, 0.15);
  text-align: center;
}
.portfolio-donut strong {
  color: #ecf0f4;
  font-size: clamp(0.8rem, 1.3vw, 1.05rem);
  font-weight: 700;
  letter-spacing: -0.04em;
}
.portfolio-donut span {
  margin-top: 0.24rem;
  color: #8892a0;
  font-size: 0.59rem;
}
.portfolio-allocation-table {
  min-width: 0;
}
.portfolio-allocation-table__head,
.portfolio-allocation-table__row {
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(4.7rem, 0.8fr) minmax(3.5rem, 0.48fr);
  gap: 0.55rem;
}
.portfolio-allocation-table__head {
  padding-bottom: 0.36rem;
  color: #7d8797;
  font-size: 0.61rem;
  font-weight: 700;
}
.portfolio-allocation-table__row {
  align-items: center;
  border-top: 1px solid rgba(158, 174, 194, 0.095);
  padding: 0.42rem 0;
  color: #dce1e8;
  font-size: 0.7rem;
}
.portfolio-allocation-table__row > span {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 0.45rem;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.portfolio-allocation-table__row i {
  flex: 0 0 auto;
  width: 0.5rem;
  height: 0.5rem;
  border-radius: 50%;
}
.portfolio-allocation-table__row strong {
  font-weight: 600;
  text-align: right;
}
.portfolio-chart-empty {
  display: flex;
  min-height: 12rem;
  align-items: center;
  justify-content: center;
  gap: 1.1rem;
  color: #8c96a5;
}
.portfolio-chart-empty__ring {
  display: grid;
  flex: 0 0 auto;
  width: 7.3rem;
  height: 7.3rem;
  place-items: center;
  border: 1rem solid #303b4a;
  border-top-color: rgba(20, 233, 193, 0.8);
  border-right-color: rgba(61, 127, 230, 0.75);
  border-radius: 50%;
  color: #aeb6c0;
}
.portfolio-chart-empty__ring svg {
  width: 1.6rem;
  height: 1.6rem;
}
.portfolio-chart-empty strong {
  display: block;
  max-width: 11rem;
  color: #e1e5eb;
  font-size: 0.78rem;
}
.portfolio-chart-empty p {
  max-width: 12rem;
  margin-top: 0.38rem;
  font-size: 0.68rem;
  line-height: 1.48;
}

.portfolio-panel--performance .portfolio-panel__body {
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.portfolio-panel--performance {
  min-height: 14.5rem;
}

.portfolio-performance-snapshot {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.75rem;
  width: 100%;
  padding: 0.15rem 0;
}

.portfolio-performance-snapshot > div {
  min-width: 0;
  padding: 0.8rem;
  border: 1px solid rgba(101, 130, 149, 0.2);
  border-radius: 0.7rem;
  background: rgba(10, 20, 27, 0.48);
}

.portfolio-performance-snapshot span {
  display: block;
