  .slice-footer__updates-cta {
    grid-column: 1 / -1;
  }
  .slice-footer__updates-cta {
    grid-row: auto;
  }
  .slice-footer__lower {
    grid-template-columns: minmax(0, 1fr);
    gap: 0.75rem;
    padding: 0.9rem 1.25rem;
  }
  .slice-footer__security-card {
    justify-self: stretch;
    min-width: 0;
    max-width: 100%;
  }
}

@media (max-width: 400px) {
  /* Keep the compact authenticated/anonymous header inside the narrowest viewport. */
  .main-navigation .site-shell {
    gap: 0.75rem;
  }

  .main-navigation .site-shell > .rounded-full {
    display: none;
  }
}

/* The sticky navigation must remain a solid surface over scrolling content. */
.main-navigation {
  isolation: isolate;
  background: #08090c;
}

/* =================================================
   Portfolio — homepage-density refinement
   ================================================= */

.portfolio-page {
  min-height: calc(100vh - 4.75rem);
  background:
    radial-gradient(ellipse 48% 24% at 82% 2%, rgba(20, 191, 144, 0.065), transparent 73%),
    linear-gradient(180deg, #080c10 0%, #06090c 44rem, #070a0d 100%);
}

.portfolio-page .portfolio-shell {
  width: min(calc(100% - clamp(2rem, 4vw, 5rem)), 96rem);
  max-width: none;
  padding-block: clamp(2.1rem, 3.3vw, 3.2rem) 3.3rem;
}

.portfolio-heading {
  min-height: 0;
  padding-bottom: 1.3rem;
}

.portfolio-heading h1 {
  margin-top: 0.4rem;
  font-size: clamp(2.7rem, 4.1vw, 4.1rem);
  font-weight: 740;
  line-height: 0.95;
}

.portfolio-heading h1 span {
  color: #29dca6;
}

.portfolio-heading > div > p:last-child {
