  font-size: 0.84rem;
  line-height: 1.55;
}

.portfolio-kpis {
  gap: 0.8rem;
}

.portfolio-kpi,
.portfolio-panel {
  border-color: rgba(130, 158, 170, 0.2);
  border-radius: 0.72rem;
  background: linear-gradient(145deg, rgba(19, 25, 31, 0.97), rgba(10, 15, 19, 0.98));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.035),
    0 13px 30px rgba(0, 0, 0, 0.16);
}

.portfolio-kpi {
  position: relative;
  min-height: 6.65rem;
  padding: 1rem 1.05rem;
}

.portfolio-kpi > div {
  padding-right: 2.6rem;
}

.portfolio-kpi p {
  color: #aeb8c4;
  font-size: 0.62rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.portfolio-kpi strong {
  margin-top: 0.48rem;
  font-size: clamp(1.2rem, 1.62vw, 1.5rem);
}

.portfolio-kpi > div > span {
  margin-top: 0.36rem;
  font-size: 0.64rem;
}

.portfolio-row {
  gap: 0.8rem;
  margin-top: 0.8rem;
}

.portfolio-row--insight {
  grid-template-columns: minmax(16.5rem, 0.98fr) minmax(22rem, 1.18fr) minmax(17rem, 0.84fr);
}

.portfolio-row--detail {
  grid-template-columns: minmax(0, 1.18fr) minmax(0, 1fr);
}

.portfolio-panel {
  min-height: 18.8rem;
}

.portfolio-panel--holdings,
.portfolio-panel--transactions {
  min-height: 14.5rem;
}

.portfolio-panel__head {
  min-height: 3.35rem;
  padding: 0.92rem 1.1rem 0.62rem;
}

.portfolio-panel__head h2 {
  font-size: 0.93rem;
}

.portfolio-panel__body {
  padding: 0 1.1rem 0.95rem;
}

.portfolio-periods {
  border-color: rgba(144, 170, 181, 0.11);
  background: rgba(6, 10, 13, 0.35);
}

.portfolio-periods button {
  min-width: 1.9rem;
  padding: 0.35rem 0.38rem;
  color: #77838f;
  font-size: 0.58rem;
}

.portfolio-periods button:last-child {
  color: #2adba5;
}

.portfolio-allocation {
  grid-template-columns: minmax(8.3rem, 0.82fr) minmax(0, 1.18fr);
  gap: 1rem;
}

.portfolio-donut {
  width: min(10.7rem, 100%);
}

.portfolio-donut > div {
  background: #0e1419;
}

.portfolio-allocation-table__head {
  color: #8f9aa7;
}

.portfolio-allocation-table__row {
  padding-block: 0.38rem;
  font-size: 0.67rem;
}

.portfolio-chart-empty {
  min-height: 12rem;
  border: 1px dashed rgba(139, 168, 181, 0.16);
  border-radius: 0.62rem;
  background:
    linear-gradient(rgba(134, 161, 173, 0.065) 1px, transparent 1px),
    linear-gradient(90deg, rgba(134, 161, 173, 0.065) 1px, transparent 1px),
    linear-gradient(180deg, rgba(19, 34, 37, 0.42), rgba(11, 16, 20, 0.3));
  background-size:
    100% 2.45rem,
    4.3rem 100%,
    auto;
}

.portfolio-panel--performance .portfolio-panel__body {
  gap: 0.65rem;
}

.portfolio-performance-empty {
  min-height: 11.9rem;
  border-color: rgba(139, 168, 181, 0.15);
  background:
    linear-gradient(rgba(134, 161, 173, 0.055) 1px, transparent 1px),
    linear-gradient(90deg, rgba(134, 161, 173, 0.055) 1px, transparent 1px),
    linear-gradient(180deg, rgba(18, 42, 40, 0.22), rgba(8, 13, 17, 0.2));
  background-size:
    100% 2.4rem,
    4.2rem 100%,
    auto;
}

.portfolio-range-summary {
  grid-template-columns: repeat(4, minmax(0, 1fr));
  margin-top: 0;
}

.portfolio-range-summary span {
  overflow: hidden;
  font-size: 0.55rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.portfolio-range-summary strong {
  font-size: 0.62rem;
}

.portfolio-panel--activity {
  min-height: 18.8rem;
}

.portfolio-activity {
  display: grid;
}

.portfolio-activity li {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 0.6rem;
  align-items: center;
  min-height: 3.3rem;
