}

.portfolio-activity > li > span.is-credit {
  background: rgba(30, 211, 159, 0.12);
}

.portfolio-activity .is-debit,
.portfolio-table .is-debit {
  color: #ef8282;
}

.portfolio-activity > li > span.is-debit {
  background: rgba(239, 93, 93, 0.11);
}

.portfolio-activity strong {
  display: block;
  overflow: hidden;
  color: #e6ebef;
  font-size: 0.68rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.portfolio-activity p,
.portfolio-activity aside span {
  display: block;
  overflow: hidden;
  margin-top: 0.16rem;
  color: #84909c;
  font-size: 0.58rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.portfolio-activity aside {
  text-align: right;
}

.portfolio-activity aside strong {
  font-variant-numeric: tabular-nums;
}

/* Dedicated Activity tab */
.portfolio-panel--activity-dedicated {
  min-height: 0;
  margin-top: 0.85rem;
}
.portfolio-panel--activity-dedicated > .portfolio-panel__head {
  min-height: 5.25rem;
  align-items: flex-end;
  gap: 1rem;
  padding: 1rem 1.2rem 0.75rem;
}
.portfolio-panel--activity-dedicated > .portfolio-panel__body {
  padding: 0;
}
.portfolio-activity-header {
  display: flex;
  min-width: 0;
  flex: 1;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1rem;
}
.portfolio-activity-filters {
  display: flex;
  min-width: 0;
  flex-wrap: wrap;
  gap: 0.25rem;
  border: 1px solid rgba(130, 158, 170, 0.16);
