  padding: 0.25rem;
  background: rgba(4, 9, 12, 0.52);
}
.portfolio-activity-filters button {
  min-height: 2.15rem;
  border-radius: 0.4rem;
  padding: 0.4rem 0.72rem;
  color: #aeb8c4;
  font-size: 0.75rem;
  font-weight: 650;
  white-space: nowrap;
}
.portfolio-activity-filters button:hover,
.portfolio-activity-filters button.is-active {
