}
.portfolio-activity-table__head,
.portfolio-activity-event {
  display: grid;
  grid-template-columns:
    minmax(12rem, 1.18fr) minmax(17rem, 1.55fr) minmax(5.3rem, 0.55fr) minmax(9.5rem, 0.82fr)
    minmax(8.3rem, 0.68fr) 1.2rem;
