}
.portfolio-activity-event__activity {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 0.75rem;
}
.portfolio-activity-event__summary {
  display: grid;
  gap: 0.26rem;
}
.portfolio-activity-event__summary strong,
.portfolio-activity-event__asset strong,
.portfolio-activity-event__cash-detail strong {
