  color: #99a7b2;
  font-size: 0.72rem;
  line-height: 1.35;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.portfolio-activity-event__asset {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 0.75rem;
}
.portfolio-activity-event__asset > span:last-child {
  display: grid;
  min-width: 0;
  gap: 0.24rem;
}
.portfolio-activity-event__thumb {
  display: grid;
  width: 3.55rem;
  height: 4.55rem;
  flex: 0 0 auto;
  place-items: center;
  overflow: hidden;
  border: 1px solid rgba(145, 166, 177, 0.2);
  border-radius: 0.35rem;
  background: #111a20;
}
.portfolio-activity-event__thumb img {
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.portfolio-activity-event__thumb svg {
  width: 1.2rem;
  color: #7e8b95;
}
.portfolio-activity-event__cash-detail {
  display: grid;
  gap: 0.24rem;
}
.portfolio-activity-event__badge {
  justify-self: start;
  border-radius: 0.32rem;
  padding: 0.34rem 0.5rem;
  font-size: 0.68rem;
  font-weight: 700;
}
.portfolio-activity-event__badge.is-trading,
.portfolio-activity-event__badge.is-cash {
  background: rgba(24, 196, 147, 0.12);
