}
.portfolio-activity-event__badge.is-ownership {
  background: rgba(145, 111, 234, 0.14);
  color: #c2a6ff;
}
.portfolio-activity-event__badge.is-distributions {
  background: rgba(70, 172, 225, 0.14);
  color: #8cd7ff;
}
.portfolio-activity-event__badge.is-account {
  background: rgba(134, 150, 165, 0.11);
  color: #b3c0ca;
}
.portfolio-activity-event__amount {
  display: grid;
  gap: 0.25rem;
}
.portfolio-activity-event__amount strong {
  font-size: 0.9rem;
  font-weight: 750;
  white-space: nowrap;
}
.portfolio-activity-event__amount small {
  color: #aab5bf;
  font-size: 0.71rem;
  line-height: 1.3;
}
.portfolio-activity-event__amount.is-credit strong {
  color: #2edca8;
}
.portfolio-activity-event__amount.is-debit strong {
  color: #f07979;
}
.portfolio-activity-event__amount.is-neutral strong {
  color: #d5dee3;
  font-size: 0.77rem;
}
.portfolio-activity-event__date {
  display: grid;
  gap: 0.25rem;
  color: #c2cdd4;
}
.portfolio-activity-event__date strong {
  font-size: 0.75rem;
  font-weight: 600;
  white-space: nowrap;
}
.portfolio-activity-event__date small {
  color: #91a0ac;
  font-size: 0.71rem;
}
.portfolio-activity-event__chevron {
  width: 1rem;
  height: 1rem;
  color: #a6b3bd;
}
.portfolio-activity-pagination {
