  align-items: center;
  justify-content: flex-end;
  gap: 1.2rem;
  padding: 0.65rem 1.5rem;
  color: #a8b5bf;
  font-size: 0.75rem;
}
.portfolio-activity-pagination label {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  white-space: nowrap;
}
.portfolio-activity-pagination select {
  border: 1px solid rgba(130, 158, 170, 0.2);
  border-radius: 0.4rem;
  padding: 0.4rem 0.55rem;
  background: #0b1217;
  color: #dbe4e8;
}
.portfolio-activity-pagination > div {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
}
.portfolio-activity-pagination button {
  display: grid;
  width: 2rem;
  height: 2rem;
  place-items: center;
  border-radius: 0.35rem;
  color: #bac7ce;
}
.portfolio-activity-pagination button:hover:not(:disabled) {
  background: rgba(128, 152, 163, 0.13);
}
.portfolio-activity-pagination button:disabled {
  opacity: 0.35;
}
.portfolio-activity-pagination button svg {
  width: 0.95rem;
  height: 0.95rem;
}
.portfolio-activity-pagination strong {
  display: grid;
  min-width: 2rem;
  height: 2rem;
  place-items: center;
  border: 1px solid rgba(32, 213, 161, 0.55);
  border-radius: 0.35rem;
  color: #34dbaa;
}
.portfolio-activity-loading {
  padding: 0.75rem 1.2rem;
}
.portfolio-activity-dialog-backdrop {
  position: fixed;
  inset: 0;
  z-index: 80;
  display: grid;
  place-items: center;
  padding: 1rem;
  background: rgba(0, 0, 0, 0.68);
}
.portfolio-activity-dialog {
  width: min(100%, 34rem);
  max-height: min(90vh, 42rem);
  overflow: auto;
  border: 1px solid rgba(130, 158, 170, 0.25);
  border-radius: 0.8rem;
  padding: 1.35rem;
  background: #0c1419;
  box-shadow: 0 24px 70px rgba(0, 0, 0, 0.45);
}
.portfolio-activity-dialog header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
}
.portfolio-activity-dialog header h2 {
  margin-top: 0.3rem;
  font-size: 1.35rem;
}
.portfolio-activity-dialog header button {
  display: grid;
  width: 2rem;
  height: 2rem;
  place-items: center;
  border-radius: 0.35rem;
  color: #aab8c1;
}
.portfolio-activity-dialog header button:hover {
  background: rgba(128, 152, 163, 0.14);
  color: #fff;
}
.portfolio-activity-dialog header svg {
  width: 1.05rem;
}
.portfolio-activity-dialog__description {
  margin-top: 1rem;
  color: #aab7c0;
  font-size: 0.82rem;
  line-height: 1.5;
}
.portfolio-activity-dialog dl {
  display: grid;
  gap: 0;
  margin-top: 1.2rem;
}
.portfolio-activity-dialog dl > div {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  border-top: 1px solid rgba(137, 164, 176, 0.12);
  padding: 0.72rem 0;
}
.portfolio-activity-dialog dt {
  color: #8f9da8;
  font-size: 0.75rem;
}
.portfolio-activity-dialog dd {
  max-width: 60%;
  color: #eef3f5;
  font-size: 0.78rem;
  font-weight: 650;
  text-align: right;
  overflow-wrap: anywhere;
}
.portfolio-activity-dialog footer {
  display: flex;
  justify-content: flex-end;
  gap: 0.65rem;
  margin-top: 1rem;
}
.portfolio-activity-dialog footer a,
.portfolio-activity-dialog footer button {
  display: inline-flex;
  min-height: 2.3rem;
  align-items: center;
  gap: 0.35rem;
  border-radius: 0.4rem;
  padding: 0.55rem 0.75rem;
  font-size: 0.76rem;
  font-weight: 700;
}
.portfolio-activity-dialog footer a {
  background: rgba(25, 209, 158, 0.12);
  color: #39dfae;
}
.portfolio-activity-dialog footer button {
  border: 1px solid rgba(130, 158, 170, 0.2);
  color: #d4dfe5;
}
.portfolio-activity-dialog footer svg {
  width: 0.85rem;
}

@media (max-width: 860px) {
  .portfolio-panel--activity-dedicated > .portfolio-panel__head {
    align-items: stretch;
  }
  .portfolio-activity-header {
    flex-direction: column;
    align-items: stretch;
  }
  .portfolio-activity-date-filter {
    align-self: flex-start;
  }
  .portfolio-activity-table__head {
    display: none;
  }
  .portfolio-activity-event {
    grid-template-columns: auto minmax(0, 1fr) auto;
    gap: 0.7rem;
    align-items: start;
    padding: 1rem;
  }
  .portfolio-activity-event__activity {
    grid-column: 1 / 3;
  }
  .portfolio-activity-event__date {
    grid-column: 3;
    grid-row: 1;
    text-align: right;
  }
  .portfolio-activity-event__asset {
    grid-column: 2 / 4;
  }
  .portfolio-activity-event__badge,
  .portfolio-activity-event__amount {
    grid-column: 2;
  }
  .portfolio-activity-event__chevron {
    grid-column: 3;
    grid-row: 4;
    justify-self: end;
  }
  .portfolio-activity-pagination {
    flex-wrap: wrap;
    justify-content: space-between;
    padding-inline: 1rem;
  }
}
@media (max-width: 520px) {
  .portfolio-activity-filters {
    overflow-x: auto;
    flex-wrap: nowrap;
  }
  .portfolio-activity-filters button {
    flex: 0 0 auto;
  }
  .portfolio-activity-event__asset strong {
    white-space: normal;
  }
  .portfolio-activity-pagination > span {
    flex-basis: 100%;
  }
}

.portfolio-compact-empty {
  display: flex;
  min-height: 12rem;
  align-items: center;
  justify-content: center;
  gap: 0.8rem;
  border: 1px dashed rgba(139, 168, 181, 0.14);
  border-radius: 0.6rem;
  color: #8c98a4;
  text-align: left;
}

.portfolio-panel--transactions .portfolio-compact-empty {
  min-height: 7.8rem;
}

.portfolio-compact-empty svg {
  width: 1.5rem;
  height: 1.5rem;
  color: #33cba0;
}

.portfolio-compact-empty strong {
  display: block;
  color: #e4e9ed;
  font-size: 0.76rem;
}

.portfolio-compact-empty p {
  max-width: 12rem;
  margin-top: 0.25rem;
  font-size: 0.65rem;
  line-height: 1.5;
}

.portfolio-table-wrap {
  border: 1px solid rgba(137, 164, 176, 0.1);
  border-radius: 0.55rem;
  background: rgba(7, 11, 15, 0.22);
}

.portfolio-table th {
  height: 2.25rem;
  color: #83909e;
  font-size: 0.56rem;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.portfolio-table td {
  height: 3.35rem;
  color: #c6d0d8;
  font-size: 0.67rem;
}

.portfolio-table tbody tr {
  border-color: rgba(137, 164, 176, 0.1);
}

.portfolio-asset > span {
  width: 2.15rem;
  height: 2.15rem;
  border-radius: 0.4rem;
  background: linear-gradient(145deg, rgba(31, 51, 55, 0.92), rgba(16, 23, 28, 0.9));
}

.portfolio-asset > span svg {
  width: 0.95rem;
  height: 0.95rem;
}

.portfolio-asset strong {
  font-size: 0.7rem;
}

.portfolio-asset--link {
  display: flex;
  min-width: 0;
  color: inherit;
  text-decoration: none;
}

.portfolio-asset--link:hover strong {
  color: var(--mint);
}

.portfolio-asset__copy {
  min-width: 0;
}

.portfolio-asset__copy small {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.portfolio-table--transactions th:nth-child(1) {
  width: 25%;
}

.portfolio-table--transactions th:nth-child(2) {
  width: 42%;
}

.portfolio-table--transactions th:nth-child(3) {
  width: 17%;
}

.portfolio-table--transactions th:nth-child(4) {
  width: 16%;
}

.portfolio-panel--transactions .portfolio-table-wrap {
  overflow-x: hidden;
}

.portfolio-table--transactions {
  min-width: 0;
  table-layout: fixed;
}

.portfolio-table--transactions td {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.portfolio-transaction-pill {
  display: inline-flex;
  max-width: 6.6rem;
  overflow: hidden;
  padding: 0.28rem 0.44rem;
  border-radius: 0.33rem;
  font-size: 0.58rem;
  font-weight: 750;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.portfolio-transaction-pill.is-credit {
  background: rgba(34, 215, 164, 0.13);
  color: #2ee1aa;
}

.portfolio-transaction-pill.is-debit {
  background: rgba(227, 83, 100, 0.13);
  color: #f18994;
}

@media (max-width: 1239px) {
  .portfolio-row--insight {
    grid-template-columns: minmax(16rem, 0.95fr) minmax(20rem, 1.05fr);
  }

  .portfolio-panel--activity {
    grid-column: 1 / -1;
    min-height: auto;
  }

  .portfolio-activity {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    column-gap: 1rem;
  }
}

@media (max-width: 899px) {
  .portfolio-page .portfolio-shell {
    width: min(calc(100% - 2rem), 50rem);
  }

  .portfolio-kpis {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .portfolio-row--insight,
  .portfolio-row--detail {
    grid-template-columns: 1fr;
  }

  .portfolio-panel--activity {
    grid-column: auto;
  }
}

@media (max-width: 599px) {
  .portfolio-page .portfolio-shell {
    width: calc(100% - 1.5rem);
    padding-top: 1.65rem;
  }

  .portfolio-heading h1 {
    font-size: clamp(2.45rem, 12vw, 3.2rem);
  }

  .portfolio-kpis {
    grid-template-columns: 1fr;
  }

  .portfolio-row {
    margin-top: 0.7rem;
  }

  .portfolio-allocation {
    grid-template-columns: 1fr;
    justify-items: center;
  }

  .portfolio-allocation-table {
    width: 100%;
  }

  .portfolio-activity {
    grid-template-columns: 1fr;
  }

  .portfolio-panel__head,
  .portfolio-panel__body {
    padding-inline: 0.85rem;
  }

  .portfolio-table-wrap {
    overflow-x: auto;
  }

  .portfolio-table {
    min-width: 34rem;
  }

  .portfolio-performance-snapshot {
    grid-template-columns: 1fr;
  }

  .portfolio-panel--transactions .portfolio-table-wrap {
    overflow-x: auto;
  }

  .portfolio-table--transactions {
    min-width: 34rem;
    table-layout: auto;
  }
}

/* ==============================================================
   Approved homepage showcase — static editorial presentation with
   real product destinations. Product pages remain API-authoritative.
   ============================================================== */

.approved-home {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  padding-bottom: 2rem;
  background:
    radial-gradient(ellipse 42% 18% at 56% 5%, rgba(25, 192, 145, 0.075), transparent 72%),
    radial-gradient(ellipse 32% 15% at 12% 18%, rgba(25, 132, 105, 0.045), transparent 75%),
    linear-gradient(180deg, #070a0d, #080a0d 45%, #07090c);
}

.approved-home .page-shell {
  max-width: 100rem;
}

.approved-home__hero {
  display: grid;
  grid-template-columns: minmax(21rem, 24rem) minmax(0, 53rem);
  justify-content: space-between;
  align-items: start;
  gap: clamp(2.5rem, 4.5vw, 5.75rem);
  padding-top: 2rem;
  padding-bottom: 2rem;
}

.approved-home__copy {
  min-width: 0;
  padding-top: 0.25rem;
}

.approved-home__copy h1 {
  margin-top: 0.5rem;
  color: #f8fafc;
  font-family: var(--font-display);
  font-size: clamp(3.4rem, 4.5vw, 4.6rem);
  font-weight: 780;
  line-height: 0.9;
  letter-spacing: -0.072em;
}

.approved-home__copy h1 span {
  display: block;
}

.approved-home__copy h1 span:last-child {
  color: var(--color-accent);
}

.approved-home__lead {
  max-width: 23.5rem;
  margin-top: 1.25rem;
  color: #9ea8b7;
  font-size: 1.02rem;
  line-height: 1.6;
}

.approved-home__actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.8rem;
  margin-top: 1.25rem;
}

.approved-home__primary-cta,
.approved-home__secondary-cta {
  display: inline-flex;
  min-height: 3rem;
  align-items: center;
  justify-content: center;
  gap: 0.55rem;
  padding: 0.75rem 1.1rem;
  border-radius: 0.55rem;
  font-size: 0.82rem;
  font-weight: 750;
}

.approved-home__primary-cta svg,
.approved-home__secondary-cta svg {
  width: 0.95rem;
  height: 0.95rem;
}

.approved-home__secondary-cta {
  border: 1px solid rgba(160, 178, 193, 0.24);
  background: rgba(8, 12, 16, 0.5);
  color: #eef2f6;
  transition:
    border-color 160ms ease,
    background-color 160ms ease;
}

.approved-home__secondary-cta:hover {
  border-color: rgba(34, 211, 165, 0.45);
  background: rgba(34, 211, 165, 0.06);
}

.approved-home__community {
  display: flex;
  align-items: center;
  gap: 0.8rem;
  margin-top: 1rem;
}

.approved-home__avatars {
  display: flex;
}

.approved-home__avatars span {
  display: grid;
  width: 1.4rem;
  height: 1.4rem;
  place-items: center;
  margin-left: -0.3rem;
  border: 1px solid #0a0d10;
  border-radius: 50%;
  background: linear-gradient(145deg, #174a42, #102823);
  color: #a9f5df;
  font-size: 0.42rem;
  font-weight: 800;
}

.approved-home__avatars span:first-child {
  margin-left: 0;
}

.approved-home__community strong,
.approved-home__community small {
  display: block;
}

.approved-home__community strong {
  color: #e9edf2;
  font-size: 0.72rem;
}

.approved-home__community small {
  margin-top: 0.1rem;
  color: #6f7a89;
  font-size: 0.6rem;
}

.approved-home__ownership-line {
  margin-top: 0.9rem;
  padding-top: 0.8rem;
  border-top: 1px solid rgba(146, 174, 185, 0.15);
}

.approved-home__ownership-line > p {
  color: var(--color-accent);
  font-size: 0.58rem;
  font-weight: 800;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.approved-home__ownership-line dl {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.55rem;
  margin-top: 0.48rem;
}

.approved-home__ownership-line div {
  min-width: 0;
}

.approved-home__ownership-line dt {
  color: #70808d;
  font-size: 0.52rem;
  line-height: 1.25;
}

.approved-home__ownership-line dd {
  margin-top: 0.18rem;
  color: #eaf0f4;
  font-size: 0.68rem;
  font-weight: 760;
