  text-transform: none;
}

.portfolio-summary-kpi strong {
  margin-top: 0.38rem;
  font-size: clamp(1.32rem, 1.7vw, 1.6rem);
  line-height: normal;
}

.portfolio-kpi__content > span {
  margin-top: 0.48rem;
  font-size: 0.7rem;
  line-height: normal;
}

.portfolio-summary-kpi--loading {
  display: flex;
  align-items: center;
  gap: 0.86rem;
  padding: 1rem 1.05rem;
}

.portfolio-summary-kpi--loading > div {
  padding: 0;
}

.portfolio-row--insight {
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.25fr) minmax(0, 0.9fr);
}

.portfolio-panel,
.portfolio-panel--activity {
  min-height: 20rem;
}

.portfolio-panel--holdings,
.portfolio-panel--transactions {
  min-height: 15.25rem;
}

.portfolio-empty-state {
  display: grid;
  min-height: 12.5rem;
  place-items: center;
  align-content: center;
  gap: 0.62rem;
  padding: 1.25rem;
  border: 1px dashed rgba(139, 168, 181, 0.15);
  border-radius: 0.62rem;
  background: linear-gradient(145deg, rgba(24, 49, 47, 0.26), rgba(9, 14, 18, 0.3));
  color: #8c98a4;
  text-align: center;
}

.portfolio-empty-state__icon {
  display: flex;
  width: 2.45rem;
  height: 2.45rem;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(50, 211, 164, 0.16);
  border-radius: 0.65rem;
  background: rgba(31, 102, 84, 0.16);
  color: #39d9ad;
}

.portfolio-empty-state__icon svg {
  width: 1.18rem;
  height: 1.18rem;
  stroke-width: 1.75;
}

.portfolio-empty-state__copy strong {
  display: block;
  color: #e4e9ed;
  font-size: 0.78rem;
}

.portfolio-empty-state__copy p {
  max-width: 19rem;
  margin-top: 0.28rem;
  color: #8c98a4;
  font-size: 0.66rem;
  line-height: 1.5;
}

.portfolio-empty-state--allocation {
  grid-template-columns: auto minmax(0, 1fr);
  justify-content: center;
  column-gap: 1rem;
  text-align: left;
}

.portfolio-chart-empty__ring {
  display: flex;
  align-items: center;
  justify-content: center;
}

.portfolio-empty-state--performance {
  flex: 1;
  min-height: 11.9rem;
  background:
    linear-gradient(rgba(134, 161, 173, 0.045) 1px, transparent 1px),
    linear-gradient(90deg, rgba(134, 161, 173, 0.045) 1px, transparent 1px),
    linear-gradient(180deg, rgba(18, 42, 40, 0.2), rgba(8, 13, 17, 0.18));
  background-size:
    100% 2.4rem,
    4.2rem 100%,
    auto;
}

.portfolio-empty-state--activity {
  min-height: 14.9rem;
}

.portfolio-empty-state--transactions {
  min-height: 7.4rem;
}

.portfolio-empty-state--table {
  min-height: 7rem;
  margin: 0.65rem 0;
}

.portfolio-periods button {
  display: inline-flex;
  min-width: 2.25rem;
  min-height: 2.25rem;
  align-items: center;
  justify-content: center;
  padding: 0.35rem 0.38rem;
}

.portfolio-table th {
  color: #9ba7b5;
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.08em;
}

@media (max-width: 1239px) {
  .portfolio-row--insight {
    grid-template-columns: minmax(16rem, 1fr) minmax(20rem, 1.25fr);
  }
}

@media (max-width: 599px) {
  .portfolio-page .portfolio-shell {
    width: calc(100% - 1.5rem);
  }

  .portfolio-heading {
    padding-bottom: 0.95rem;
  }

  .portfolio-summary-kpi {
    min-height: 7.35rem;
    padding: 1rem 1.1rem;
  }

  .portfolio-empty-state--allocation {
    grid-template-columns: 1fr;
    justify-items: center;
    text-align: center;
  }

  .portfolio-periods button {
    min-width: 2.1rem;
    min-height: 2.1rem;
  }
}

/* Public Vault Live showcase: intentionally public projection and illustrative education. */
.vault-live-page {
  --accent: var(--color-accent);
  --border: var(--color-border);
  --elevated: var(--color-elevated);
  --surface: var(--color-surface);
  --text: var(--color-foreground);
  --text-muted: var(--color-muted);
  --text-subtle: var(--color-subtle);
  overflow: clip;
  padding: clamp(2.5rem, 5vw, 5rem) 0 5rem;
  background:
    radial-gradient(
      circle at 74% 7%,
      color-mix(in srgb, var(--accent) 10%, transparent),
      transparent 25rem
    ),
    linear-gradient(180deg, color-mix(in srgb, var(--surface) 26%, transparent), transparent 20rem);
}

.vault-live-shell {
  width: min(calc(100% - 2.5rem), 92rem);
}
.vault-live-hero {
  display: grid;
  grid-template-columns: minmax(16rem, 0.85fr) minmax(28rem, 1.35fr);
  gap: clamp(2rem, 6vw, 6rem);
  align-items: center;
}
.vault-live-hero__copy {
  max-width: 38rem;
}
.vault-live-hero__title {
  max-width: 11ch;
  margin: 0.6rem 0 1rem;
  font-size: clamp(2.75rem, 5vw, 5.3rem);
  letter-spacing: -0.07em;
  line-height: 0.92;
}
.vault-live-hero__lede {
  max-width: 35rem;
  font-size: 1.08rem;
  line-height: 1.65;
  color: var(--text-subtle);
}
.vault-live-hero__privacy {
  max-width: 38rem;
  margin-top: 1rem;
  font-size: 0.79rem;
  line-height: 1.55;
  color: var(--text-muted);
}
.vault-live-data-status {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  margin: 0.85rem 0 0;
  color: var(--accent);
  font-size: 0.72rem;
  font-weight: 740;
}
.vault-live-data-status i {
  width: 0.4rem;
  height: 0.4rem;
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 0.6rem color-mix(in srgb, currentColor 50%, transparent);
}
.vault-live-hero__actions,
.vault-live-cta > div:last-child {
  display: flex;
  flex-wrap: wrap;
  gap: 0.7rem;
  margin-top: 1.5rem;
}
.vault-live-button {
  display: inline-flex;
  min-height: 2.65rem;
  align-items: center;
  justify-content: center;
  gap: 0.45rem;
  padding: 0.65rem 0.95rem;
  border: 1px solid var(--border);
  border-radius: 0.55rem;
  font-size: 0.82rem;
  font-weight: 780;
  transition:
    border-color 0.18s ease,
    background 0.18s ease,
    transform 0.18s ease;
}
.vault-live-button:hover {
  transform: translateY(-1px);
  border-color: color-mix(in srgb, var(--accent) 60%, var(--border));
}
.vault-live-button--primary {
  border-color: color-mix(in srgb, var(--accent) 80%, transparent);
  background: linear-gradient(
    135deg,
    var(--accent),
    color-mix(in srgb, var(--accent) 74%, #00a979)
  );
  color: #031511;
  box-shadow: 0 0.65rem 1.2rem color-mix(in srgb, var(--accent) 22%, transparent);
}
.vault-live-button--secondary {
  background: color-mix(in srgb, var(--elevated) 82%, transparent);
  color: var(--text);
}
.vault-live-hero__actions svg,
.vault-live-cta svg,
.text-link svg {
  width: 1rem;
  height: 1rem;
}

.vault-live-visual,
.vault-live-panel,
.vault-live-featured,
.vault-live-cta {
  border: 1px solid var(--border);
  border-radius: 1rem;
  background: linear-gradient(
    145deg,
    color-mix(in srgb, var(--elevated) 92%, #062a25),
    var(--elevated)
  );
  box-shadow: 0 1.25rem 3rem rgb(0 0 0 / 0.15);
}
.vault-live-visual {
  position: relative;
  display: grid;
  grid-template-columns: 11rem minmax(0, 1fr);
  gap: 1rem;
  height: 19rem;
  padding: 0.75rem;
  overflow: hidden;
}
.vault-live-visual::after {
  position: absolute;
  inset: 50% -20% -45%;
  content: "";
  background: radial-gradient(
    ellipse,
    color-mix(in srgb, var(--accent) 25%, transparent),
    transparent 62%
  );
  pointer-events: none;
}
.vault-live-visual__asset {
  position: relative;
  z-index: 1;
  display: grid;
  place-items: center;
  height: 17.5rem;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--accent) 35%, var(--border));
  border-radius: 0.8rem;
  background: #071614;
}
.vault-live-visual__asset img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  filter: saturate(0.9) contrast(1.04);
}
.vault-live-visual__asset > svg {
  width: 3rem;
  height: 3rem;
  color: var(--accent);
}
.vault-live-visual__ring {
  position: absolute;
  right: 9%;
  bottom: 9%;
  left: 9%;
  height: 1.25rem;
  border: 1px solid color-mix(in srgb, var(--accent) 72%, transparent);
  border-radius: 50%;
  box-shadow: 0 0 1.5rem color-mix(in srgb, var(--accent) 45%, transparent);
}
.vault-live-visual__track {
  position: relative;
  z-index: 1;
  align-self: center;
  display: grid;
  gap: 0.85rem;
  /* Reserve the lower detail strip so the final lifecycle step clears its divider. */
  padding-bottom: 1.25rem;
}
.vault-live-visual__step {
  position: relative;
  display: grid;
  grid-template-columns: 1.7rem 1fr;
  gap: 0.65rem;
  align-items: center;
  min-height: 2.15rem;
  color: var(--text-subtle);
  font-size: 0.7rem;
  font-weight: 750;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.vault-live-visual__step i {
  position: absolute;
  top: 2rem;
  left: 0.84rem;
  width: 1px;
  height: 1.05rem;
  background: linear-gradient(var(--accent), transparent);
}
.vault-live-visual__node {
  display: grid;
  width: 1.7rem;
  height: 1.7rem;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--accent) 50%, var(--border));
  border-radius: 50%;
  background: color-mix(in srgb, var(--accent) 12%, var(--elevated));
  color: var(--accent);
}
.vault-live-visual__node svg {
  width: 0.78rem;
  height: 0.78rem;
}
.vault-live-visual__detail {
  position: absolute;
  z-index: 1;
  right: 0.75rem;
  bottom: 0.75rem;
  left: 12.75rem;
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.4rem 0.65rem;
  padding-top: 0.65rem;
  border-top: 1px solid var(--border);
}
.vault-live-visual__detail > span {
  width: 100%;
  color: var(--accent);
  font-size: 0.65rem;
  font-weight: 750;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}
.vault-live-visual__detail strong {
  font-size: 0.94rem;
}
.vault-live-visual__detail p {
  margin: 0;
  color: var(--text-muted);
  font-size: 0.77rem;
}

.vault-live-metrics {
  position: relative;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1px;
  margin-top: 2rem;
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: 0.85rem;
  background: var(--border);
}
.vault-live-metric {
  display: flex;
  min-height: 7.1rem;
  align-items: center;
  gap: 0.8rem;
  padding: 1.1rem;
  background: var(--elevated);
}
.vault-live-metric__icon {
  display: grid;
  width: 2.35rem;
  height: 2.35rem;
  flex: 0 0 auto;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--accent) 42%, var(--border));
  border-radius: 0.6rem;
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 8%, var(--elevated));
}
.vault-live-metric__icon svg {
  width: 1rem;
  height: 1rem;
}
.vault-live-metric p,
.vault-live-metric span {
  margin: 0;
  color: var(--text-muted);
  font-size: 0.68rem;
}
.vault-live-metric p {
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.vault-live-metric strong {
  display: block;
  margin: 0.25rem 0;
  font-size: 1.5rem;
}
.vault-live-showcase-label {
  color: var(--text-muted);
  font-size: 0.68rem;
  letter-spacing: 0.03em;
}
.vault-live-metrics .vault-live-showcase-label {
  position: absolute;
  right: 0.75rem;
  bottom: 0.45rem;
}

.vault-live-grid {
  display: grid;
  gap: 1.15rem;
  margin-top: 1.15rem;
}
.vault-live-grid--activity {
  grid-template-columns: minmax(0, 1.45fr) minmax(19rem, 0.75fr);
}
.vault-live-grid--market {
  grid-template-columns: minmax(0, 1.45fr) minmax(18rem, 0.75fr);
