  align-items: start;
  justify-content: center;
  padding: clamp(1.3rem, 4vw, 3rem);
}
.vault-live-featured__copy h2 {
  margin: 0.5rem 0 0.25rem;
  font-size: clamp(1.9rem, 4vw, 3rem);
  letter-spacing: -0.06em;
}
.vault-live-featured__copy > p {
  margin: 0;
