}
.vault-live-cta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
  margin-top: 1.15rem;
  padding: clamp(1.3rem, 3vw, 2rem);
  background: linear-gradient(
    120deg,
    color-mix(in srgb, var(--accent) 16%, var(--elevated)),
    var(--elevated) 68%
  );
}
.vault-live-cta h2 {
  margin: 0.25rem 0;
  font-size: clamp(1.5rem, 3vw, 2.3rem);
  letter-spacing: -0.055em;
}
.vault-live-cta p:last-child {
  max-width: 43rem;
  margin: 0;
  color: var(--text-subtle);
  font-size: 0.85rem;
}
.vault-live-loading,
.vault-live-unavailable {
  display: grid;
  gap: 1rem;
  margin-top: 2rem;
  padding: clamp(1.25rem, 4vw, 2.5rem);
  border: 1px solid var(--border);
  border-radius: 1rem;
  background: var(--elevated);
}
.vault-live-loading {
  min-height: 14rem;
  align-content: center;
}
.vault-live-loading__eyebrow {
  color: var(--accent);
  font-size: 0.7rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}
.vault-live-loading strong {
  font-size: clamp(1.3rem, 2vw, 1.8rem);
}
.vault-live-loading__bars {
  display: grid;
  gap: 0.65rem;
  max-width: 43rem;
}
.vault-live-loading__bars i {
  display: block;
  height: 0.8rem;
  border-radius: 99px;
  background: linear-gradient(
    90deg,
    color-mix(in srgb, var(--accent) 12%, var(--surface)),
    var(--surface),
    color-mix(in srgb, var(--accent) 12%, var(--surface))
  );
}
.vault-live-loading__bars i:nth-child(2) {
  width: 78%;
}
.vault-live-loading__bars i:nth-child(3) {
  width: 56%;
}
.vault-live-unavailable {
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
}
.vault-live-unavailable h1 {
  margin: 0.25rem 0;
  font-size: clamp(1.5rem, 3vw, 2.35rem);
  letter-spacing: -0.05em;
}
.vault-live-unavailable p:last-child {
  max-width: 48rem;
  margin: 0;
  color: var(--text-subtle);
}
.vault-live-unavailable--example {
  grid-template-columns: auto minmax(0, 1fr) auto;
}
.vault-live-beta-example {
  position: relative;
  display: grid;
  width: 7.5rem;
  height: 10rem;
  place-items: center;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--accent) 35%, var(--border));
  border-radius: 0.8rem;
  background: #071614;
}
.vault-live-beta-example img {
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.vault-live-beta-example span {
  position: absolute;
  right: 0.4rem;
  bottom: 0.4rem;
  left: 0.4rem;
  padding: 0.25rem 0.35rem;
  border-radius: 0.3rem;
  background: rgb(5 13 13 / 0.82);
  color: var(--accent);
  font-size: 0.52rem;
  font-weight: 800;
  letter-spacing: 0.07em;
  text-align: center;
  text-transform: uppercase;
}

.featured-market-hero--static-example {
  display: grid;
  grid-template-columns: minmax(7rem, 8rem) minmax(0, 1fr);
  gap: 1rem;
  align-items: center;
  padding: 0.9rem;
}
.approved-home .featured-market-hero--static-example {
  grid-template-columns: minmax(7rem, 8rem) minmax(0, 1fr);
  max-width: 100%;
  height: auto;
  min-height: 0;
}
.featured-market-hero__static-media {
  position: relative;
  display: grid;
  min-height: 11rem;
  place-items: center;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--accent) 35%, var(--border));
  border-radius: 0.75rem;
  background: #071614;
}
.featured-market-hero__static-media img {
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.featured-market-hero__static-media span {
  position: absolute;
  right: 0.35rem;
  bottom: 0.35rem;
  left: 0.35rem;
  padding: 0.24rem 0.3rem;
  border-radius: 0.3rem;
  background: rgb(5 13 13 / 0.82);
  color: var(--accent);
  font-size: 0.5rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-align: center;
  text-transform: uppercase;
}
.featured-market-hero--static-example h2 {
  margin: 0.25rem 0;
}
.featured-market-hero--static-example p:not(.page-kicker) {
  margin: 0 0 0.8rem;
  color: var(--text-subtle);
  font-size: 0.78rem;
  line-height: 1.5;
}

/* High-impact static editorial treatment for the 1999 Base Set reference. */
.approved-home .featured-market-hero--charizard {
  position: relative;
  isolation: isolate;
  display: grid;
  grid-template-columns: minmax(11rem, 15rem) minmax(0, 1fr);
  gap: 1.35rem;
  min-height: 20rem;
  padding: 1.15rem;
  overflow: hidden;
  border: 1px solid rgb(34 211 165 / 0.46);
  background:
    radial-gradient(circle at 17% 83%, rgb(34 211 165 / 0.2), transparent 38%),
    linear-gradient(135deg, #071c1b 0%, #0b1014 53%, #061b18 100%);
  box-shadow:
    inset 0 1px 0 rgb(255 255 255 / 0.09),
    0 22px 65px rgb(34 211 165 / 0.16);
}
.approved-home .featured-market-hero--charizard::before {
  position: absolute;
  z-index: -1;
  inset: -40% -15%;
  background: conic-gradient(
    from 35deg,
    transparent 0 32%,
    rgb(79 255 203 / 0.12),
    transparent 45% 72%,
    rgb(34 211 165 / 0.1),
    transparent 84%
  );
  content: "";
  animation: charizard-showcase-sweep 12s linear infinite;
}
.charizard-showcase__glow {
  position: absolute;
  z-index: -1;
  width: 13rem;
  height: 13rem;
  right: 4%;
  bottom: -45%;
  border-radius: 50%;
  background: rgb(34 211 165 / 0.3);
  filter: blur(45px);
  animation: charizard-showcase-pulse 4.5s ease-in-out infinite;
}
.charizard-showcase__eyebrow {
  position: absolute;
  z-index: 2;
  top: 0.78rem;
  right: 1rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  color: rgb(177 250 226 / 0.78);
  font-size: 0.58rem;
  font-weight: 800;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}
.charizard-showcase__eyebrow span:first-child {
  color: #63f1c0;
  font-size: 0.7rem;
}
.approved-home .featured-market-hero--charizard .featured-market-hero__static-media {
  isolation: isolate;
  z-index: 1;
  align-self: end;
  min-height: 17rem;
  border-color: rgb(34 211 165 / 0.62);
  background: linear-gradient(145deg, #12201f, #080b0d);
  box-shadow:
    0 0 0 1px rgb(177 250 226 / 0.1),
    0 18px 36px rgb(0 0 0 / 0.42),
    0 0 38px rgb(34 211 165 / 0.24);
  transform: rotate(-2deg);
  animation:
    charizard-card-float 6s ease-in-out infinite,
    charizard-card-radiance 4.8s ease-in-out infinite;
}
.approved-home .featured-market-hero--charizard .featured-market-hero__static-media::before {
  position: absolute;
  z-index: 0;
  inset: -28%;
  border-radius: 50%;
  background: conic-gradient(
    from 210deg,
    transparent 0 32%,
    rgb(117 255 218 / 0.2) 42%,
    transparent 52% 75%,
    rgb(34 211 165 / 0.16) 87%,
    transparent
  );
  content: "";
  filter: blur(16px);
  animation: charizard-card-aura 9s linear infinite;
  pointer-events: none;
}
.approved-home .featured-market-hero--charizard .featured-market-hero__static-media::after {
  position: absolute;
  z-index: 2;
  inset: -20% 40% -20% -65%;
  background: linear-gradient(
    108deg,
    transparent 32%,
    rgb(255 255 255 / 0.3) 47%,
    rgb(116 255 218 / 0.22) 51%,
    transparent 64%
  );
  content: "";
  transform: translateX(-35%) rotate(12deg);
  animation: charizard-card-sheen 5.5s ease-in-out infinite;
  pointer-events: none;
}
.approved-home .featured-market-hero--charizard .featured-market-hero__static-media img {
  position: relative;
  z-index: 1;
  padding: 0.35rem;
  object-fit: contain;
  animation: charizard-card-image 7s ease-in-out infinite;
}
.charizard-showcase__copy {
  z-index: 1;
  align-self: center;
  min-width: 0;
  padding-top: 1.4rem;
}
.charizard-showcase__tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.38rem;
  margin-bottom: 0.8rem;
}
.charizard-showcase__tags span {
  padding: 0.28rem 0.48rem;
  border: 1px solid rgb(34 211 165 / 0.3);
  border-radius: 999px;
  background: rgb(34 211 165 / 0.1);
  color: #a7f3d0;
  font-size: 0.56rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.approved-home .featured-market-hero--charizard .page-kicker {
  color: #22d3a5;
}
.approved-home .featured-market-hero--charizard h2 {
  max-width: 22rem;
  margin: 0.25rem 0 0.65rem;
  color: #ecfffb;
  font-size: clamp(1.45rem, 2.4vw, 2.3rem);
  letter-spacing: -0.045em;
  line-height: 0.98;
}
.approved-home .featured-market-hero--charizard .charizard-showcase__copy > p:not(.page-kicker) {
  max-width: 28rem;
  color: rgb(201 244 231 / 0.8);
  font-size: 0.82rem;
  line-height: 1.55;
}
.charizard-showcase__cta {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  margin-top: 0.5rem;
  color: #72f1ca;
  font-size: 0.76rem;
  font-weight: 800;
  text-decoration: none;
}
.charizard-showcase__cta span {
  font-size: 1rem;
  transition: transform 170ms ease;
}
.charizard-showcase__cta:hover span,
.charizard-showcase__cta:focus-visible span {
  transform: translate(0.15rem, -0.15rem);
}
.charizard-showcase__stamp {
  position: absolute;
  z-index: 2;
  right: 1rem;
  bottom: 0.85rem;
  display: flex;
  align-items: center;
  gap: 0.4rem;
  color: rgb(177 250 226 / 0.5);
  font-size: 0.5rem;
  font-weight: 800;
  letter-spacing: 0.11em;
  text-align: right;
  text-transform: uppercase;
}
.charizard-showcase__stamp span {
  color: #22d3a5;
  font-size: 0.75rem;
  letter-spacing: 0.08em;
}
.charizard-showcase__stamp small {
  line-height: 1.25;
}
@keyframes charizard-card-float {
  0%,
  100% {
    transform: rotate(-2deg) translateY(0);
  }
  50% {
    transform: rotate(1deg) translateY(-0.45rem);
  }
}
@keyframes charizard-card-radiance {
  0%,
  100% {
    box-shadow:
      0 0 0 1px rgb(177 250 226 / 0.1),
      0 18px 36px rgb(0 0 0 / 0.42),
      0 0 38px rgb(34 211 165 / 0.2);
  }
  50% {
    box-shadow:
      0 0 0 1px rgb(177 250 226 / 0.24),
      0 22px 42px rgb(0 0 0 / 0.48),
      0 0 58px rgb(34 211 165 / 0.42);
  }
}
@keyframes charizard-card-aura {
  to {
    transform: rotate(360deg);
  }
}
@keyframes charizard-card-sheen {
  0%,
  25% {
    opacity: 0;
    transform: translateX(-35%) rotate(12deg);
  }
  42% {
    opacity: 0.9;
  }
  68%,
  100% {
    opacity: 0;
    transform: translateX(210%) rotate(12deg);
  }
}
@keyframes charizard-card-image {
  0%,
  100% {
    filter: saturate(1.04) contrast(1.02) brightness(1);
  }
  50% {
    filter: saturate(1.12) contrast(1.05) brightness(1.06);
  }
}
@keyframes charizard-showcase-sweep {
  to {
    transform: rotate(360deg);
  }
}
@keyframes charizard-showcase-pulse {
  0%,
  100% {
    opacity: 0.55;
    transform: scale(0.92);
  }
  50% {
    opacity: 0.95;
    transform: scale(1.08);
  }
}
@media (prefers-reduced-motion: reduce) {
  .approved-home .featured-market-hero--charizard::before,
  .charizard-showcase__glow,
  .approved-home .featured-market-hero--charizard .featured-market-hero__static-media,
  .approved-home .featured-market-hero--charizard .featured-market-hero__static-media::before,
  .approved-home .featured-market-hero--charizard .featured-market-hero__static-media::after,
  .approved-home .featured-market-hero--charizard .featured-market-hero__static-media img {
    animation: none;
  }
}

@media (max-width: 639px) {
  .vault-live-unavailable--example {
    grid-template-columns: 1fr;
  }
  .vault-live-beta-example {
    width: min(8rem, 100%);
  }
  .approved-home .featured-market-hero--static-example {
    grid-template-columns: 1fr;
  }
