/* Keep the collector spotlight inside its content column. Both panels must be
 * allowed to shrink; the published-card grid then consumes only the available
 * featured-panel width instead of reserving a fourth empty fixed track. */
.collectors-spotlight {
  max-width: 100%;
  grid-template-columns: minmax(0, 13fr) minmax(0, 7fr);
}
.collectors-spotlight > .featured-collector-card,
.collectors-spotlight > .collector-discovery-panel,
.featured-holdings,
.featured-holdings-grid,
.featured-holding-card {
  min-width: 0;
  max-width: 100%;
}
.featured-holdings-grid {
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 10.5rem), 1fr));
}
.featured-collector-identity__copy,
.featured-collector-identity h2,
.featured-holding-copy,
.featured-holding-copy > div {
  min-width: 0;
}
.featured-collector-identity h2,
.featured-collector-identity strong,
.featured-collector-identity p,
.featured-holding-copy h4,
.featured-holding-copy > p,
.featured-holding-copy > div strong,
.featured-holding-copy > div span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.featured-collector-identity h2 svg {
