  background: linear-gradient(145deg, rgba(31, 51, 55, 0.92), rgba(16, 23, 28, 0.9));
  color: #a2acb8;
}
.portfolio-asset__icon svg {
  width: 0.95rem;
  height: 0.95rem;
}
.portfolio-asset__copy {
  display: block;
  width: auto;
  height: auto;
  min-width: 0;
  flex: 1 1 auto;
  place-items: initial;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: inherit;
}
.portfolio-asset__copy strong,
.portfolio-asset__copy small {
  display: block;
