  min-width: 0.85rem;
  height: 0.85rem;
  place-items: center;
  padding-inline: 0.14rem;
  border-width: 1px;
  color: var(--color-background);
  font-size: 0.52rem;
  font-weight: 800;
  line-height: 1;
}
.notification-list__row {
  min-height: 4.5rem;
