  z-index: 1;
  width: 1.4rem;
  height: 1.4rem;
  margin: auto;
  color: var(--color-subtle);
}

/* The featured profile is an ordinary vertical flow: keep the identity below
 * its kicker and let its title truncate within the available card width. */
.featured-collector-identity {
  min-width: 0;
  margin-top: 0.55rem;
}
.featured-collector-identity__copy {
  flex: 1 1 0;
}
.featured-collector-identity h2 {
  min-width: 0;
}
.featured-collector-identity h2 > span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.featured-holdings-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

/* The generic portfolio span styling also matches the text wrapper. Give the
 * identity children explicit, more specific flex roles so title copy can
 * never occupy the thumbnail's column. */
.portfolio-asset {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 0.55rem;
}
.portfolio-asset > .portfolio-asset__icon {
  display: grid;
  width: 2.15rem;
  height: 2.15rem;
  flex: 0 0 2.15rem;
  place-items: center;
}
.portfolio-asset > .portfolio-asset__copy {
  display: block;
  width: auto;
  height: auto;
  min-width: 0;
  flex: 1 1 auto;
  padding: 0;
  border: 0;
  background: transparent;
}
.portfolio-asset > .portfolio-asset__copy strong,
.portfolio-asset > .portfolio-asset__copy small {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* The featured Vault Live path is a real grid: the lifecycle track and its
 * public-asset detail occupy separate rows, so the final timeline item never
 * competes with the divider below it. */
.vault-live-visual {
  grid-template-rows: minmax(0, 1fr) auto;
  height: auto;
  min-height: 19rem;
}
.vault-live-visual__asset {
  height: auto;
  min-height: 17.5rem;
  grid-row: 1 / span 2;
}
.vault-live-visual__track {
  align-self: center;
  min-width: 0;
  padding-bottom: 0.9rem;
}
.vault-live-visual__detail {
  position: static;
  min-width: 0;
  grid-column: 2;
  align-self: end;
  padding-top: 0.85rem;
}
.vault-live-visual__detail strong,
.vault-live-visual__detail p {
  min-width: 0;
  overflow-wrap: anywhere;
}

.trading-review-actions,
.trading-result-actions {
  gap: 0.75rem;
}
.trading-review-actions > button,
.trading-result-actions > a {
  display: inline-flex;
  min-height: 3.125rem;
  align-items: center;
  justify-content: center;
  padding: 0.78rem 1.1rem;
  font-size: 0.82rem;
  font-weight: 700;
  line-height: 1.2;
  text-align: center;
  white-space: nowrap;
}

@media (max-width: 520px) {
  .vault-live-visual {
    grid-template-rows: 13rem auto auto;
    min-height: 0;
  }
  .vault-live-visual__asset {
    min-height: 0;
    height: 13rem;
    grid-row: auto;
  }
  .vault-live-visual__track {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    align-self: start;
    padding-bottom: 0;
  }
  .vault-live-visual__detail {
    grid-column: auto;
  }
}

