.list-simple-fields input:focus,
.list-simple-fields select:focus,
.list-simple-fields textarea:focus {
  border-color: #22d3a5;
  box-shadow: 0 0 0 3px rgba(34, 211, 165, 0.12);
}
.list-field-wide {
  grid-column: 1 / -1;
}
.list-help-card,
.list-submit-notice {
  display: flex;
  gap: 0.75rem;
  align-items: flex-start;
  margin-top: 1.5rem;
  padding: 1rem;
  border: 1px solid rgba(34, 211, 165, 0.2);
  border-radius: 0.7rem;
  background: rgba(21, 183, 141, 0.07);
}
.list-help-card svg,
.list-submit-notice svg {
  flex: 0 0 auto;
  width: 1.15rem;
  color: #2adba7;
}
.list-help-card strong {
  color: #e6f4f1;
  font-size: 0.8rem;
}
.list-help-card p,
.list-submit-notice p {
  margin-top: 0.2rem;
  color: #94a8b1;
  font-size: 0.75rem;
  line-height: 1.5;
}
.list-more-details {
  margin-top: 1.5rem;
  border-top: 1px solid rgba(148, 172, 184, 0.13);
  padding-top: 1rem;
}
.list-more-details summary {
  cursor: pointer;
  color: #2adba7;
  font-size: 0.78rem;
  font-weight: 750;
}
.list-terms-check {
  display: flex;
  gap: 0.7rem;
  align-items: flex-start;
  margin-top: 1.5rem;
  color: #9eafb8;
  font-size: 0.76rem;
  line-height: 1.45;
}
.list-terms-check input {
  width: 1rem;
  height: 1rem;
  margin-top: 0.08rem;
  accent-color: #22d3a5;
}
.list-step > .button-primary {
  display: inline-flex;
  gap: 0.5rem;
  align-items: center;
  min-height: 3rem;
  margin-top: 1.5rem;
  padding: 0 1rem;
}
.list-step > .button-primary svg {
  width: 1rem;
}
.list-step-hint {
  margin-top: 1rem !important;
  color: #8293a0 !important;
  font-size: 0.74rem !important;
}
.list-market-result {
  margin-top: 1.5rem;
  overflow: hidden;
  border: 1px solid rgba(54, 213, 168, 0.24);
  border-radius: 0.78rem;
  background: rgba(7, 26, 25, 0.6);
}
.list-market-result__top {
  display: grid;
  gap: 0.22rem;
  padding: 1rem;
  border-bottom: 1px solid rgba(126, 169, 163, 0.17);
}
.list-market-result__top span {
  color: #2adba7;
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}
.list-market-result__top strong {
  color: #e9f6f1;
  font-size: 0.9rem;
}
.list-market-result__metrics {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0;
}
.list-market-result__metrics > div {
  min-width: 0;
  padding: 0.95rem 1rem;
  border-right: 1px solid rgba(126, 169, 163, 0.12);
  border-bottom: 1px solid rgba(126, 169, 163, 0.12);
}
.list-market-result__metrics dt {
  color: #8c9da5;
  font-size: 0.62rem;
  line-height: 1.35;
}
.list-market-result__metrics dd {
  overflow: hidden;
  margin-top: 0.28rem;
  color: #eef9f4;
  font-size: 0.8rem;
