  font-weight: 700;
}
.list-market-observations a {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.55rem 0;
  border-bottom: 1px solid rgba(126, 169, 163, 0.12);
  color: #d7e3e0;
  font-size: 0.72rem;
}
.list-market-observations a span {
  display: grid;
  gap: 0.12rem;
  min-width: 0;
}
.list-market-observations small {
  overflow: hidden;
  color: #899ba2;
  font-size: 0.63rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.list-market-observations b {
  flex: 0 0 auto;
