}
.list-photo-guidance {
  display: flex;
  flex-wrap: wrap;
  gap: 0.55rem;
  margin-top: 1.35rem;
}
.list-photo-guidance span {
  display: inline-flex;
  gap: 0.28rem;
  align-items: center;
  padding: 0.36rem 0.55rem;
  border-radius: 999px;
  background: rgba(49, 82, 81, 0.25);
  color: #b3c5c2;
