}
.list-pregrade {
  margin-top: 1.35rem;
  padding: 1rem;
  border: 1px solid rgba(38, 212, 162, 0.28);
  border-radius: 0.8rem;
  background: linear-gradient(135deg, rgba(38, 212, 162, 0.08), rgba(11, 17, 22, 0.72));
}
.list-pregrade__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
}
.list-pregrade__header h3 {
  margin: 0.2rem 0 0;
  font-size: 1.05rem;
}
.list-pregrade__header p:not(.page-kicker) {
  margin: 0.3rem 0 0;
  color: #b8c9d0;
  font-size: 0.78rem;
}
.list-pregrade__badge {
  padding: 0.25rem 0.5rem;
  border: 1px solid rgba(38, 212, 162, 0.35);
  border-radius: 999px;
  color: #9ef0d5;
  font-size: 0.65rem;
  white-space: nowrap;
}
.list-pregrade__guidance,
.list-pregrade__disclosure,
.list-pregrade__message {
  margin: 0.85rem 0;
  color: #9aadb7;
  font-size: 0.72rem;
  line-height: 1.55;
}
.list-pregrade__result {
  display: grid;
  grid-template-columns: minmax(8rem, 0.7fr) minmax(0, 1.3fr);
  gap: 1rem;
  margin: 1rem 0;
  padding: 0.8rem;
  border: 1px solid rgba(151, 177, 188, 0.18);
  border-radius: 0.65rem;
  background: rgba(4, 9, 13, 0.48);
}
.list-pregrade__estimate {
  display: grid;
  align-content: center;
  gap: 0.15rem;
}
.list-pregrade__estimate span {
  color: #9aadb7;
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}
.list-pregrade__estimate strong {
  color: #e9fbf5;
  font-size: 2rem;
  line-height: 1;
}
.list-pregrade__estimate small {
  color: #9ef0d5;
  font-size: 0.75rem;
}
.list-pregrade__result dl {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.55rem;
  margin: 0;
}
.list-pregrade__result dl div {
  padding: 0.45rem;
  border-radius: 0.45rem;
  background: rgba(151, 177, 188, 0.08);
}
.list-pregrade__result dt {
  color: #8fa0aa;
  font-size: 0.65rem;
}
.list-pregrade__result dd {
  margin: 0.15rem 0 0;
  color: #e9fbf5;
  font-size: 0.9rem;
}
.list-pregrade__result > p,
.list-pregrade__result > details,
.list-pregrade__result > ul {
  grid-column: 1 / -1;
  margin: 0;
  color: #9aadb7;
  font-size: 0.7rem;
  line-height: 1.45;
}
.list-pregrade__result details summary {
  color: #b8c9d0;
  cursor: pointer;
}
.list-pregrade__result ul {
  padding-left: 1rem;
  color: #f0c58a;
}
.list-pregrade__visual-report {
  display: grid;
  grid-template-columns: minmax(13rem, 0.9fr) minmax(12rem, 1fr);
  gap: 1rem;
  grid-column: 1 / -1;
}
.list-pregrade__visual-panel {
  display: grid;
  min-height: 17rem;
  place-items: center;
  position: relative;
  padding: 1rem;
  border: 1px solid rgba(151, 177, 188, 0.2);
  border-radius: 0.65rem;
  background: #071017;
  box-shadow: 0 1rem 2.5rem rgba(0, 0, 0, 0.24);
}
.list-pregrade__visual-panel img {
  display: block;
  width: 100%;
  max-height: 25rem;
  object-fit: contain;
  border-radius: 0.35rem;
}
.list-pregrade__visual-label {
  position: absolute;
  top: 0.55rem;
  left: 0.65rem;
  z-index: 1;
  padding: 0.2rem 0.4rem;
  border-radius: 0.25rem;
  background: rgba(4, 9, 13, 0.75);
  color: #b8c9d0;
  font-size: 0.62rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}
.list-pregrade__visual-controls {
  display: grid;
  align-content: center;
  gap: 0.7rem;
}
.list-pregrade__visual-controls p {
  margin: 0;
  color: #9aadb7;
  font-size: 0.7rem;
  line-height: 1.5;
}
.list-pregrade__segmented {
  display: inline-flex;
  width: fit-content;
  max-width: 100%;
  gap: 0.2rem;
  padding: 0.2rem;
  border: 1px solid rgba(151, 177, 188, 0.2);
  border-radius: 0.45rem;
  background: rgba(151, 177, 188, 0.08);
}
.list-pregrade__segmented button {
  border: 0;
  border-radius: 0.3rem;
  padding: 0.4rem 0.65rem;
  background: transparent;
  color: #9aadb7;
  font-size: 0.68rem;
  cursor: pointer;
}
.list-pregrade__segmented button.is-active {
  background: #1b806b;
  color: #effff9;
}
.list-pregrade__visual-unavailable {
  grid-column: 1 / -1;
  padding: 0.7rem;
  border: 1px dashed rgba(151, 177, 188, 0.25);
  border-radius: 0.45rem;
  color: #9aadb7;
  font-size: 0.72rem;
}
.list-pregrade__ratios {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.45rem;
  margin: 0;
}
.list-pregrade__ratios div {
  padding: 0.4rem;
  border-radius: 0.35rem;
  background: rgba(151, 177, 188, 0.08);
}
.list-pregrade__ratios dt {
  color: #8fa0aa;
  font-size: 0.62rem;
  text-transform: capitalize;
}
.list-pregrade__ratios dd {
  margin: 0.15rem 0 0;
  color: #e9fbf5;
  font-size: 0.75rem;
}
.list-pregrade__score-report {
  display: grid;
  grid-template-columns: minmax(8rem, 0.7fr) minmax(0, 1.3fr);
  gap: 1rem;
  grid-column: 1 / -1;
}
@media (max-width: 640px) {
  .list-pregrade__visual-report,
  .list-pregrade__score-report {
    grid-template-columns: 1fr;
  }
  .list-pregrade__visual-panel {
    min-height: 14rem;
  }
  .list-pregrade__visual-panel img {
    max-height: 20rem;
  }
}
.list-photo-card {
  min-width: 0;
  overflow: hidden;
  border: 1px solid rgba(145, 171, 181, 0.18);
  border-radius: 0.75rem;
  background: rgba(7, 13, 17, 0.56);
}
.list-photo-card__preview {
  display: grid;
  min-height: 13rem;
  place-items: center;
  gap: 0.35rem;
  border-bottom: 1px solid rgba(145, 171, 181, 0.13);
  background: linear-gradient(145deg, rgba(21, 35, 39, 0.62), rgba(6, 11, 14, 0.7));
  color: #9eafb8;
  font-size: 0.72rem;
  text-align: center;
}
.list-photo-card__preview img {
  width: 100%;
  height: 13rem;
  object-fit: contain;
}
.list-photo-card__preview svg {
  width: 2rem;
  height: 2rem;
  color: #65d5b3;
}
.list-photo-card__preview strong {
  color: #e2f0ed;
  font-size: 0.78rem;
}
.list-photo-card__preview span {
  color: #8da2a7;
  font-size: 0.67rem;
}
.list-photo-card__body {
  display: grid;
  gap: 1rem;
  padding: 0.95rem;
}
.list-photo-card__body h3 {
  margin: 0;
  color: #edf5f2;
  font-size: 0.82rem;
}
.list-photo-card__body h3 em {
  margin-left: 0.2rem;
  color: #2adba7;
  font-size: 0.62rem;
  font-style: normal;
  text-transform: uppercase;
}
.list-photo-card__body p {
  margin-top: 0.35rem;
  color: #91a1a9;
  font-size: 0.68rem;
  line-height: 1.45;
}
.list-photo-card__body small {
  display: block;
  margin-top: 0.4rem;
  color: #2adba7;
  font-size: 0.62rem;
}
.list-photo-card__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
}
.list-photo-card__actions label {
  display: inline-flex;
  gap: 0.32rem;
  align-items: center;
  min-height: 2.25rem;
  padding: 0 0.6rem;
  font-size: 0.68rem;
  cursor: pointer;
}
.list-photo-card__actions input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
  pointer-events: none;
}
.list-photo-card__actions svg {
  width: 0.85rem;
}
.list-photo-remove {
  display: grid;
  width: 2.25rem;
  height: 2.25rem;
  place-items: center;
  border: 1px solid rgba(231, 121, 131, 0.35);
  border-radius: 0.45rem;
  color: #f08b94;
}
.list-photo-remove svg {
  width: 0.9rem;
}
.list-review-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1rem;
  margin-top: 1.5rem;
}
.list-review-block {
  padding: 1rem;
  border: 1px solid rgba(149, 171, 181, 0.16);
  border-radius: 0.7rem;
  background: rgba(7, 13, 17, 0.42);
}
.list-review-block header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
}
.list-review-block h3 {
  margin: 0;
  font-size: 0.82rem;
}
.list-review-block button {
  color: #2adba7;
  font-size: 0.68rem;
  font-weight: 750;
}
.list-review-block dl {
  display: grid;
  gap: 0.55rem;
  margin-top: 0.8rem;
}
.list-review-block dl > div {
  display: grid;
  grid-template-columns: minmax(0, 0.9fr) minmax(0, 1.1fr);
  gap: 0.5rem;
}
.list-review-block dt {
  color: #81929e;
  font-size: 0.65rem;
}
.list-review-block dd {
  overflow: hidden;
  color: #e2ece9;
  font-size: 0.68rem;
  text-align: right;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.list-guided-actions {
  position: sticky;
  bottom: 0.8rem;
  z-index: 4;
  display: flex;
  gap: 0.7rem;
  align-items: center;
  margin-top: 1rem;
  padding: 0.7rem;
  border: 1px solid rgba(151, 177, 188, 0.22);
  border-radius: 0.8rem;
  background: rgba(11, 17, 22, 0.96);
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.34);
  backdrop-filter: blur(12px);
}
.list-guided-actions .button-secondary,
.list-guided-actions .button-primary {
  display: inline-flex;
  gap: 0.38rem;
  align-items: center;
  min-height: 2.65rem;
  padding: 0 0.85rem;
  font-size: 0.75rem;
}
.list-guided-actions svg {
  width: 0.9rem;
}
.list-guided-save-status {
  flex: 1;
  color: #8fa0aa;
  font-size: 0.68rem;
  text-align: center;
}
.list-guided-notice,
.list-guided-error {
  display: flex;
  gap: 0.45rem;
  align-items: center;
  margin-bottom: 1rem;
  padding: 0.75rem 0.85rem;
  border-radius: 0.65rem;
  font-size: 0.75rem;
}
.list-guided-notice {
  border: 1px solid rgba(38, 212, 162, 0.22);
  background: rgba(28, 176, 134, 0.1);
  color: #bcf5e2;
}
.list-guided-error {
  border: 1px solid rgba(239, 126, 137, 0.27);
  background: rgba(170, 49, 62, 0.12);
  color: #ffb2b8;
}
.list-guided-notice svg,
.list-guided-error svg {
  flex: 0 0 auto;
  width: 1rem;
}
.list-my-submissions {
  margin-top: 2rem;
  padding: 1.25rem;
}
.list-my-submissions h2 {
  margin-top: 0.35rem;
  color: #f2f7f5;
  font-family: var(--font-display);
  font-size: 1.25rem;
  letter-spacing: -0.04em;
}
.list-my-submissions > p {
  margin-top: 1rem;
  color: #8fa0a9;
  font-size: 0.78rem;
}
.list-my-submissions > div {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.65rem;
  margin-top: 1rem;
}
.list-my-submissions a {
  display: flex;
  gap: 0.65rem;
  align-items: center;
  min-width: 0;
  padding: 0.8rem;
  border: 1px solid rgba(149, 171, 181, 0.14);
  border-radius: 0.6rem;
  color: #dce9e6;
}
.list-my-submissions a > svg:first-child {
  flex: 0 0 auto;
  width: 1.15rem;
  color: #2adba7;
}
.list-my-submissions a > span {
  display: grid;
  min-width: 0;
  flex: 1;
  gap: 0.2rem;
}
.list-my-submissions strong,
.list-my-submissions small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.list-my-submissions strong {
  color: #e8f1ef;
  font-size: 0.74rem;
}
.list-my-submissions small {
  color: #8799a2;
  font-size: 0.62rem;
}
.list-my-submissions a > svg:last-child {
  flex: 0 0 auto;
  width: 0.95rem;
  color: #5dcdb0;
}
.list-received {
  max-width: 43rem;
  margin: 6vh auto;
  padding: clamp(1.5rem, 5vw, 3rem);
  text-align: center;
}
.list-received > svg {
  width: 2.5rem;
  height: 2.5rem;
  padding: 0.55rem;
  border-radius: 50%;
  background: rgba(31, 211, 164, 0.14);
  color: #2adba7;
}
.list-received > p:last-of-type {
  max-width: 33rem;
  margin: 1rem auto 0;
  color: #9dafb7;
  font-size: 0.86rem;
  line-height: 1.55;
}
.list-received ol {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0.45rem;
  margin: 1.7rem 0;
}
.list-received li {
  padding: 0.42rem 0.58rem;
  border: 1px solid rgba(149, 171, 181, 0.16);
  border-radius: 999px;
  color: #a8b9bd;
  font-size: 0.67rem;
}
.list-received li:first-child {
  border-color: rgba(34, 211, 165, 0.35);
  color: #2adba7;
}
.list-received > div {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0.65rem;
}
.list-received .button-primary,
.list-received .button-secondary {
  display: inline-flex;
  align-items: center;
  min-height: 2.7rem;
  padding: 0 0.9rem;
  font-size: 0.75rem;
}
@media (max-width: 720px) {
  .list-guided-shell {
    width: min(calc(100% - 1.25rem), 60rem);
  }
  .list-guided-heading {
    display: block;
  }
  .list-guided-drafts {
    margin-top: 1rem;
  }
  .list-step-progress {
    overflow-x: auto;
  }
  .list-step-progress ol {
    min-width: 40rem;
  }
  .list-step-progress button {
    min-height: 3.35rem;
  }
  .list-simple-fields,
  .list-simple-fields--details,
  .list-photo-grid,
  .list-photo-grid--optional,
  .list-review-grid,
  .list-my-submissions > div {
    grid-template-columns: 1fr;
  }
  .list-market-result__metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .list-photo-card__preview,
  .list-photo-card__preview img {
    min-height: 11rem;
    height: 11rem;
  }
  .list-pregrade__header {
    display: block;
  }
  .list-pregrade__badge {
    display: inline-block;
    margin-top: 0.65rem;
  }
  .list-pregrade__result {
    grid-template-columns: 1fr;
  }
  .list-guided-actions {
    bottom: 0;
    margin-inline: -0.05rem;
    border-radius: 0.75rem 0.75rem 0 0;
  }
  .list-guided-save-status {
    display: none;
  }
  .list-guided-actions .button-secondary,
  .list-guided-actions .button-primary {
    flex: 1;
    justify-content: center;
  }
}
/* Collector workspace foundation pass */
.collector-workspace-main {
  width: min(100%, 1500px);
  margin: 0 auto;
  padding-inline: clamp(1.25rem, 3vw, 3rem);
}
.collector-workspace-content--page {
  gap: 1.25rem;
  padding-bottom: 3.5rem;
}
.collector-page-heading {
  max-width: 48rem;
  margin: 1.4rem 0 0.2rem;
}
.collector-page-heading h2 {
  font-size: clamp(1.75rem, 3vw, 2.4rem);
}
.collector-page-heading span {
  max-width: 43rem;
  line-height: 1.55;
}
.collector-panel {
  border-radius: 0.75rem;
}
.collector-asset-grid.is-full {
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 1rem;
}
.collector-asset-card {
  position: relative;
  align-content: start;
  gap: 0.42rem;
  padding: 0.68rem;
  border: 1px solid #26333c;
  border-radius: 0.7rem;
  background: rgba(8, 17, 24, 0.78);
  transition:
    border-color 160ms ease,
    transform 160ms ease;
}
.collector-asset-card:hover {
  border-color: rgba(44, 214, 176, 0.78);
  transform: translateY(-2px);
}
.collector-asset-card__image {
  height: clamp(13rem, 17vw, 16.5rem);
  border-radius: 0.5rem;
}
.collector-asset-card strong {
  font-size: 0.78rem;
  line-height: 1.35;
  white-space: normal;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}
.collector-asset-card > span {
  font-size: 0.66rem;
}
.collector-asset-card > b {
  font-size: 0.82rem;
}
.collector-asset-card__cta {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  margin-top: 0.15rem;
  color: #32dfb6 !important;
  font-size: 0.64rem !important;
  font-weight: 700;
}
.collector-asset-card__cta svg {
  width: 0.85rem;
  height: 0.85rem;
}
.collector-record-list {
  padding: 0.25rem 1rem;
}
.collector-record-row {
  display: grid;
  width: 100%;
  min-width: 0;
  grid-template-columns: 3.5rem minmax(14rem, 1.8fr) minmax(8rem, 0.9fr) auto auto 0.8rem;
  gap: 1rem;
  align-items: center;
  padding: 0.85rem 0;
  border-bottom: 1px solid #26323d;
  text-align: left;
}
.collector-record-row:last-child {
  border-bottom: 0;
}
.collector-record-row__image,
.collector-asset-thumbnail {
  display: grid;
  width: 3.35rem;
  height: 4.25rem;
  flex: 0 0 auto;
  place-items: center;
  overflow: hidden;
  border: 1px solid #31414c;
  border-radius: 0.45rem;
  background: radial-gradient(circle, rgba(21, 89, 78, 0.35), #071016 72%);
  color: #35ddb7;
}
.collector-record-row__image img,
.collector-asset-thumbnail img {
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.collector-record-row__image svg,
.collector-asset-thumbnail svg {
  width: 1.1rem;
  height: 1.1rem;
}
.collector-record-row__content {
  display: grid;
  min-width: 0;
  gap: 0.18rem;
}
.collector-record-row__content small,
.collector-record-row__content > span,
.collector-record-row__meta {
  overflow: hidden;
  color: #91a3b5;
  font-size: 0.65rem;
  line-height: 1.4;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.collector-record-row__content small {
  color: #32dfb6;
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.11em;
  text-transform: uppercase;
}
.collector-record-row__content strong {
  overflow: hidden;
  color: #f2f6f9;
  font-size: 0.78rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.collector-record-row__meta {
  color: #c2ced8;
}
.collector-record-row > b {
  color: #fff;
  font-size: 0.82rem;
  white-space: nowrap;
