  gap: 1rem;
}
.collector-settings-grid > article {
  display: grid;
  align-content: start;
  gap: 0.65rem;
  min-height: 14rem;
  padding: 1.15rem;
}
.collector-settings-grid strong {
  color: #f4f8fb;
  font-size: 0.9rem;
}
.collector-settings-grid p {
  color: #9cadbd;
  font-size: 0.72rem;
  line-height: 1.55;
}
.collector-settings__icon {
