}
.collector-asset-detail__content {
  display: grid;
  gap: 0.85rem;
  min-width: 0;
}
.collector-detail-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
  padding: 0.55rem;
  border: 1px solid #26313b;
  border-radius: 0.6rem;
  background: #0a1219;
}
.collector-detail-tabs button {
  border-radius: 0.4rem;
  padding: 0.5rem 0.7rem;
  color: #98aabb;
  font-size: 0.67rem;
  font-weight: 700;
  text-transform: capitalize;
}
.collector-detail-tabs button.is-active {
  background: rgba(0, 194, 155, 0.14);
  color: #41e6bf;
}
.collector-detail-panel {
  min-height: 18rem;
  padding: 1.25rem;
}
.collector-detail-panel h3 {
  font-size: 1rem;
  text-transform: capitalize;
}
.collector-detail-panel dd {
  overflow: visible;
  white-space: normal;
  line-height: 1.5;
}
.collector-detail-evidence {
  display: grid;
  gap: 0.5rem;
  margin-top: 0.25rem;
}
.collector-detail-evidence li {
  display: grid;
  grid-template-columns: 1.5rem minmax(0, 1fr);
  gap: 0.55rem;
  align-items: center;
  padding: 0.6rem;
  border: 1px solid #26333c;
  border-radius: 0.45rem;
}
.collector-detail-evidence li > svg {
  width: 0.9rem;
  color: #40e2bd;
}
.collector-detail-evidence li span {
  display: grid;
  gap: 0.12rem;
}
.collector-detail-evidence strong {
  color: #edf5f8;
  font-size: 0.7rem;
}
.collector-detail-evidence small {
  color: #97aabd;
  font-size: 0.62rem;
}
@media (max-width: 1320px) {
  .collector-asset-grid.is-full {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}
@media (max-width: 980px) {
  .collector-asset-grid.is-full {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .collector-record-row {
    grid-template-columns: 3.5rem minmax(12rem, 1fr) auto auto 0.8rem;
  }
  .collector-record-row__meta {
    display: none;
  }
  .collector-document-groups {
    grid-template-columns: 1fr;
  }
  .collector-settings-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 820px) {
  .collector-profile-layout,
  .collector-asset-detail {
    grid-template-columns: 1fr;
  }
  .collector-asset-detail > .collector-asset-card {
    position: static;
  }
  .collector-asset-detail > .collector-asset-card .collector-asset-card__image {
    height: 19rem;
  }
  .collector-asset-grid.is-full {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .collector-asset-card__image {
    height: 13rem;
  }
  .collector-record-row {
    grid-template-columns: 3.2rem minmax(0, 1fr) auto 0.75rem;
    gap: 0.65rem;
  }
  .collector-record-row__image {
    width: 3rem;
    height: 3.8rem;
  }
  .collector-record-row > b {
    display: none;
  }
  .collector-request-cards {
    grid-template-columns: 1fr;
  }
  .collector-settings-grid {
    grid-template-columns: 1fr;
  }
  .collector-settings-grid > article {
    min-height: 0;
  }
}
@media (max-width: 520px) {
  .collector-workspace-main {
    padding-inline: 0.85rem;
  }
  .collector-profile-editor {
    grid-template-columns: 1fr;
  }
  .collector-profile-editor > label {
    grid-column: 1 / -1;
  }
  .collector-asset-grid.is-full {
    grid-template-columns: 1fr;
  }
  .collector-asset-card__image {
    height: 17rem;
  }
  .collector-record-row .collector-status {
    display: none;
  }
  .collector-detail-tabs {
    overflow-x: auto;
    flex-wrap: nowrap;
  }
  .collector-detail-tabs button {
    white-space: nowrap;
  }
}
