}
.asset-redesign .asset-details-panel > div:not(.asset-section-label) {
  padding: 0.7rem 0;
}
.asset-redesign .asset-details-panel > div:not(.asset-section-label) span {
  font-size: 0.78rem;
}
.asset-redesign .asset-details-panel > div:not(.asset-section-label) strong {
