}
.asset-ownership-panel--simple {
  padding: 1.2rem;
}
.asset-redesign .asset-ownership-panel--simple h2 {
  margin: 0 0 1rem;
  font-family: inherit;
  font-size: 1.25rem;
  letter-spacing: -0.035em;
  text-transform: none;
}
.asset-availability-box {
  display: flex;
  align-items: flex-start;
  gap: 0.8rem;
  border: 1px solid rgba(244, 190, 86, 0.3);
