  background: rgba(116, 81, 27, 0.12);
}
.asset-availability-icon {
  display: grid;
  width: 1.6rem;
  height: 1.6rem;
  place-items: center;
  flex: 0 0 auto;
  border: 1px solid #e9bd66;
  border-radius: 50%;
  color: #e9bd66;
  font-size: 1rem;
}
.asset-availability-box strong {
  color: #f3d18d;
  font-size: 0.9rem;
}
.asset-availability-box p {
  margin: 0.25rem 0 0;
  color: #b4b7a8;
  font-size: 0.78rem;
  line-height: 1.45;
}
.asset-ownership-facts {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.5rem;
  margin-top: 1rem;
}
.asset-ownership-facts dl {
  margin: 0;
  border: 1px solid rgba(109, 150, 158, 0.17);
  border-radius: 0.65rem;
  padding: 0.7rem;
}
.asset-ownership-facts dd {
  min-height: 1.8rem;
  font-size: 0.95rem;
}
.asset-redesign .asset-details-panel .asset-panel-helper {
  margin: 0 0 0.5rem;
  font-size: 0.78rem;
}
.asset-redesign .asset-similar-section {
  margin-top: 0;
  padding: 1.2rem;
}

.asset-slice-grade-panel {
  min-width: 0;
  border: 1px solid rgba(72, 196, 166, 0.28);
  border-radius: 1rem;
  padding: 1.2rem;
  background: linear-gradient(145deg, rgba(11, 38, 40, 0.9), rgba(7, 16, 21, 0.98));
  box-shadow: 0 18px 45px rgba(0, 0, 0, 0.14);
}
.asset-slice-grade-panel__header,
.asset-slice-grade-panel__evidence-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
}
.asset-slice-grade-panel__header h2 {
  margin: 0;
  font-family: inherit;
  font-size: 1.35rem;
  letter-spacing: -0.035em;
}
.asset-slice-grade-panel__header p:not(.asset-section-label) {
  max-width: 48rem;
  margin: 0.35rem 0 0;
  color: #a8c0c3;
  font-size: 0.8rem;
  line-height: 1.5;
}
.asset-slice-grade-panel__badge {
  flex: 0 0 auto;
  border: 1px solid rgba(55, 220, 178, 0.42);
  border-radius: 999px;
  padding: 0.42rem 0.6rem;
  color: #56e1ba;
  font-size: 0.64rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}
.asset-slice-grade-panel__summary {
  display: grid;
  grid-template-columns: minmax(11rem, 0.7fr) minmax(0, 1.3fr);
  gap: 0.8rem;
  margin-top: 1rem;
}
.asset-slice-grade-panel__score {
  display: grid;
  align-content: center;
  gap: 0.25rem;
  border: 1px solid rgba(93, 170, 165, 0.2);
  border-radius: 0.75rem;
  padding: 0.9rem;
  background: rgba(5, 18, 21, 0.58);
}
.asset-slice-grade-panel__score span,
.asset-slice-grade-panel__facts span,
.asset-slice-grade-panel__evidence-heading span {
  color: #8fa8ae;
  font-size: 0.68rem;
}
.asset-slice-grade-panel__score strong {
  color: #effcf8;
  font-size: 2rem;
  letter-spacing: -0.04em;
}
.asset-slice-grade-panel__score small {
  color: #38dcb2;
  font-size: 0.75rem;
  font-weight: 750;
}
.asset-slice-grade-panel__facts {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  border: 1px solid rgba(93, 170, 165, 0.2);
  border-radius: 0.75rem;
  overflow: hidden;
  background: rgba(5, 18, 21, 0.42);
}
.asset-slice-grade-panel__facts div {
  display: grid;
  align-content: center;
  gap: 0.3rem;
  min-width: 0;
  padding: 0.8rem;
  border-left: 1px solid rgba(93, 170, 165, 0.14);
}
.asset-slice-grade-panel__facts div:first-child {
  border-left: 0;
}
.asset-slice-grade-panel__facts strong {
  color: #e7f5f1;
  font-size: 0.95rem;
}
.asset-slice-grade-panel__evidence {
  margin-top: 0.85rem;
  border-top: 1px solid rgba(93, 170, 165, 0.17);
  padding-top: 0.9rem;
}
.asset-slice-grade-panel__evidence-heading strong {
  display: block;
  color: #e7f5f1;
  font-size: 0.86rem;
}
.asset-slice-grade-panel__evidence-heading small {
  color: #8fa8ae;
  font-size: 0.68rem;
}
.asset-slice-grade-panel__images {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(8rem, 1fr));
  gap: 0.65rem;
  margin-top: 0.65rem;
}
.asset-slice-grade-panel__images figure {
  min-width: 0;
  margin: 0;
}
.asset-slice-grade-panel__image-button {
  position: relative;
  display: block;
  width: 100%;
  padding: 0;
  border: 0;
  border-radius: 0.6rem;
  background: transparent;
  color: inherit;
  cursor: zoom-in;
  text-align: left;
}
.asset-slice-grade-panel__images img {
  display: block;
  width: 100%;
  height: 10rem;
  object-fit: contain;
  border: 1px solid rgba(93, 170, 165, 0.2);
  border-radius: 0.6rem;
  background: #061215;
  transition:
    border-color 0.2s ease,
    box-shadow 0.2s ease,
    transform 0.2s ease;
}
.asset-slice-grade-panel__image-button span {
  position: absolute;
  right: 0.55rem;
  bottom: 0.55rem;
  border: 1px solid rgba(220, 247, 239, 0.22);
  border-radius: 999px;
  padding: 0.28rem 0.45rem;
  background: rgba(3, 12, 15, 0.78);
  color: #dffbf4;
  font-size: 0.58rem;
  font-weight: 750;
  opacity: 0;
  transform: translateY(0.2rem);
  transition:
    opacity 0.2s ease,
    transform 0.2s ease;
}
.asset-slice-grade-panel__image-button:hover img,
.asset-slice-grade-panel__image-button:focus-visible img {
  border-color: rgba(55, 220, 178, 0.72);
  box-shadow: 0 0 0 0.2rem rgba(55, 220, 178, 0.1);
  transform: translateY(-0.1rem);
}
.asset-slice-grade-panel__image-button:hover span,
.asset-slice-grade-panel__image-button:focus-visible span {
  opacity: 1;
  transform: translateY(0);
}
.asset-slice-grade-panel__images figcaption {
  margin-top: 0.35rem;
  color: #9eb6b9;
  font-size: 0.66rem;
}
.asset-slice-grade-panel__empty,
.asset-slice-grade-panel__note {
  margin: 0.7rem 0 0;
  color: #9eb6b9;
  font-size: 0.72rem;
}
.asset-slice-grade-panel__note {
  color: #e0bd74;
}
.asset-slice-grade-lightbox {
  position: fixed;
  z-index: 130;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 1.5rem;
  background: rgba(1, 7, 10, 0.9);
  backdrop-filter: blur(8px);
}
.asset-slice-grade-lightbox__content {
  width: min(58rem, 100%);
  max-height: min(92vh, 56rem);
  overflow: auto;
  border: 1px solid rgba(72, 196, 166, 0.45);
  border-radius: 1rem;
  padding: 1rem;
  background: linear-gradient(145deg, rgba(10, 35, 37, 0.98), rgba(5, 13, 18, 0.99));
  box-shadow: 0 2rem 6rem rgba(0, 0, 0, 0.5);
}
.asset-slice-grade-lightbox__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
}
.asset-slice-grade-lightbox__header strong {
  display: block;
  margin-top: 0.25rem;
  color: #effcf8;
  font-size: 1rem;
}
.asset-slice-grade-lightbox__close {
  display: grid;
  width: 2.2rem;
  height: 2.2rem;
  flex: 0 0 auto;
  place-items: center;
  border: 1px solid rgba(93, 170, 165, 0.3);
  border-radius: 50%;
  background: rgba(5, 18, 21, 0.7);
  color: #dffbf4;
  cursor: pointer;
  font-size: 1.4rem;
  line-height: 1;
}
.asset-slice-grade-lightbox__close:hover,
.asset-slice-grade-lightbox__close:focus-visible {
  border-color: #38dcb2;
  color: #38dcb2;
}
.asset-slice-grade-lightbox__image-wrap {
  display: grid;
  min-height: min(60vh, 36rem);
  margin-top: 0.8rem;
  place-items: center;
  border: 1px solid rgba(93, 170, 165, 0.2);
  border-radius: 0.75rem;
  padding: 1rem;
  background: rgba(2, 10, 13, 0.72);
}
.asset-slice-grade-lightbox__image-wrap img {
  display: block;
  max-width: 100%;
  max-height: min(70vh, 44rem);
  object-fit: contain;
}
.asset-slice-grade-lightbox__hint {
  margin: 0.7rem 0 0;
  color: #8fa8ae;
  font-size: 0.68rem;
  text-align: center;
}

@media (max-width: 900px) {
  .asset-redesign-hero {
    grid-template-columns: minmax(0, 1fr);
  }
  .asset-redesign-media .asset-showcase {
    min-height: 28rem;
  }
  .asset-redesign-grid {
    grid-template-columns: minmax(0, 1fr);
  }
}
@media (max-width: 640px) {
  .asset-detail-page .asset-redesign {
    gap: 0.85rem;
    padding-bottom: 2rem;
  }
  .asset-detail-page .asset-page-heading {
    display: grid;
    align-items: start;
    gap: 0.75rem;
    padding-top: 0.6rem;
  }
  .asset-detail-page .asset-page-heading h1 {
    font-size: clamp(2rem, 11vw, 3rem);
  }
  .asset-page-subtitle {
    font-size: 0.82rem;
    line-height: 1.45;
  }
  .asset-page-heading__actions {
    padding: 0;
  }
  .asset-redesign-media .asset-showcase {
    min-height: 24rem;
  }
  .asset-redesign-media .asset-showcase > img {
    max-height: 21rem;
  }
  .asset-readiness-card,
  .asset-value-overview,
  .asset-how-it-works,
  .asset-details-panel--compact,
  .asset-ownership-panel--simple,
  .asset-slice-grade-panel {
    padding: 1rem;
  }
  .asset-readiness-heading {
    display: grid;
    gap: 0.7rem;
  }
  .asset-readiness-heading .asset-status-badge {
    justify-self: start;
  }
  .asset-value-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .asset-value-grid dl {
    border-top: 1px solid rgba(109, 150, 158, 0.17);
    border-left: 0;
  }
  .asset-value-grid dl:nth-child(odd) {
    border-right: 1px solid rgba(109, 150, 158, 0.17);
  }
  .asset-value-grid dl:nth-child(-n + 2) {
    border-top: 0;
  }
  .asset-how-it-works__grid {
    grid-template-columns: minmax(0, 1fr);
  }
  .asset-how-it-works__grid > div {
    display: grid;
    grid-template-columns: 1.65rem minmax(0, 1fr);
    gap: 0.2rem 0.7rem;
    align-items: center;
  }
  .asset-how-it-works__grid b {
    grid-row: span 2;
    margin: 0;
  }
  .asset-how-it-works__grid p {
    grid-column: 2;
  }
  .asset-redesign .asset-chart-stats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .asset-redesign .asset-chart-stats dl:nth-child(odd) {
    border-left: 0;
  }
  .asset-redesign .asset-chart-stats dl:nth-child(n + 3) {
    border-top: 1px solid rgba(145, 174, 184, 0.08);
  }
  .asset-ownership-facts {
    grid-template-columns: 1fr;
  }
  .asset-redesign-grid--lower {
    grid-template-columns: minmax(0, 1fr);
  }
  .asset-slice-grade-panel__header {
    display: grid;
  }
  .asset-slice-grade-panel__summary {
    grid-template-columns: minmax(0, 1fr);
  }
  .asset-slice-grade-panel__facts {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .asset-slice-grade-panel__facts div:nth-child(odd) {
    border-left: 0;
  }
  .asset-slice-grade-panel__facts div:nth-child(n + 3) {
    border-top: 1px solid rgba(93, 170, 165, 0.14);
  }
  .asset-slice-grade-lightbox {
    padding: 0.75rem;
  }
  .asset-slice-grade-lightbox__content {
    padding: 0.75rem;
  }
  .asset-slice-grade-lightbox__image-wrap {
    min-height: 60vh;
    padding: 0.5rem;
  }
  .asset-slice-grade-panel__image-button span {
    opacity: 1;
    transform: none;
  }
  .asset-redesign .asset-price-panel > header {
    display: grid;
    gap: 0.7rem;
  }
  .asset-redesign .asset-price-panel > header > div:last-child {
    justify-content: flex-start;
  }
}

/* Portfolio overview layout guardrails: keep dense panels readable at desktop widths. */
.portfolio-page--approved .portfolio-overview-content > .portfolio-panel,
.portfolio-page--approved .portfolio-overview-content > .portfolio-panel > .portfolio-panel__body,
.portfolio-page--approved .portfolio-performance-hero,
.portfolio-page--approved .portfolio-performance-hero__value,
.portfolio-page--approved .portfolio-performance-periods,
.portfolio-page--approved .portfolio-table-wrap,
.portfolio-page--approved .portfolio-empty-state--table {
  min-width: 0;
  box-sizing: border-box;
}

.portfolio-page--approved .portfolio-panel--hero-performance .portfolio-panel__head {
  min-width: 0;
  align-items: flex-start;
