  .admin-review-toolbar .admin-select:nth-of-type(n + 4),
  .admin-review-more-filters {
    grid-row: 2;
  }

  .admin-review-detail .admin-review-top-grid {
    grid-template-columns: minmax(0, 1.25fr) minmax(15rem, 0.9fr);
  }

  .admin-review-detail .admin-review-top-grid > :last-child {
    grid-column: 1 / -1;
  }
