@media (max-width: 920px) {
  .admin-review-toolbar {
    grid-template-columns: minmax(0, 1fr) repeat(2, minmax(0, auto));
  }

  .admin-review-detail .admin-review-queue-item {
    flex-basis: 16rem;
  }

  .admin-review-detail .admin-review-content-grid,
  .admin-review-detail .admin-review-overview-grid {
    grid-template-columns: 1fr;
  }

  .admin-review-detail .admin-review-rail {
    position: static;
