  .admin-review-detail .admin-review-top-grid {
    grid-template-columns: 1fr;
  }

  .admin-review-detail .admin-review-top-grid > :last-child {
    grid-column: auto;
  }

  .admin-review-detail .admin-review-collectible {
    grid-template-columns: 5.5rem minmax(0, 1fr);
  }

  .admin-review-detail .admin-review-header {
    align-items: stretch;
    flex-direction: column;
