}

/* 0003 — similar assets use their projected public media and never expose a
   raw field name as fallback UI. */
.asset-similar-grid {
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 240px), 1fr));
}

.asset-similar-grid.is-single {
  grid-template-columns: minmax(0, 420px);
