  color: rgba(181, 200, 205, 0.68);
  font-size: 0.62rem;
  text-align: center;
}

.asset-similar-section > header button:disabled {
  cursor: not-allowed;
  opacity: 0.35;
}

/* 0004 — execution rows reserve readable columns and stack on narrow cards. */
.asset-recent-trades li {
  min-width: 0;
  grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr) max-content;
  gap: 0.6rem;
  align-items: baseline;
  padding-block: 0.28rem;
  line-height: 1.35;
}

.asset-recent-trades li span,
.asset-recent-trades li strong,
.asset-recent-trades li em {
  min-width: 0;
  overflow-wrap: anywhere;
  white-space: normal;
}

.asset-recent-trades li strong,
.asset-recent-trades li em {
  text-align: right;
}

/* 0005 — shared card primitive keeps the body and CTA aligned in Grid and
   Compact modes, including cards with optional metadata. */
.market-asset-grid,
.market-asset-grid.is-compact {
  align-items: stretch;
}

.market-investment-card {
  height: 100%;
}

.market-card-body {
  display: flex;
  min-width: 0;
  flex: 1 1 auto;
  flex-direction: column;
}

.market-card-heading,
.market-card-heading h2,
.market-card-grade,
.market-card-condition,
.market-card-value,
.market-card-reference,
.market-card-metrics,
.market-ownership {
