/* 0006 — the detailed row has four children, so its action owns the fourth
   column instead of being pushed into an unintended fifth column. */
.market-detailed-row {
  grid-template-columns: 104px minmax(12rem, 1.15fr) minmax(0, 1.6fr) minmax(7.5rem, auto);
}

.market-detailed-row > a:first-child {
