.wallet-timeline__step {
  position: relative;
  min-width: 0;
  padding-top: 1.7rem;
  text-align: center;
}
.wallet-timeline__step::before {
  position: absolute;
  top: 0.65rem;
  left: 0;
  right: 0;
  height: 1px;
  background: rgba(134, 164, 171, 0.28);
  content: "";
}
.wallet-timeline__step:first-child::before {
  left: 50%;
}
.wallet-timeline__step:last-child::before {
  right: 50%;
}
.wallet-timeline__step > span {
  position: absolute;
  top: 0.2rem;
  left: 50%;
  z-index: 1;
  display: grid;
  width: 0.95rem;
  height: 0.95rem;
  place-items: center;
  border: 1px solid rgba(137, 163, 172, 0.35);
  border-radius: 50%;
