  cursor: pointer;
  font-size: 0.6rem;
  font-weight: 700;
  white-space: nowrap;
}
.list-optional-role__actions button {
  display: grid;
  width: 1.45rem;
  height: 1.45rem;
  place-items: center;
  border: 1px solid rgba(234, 116, 121, 0.24);
  border-radius: 0.3rem;
  color: #e58c90;
  background: transparent;
}
.list-optional-role__actions button svg {
  width: 0.65rem;
  height: 0.65rem;
}
.list-photo-info-bar,
.list-photo-context {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  margin: 1rem 1.25rem 0;
  padding: 0.7rem 0.8rem;
  border: 1px solid rgba(50, 220, 175, 0.17);
  border-radius: 0.55rem;
  color: #a7c1bf;
  background: rgba(17, 82, 68, 0.12);
  font-size: 0.68rem;
}
.list-photo-info-bar svg,
.list-photo-context svg {
  width: 1rem;
  height: 1rem;
  flex: none;
  color: #36dfb1;
}
.list-photo-info-bar span {
  color: #8ca6a6;
}
.list-photo-context {
  margin-bottom: 1rem;
  color: #a2b8ba;
}
.list-guided-card:has(.list-step--photos) > .list-guided-actions {
  margin-top: 1rem;
}
@media (max-width: 1390px) {
  .list-required-photo-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}
@media (max-width: 980px) {
  .list-photos-layout {
    grid-template-columns: 1fr;
  }
  .list-photo-rail {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    padding: 0 1.25rem;
  }
  .list-photo-rail-card--help {
    grid-column: auto;
  }
}
@media (max-width: 760px) {
  .list-required-photo-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .list-photo-rail {
    grid-template-columns: 1fr;
  }
  .list-photo-rail-card--help {
    grid-column: auto;
  }
  .list-photo-camera {
    display: inline-flex !important;
  }
  .list-additional-upload-row {
    grid-template-columns: 1fr;
  }
  .list-additional-dropzone {
    min-height: 7rem;
  }
}
@media (max-width: 480px) {
  .list-photos-heading {
    padding-inline: 0.95rem;
  }
  .list-photos-section {
    margin-inline: 0.95rem;
    padding: 0.65rem;
  }
  .list-photos-section__heading {
    display: grid;
  }
  .list-photo-count {
    width: fit-content;
  }
  .list-required-photo-grid {
    grid-template-columns: 1fr;
  }
  .list-photo-tile__preview,
  .list-photo-tile__preview img {
    min-height: 8.5rem;
    height: 8.5rem;
  }
  .list-optional-role-grid {
    grid-template-columns: 1fr;
  }
  .list-photo-info-bar,
  .list-photo-context {
    margin-inline: 0.95rem;
    align-items: flex-start;
    flex-wrap: wrap;
  }
  .list-photo-info-bar span {
    flex-basis: 100%;
    padding-left: 1.55rem;
  }
  .list-photo-rail {
    padding-inline: 0.95rem;
  }
}

