}
.physical-intake-shipment-card {
  display: grid;
  grid-template-columns: minmax(0, 0.95fr) minmax(20rem, 1.05fr);
  gap: 1.25rem;
  padding-top: 1rem;
}
.physical-intake-shipment-card > div > strong {
  color: #dcefeb;
  font-size: 0.83rem;
}
.physical-intake-shipment-card > div > p {
  margin-top: 0.38rem;
}
.physical-intake-shipment-card dl {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.7rem 1rem;
  margin: 0;
}
.physical-intake-shipment-card dt {
  color: #76939b;
  font-size: 0.56rem;
  text-transform: uppercase;
  letter-spacing: 0.075em;
}
.physical-intake-shipment-card dd {
  margin: 0.22rem 0 0;
  color: #e0efeb;
  font-size: 0.68rem;
  overflow-wrap: anywhere;
}
.physical-intake-verification-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(12rem, 0.65fr);
  gap: 1.3rem;
  padding-top: 1rem;
}
.physical-intake-check-list {
  display: grid;
  gap: 0;
  margin: 0.85rem 0 0;
}
.physical-intake-check-list div {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  border-top: 1px solid #1d3943;
  padding: 0.5rem 0;
}
.physical-intake-check-list dt,
.physical-intake-check-list dd {
  font-size: 0.66rem;
}
.physical-intake-check-list dt {
  color: #9ab1b7;
}
.physical-intake-check-list dd {
  margin: 0;
  color: #aebfc2;
}
.physical-intake-check-list .is-pass {
  color: #45ddb9;
}
.physical-intake-check-list .is-fail {
  color: #ff868a;
}
.physical-intake-history-list {
  display: grid;
  gap: 0;
  margin: 0;
  padding: 0.35rem 0 0;
  list-style: none;
}
.physical-intake-history-list li {
  position: relative;
  display: grid;
  grid-template-columns: 1rem minmax(0, 1fr);
  gap: 0.7rem;
  padding: 0.45rem 0 0.75rem;
}
.physical-intake-history-list li::before {
  position: absolute;
  top: 1rem;
  bottom: -0.25rem;
  left: 0.31rem;
  width: 1px;
  background: #2b4a56;
  content: "";
}
.physical-intake-history-list li:last-child::before {
  display: none;
}
.physical-intake-history-list li > span {
  z-index: 1;
  width: 0.65rem;
  height: 0.65rem;
  margin-top: 0.15rem;
  border: 2px solid #42dcb9;
  border-radius: 50%;
  background: #0d2028;
}
.physical-intake-history-list strong,
.physical-intake-history-list small {
  display: block;
}
.physical-intake-history-list strong {
  color: #dff2ed;
  font-size: 0.7rem;
}
.physical-intake-history-list small {
  margin-top: 0.17rem;
  color: #8aa5ac;
  font-size: 0.6rem;
}
.physical-intake-history-list details {
  margin-top: 0.35rem;
  color: #7f9da6;
  font-size: 0.6rem;
}
.physical-intake-history-list summary {
  cursor: pointer;
  color: #57dabb;
}
.physical-intake-history-list code {
  display: block;
  overflow: auto;
  margin-top: 0.35rem;
  color: #b3c7c8;
  font-size: 0.55rem;
  white-space: pre-wrap;
}
.physical-intake-empty-history {
  padding: 1.1rem 0.1rem 0.25rem;
}
.physical-intake-detail-not-found {
  width: min(38rem, 100%);
  padding: 1.2rem;
}
.physical-intake-detail-not-found h2 {
  margin: 0.3rem 0;
  color: #e2f1ee;
  font-size: 1rem;
}
.physical-intake-detail-not-found p:not(.admin-console-eyebrow) {
  color: #99b2b8;
  font-size: 0.7rem;
  line-height: 1.5;
}
@media (max-width: 1180px) {
  .physical-intake-detail-metadata {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .physical-intake-detail-metadata > div:nth-child(3) {
    border-right: 0;
  }
  .physical-intake-detail-metadata > div:nth-child(-n + 3) {
    border-bottom: 1px solid #1d3a45;
  }
  .physical-intake-detail-layout {
    grid-template-columns: 1fr;
  }
  .physical-intake-detail-rail {
    position: static;
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .physical-intake-next-action-card {
    grid-column: 1 / -1;
  }
}
@media (max-width: 860px) {
  .physical-intake-detail-identity {
    grid-template-columns: 5.6rem minmax(0, 1fr);
  }
  .physical-intake-detail-identity > img,
  .physical-intake-detail-identity > .physical-intake-thumbnail-placeholder {
    width: 5.6rem;
    height: 7.65rem;
  }
  .physical-intake-detail-identity > .admin-status-pill {
    grid-column: 2;
    justify-self: start;
  }
  .physical-intake-stepper {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    row-gap: 1rem;
  }
  .physical-intake-stepper li:nth-child(3n)::after {
    display: none;
  }
  .physical-intake-workflow-split,
  .physical-intake-shipment-card,
  .physical-intake-verification-layout {
    grid-template-columns: 1fr;
  }
  .physical-intake-destination-summary {
    border-top: 1px solid #1d3943;
    border-left: 0;
    padding-top: 0.9rem;
    padding-left: 0;
  }
}
@media (max-width: 620px) {
  .physical-intake-detail-page {
    padding-bottom: 1rem;
  }
  .physical-intake-detail-hero,
  .physical-intake-workflow-card {
    padding: 0.8rem;
  }
  .physical-intake-detail-metadata {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .physical-intake-detail-metadata > div {
    border-bottom: 1px solid #1d3a45;
  }
  .physical-intake-detail-metadata > div:nth-child(2n) {
    border-right: 0;
  }
  .physical-intake-detail-metadata > div:last-child {
    border-bottom: 0;
  }
  .physical-intake-stepper {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .physical-intake-stepper li:nth-child(3n)::after {
    display: block;
  }
  .physical-intake-stepper li:nth-child(2n)::after {
    display: none;
  }
  .physical-intake-detail-rail {
    grid-template-columns: 1fr;
  }
  .physical-intake-next-action-card {
    grid-column: auto;
  }
  .physical-intake-detail-tabs {
    overflow-x: auto;
  }
  .physical-intake-detail-tabs button {
    padding-inline: 0.7rem;
    white-space: nowrap;
  }
  .physical-intake-shipment-card dl {
    grid-template-columns: 1fr;
    gap: 0.55rem;
  }
}
